<?php

// phpcs:disable Generic.Files.OneObjectStructurePerFile.MultipleFound

use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the PostgreSQL driver scaffold.
 */
class WP_PostgreSQL_Driver_Tests extends TestCase {
	/**
	 * Number of times the static FETCH_FUNC regression callback was invoked.
	 *
	 * @var int
	 */
	private static $mysql_introspection_fetch_func_invocations = 0;

	/**
	 * Real PostgreSQL schemas created for the current test.
	 *
	 * @var array<int,array{pdo:PDO,schema:string}>
	 */
	private $real_pgsql_test_schemas = array();

	/**
	 * Drop isolated real PostgreSQL schemas created during the test.
	 */
	protected function tearDown(): void {
		foreach ( array_reverse( $this->real_pgsql_test_schemas ) as $cleanup ) {
			try {
				$pdo = $cleanup['pdo'];
				if ( $pdo->inTransaction() ) {
					$pdo->rollBack();
				}

				$pdo->exec(
					'DROP SCHEMA IF EXISTS ' .
					WP_PostgreSQL_Connection::quote_identifier_value( $cleanup['schema'] ) .
					' CASCADE'
				);
			} catch ( Throwable $e ) {
				// Cleanup should not mask the test result.
			}
		}

		$this->real_pgsql_test_schemas = array();
		parent::tearDown();
	}

	/**
	 * Tests SELECT queries return fetched rows and normalized metadata.
	 */
	public function test_query_returns_rows_and_metadata(): void {
		$driver = $this->create_real_pgsql_driver();

		$rows = $driver->query( "SELECT 1 AS id, 'ok' AS value" );

		$this->assertCount( 1, $rows );
		$this->assertSame( '1', $rows[0]->id );
		$this->assertSame( 'ok', $rows[0]->value );
		$this->assertSame( 'SELECT 1 AS id, \'ok\' AS value', $driver->get_last_mysql_query() );
		$this->assertSame(
			array(
				array(
					'sql'    => "SELECT 1 AS id, 'ok' AS value",
					'params' => array(),
				),
			),
			$this->get_last_schema_postgresql_queries( $driver )
		);

		$column_meta = $driver->get_last_column_meta();
		$this->assertCount( 2, $column_meta );
		$this->assertSame( 'id', $column_meta[0]['name'] );
		$this->assertSame( 'wptests', $column_meta[0]['mysqli:db'] );
		$this->assertArrayHasKey( 'mysqli:type', $column_meta[0] );
		$this->assertArrayHasKey( 'mysqli:charsetnr', $column_meta[0] );
	}

	/**
	 * Tests MySQL single-quoted SELECT aliases are translated to PostgreSQL identifiers.
	 */
	public function test_select_single_quoted_projection_aliases_translate_to_postgresql_identifiers(): void {
		$driver = $this->create_real_pgsql_driver();

		$driver->query(
			"SELECT TABLE_NAME AS 'table', TABLE_ROWS AS 'rows', SUM(data_length + index_length) as 'bytes'
			FROM information_schema.TABLES
			WHERE TABLE_SCHEMA = 'wordpress_develop_tests'
			AND TABLE_NAME IN ('wptests_comments','wptests_options','wptests_posts','wptests_terms','wptests_users')
			GROUP BY TABLE_NAME"
		);

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringNotContainsString( "AS 'table'", $sql );
		$this->assertStringNotContainsString( "AS 'rows'", $sql );
		$this->assertStringNotContainsString( "as 'bytes'", $sql );
		$this->assertStringContainsString( 'AS "table"', $sql );
		$this->assertStringContainsString( 'AS "rows"', $sql );
		$this->assertStringContainsString( 'as "bytes"', $sql );
		$this->assertStringContainsString( "'wordpress_develop_tests'", $sql );
		$this->assertStringContainsString( "'wptests_posts'", $sql );

		$rows = $driver->query( "SELECT 'table' AS 'alias', 1 AS id WHERE 'rows' = 'rows'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'table', $rows[0]->alias );
		$this->assertSame(
			"SELECT 'table' AS \"alias\", 1 AS id WHERE 'rows' = 'rows'",
			$this->get_last_single_postgresql_sql( $driver )
		);
	}

	/**
	 * Tests MySQL optimizer index hints are removed before PostgreSQL execution.
	 */
	public function test_select_index_hints_are_removed_before_postgresql_execution(): void {
		$driver = $this->create_driver_with_index_hint_tables();

		$queries = array(
			'SELECT * FROM t USE INDEX (i)'    => 'SELECT * FROM t',
			'SELECT * FROM t USE KEY (k)'      => 'SELECT * FROM t',
			'SELECT * FROM t FORCE INDEX (i)'  => 'SELECT * FROM t',
			'SELECT * FROM t FORCE KEY (k)'    => 'SELECT * FROM t',
			'SELECT * FROM t IGNORE INDEX (i)' => 'SELECT * FROM t',
			'SELECT * FROM t IGNORE KEY (k)'   => 'SELECT * FROM t',
			'SELECT * FROM t USE INDEX FOR JOIN (i) JOIN j ON t.id = j.t_id' => 'SELECT * FROM t JOIN j ON t.id = j.t_id',
			'SELECT * FROM t USE INDEX FOR ORDER BY (i) ORDER BY id DESC' => 'SELECT * FROM t ORDER BY id DESC',
			'SELECT id FROM t USE INDEX FOR GROUP BY (i) GROUP BY id HAVING id = 1' => 'SELECT id FROM t GROUP BY id HAVING id = 1',
			'SELECT t.id FROM `t` USE INDEX (i) USE INDEX FOR JOIN (j) USE KEY FOR ORDER BY (o) IGNORE INDEX FOR GROUP BY (g) JOIN j ON t.id = j.t_id WHERE t.id = 1 GROUP BY t.id HAVING t.id = 1 ORDER BY t.id DESC' => 'SELECT t.id FROM "t" JOIN j ON t.id = j.t_id WHERE t.id = 1 GROUP BY t.id HAVING t.id = 1 ORDER BY t.id DESC',
		);

		foreach ( $queries as $mysql_query => $postgresql_sql ) {
			$rows = $driver->query( $mysql_query );

			$this->assertSame( array(), $rows, $mysql_query );
			$sql = $this->get_last_single_postgresql_sql( $driver );
			$this->assertSame( $postgresql_sql, $sql, $mysql_query );
			$this->assert_postgresql_sql_omits_mysql_index_hints( $sql );
		}
	}

	/**
	 * Tests quoted table and index identifiers keep aliases while index hints are removed.
	 */
	public function test_select_index_hints_preserve_quoted_table_and_alias(): void {
		$driver = $this->create_driver_with_index_hint_tables();

		$driver->query( "INSERT INTO t (id, value) VALUES (1, 'first')" );

		$rows = $driver->query( 'SELECT tt.id FROM `t` AS tt USE INDEX (`ix_t_id`) WHERE tt.id = 1' );

		$this->assertCount( 1, $rows );
		$this->assertSame( '1', $rows[0]->id );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertSame( 'SELECT tt.id FROM "t" AS tt WHERE tt.id = 1', $sql );
		$this->assert_postgresql_sql_omits_mysql_index_hints( $sql );
	}

	/**
	 * Tests malformed MySQL index hints are not sent raw to PostgreSQL.
	 */
	public function test_malformed_select_index_hint_is_rejected_before_postgresql_execution(): void {
		$driver = $this->create_driver_with_index_hint_tables();

		try {
			$driver->query( 'SELECT * FROM t USE INDEX' );
			$this->fail( 'Malformed MySQL index hint was not rejected.' );
		} catch ( InvalidArgumentException $exception ) {
			$this->assertSame( 'Unsupported MySQL index hint syntax.', $exception->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests result column metadata is normalized only when requested.
	 */
	public function test_query_defers_column_metadata_until_requested(): void {
		$driver = $this->create_real_pgsql_driver();

		$rows = $driver->query( "SELECT 1 AS id, 'ok' AS value" );

		$this->assertCount( 1, $rows );
		$this->assertSame( 2, $driver->get_last_column_count() );
		$this->assertSame( array(), $this->get_driver_private_property( $driver, 'last_column_meta' ) );
		$this->assertInstanceOf( PDOStatement::class, $this->get_driver_private_property( $driver, 'last_column_meta_statement' ) );

		$column_meta = $driver->get_last_column_meta();
		$this->assertCount( 2, $column_meta );
		$this->assertSame( 'id', $column_meta[0]['name'] );
		$this->assertNull( $this->get_driver_private_property( $driver, 'last_column_meta_statement' ) );
	}

	/**
	 * Tests result fetching avoids fetchAll() only for plain row fetch modes.
	 */
	public function test_result_fetch_helper_uses_incremental_path_only_for_plain_row_modes(): void {
		$driver = ( new ReflectionClass( WP_PostgreSQL_Driver::class ) )->newInstanceWithoutConstructor();
		$method = new ReflectionMethod( WP_PostgreSQL_Driver::class, 'fetch_and_decode_postgresql_result_rows' );
		if ( PHP_VERSION_ID < 80100 ) {
			$method->setAccessible( true );
		}

		$first_row        = (object) array(
			'id'    => '1',
			'label' => 'first',
		);
		$second_row       = (object) array(
			'id'    => '2',
			'label' => 'second',
		);
		$plain_statement  = new WP_PostgreSQL_Result_Materialization_Test_Statement(
			array( $first_row, $second_row )
		);
		$plain_fetch_rows = $method->invoke(
			$driver,
			$plain_statement,
			PDO::FETCH_OBJ,
			array()
		);

		$this->assertSame( array( $first_row, $second_row ), $plain_fetch_rows );
		$this->assertSame( array( PDO::FETCH_OBJ, PDO::FETCH_OBJ, PDO::FETCH_OBJ ), $plain_statement->fetch_modes );
		$this->assertSame( array(), $plain_statement->fetch_all_modes );

		$grouped_fetch_rows = array(
			'odd' => array(
				array(
					'label' => 'first',
				),
			),
		);
		$grouped_statement  = new WP_PostgreSQL_Result_Materialization_Test_Statement(
			array(),
			$grouped_fetch_rows
		);
		$fallback_rows      = $method->invoke(
			$driver,
			$grouped_statement,
			PDO::FETCH_GROUP | PDO::FETCH_ASSOC,
			array()
		);

		$this->assertSame( $grouped_fetch_rows, $fallback_rows );
		$this->assertSame( array(), $grouped_statement->fetch_modes );
		$this->assertSame( array( PDO::FETCH_GROUP | PDO::FETCH_ASSOC ), $grouped_statement->fetch_all_modes );
		$this->assertSame( array( array() ), $grouped_statement->fetch_all_args );
	}

	/**
	 * Tests default object row materialization preserves ordering and metadata.
	 */
	public function test_query_materializes_default_object_rows_without_changing_public_contract(): void {
		$driver = $this->create_driver();

		$driver->get_connection()->query(
			'CREATE TABLE result_materialization_order (
				id INTEGER PRIMARY KEY,
				label TEXT NOT NULL
			)'
		);
		$driver->get_connection()->query(
			"INSERT INTO result_materialization_order (id, label) VALUES
				(1, 'first'),
				(2, 'second'),
				(3, 'third')"
		);

		$rows = $driver->query( 'SELECT id, label FROM result_materialization_order ORDER BY id DESC' );

		$row_ids    = array();
		$row_labels = array();
		foreach ( $rows as $row ) {
			$row_ids[]    = $row->id;
			$row_labels[] = $row->label;
		}

		$this->assertSame( $rows, $driver->get_last_return_value() );
		$this->assertSame( array( '3', '2', '1' ), $row_ids );
		$this->assertSame( array( 'third', 'second', 'first' ), $row_labels );
		$this->assertSame( 2, $driver->get_last_column_count() );
		$this->assertSame( array(), $this->get_driver_private_property( $driver, 'last_column_meta' ) );
		$this->assertInstanceOf( PDOStatement::class, $this->get_driver_private_property( $driver, 'last_column_meta_statement' ) );
		$this->assertSame( array( 'id', 'label' ), array_column( $driver->get_last_column_meta(), 'name' ) );
	}

	/**
	 * Tests associative and grouped fetch modes keep their public result shapes.
	 */
	public function test_query_preserves_associative_and_grouped_fetch_modes(): void {
		$driver = $this->create_driver();

		$driver->get_connection()->query(
			'CREATE TABLE result_materialization_fetch_modes (
				id INTEGER PRIMARY KEY,
				category TEXT NOT NULL,
				label TEXT NOT NULL
			)'
		);
		$driver->get_connection()->query(
			"INSERT INTO result_materialization_fetch_modes (id, category, label) VALUES
				(1, 'odd', 'first'),
				(2, 'even', 'second'),
				(3, 'odd', 'third')"
		);

		$assoc_rows = $driver->query(
			'SELECT id, label FROM result_materialization_fetch_modes ORDER BY id ASC',
			PDO::FETCH_ASSOC
		);

		$this->assertSame(
			array(
				array(
					'id'    => '1',
					'label' => 'first',
				),
				array(
					'id'    => '2',
					'label' => 'second',
				),
				array(
					'id'    => '3',
					'label' => 'third',
				),
			),
			$assoc_rows
		);
		$this->assertSame( $assoc_rows, $driver->get_last_return_value() );

		$grouped_rows = $driver->query(
			'SELECT category, label FROM result_materialization_fetch_modes ORDER BY category ASC, id ASC',
			PDO::FETCH_GROUP | PDO::FETCH_ASSOC
		);

		$this->assertSame(
			array(
				'even' => array(
					array(
						'label' => 'second',
					),
				),
				'odd'  => array(
					array(
						'label' => 'first',
					),
					array(
						'label' => 'third',
					),
				),
			),
			$grouped_rows
		);
		$this->assertSame( $grouped_rows, $driver->get_last_return_value() );
	}

	/**
	 * Tests larger result sets stay fully materialized for wpdb compatibility.
	 */
	public function test_query_keeps_large_results_materialized_for_wpdb_compatibility(): void {
		$driver = $this->create_driver();

		$driver->get_connection()->query(
			'CREATE TABLE result_materialization_large (
				id INTEGER PRIMARY KEY,
				label TEXT NOT NULL
			)'
		);
		$driver->get_connection()->query(
			"INSERT INTO result_materialization_large (id, label)
			SELECT g, 'row-' || CAST(g AS text)
			FROM generate_series(1, 256) AS g"
		);

		$rows = $driver->query( 'SELECT id, label FROM result_materialization_large ORDER BY id ASC' );

		$this->assertCount( 256, $rows );
		$this->assertSame( '1', $rows[0]->id );
		$this->assertSame( 'row-1', $rows[0]->label );
		$this->assertSame( '256', $rows[255]->id );
		$this->assertSame( 'row-256', $rows[255]->label );
		$this->assertSame( $rows, $driver->get_last_return_value() );
		$this->assertSame( 2, $driver->get_last_column_count() );
	}

	/**
	 * Tests write queries return PDO row counts.
	 */
	public function test_write_query_returns_row_count(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE t (id INTEGER PRIMARY KEY, value TEXT)' );
		$result = $driver->query( "INSERT INTO t (id, value) VALUES (1, 'first')" );

		$this->assertSame( 1, $result );
		$this->assertSame( 1, $driver->get_last_return_value() );
		$this->assertSame( array(), $driver->get_last_column_meta() );
		$this->assertSame( 0, $driver->get_last_column_count() );
	}

	/**
	 * Tests simple WordPress INSERT statements are translated to PostgreSQL.
	 */
	public function test_simple_wordpress_insert_with_backticks_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_users (user_login TEXT NOT NULL)' );

		$insert = "INSERT INTO `wptests_users` (`user_login`) VALUES ('admin')";

		$this->assertSame( 1, $driver->query( $insert ) );
		$this->assertSame( $insert, $driver->get_last_mysql_query() );

		$queries = $driver->get_last_postgresql_queries();
		$this->assertCount( 1, $queries );
		$this->assertSame(
			'INSERT INTO "wptests_users" ("user_login") VALUES (\'admin\')',
			$this->remove_real_pgsql_test_schema_qualifiers( $queries[0]['sql'] )
		);
		$this->assertSame( array(), $queries[0]['params'] );

		$rows = $driver->query( "SELECT user_login FROM wptests_users WHERE user_login = 'admin'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'admin', $rows[0]->user_login );
	}

	/**
	 * Tests simple MySQL INSERT forms without INTO and with multi-row VALUES are translated.
	 */
	public function test_simple_insert_without_into_and_multi_row_values_translate_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_bulk_insert (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );

		$this->assertSame(
			2,
			$driver->query( "INSERT wptests_bulk_insert (`id`, `value`) VALUES (1, 'one'), (2, 'two')" )
		);
		$this->assertSame(
			'INSERT INTO "wptests_bulk_insert" ("id", "value") VALUES (1, \'one\'), (2, \'two\')',
			$this->remove_real_pgsql_test_schema_qualifiers( $this->get_last_single_postgresql_sql( $driver ) )
		);

		$this->assertSame(
			1,
			$driver->query( "INSERT IGNORE wptests_bulk_insert (`id`, `value`) VALUES (2, 'duplicate'), (3, 'three')" )
		);
		$this->assertSame(
			'INSERT INTO "wptests_bulk_insert" ("id", "value") VALUES (2, \'duplicate\'), (3, \'three\') ON CONFLICT DO NOTHING',
			$this->remove_real_pgsql_test_schema_qualifiers( $this->get_last_single_postgresql_sql( $driver ) )
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_bulk_insert ORDER BY id' );
		$this->assertSame(
			array(
				array( '1', 'one' ),
				array( '2', 'two' ),
				array( '3', 'three' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->value );
				},
				$rows
			)
		);
	}

	/**
	 * Tests singular VALUE row-list INSERT syntax is translated like VALUES.
	 */
	public function test_value_keyword_insert_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_value_keyword_insert (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );

		$insert = "INSERT INTO wptests_value_keyword_insert (`id`, `value`) VALUE (1, 'one')";

		$this->assertSame( 1, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO "wptests_value_keyword_insert" ("id", "value") VALUES (1, \'one\')',
			$this->remove_real_pgsql_test_schema_qualifiers( $this->get_last_single_postgresql_sql( $driver ) )
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_value_keyword_insert' );
		$this->assertCount( 1, $rows );
		$this->assertSame( '1', $rows[0]->id );
		$this->assertSame( 'one', $rows[0]->value );
	}

	/**
	 * Tests columnless INSERT VALUES statements infer target columns from MySQL metadata.
	 */
	public function test_columnless_insert_values_uses_mysql_metadata_columns(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_columnless_insert (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );
		$this->install_mysql_schema_metadata_fixture(
			$driver,
			'CREATE TABLE wptests_columnless_insert (
				id bigint(20) unsigned NOT NULL,
				value longtext NOT NULL,
				PRIMARY KEY (id)
			)'
		);

		$insert = "INSERT INTO `wptests_columnless_insert` VALUES (1, 'one'), (2, 'two')";

		$this->assertSame( 2, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO "wptests_columnless_insert" ("id", "value") VALUES (1, \'one\'), (2, \'two\')',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_columnless_insert ORDER BY id' );
		$this->assertEquals(
			array(
				(object) array(
					'id'    => '1',
					'value' => 'one',
				),
				(object) array(
					'id'    => '2',
					'value' => 'two',
				),
			),
			$rows
		);
	}

	/**
	 * Tests INSERT IGNORE ... SELECT without INTO keeps SQLite plugin-corpus parity.
	 */
	public function test_insert_ignore_select_without_into_translates_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_insert_ignore_select (id INTEGER PRIMARY KEY, value TEXT NOT NULL)' );
		$driver->query( 'CREATE TABLE wptests_insert_ignore_select_source (id INTEGER NOT NULL, value TEXT NOT NULL)' );
		$driver->query( "INSERT INTO wptests_insert_ignore_select (id, value) VALUES (1, 'existing')" );
		$driver->query( "INSERT INTO wptests_insert_ignore_select_source (id, value) VALUES (1, 'duplicate'), (2, 'new')" );

		$insert = 'INSERT IGNORE wptests_insert_ignore_select (`id`, `value`)
			SELECT id, value FROM wptests_insert_ignore_select_source ORDER BY id';

		$this->assertSame( 1, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO wptests_insert_ignore_select ("id", "value") SELECT id, value FROM wptests_insert_ignore_select_source ORDER BY id ON CONFLICT DO NOTHING',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_insert_ignore_select ORDER BY id' );
		$this->assertSame(
			array(
				array( '1', 'existing' ),
				array( '2', 'new' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->value );
				},
				$rows
			)
		);
	}

	/**
	 * Tests simple MySQL INSERT ... SET assignments are translated to PostgreSQL.
	 */
	public function test_simple_insert_set_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_insert_set (id INTEGER PRIMARY KEY, value TEXT NOT NULL, attempts INTEGER NOT NULL)' );

		$insert = "INSERT INTO wptests_insert_set SET id = 1, value = 'one', attempts = 2";

		$this->assertSame( 1, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_set" ("id", "value", "attempts") VALUES (1, \'one\', 2)',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, value, attempts FROM wptests_insert_set' );
		$this->assertCount( 1, $rows );
		$this->assertSame( '1', $rows[0]->id );
		$this->assertSame( 'one', $rows[0]->value );
		$this->assertSame( '2', $rows[0]->attempts );

		$insert_ignore = "INSERT IGNORE wptests_insert_set SET id = 1, value = 'ignored', attempts = 3";

		$this->assertSame( 0, $driver->query( $insert_ignore ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_set" ("id", "value", "attempts") VALUES (1, \'ignored\', 3) ON CONFLICT DO NOTHING',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT value, attempts FROM wptests_insert_set WHERE id = 1' );
		$this->assertSame( 'one', $rows[0]->value );
		$this->assertSame( '2', $rows[0]->attempts );

		$qualified_insert = "INSERT INTO wptests_insert_set SET wptests_insert_set.id = 2, wptests_insert_set.value = 'two', wptests.wptests_insert_set.attempts = 4";

		$this->assertSame( 1, $driver->query( $qualified_insert ) );
		$this->assertSame(
			'INSERT INTO "wptests_insert_set" ("id", "value", "attempts") VALUES (2, \'two\', 4)',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT value, attempts FROM wptests_insert_set WHERE id = 2' );
		$this->assertSame( 'two', $rows[0]->value );
		$this->assertSame( '4', $rows[0]->attempts );
	}

