		$this->assertStringContainsString(
			'INSERT INTO "wptests_replace_select_defaults" ("color", "id", "size", "name")',
			$postgresql_sql
		);
		$this->assertStringContainsString(
			'SELECT "__wp_pg_replace_rows_source".*, \'\' AS "name" FROM (SELECT',
			$postgresql_sql
		);
		$this->assertStringContainsString(
			'("__wp_pg_replace_target"."id" = "__wp_pg_replace_rows"."id")',
