	/**
	 * Tests columnless INSERT ... SELECT infers target columns from MySQL metadata.
	 */
	public function test_columnless_insert_select_uses_mysql_metadata_columns(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_insert_select_columnless (
				id INTEGER PRIMARY KEY,
				value TEXT NOT NULL
			)'
		);
		$this->install_mysql_schema_metadata_fixture(
			$driver,
			'CREATE TABLE wptests_insert_select_columnless (
				id bigint(20) unsigned NOT NULL,
				value longtext NOT NULL,
				PRIMARY KEY (id)
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_insert_select_columnless_source (
				id INTEGER NOT NULL,
				value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_insert_select_columnless_source (id, value) VALUES (1, 'one'), (2, 'two')" );

		$insert = 'INSERT INTO wptests_insert_select_columnless
			SELECT id, value FROM wptests_insert_select_columnless_source WHERE 1 = 1';

		$this->assertSame( 2, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO wptests_insert_select_columnless ("id", "value") SELECT id, value FROM wptests_insert_select_columnless_source WHERE 1 = 1',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_insert_select_columnless ORDER BY id' );
		$this->assertEquals(
			array(
				(object) array(
					'id'    => '1',
					'value' => 'one',
				),
				(object) array(
					'id'    => '2',
					'value' => 'two',
				),
			),
			$rows
		);
	}

	/**
	 * Tests unsupported generic DML shapes fail closed in the narrow translators.
	 */
	public function test_unsupported_simple_dml_shapes_return_null_translation(): void {
		$driver = $this->create_driver();

		$unsupported_query_methods = array(
			'UPDATE wptests_unsupported, wptests_other SET wptests_other.id = wptests_unsupported.id, wptests_unsupported.id = wptests_other.id WHERE wptests_other.id = 1' => 'translate_simple_mysql_update_query',
		);

		foreach ( $unsupported_query_methods as $query => $method_name ) {
			if ( 'translate_simple_mysql_insert_query' === $method_name || 'translate_simple_mysql_replace_query' === $method_name ) {
				$this->assertNull(
					$this->translate_driver_query_data_with_private_method( $driver, $method_name, $query ),
					$query
				);
				continue;
			}

			$this->assertNull(
				$this->translate_driver_query_with_private_method( $driver, $method_name, $query ),
				$query
			);
		}
	}

	/**
	 * Tests AUTO_INCREMENT zero values generate IDs unless NO_AUTO_VALUE_ON_ZERO is active.
	 */
	public function test_auto_increment_zero_respects_no_auto_value_on_zero_sql_mode(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_posts (
				ID bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				post_title varchar(255) NOT NULL DEFAULT "",
				PRIMARY KEY (ID)
			)'
		);
		$this->assertSame( 1, $driver->query( "INSERT INTO wptests_posts (`ID`, `post_title`) VALUES (0, 'zero')" ) );
		$this->assertSame(
			'INSERT INTO "wptests_posts" ("ID", "post_title") VALUES (DEFAULT, \'zero\')',
			$this->remove_real_pgsql_test_schema_qualifiers( $this->get_last_single_postgresql_sql( $driver ) )
		);
		$this->assertSame( 1, $driver->get_insert_id() );

		$this->assertSame( 1, $driver->query( "INSERT INTO wptests_posts (`ID`, `post_title`) VALUES ('0', 'quoted zero')" ) );
		$this->assertSame( 2, $driver->get_insert_id() );

		$driver->set_sql_mode( 'NO_AUTO_VALUE_ON_ZERO' );
		$this->assertSame( 1, $driver->query( "INSERT INTO wptests_posts (`ID`, `post_title`) VALUES (0, 'literal zero')" ) );
		$this->assertContains(
			'INSERT INTO "wptests_posts" ("ID", "post_title") VALUES (0, \'literal zero\')',
			$this->get_normalized_last_postgresql_sql_statements( $driver )
		);
		$this->assertSame( 0, $driver->get_insert_id() );

		$rows = $driver->query( 'SELECT ID, post_title FROM wptests_posts ORDER BY ID' );
		$this->assertSame(
			array(
				array( '0', 'literal zero' ),
				array( '1', 'zero' ),
				array( '2', 'quoted zero' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->ID, $row->post_title );
				},
				$rows
			)
		);
	}

	/**
	 * Tests AUTO_INCREMENT zero handling applies to ON DUPLICATE KEY UPDATE VALUES rows.
	 */
	public function test_auto_increment_zero_respects_sql_mode_for_upsert_values(): void {
		$driver = $this->create_driver();
		$this->install_identity_upsert_table_with_mysql_metadata( $driver );

		$upsert = "INSERT INTO `wptests_identity_upsert` (`id`, `value`) VALUES (0, 'generated')
			ON DUPLICATE KEY UPDATE `value` = VALUES(`value`)";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame(
			'INSERT INTO "wptests_identity_upsert" ("id", "value") VALUES (DEFAULT, \'generated\') ON CONFLICT ("id") DO UPDATE SET "value" = excluded."value"',
			$this->remove_real_pgsql_test_schema_qualifiers( $this->get_last_single_postgresql_sql( $driver ) )
		);
		$this->assertSame( 1, $driver->get_insert_id() );

		$driver->set_sql_mode( 'NO_AUTO_VALUE_ON_ZERO' );
		$upsert = "INSERT INTO `wptests_identity_upsert` (`id`, `value`) VALUES (0, 'literal zero')
			ON DUPLICATE KEY UPDATE `value` = VALUES(`value`)";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertContains(
			'INSERT INTO "wptests_identity_upsert" ("id", "value") VALUES (0, \'literal zero\') ON CONFLICT ("id") DO UPDATE SET "value" = excluded."value"',
			$this->get_normalized_last_postgresql_sql_statements( $driver )
		);
		$this->assertSame( 0, $driver->get_insert_id() );

		$rows = $driver->query( 'SELECT id, value FROM wptests_identity_upsert ORDER BY id' );
		$this->assertSame(
			array(
				array( '0', 'literal zero' ),
				array( '1', 'generated' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->value );
				},
				$rows
			)
		);
	}

	/**
	 * Tests AUTO_INCREMENT zero handling applies to INSERT ... SET and REPLACE rows.
	 */
	public function test_auto_increment_zero_respects_sql_mode_for_insert_set_and_replace(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_zero_dml (
				ID bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				post_title varchar(255) NOT NULL DEFAULT "",
				PRIMARY KEY (ID)
			)'
		);

		$this->assertSame( 1, $driver->query( "INSERT INTO wptests_zero_dml SET ID = 0, post_title = 'set-generated'" ) );
		$this->assertSame(
			'INSERT INTO "wptests_zero_dml" ("ID", "post_title") VALUES (DEFAULT, \'set-generated\')',
			$this->remove_real_pgsql_test_schema_qualifiers( $this->get_last_single_postgresql_sql( $driver ) )
		);
		$this->assertSame( 1, $driver->get_insert_id() );

		$this->assertSame( 1, $driver->query( "REPLACE INTO wptests_zero_dml (`ID`, `post_title`) VALUES ('0', 'replace-generated')" ) );
		$this->assert_last_postgresql_sql_statements(
			$driver,
			array(
				'INSERT INTO "wptests_zero_dml" ("ID", "post_title") VALUES (DEFAULT, \'replace-generated\')',
			)
		);
		$this->assertSame( 2, $driver->get_insert_id() );

		$driver->set_sql_mode( 'NO_AUTO_VALUE_ON_ZERO' );

		$this->assertSame( 1, $driver->query( "INSERT INTO wptests_zero_dml SET ID = 0, post_title = 'set-literal'" ) );
		$this->assertContains(
			'INSERT INTO "wptests_zero_dml" ("ID", "post_title") VALUES (0, \'set-literal\')',
			$this->get_normalized_last_postgresql_sql_statements( $driver )
		);
		$this->assertSame( 0, $driver->get_insert_id() );

		$this->assertSame( 2, $driver->query( "REPLACE INTO wptests_zero_dml (`ID`, `post_title`) VALUES (0, 'replace-literal')" ) );
		$this->assertContains(
			'DELETE FROM "wptests_zero_dml" WHERE ("ID" = 0)',
			$this->get_normalized_last_postgresql_sql_statements( $driver )
		);
		$this->assertContains(
			'INSERT INTO "wptests_zero_dml" ("ID", "post_title") VALUES (0, \'replace-literal\')',
			$this->get_normalized_last_postgresql_sql_statements( $driver )
		);
		$this->assertSame( 0, $driver->get_insert_id() );

		$rows = $driver->query( 'SELECT `ID` AS id, post_title FROM wptests_zero_dml ORDER BY `ID`' );
		$this->assertSame(
			array(
				array( '0', 'replace-literal' ),
				array( '1', 'set-generated' ),
				array( '2', 'replace-generated' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->post_title );
				},
				$rows
			)
		);
	}

	/**
	 * Tests AUTO_INCREMENT zero handling applies to INSERT ... SELECT projections.
	 */
	public function test_auto_increment_zero_respects_sql_mode_for_insert_select(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_insert_select_posts (
				ID bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				post_title varchar(255) NOT NULL DEFAULT "",
				PRIMARY KEY (ID)
			)'
		);
		$this->assertSame( 1, $driver->query( "INSERT INTO `wptests_insert_select_posts` (`ID`, `post_title`) SELECT 0, 'generated' FROM DUAL" ) );
		$generated_insert_select_sql = array_map(
			static function ( string $sql ): string {
				return (string) preg_replace(
					"/'wp_pg_test_[0-9a-f]{16}[.]wptests_insert_select_posts'/",
					"'wp_pg_test_schema.wptests_insert_select_posts'",
					$sql
				);
			},
			$this->get_normalized_last_postgresql_sql_statements( $driver )
		);
		$this->assertContains(
			'INSERT INTO "wptests_insert_select_posts" ("ID", "post_title") SELECT nextval(pg_get_serial_sequence(\'wp_pg_test_schema.wptests_insert_select_posts\', \'ID\')) , \'generated\'',
			$generated_insert_select_sql
		);
		$this->assertSame( 0, $driver->get_insert_id() );

		$driver->set_sql_mode( 'NO_AUTO_VALUE_ON_ZERO' );
		$this->assertSame( 1, $driver->query( "INSERT INTO `wptests_insert_select_posts` (`ID`, `post_title`) SELECT 0, 'literal zero' FROM DUAL" ) );
		$this->assertContains(
			'INSERT INTO "wptests_insert_select_posts" ("ID", "post_title") SELECT 0, \'literal zero\'',
			$this->get_normalized_last_postgresql_sql_statements( $driver )
		);
		$this->assertSame( 0, $driver->get_insert_id() );

		$rows = $driver->query( 'SELECT ID, post_title FROM wptests_insert_select_posts ORDER BY ID' );
		$this->assertSame(
			array(
				array( '0', 'literal zero' ),
				array( '1', 'generated' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->ID, $row->post_title );
				},
				$rows
			)
		);
	}

	/**
	 * Tests inserts omitting AUTO_INCREMENT skip identity sequence repair work.
	 */
	public function test_real_pgsql_implicit_auto_increment_insert_skips_identity_sequence_repair(): void {
		$driver = $this->create_real_pgsql_driver( 'wptests', true );

		$driver->query(
			'CREATE TABLE seq_repair_implicit (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				value longtext NOT NULL,
				PRIMARY KEY (id)
			)'
		);

		$logged_sql = array();
		$driver->get_connection()->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);

		$this->assertSame( 1, $driver->query( "INSERT INTO seq_repair_implicit (`value`) VALUES ('first')" ) );
		$this->assertSame( 1, $driver->get_insert_id() );
		$this->assertSame( 0, $this->count_identity_sequence_repair_metadata_queries( $logged_sql ) );
		$this->assertSame( array(), $this->get_identity_sequence_repair_queries( $driver->get_last_postgresql_queries() ) );

		$this->assertSame( 1, $driver->query( "INSERT INTO seq_repair_implicit (`value`) VALUES ('second')" ) );
		$this->assertSame( 2, $driver->get_insert_id() );

		$rows = $driver->query( 'SELECT id, value FROM seq_repair_implicit ORDER BY id' );
		$this->assertSame(
			array(
				array( '1', 'first' ),
				array( '2', 'second' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->value );
				},
				$rows
			)
		);
	}

	/**
	 * Tests explicit AUTO_INCREMENT inserts still repair the PostgreSQL identity sequence.
	 */
	public function test_real_pgsql_explicit_auto_increment_insert_repairs_identity_sequence(): void {
		$driver = $this->create_real_pgsql_driver( 'wptests', true );

		$driver->query(
			'CREATE TABLE seq_repair_explicit (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				value longtext NOT NULL,
				PRIMARY KEY (id)
			)'
		);

		$this->assertSame( 1, $driver->query( "INSERT INTO seq_repair_explicit (`id`, `value`) VALUES (10, 'explicit')" ) );
		$this->assertSame( 10, $driver->get_insert_id() );

		$repair_queries = $this->get_identity_sequence_repair_queries( $driver->get_last_postgresql_queries() );
