	/**
	 * Tests inserts into tables without AUTO_INCREMENT skip identity sequence repair work.
	 */
	public function test_real_pgsql_insert_into_table_without_auto_increment_uses_identity_eligibility_cache_and_invalidates_on_ddl(): void {
		$driver = $this->create_real_pgsql_driver( 'wptests', true );

		$driver->query(
			'CREATE TABLE seq_repair_plain (
				id int NOT NULL,
				value longtext NOT NULL,
				PRIMARY KEY (id)
			)'
		);

		$logged_sql = array();
		$driver->get_connection()->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);

		$this->assertSame( 1, $driver->query( "INSERT INTO seq_repair_plain (`id`, `value`) VALUES (1, 'first')" ) );
		$this->assertSame( 1, $driver->query( "INSERT INTO seq_repair_plain (`id`, `value`) VALUES (2, 'second')" ) );
		$this->assertSame( 0, $this->count_dml_identity_eligibility_metadata_queries( $logged_sql ) );
		$this->assertSame( 0, $this->count_identity_sequence_repair_metadata_queries( $logged_sql ) );
		$this->assertSame( array(), $this->get_identity_sequence_repair_queries( $driver->get_last_postgresql_queries() ) );

		$rows = $driver->query( 'SELECT id, value FROM seq_repair_plain ORDER BY id' );
		$this->assertSame(
			array(
				array( '1', 'first' ),
				array( '2', 'second' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->value );
				},
				$rows
			)
		);

		$this->assertSame( 0, $driver->query( 'ALTER TABLE seq_repair_plain CHANGE COLUMN `id` `id` int NOT NULL AUTO_INCREMENT' ) );

		$logged_sql = array();
		$this->assertSame( 1, $driver->query( "INSERT INTO seq_repair_plain (`id`, `value`) VALUES (10, 'explicit')" ) );
		$this->assertSame( 10, $driver->get_insert_id() );
		$this->assertSame( 1, $this->count_dml_identity_eligibility_metadata_queries( $logged_sql ) );
		$this->assertSame( 1, $this->count_identity_sequence_repair_metadata_queries( $logged_sql ) );

		$repair_queries = $this->get_identity_sequence_repair_queries( $driver->get_last_postgresql_queries() );
		$this->assertCount( 1, $repair_queries );
		$this->assertStringContainsString(
			'"seq_repair_plain_id_seq"',
			$repair_queries[0]['params'][0]
		);

		$this->assertSame( 1, $driver->query( "INSERT INTO seq_repair_plain (`value`) VALUES ('implicit')" ) );
		$this->assertSame( 11, $driver->get_insert_id() );
		$this->assertSame( 1, $this->count_dml_identity_eligibility_metadata_queries( $logged_sql ) );
		$this->assertSame( 1, $this->count_identity_sequence_repair_metadata_queries( $logged_sql ) );

		$rows = $driver->query( 'SELECT id, value FROM seq_repair_plain ORDER BY id' );
		$this->assertSame(
			array(
				array( '1', 'first' ),
				array( '2', 'second' ),
				array( '10', 'explicit' ),
				array( '11', 'implicit' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->value );
				},
				$rows
			)
		);
	}

	/**
	 * Tests WooCommerce-style session upserts with WordPress %i double-quoted table identifiers.
	 */
	public function test_double_quoted_table_identifier_upsert_and_select_are_translated(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_woocommerce_sessions (
				session_id INTEGER PRIMARY KEY,
				session_key TEXT NOT NULL UNIQUE,
				session_value TEXT NOT NULL,
				session_expiry INTEGER NOT NULL
			)'
		);
		$this->install_mysql_schema_metadata_fixture(
			$driver,
			'CREATE TABLE wptests_woocommerce_sessions (
				session_id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				session_key char(32) NOT NULL,
				session_value longtext NOT NULL,
				session_expiry bigint(20) unsigned NOT NULL,
				PRIMARY KEY (session_id),
				UNIQUE KEY session_key (session_key)
			)'
		);

		$upsert = "INSERT INTO \"wptests_woocommerce_sessions\" (`session_key`, `session_value`, `session_expiry`)
			VALUES ('session-key', 'first', 1781870576)
			ON DUPLICATE KEY UPDATE `session_value` = VALUES(`session_value`), `session_expiry` = VALUES(`session_expiry`)";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame(
			'INSERT INTO "wptests_woocommerce_sessions" ("session_key", "session_value", "session_expiry") VALUES (\'session-key\', \'first\', 1781870576) ON CONFLICT ("session_key") DO UPDATE SET "session_value" = excluded."session_value", "session_expiry" = excluded."session_expiry"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$duplicate_upsert = "INSERT INTO \"wptests_woocommerce_sessions\" (`session_key`, `session_value`, `session_expiry`)
			VALUES ('session-key', 'second', 1781870577)
			ON DUPLICATE KEY UPDATE `session_value` = VALUES(`session_value`), `session_expiry` = VALUES(`session_expiry`)";

		$this->assertSame( 1, $driver->query( $duplicate_upsert ) );

		$rows = $driver->query( "SELECT session_value, session_expiry FROM \"wptests_woocommerce_sessions\" WHERE session_key = 'session-key'" );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'second', $rows[0]->session_value );
		$this->assertSame( '1781870577', $rows[0]->session_expiry );
		$this->assertSame(
			'SELECT session_value, session_expiry FROM "wptests_woocommerce_sessions" WHERE session_key = \'session-key\'',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$count_rows = $driver->query( "SELECT COUNT(*) AS session_count FROM \"wptests_woocommerce_sessions\" WHERE session_key = 'session-key'" );

		$this->assertCount( 1, $count_rows );
		$this->assertSame( '1', $count_rows[0]->session_count );
		$this->assertSame(
			'SELECT COUNT(*) AS session_count FROM "wptests_woocommerce_sessions" WHERE session_key = \'session-key\'',
			$this->get_last_single_postgresql_sql( $driver )
		);
	}

	/**
	 * Tests unsupported LAST_INSERT_ID(expr) upsert assignments fail closed.
	 */
	public function test_upsert_last_insert_id_assignment_unsupported_shapes_fail_closed(): void {
		$driver = $this->create_driver();

		$this->install_identity_unique_upsert_table_with_mysql_metadata( $driver );
		$driver->get_connection()->query( "INSERT INTO wptests_identity_unique_upsert (id, slug, value) VALUES (7, 'existing', 'old')" );

		$queries = array(
			"INSERT INTO `wptests_identity_unique_upsert` (`slug`, `value`)
				VALUES ('existing', 'updated')
				ON DUPLICATE KEY UPDATE `value` = LAST_INSERT_ID(`id`)",
			"INSERT INTO `wptests_identity_unique_upsert` (`slug`, `value`)
				VALUES ('existing', 'updated')
				ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id` + 1)",
			"INSERT INTO `wptests_identity_unique_upsert` (`slug`, `value`)
				VALUES ('existing', 'updated'), ('new', 'created')
				ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id`)",
		);

		foreach ( $queries as $query ) {
			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported LAST_INSERT_ID() upsert assignment to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ON DUPLICATE KEY UPDATE statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
