		$insert = "INSERT LOW_PRIORITY INTO `wptests_options` (`option_name`, `option_value`, `autoload`)
			VALUES ('siteurl', 'http://example.org', 'yes')
			ON DUPLICATE KEY UPDATE `option_value` = VALUES(`option_value`),
