		$driver = $this->create_driver();

		$this->assertSame(
			0,
			$driver->query(
				'CREATE TABLE wptests_unnamed_unique_upsert (
					id int(11) NOT NULL,
					name varchar(255) DEFAULT NULL,
					other varchar(255) DEFAULT NULL,
					PRIMARY KEY (id),
					UNIQUE KEY (name)
				)'
			)
		);

		$insert = 'INSERT INTO wptests_unnamed_unique_upsert (id, `name`, other)
			VALUES (1, "name", "test")
