		$this->assertSame(
			'INSERT INTO "wptests_unnamed_unique_upsert" ("id", "name", "other") VALUES (2, \'name\', \'updated\') ON CONFLICT (SUBSTR(CAST("name" AS text), 1, 191)) DO UPDATE SET "other" = excluded."other"',
