	/**
	 * Tests ON DUPLICATE KEY UPDATE supports VALUES() for omitted table columns.
	 */
	public function test_upsert_update_assignments_support_values_for_omitted_columns(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_omitted_values_upsert (
				id INTEGER PRIMARY KEY,
				label TEXT NOT NULL,
				note TEXT,
				counter INTEGER NOT NULL,
				bonus INTEGER NOT NULL DEFAULT 0
			)'
		);
		$this->install_mysql_schema_metadata_fixture(
			$driver,
			'CREATE TABLE wptests_omitted_values_upsert (
				id bigint(20) unsigned NOT NULL,
				label varchar(191) NOT NULL,
				note longtext DEFAULT NULL,
				counter int(11) NOT NULL,
				bonus int(11) NOT NULL DEFAULT 0,
				PRIMARY KEY (id)
			)'
		);
		$driver->query( "INSERT INTO wptests_omitted_values_upsert (id, label, note, counter, bonus) VALUES (1, 'old', 'old-note', 5, 7)" );

		$upsert = "INSERT INTO `wptests_omitted_values_upsert` (`id`, `label`, `counter`)
			VALUES (1, 'new', 1)
			ON DUPLICATE KEY UPDATE `label` = VALUES(`label`),
			                        `note` = VALUES(`note`),
			                        `counter` = `counter` + VALUES(`bonus`)";

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'INSERT INTO "wptests_omitted_values_upsert" ("id", "label", "counter") VALUES (1, \'new\', 1) ON CONFLICT ("id") DO UPDATE SET "label" = excluded."label", "note" = excluded."note", "counter" = "wptests_omitted_values_upsert"."counter" + excluded."bonus"',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( 'SELECT label, note, counter, bonus FROM wptests_omitted_values_upsert WHERE id = 1' );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'new', $rows[0]->label );
		$this->assertNull( $rows[0]->note );
		$this->assertSame( '5', $rows[0]->counter );
		$this->assertSame( '7', $rows[0]->bonus );
	}

	/**
	 * Tests omitted unique-key columns can use table defaults as upsert arbiters.
	 */
	public function test_upsert_uses_defaulted_omitted_unique_key_conflict_target(): void {
		$driver = $this->create_driver();

		$driver->get_connection()->query(
			"CREATE TABLE wptests_default_unique_upsert (
				slug TEXT NOT NULL DEFAULT 'shared',
				value TEXT NOT NULL,
				UNIQUE (slug)
			)"
		);
		$this->install_mysql_schema_metadata_fixture(
			$driver,
			"CREATE TABLE wptests_default_unique_upsert (
				slug varchar(191) NOT NULL DEFAULT 'shared',
				value longtext NOT NULL,
				UNIQUE KEY slug (slug)
			)"
		);
		$driver->get_connection()->query( "INSERT INTO wptests_default_unique_upsert (slug, value) VALUES ('shared', 'old')" );

		$update = "INSERT INTO `wptests_default_unique_upsert` (`value`)
			VALUES ('updated')
			ON DUPLICATE KEY UPDATE `value` = VALUES(`value`)";

		$this->assertSame( 1, $driver->query( $update ) );
		$this->assertSame(
			'INSERT INTO "wptests_default_unique_upsert" ("value") VALUES (\'updated\') ON CONFLICT ("slug") DO UPDATE SET "value" = excluded."value"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT slug, value FROM wptests_default_unique_upsert' );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'shared', $rows[0]->slug );
		$this->assertSame( 'updated', $rows[0]->value );

		$driver->get_connection()->query( 'DELETE FROM wptests_default_unique_upsert' );

		$insert = "INSERT INTO `wptests_default_unique_upsert` (`value`)
			VALUES ('inserted')
			ON DUPLICATE KEY UPDATE `value` = VALUES(`value`)";

		$this->assertSame( 1, $driver->query( $insert ) );
		$this->assertSame(
			'INSERT INTO "wptests_default_unique_upsert" ("value") VALUES (\'inserted\') ON CONFLICT ("slug") DO UPDATE SET "value" = excluded."value"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT slug, value FROM wptests_default_unique_upsert' );

		$this->assertCount( 1, $rows );
		$this->assertSame( 'shared', $rows[0]->slug );
		$this->assertSame( 'inserted', $rows[0]->value );
	}

	/**
	 * Tests ON DUPLICATE KEY UPDATE supports MySQL VALUES-row alias expressions.
	 */
	public function test_upsert_update_assignments_support_values_row_alias_expressions(): void {
		$driver = $this->create_driver();
		$this->install_strict_integer_values_table_with_mysql_metadata( $driver );
		$driver->query( 'INSERT INTO wptests_strict_ints (id, int_value) VALUES (1, 4)' );

		$upsert = 'INSERT INTO `wptests_strict_ints` (`id`, `int_value`)
			VALUES (1, 3) AS incoming
			ON DUPLICATE KEY UPDATE `int_value` = `int_value` + incoming.`int_value`';

		$this->assertSame( 1, $driver->query( $upsert ) );
		$this->assertSame(
			'INSERT INTO "wptests_strict_ints" ("id", "int_value") VALUES (1, 3) ON CONFLICT ("id") DO UPDATE SET "int_value" = "wptests_strict_ints"."int_value" + excluded."int_value"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT int_value FROM wptests_strict_ints WHERE id = 1' );

		$this->assertCount( 1, $rows );
		$this->assertSame( '7', $rows[0]->int_value );

		$column_alias_upsert = 'INSERT INTO `wptests_strict_ints` (`id`, `int_value`)
			VALUES (1, 11) AS incoming(row_id, new_value)
			ON DUPLICATE KEY UPDATE `int_value` = new_value';

		$this->assertSame( 1, $driver->query( $column_alias_upsert ) );
		$this->assertSame(
			'INSERT INTO "wptests_strict_ints" ("id", "int_value") VALUES (1, 11) ON CONFLICT ("id") DO UPDATE SET "int_value" = excluded."int_value"',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT int_value FROM wptests_strict_ints WHERE id = 1' );

		$this->assertCount( 1, $rows );
		$this->assertSame( '11', $rows[0]->int_value );
	}

