	/**
	 * Tests WooCommerce reserved-stock INSERT SELECT upserts with FROM DUAL predicates.
	 */
	public function test_woocommerce_reserved_stock_insert_select_on_duplicate_key_update(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_wc_reserved_stock (
				`order_id` bigint(20) unsigned NOT NULL,
				`product_id` bigint(20) unsigned NOT NULL,
				`stock_quantity` double NOT NULL DEFAULT 0,
				`timestamp` datetime NOT NULL DEFAULT "0000-00-00 00:00:00",
				`expires` datetime NOT NULL DEFAULT "0000-00-00 00:00:00",
				PRIMARY KEY (`order_id`, `product_id`)
			)'
		);

		$insert = 'INSERT INTO wptests_wc_reserved_stock (order_id, product_id, stock_quantity, timestamp, expires)
			SELECT 5001, 89, 2, NOW(), ( NOW() + INTERVAL 10 MINUTE ) FROM DUAL
			WHERE ( SELECT 12 FOR UPDATE ) - ( SELECT IFNULL(SUM(stock_quantity), 0) FROM wptests_wc_reserved_stock WHERE product_id = 89 FOR UPDATE ) >= 2
			ON DUPLICATE KEY UPDATE expires = VALUES(expires), stock_quantity = VALUES(stock_quantity)';

		$translate = new ReflectionMethod( WP_PostgreSQL_Driver::class, 'translate_mysql_on_duplicate_key_update_query' );
		$upsert    = $translate->invoke( $driver, $insert );

		$this->assertIsArray( $upsert );
		$this->assertTrue( $upsert['upsert_select_materialized'] );
		$this->assertStringContainsString( "INTERVAL '1 minute'", $upsert['materialize_statements'][1] );
		$this->assertStringNotContainsString( 'INTERVAL 10 MINUTE', $upsert['materialize_statements'][1] );
		$this->assertStringNotContainsString( 'FOR UPDATE', $upsert['materialize_statements'][1] );
		$this->assertSame(
			'INSERT INTO "wptests_wc_reserved_stock" ("order_id", "product_id", "stock_quantity", "timestamp", "expires") SELECT "__wp_pg_upsert_rows"."order_id", "__wp_pg_upsert_rows"."product_id", "__wp_pg_upsert_rows"."stock_quantity", "__wp_pg_upsert_rows"."timestamp", "__wp_pg_upsert_rows"."expires" FROM "__wp_pg_upsert_select_9a6b0de90d5c" AS "__wp_pg_upsert_rows" WHERE 1 = 1 ON CONFLICT ("order_id", "product_id") DO UPDATE SET "expires" = excluded."expires", "stock_quantity" = excluded."stock_quantity"',
			$upsert['mutation_statements'][0]
		);
	}

	/**
	 * Tests duplicate SELECT source keys replay with MySQL row-by-row upsert semantics.
	 */
	public function test_insert_select_on_duplicate_key_update_with_duplicate_source_conflict_keys_replays_rows_sequentially(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_plugin_lookup_duplicate (
				source TEXT NOT NULL,
				external_id TEXT NOT NULL,
				attempts INTEGER NOT NULL,
				payload TEXT NOT NULL,
				UNIQUE (source, external_id)
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_plugin_lookup_duplicate_source (
				seq INTEGER NOT NULL,
				source TEXT NOT NULL,
				external_id TEXT NOT NULL,
				attempts INTEGER NOT NULL,
				payload TEXT NOT NULL
			)'
		);
		$this->install_mysql_schema_metadata_fixture(
			$driver,
			'CREATE TABLE wptests_plugin_lookup_duplicate (
				source varchar(64) NOT NULL,
				external_id varchar(64) NOT NULL,
				attempts int(11) NOT NULL DEFAULT 0,
				payload longtext NOT NULL,
				UNIQUE KEY source_external_id (source, external_id)
			)'
		);
		$this->install_mysql_schema_metadata_fixture(
			$driver,
			'CREATE TABLE wptests_plugin_lookup_duplicate_source (
				seq int(11) NOT NULL,
				source varchar(64) NOT NULL,
				external_id varchar(64) NOT NULL,
				attempts int(11) NOT NULL,
				payload longtext NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_plugin_lookup_duplicate (source, external_id, attempts, payload) VALUES ('feed', 'abc', 10, 'old')" );
		$driver->query( "INSERT INTO wptests_plugin_lookup_duplicate_source (seq, source, external_id, attempts, payload) VALUES (1, 'feed', 'abc', 1, 'first'), (2, 'feed', 'abc', 2, 'second')" );

		$upsert = 'INSERT INTO `wptests_plugin_lookup_duplicate` (`source`, `external_id`, `attempts`, `payload`)
			SELECT `source`, `external_id`, `attempts`, `payload` FROM `wptests_plugin_lookup_duplicate_source` ORDER BY `seq`
			ON DUPLICATE KEY UPDATE `attempts` = `attempts` + VALUES(`attempts`),
			                        `payload` = VALUES(`payload`)';

		$this->assertSame( 2, $driver->query( $upsert ) );

		$sql = array_column( $driver->get_last_postgresql_queries(), 'sql' );
		$this->assertCount( 7, $sql );
		$this->assertRegExp( '/^DROP TABLE IF EXISTS "__wp_pg_upsert_select_[a-f0-9]{12}"$/', $sql[0] );
		$this->assertRegExp( '/^CREATE TEMPORARY TABLE "__wp_pg_upsert_select_[a-f0-9]{12}" AS SELECT /', $sql[1] );
		$this->assertRegExp( '/^CREATE TEMPORARY TABLE "__wp_pg_upsert_select_ord_[a-f0-9]{12}" AS SELECT ROW_NUMBER\(\) OVER \(\) AS "__wp_pg_upsert_ordinal"/', $sql[2] );
		$this->assertStringContainsString( '"__wp_pg_upsert_rows"."__wp_pg_upsert_ordinal" = 1', $sql[3] );
		$this->assertStringContainsString( '"__wp_pg_upsert_rows"."__wp_pg_upsert_ordinal" = 2', $sql[4] );
		$this->assertStringContainsString( 'ON CONFLICT ("source", "external_id") DO UPDATE SET "attempts" = "wptests_plugin_lookup_duplicate"."attempts" + excluded."attempts", "payload" = excluded."payload"', $sql[3] );
		$this->assertStringContainsString( 'ON CONFLICT ("source", "external_id") DO UPDATE SET "attempts" = "wptests_plugin_lookup_duplicate"."attempts" + excluded."attempts", "payload" = excluded."payload"', $sql[4] );
		$this->assertRegExp( '/^DROP TABLE IF EXISTS "__wp_pg_upsert_select_ord_[a-f0-9]{12}"$/', $sql[5] );
		$this->assertSame( $sql[0], $sql[6] );

