			'UPDATE "wptests_update_ignore_unique" SET "slug" = \'a\', "note" = \'changed\' WHERE (slug = \'b\') AND ("slug" IS DISTINCT FROM (\'a\') OR "note" IS DISTINCT FROM (\'changed\'))',
