	/**
	 * Tests MySQL inner joined UPDATE statements translate through PostgreSQL UPDATE FROM.
	 */
	public function test_inner_join_update_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_joined (
				id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_joined_meta (
				post_id INTEGER NOT NULL,
				meta_key TEXT NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_joined (id, status) VALUES (1, 'draft'), (2, 'draft')" );
		$driver->query( "INSERT INTO wptests_update_joined_meta (post_id, meta_key, meta_value) VALUES (1, '_status', 'publish'), (2, '_other', 'private')" );

		$update = "UPDATE wptests_update_joined AS p JOIN wptests_update_joined_meta AS pm ON p.id = pm.post_id SET p.status = pm.meta_value WHERE pm.meta_key = '_status'";

		$this->assertSame( 1, $driver->query( $update ) );
		$this->assertSame( 0, $driver->query( $update ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'UPDATE "wptests_update_joined" AS "p" SET "status" = pm.meta_value FROM "wptests_update_joined_meta" AS "pm" WHERE (p.id = pm.post_id) AND (pm.meta_key = \'_status\') AND ("p"."status" IS DISTINCT FROM (pm.meta_value))',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( 'SELECT id, status FROM wptests_update_joined ORDER BY id' );
		$this->assertSame( 'publish', $rows[0]->status );
		$this->assertSame( 'draft', $rows[1]->status );
	}

	/**
	 * Tests joined UPDATE ORDER BY without LIMIT is preserved in a derived source.
	 */
	public function test_joined_update_order_by_without_limit_preserves_ordering(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_joined_order (
				ctid INTEGER UNIQUE NOT NULL,
				id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_joined_order_meta (
				post_id INTEGER NOT NULL,
				meta_key TEXT NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_joined_order (ctid, id, status) VALUES (1, 1, 'draft'), (2, 2, 'draft'), (3, 3, 'publish')" );
		$driver->query( "INSERT INTO wptests_update_joined_order_meta (post_id, meta_key, meta_value) VALUES (1, '_status', 'private'), (2, '_status', 'scheduled'), (3, '_other', 'ignore')" );

		$update = "UPDATE wptests_update_joined_order AS p
			JOIN wptests_update_joined_order_meta AS pm ON p.id = pm.post_id
			SET p.status = pm.meta_value
			WHERE pm.meta_key = '_status'
			ORDER BY pm.meta_value ASC, p.id DESC";

		$this->assertSame( 2, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'UPDATE "wptests_update_joined_order" AS "p" SET "status" = "mysql_update_values"."mysql_update_value_0"', $sql );
		$this->assertStringContainsString( 'FROM (SELECT "p".ctid AS "mysql_update_target_ctid", pm.meta_value AS "mysql_update_value_0"', $sql );
		$this->assertStringContainsString( "WHERE (p.id = pm.post_id) AND (pm.meta_key = '_status') ORDER BY pm.meta_value ASC, p.id DESC", $sql );

		$rows = $driver->query( 'SELECT id, status FROM wptests_update_joined_order ORDER BY id' );
		$this->assertSame( 'private', $rows[0]->status );
		$this->assertSame( 'scheduled', $rows[1]->status );
		$this->assertSame( 'publish', $rows[2]->status );
	}

	/**
	 * Tests joined UPDATE expression ORDER BY clauses without LIMIT are translated.
	 */
	public function test_joined_update_expression_order_by_without_limit_is_translated(): void {
		$driver = $this->create_driver();

		$update = "UPDATE wptests_update_joined_order AS p
			JOIN wptests_update_joined_order_meta AS pm ON p.id = pm.post_id
			SET p.status = pm.meta_value
			WHERE pm.meta_key = '_status'
			ORDER BY LENGTH(pm.meta_value), p.id + 0 DESC";

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			$update
		);

		$this->assertStringContainsString( 'FROM (SELECT "p".ctid AS "mysql_update_target_ctid", pm.meta_value AS "mysql_update_value_0"', $sql );
		$this->assertStringContainsString( 'ORDER BY CASE WHEN ', $sql );
		$this->assertStringContainsString( 'ELSE OCTET_LENGTH(CONVERT_TO(CAST(pm.meta_value AS text), \'UTF8\')) END, p.id + 0 DESC', $sql );
	}

	/**
	 * Tests bounded joined UPDATE ORDER BY/LIMIT forms update the intended matched row slice.
	 */
	public function test_joined_update_order_by_limit_updates_ordered_slice(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_joined_limit (
				ctid INTEGER UNIQUE NOT NULL,
				id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_joined_limit_meta (
				post_id INTEGER NOT NULL,
				priority INTEGER NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query(
			"INSERT INTO wptests_update_joined_limit (ctid, id, status) VALUES
				(1, 1, 'queued'),
				(2, 2, 'queued'),
				(3, 3, 'queued'),
				(4, 4, 'done')"
		);
		$driver->query(
			"INSERT INTO wptests_update_joined_limit_meta (post_id, priority, meta_value) VALUES
				(1, 30, 'third'),
				(2, 10, 'first'),
				(3, 20, 'second'),
				(4, 1, 'skip')"
		);

		$update = "UPDATE wptests_update_joined_limit AS p
			JOIN wptests_update_joined_limit_meta AS pm ON pm.post_id = p.id
			SET p.status = pm.meta_value
			WHERE p.status = 'queued'
			ORDER BY pm.priority ASC, p.id DESC
			LIMIT 1, 2";

		$this->assertSame( 2, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'FROM (SELECT "p".ctid AS "mysql_update_target_ctid", pm.meta_value AS "mysql_update_value_0"', $sql );
		$this->assertStringContainsString( "WHERE (pm.post_id = p.id) AND (p.status = 'queued') ORDER BY pm.priority ASC, p.id DESC LIMIT 2 OFFSET 1", $sql );

		$rows = $driver->query( 'SELECT id, status FROM wptests_update_joined_limit ORDER BY id' );
		$this->assertSame( 'third', $rows[0]->status );
		$this->assertSame( 'queued', $rows[1]->status );
		$this->assertSame( 'second', $rows[2]->status );
		$this->assertSame( 'done', $rows[3]->status );

		$comma_update = "UPDATE wptests_update_joined_limit AS p, wptests_update_joined_limit_meta AS pm
			SET p.status = 'limited'
			WHERE pm.post_id = p.id AND p.status = 'queued'
			LIMIT 1";

		$this->assertSame( 1, $driver->query( $comma_update ) );
		$this->assertStringContainsString( 'LIMIT 1', $this->get_last_single_postgresql_sql( $driver ) );
	}

