	/**
	 * Tests Action Scheduler claim UPDATE uses ordered limited derived sources.
	 */
	public function test_action_scheduler_claim_update_with_ordered_limited_derived_source(): void {
		$driver = $this->create_driver();

		$driver->set_sql_mode( '' );
		$driver->query(
			"CREATE TABLE wptests_actionscheduler_actions (
				action_id INTEGER PRIMARY KEY,
				status TEXT NOT NULL,
				scheduled_date_gmt TEXT NULL default '0000-00-00 00:00:00',
				scheduled_date_local TEXT NULL default '0000-00-00 00:00:00',
				priority INTEGER NOT NULL default '10',
				attempts INTEGER NOT NULL default '0',
				last_attempt_gmt TEXT NULL default '0000-00-00 00:00:00',
				last_attempt_local TEXT NULL default '0000-00-00 00:00:00',
				claim_id INTEGER NOT NULL default '0'
			)"
		);
		$driver->query(
			"INSERT INTO wptests_actionscheduler_actions
				(action_id, status, scheduled_date_gmt, scheduled_date_local, priority, attempts, claim_id)
			VALUES
				(1, 'pending', '2025-09-03 12:00:00', '2025-09-03 12:00:00', 20, 1, 0),
				(2, 'pending', '2025-09-03 11:00:00', '2025-09-03 11:00:00', 5, 2, 0),
				(3, 'complete', '2025-09-03 10:00:00', '2025-09-03 10:00:00', 1, 0, 0),
				(4, 'pending', '2025-09-03 09:00:00', '2025-09-03 09:00:00', 1, 0, 9),
				(5, 'pending', '2025-09-04 09:00:00', '2025-09-04 09:00:00', 1, 0, 0)"
		);

		$update = "UPDATE wptests_actionscheduler_actions t1
			JOIN (
				SELECT action_id
				FROM wptests_actionscheduler_actions
				WHERE claim_id = 0 AND scheduled_date_gmt <= '2025-09-03 12:23:55' AND status = 'pending'
				ORDER BY priority ASC, attempts ASC, scheduled_date_gmt ASC, action_id ASC
				LIMIT 2
				FOR UPDATE
			) t2 ON t1.action_id = t2.action_id
			SET claim_id = 37, last_attempt_gmt = '2025-09-03 12:23:55', last_attempt_local = '2025-09-03 12:23:55'";

		$this->assertSame( 2, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'ORDER BY priority ASC, attempts ASC, scheduled_date_gmt ASC, action_id ASC LIMIT 2', $sql );
		$this->assertStringNotContainsString( 'FOR UPDATE', $sql );

		$rows = $driver->query( 'SELECT action_id, claim_id, last_attempt_gmt, last_attempt_local FROM wptests_actionscheduler_actions ORDER BY action_id' );
		$this->assertSame( array( '37', '37', '0', '9', '0' ), array_column( $rows, 'claim_id' ) );
		$this->assertSame( '2025-09-03 12:23:55', $rows[0]->last_attempt_gmt );
		$this->assertSame( '2025-09-03 12:23:55', $rows[1]->last_attempt_local );
		$this->assertSame( '0000-00-00 00:00:00', $rows[2]->last_attempt_gmt );
	}

	/**
	 * Tests MySQL inner joined UPDATE ... USING statements translate to PostgreSQL predicates.
	 */
	public function test_inner_join_update_using_is_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_joined_using (
				post_id INTEGER PRIMARY KEY,
				status TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_joined_using_meta (
				post_id INTEGER NOT NULL,
				meta_key TEXT NOT NULL,
				meta_value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_joined_using (post_id, status) VALUES (1, 'draft'), (2, 'draft')" );
		$driver->query( "INSERT INTO wptests_update_joined_using_meta (post_id, meta_key, meta_value) VALUES (1, '_status', 'publish'), (2, '_other', 'private')" );

		$update = "UPDATE wptests_update_joined_using AS p INNER JOIN wptests_update_joined_using_meta AS pm USING (post_id) SET p.status = pm.meta_value WHERE pm.meta_key = '_status'";

		$this->assertSame( 1, $driver->query( $update ) );
		$this->assertSame( 0, $driver->query( $update ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'UPDATE "wptests_update_joined_using" AS "p" SET "status" = pm.meta_value FROM "wptests_update_joined_using_meta" AS "pm" WHERE (p.post_id = pm.post_id) AND (pm.meta_key = \'_status\') AND ("p"."status" IS DISTINCT FROM (pm.meta_value))',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query( 'SELECT post_id, status FROM wptests_update_joined_using ORDER BY post_id' );
		$this->assertSame( 'publish', $rows[0]->status );
		$this->assertSame( 'draft', $rows[1]->status );
	}

	/**
	 * Tests joined UPDATE can target a non-leftmost table and MySQL join modifiers.
	 */
	public function test_joined_update_non_leftmost_target_and_join_modifiers_translate_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_join_source (
				id INTEGER PRIMARY KEY,
				value TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_join_target (
				id INTEGER PRIMARY KEY,
				value TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_join_source (id, value) VALUES (1, 'one'), (2, 'two'), (3, 'three')" );
		$driver->query( "INSERT INTO wptests_update_join_target (id, value) VALUES (1, 'old'), (2, 'old'), (3, 'old')" );

		$this->assertSame(
			1,
			$driver->query(
				'UPDATE wptests_update_join_source AS s
				JOIN wptests_update_join_target AS t ON t.id = s.id
				SET t.value = s.value
				WHERE s.id = 1'
			)
		);
		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'UPDATE "wptests_update_join_target" AS "t" SET "value" = s.value FROM "wptests_update_join_source" AS "s"', $sql );
		$this->assertStringContainsString( '(t.id = s.id)', $sql );

		$this->assertSame(
			1,
			$driver->query(
				'UPDATE LOW_PRIORITY wptests_update_join_target AS t
				CROSS JOIN wptests_update_join_source AS s
				SET t.value = s.value
				WHERE t.id = s.id AND t.id = 2'
			)
		);

		$this->assertSame(
			1,
			$driver->query(
				'UPDATE IGNORE wptests_update_join_target AS t
				STRAIGHT_JOIN wptests_update_join_source AS s ON s.id = t.id
				SET t.value = s.value
				WHERE t.id = 3'
			)
		);

		$rows = $driver->query( 'SELECT id, value FROM wptests_update_join_target ORDER BY id' );
		$this->assertSame( 'one', $rows[0]->value );
		$this->assertSame( 'two', $rows[1]->value );
		$this->assertSame( 'three', $rows[2]->value );
	}

	/**
	 * Tests joined UPDATE IGNORE skips rows that would violate unique constraints.
	 */
	public function test_joined_update_ignore_unique_conflict_returns_zero_and_preserves_rows(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_update_ignore_join_target (
				id INTEGER PRIMARY KEY,
				slug TEXT NOT NULL UNIQUE,
				note TEXT NOT NULL
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_update_ignore_join_source (
				id INTEGER PRIMARY KEY,
				new_slug TEXT NOT NULL,
				new_note TEXT NOT NULL
			)'
		);
		$driver->query( "INSERT INTO wptests_update_ignore_join_target (id, slug, note) VALUES (1, 'a', 'first'), (2, 'b', 'second')" );
		$driver->query( "INSERT INTO wptests_update_ignore_join_source (id, new_slug, new_note) VALUES (2, 'a', 'changed')" );

		$update = 'UPDATE IGNORE wptests_update_ignore_join_target AS t
			JOIN wptests_update_ignore_join_source AS s ON s.id = t.id
			SET t.slug = s.new_slug, t.note = s.new_note
			WHERE t.id = 2';

		$this->assertSame( 0, $driver->query( $update ) );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'UPDATE "wptests_update_ignore_join_target" AS "t" SET "slug" = s.new_slug, "note" = s.new_note', $sql );
		$this->assertStringContainsString( 'FROM "wptests_update_ignore_join_source" AS "s"', $sql );

		$rows = $driver->query( 'SELECT id, slug, note FROM wptests_update_ignore_join_target ORDER BY id' );

		$this->assertSame( array( 'a', 'b' ), array_column( $rows, 'slug' ) );
		$this->assertSame( array( 'first', 'second' ), array_column( $rows, 'note' ) );
	}

	/**
	 * Tests MySQL multi-target UPDATE statements translate to PostgreSQL writable CTEs.
	 */
	public function test_multi_target_update_is_translated_to_writable_ctes(): void {
		$driver = $this->create_driver();

		$update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value, t.value = s.value
			WHERE t.id = s.id AND s.id = 1';

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$update
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'WITH mysql_update_rows AS MATERIALIZED', $sql );
		$this->assertStringContainsString( 'SELECT "s".ctid AS "mysql_update_0_ctid", t.value AS "mysql_update_value_0", "t".ctid AS "mysql_update_1_ctid", s.value AS "mysql_update_value_1"', $sql );
		$this->assertStringContainsString( 'FROM "wptests_update_source" AS "s", "wptests_update_target" AS "t"', $sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id AND s.id = 1)', $sql );
		$this->assertStringContainsString( 'mysql_update_target_0 AS (UPDATE "wptests_update_source" AS "s" SET "value" = mysql_update_rows."mysql_update_value_0" FROM mysql_update_rows WHERE ("s".ctid = mysql_update_rows."mysql_update_0_ctid")', $sql );
		$this->assertStringContainsString( 'mysql_update_target_1 AS (UPDATE "wptests_update_target" AS "t" SET "value" = mysql_update_rows."mysql_update_value_1" FROM mysql_update_rows WHERE ("t".ctid = mysql_update_rows."mysql_update_1_ctid")', $sql );
		$this->assertStringContainsString( 'SELECT (SELECT COUNT(*) FROM mysql_update_target_0) + (SELECT COUNT(*) FROM mysql_update_target_1) AS affected_rows', $sql );

		$join_update = 'UPDATE wptests_update_source AS s
			JOIN wptests_update_target AS t ON t.id = s.id
			SET s.value = t.value, t.value = s.value
			WHERE s.id = 1';
		$join_sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$join_update
		);

		$this->assertNotNull( $join_sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id) AND (s.id = 1)', $join_sql );
		$this->assertStringNotContainsString( 'ORDER BY', $join_sql );

		$ordered_update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value, t.value = s.value
			WHERE t.id = s.id
			ORDER BY t.id DESC, LENGTH(s.value)';
		$ordered_sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$ordered_update
		);

		$this->assertNotNull( $ordered_sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id)', $ordered_sql );
		$this->assertStringContainsString( 'ORDER BY t.id DESC, CASE WHEN ', $ordered_sql );
		$this->assertStringContainsString( 'ELSE OCTET_LENGTH(CONVERT_TO(CAST(s.value AS text), \'UTF8\')) END', $ordered_sql );

		$limited_update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value, t.value = s.value
			WHERE t.id = s.id
			ORDER BY t.id DESC, s.value ASC
			LIMIT 1, 2';
		$limited_sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$limited_update
		);

		$this->assertNotNull( $limited_sql );
		$this->assertStringContainsString( 'WITH mysql_update_rows AS MATERIALIZED', $limited_sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id) ORDER BY t.id DESC, s.value ASC LIMIT 2 OFFSET 1', $limited_sql );

		$limit_only_update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value, t.value = s.value
			WHERE t.id = s.id
			LIMIT 2';
		$limit_only_sql    = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_update_query',
			$limit_only_update
		);

		$this->assertNotNull( $limit_only_sql );
		$this->assertStringContainsString( 'WHERE (t.id = s.id) LIMIT 2', $limit_only_sql );
		$this->assertStringNotContainsString( 'ORDER BY', $limit_only_sql );

		$single_target_update = 'UPDATE wptests_update_source AS s, wptests_update_target AS t
			SET s.value = t.value
			WHERE t.id = s.id';

		$this->assertNull(
			$this->translate_driver_query_with_private_method(
				$driver,
				'translate_mysql_multi_target_update_query',
				$single_target_update
			)
		);
	}

	/**
	 * Tests joined UPDATE statements can read from information_schema sources.
	 */
	public function test_joined_update_can_read_information_schema_sources(): void {
		$driver = $this->create_driver();
		$this->install_direct_information_schema_options_metadata( $driver );

		$update = 'UPDATE wptests_options AS o
			JOIN information_schema.tables AS it ON o.option_name = it.table_name
			SET o.option_value = it.table_type
			WHERE it.table_schema = DATABASE()
			ORDER BY it.table_name';

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_simple_mysql_update_query',
			$update
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'UPDATE "wptests_options" AS "o" SET "option_value" = "mysql_update_values"."mysql_update_value_0"', $sql );
		$this->assertStringContainsString( 'SELECT "o".ctid AS "mysql_update_target_ctid", "it"."TABLE_TYPE" AS "mysql_update_value_0"', $sql );
		$this->assertStringContainsString( 'FROM "wptests_options" AS "o" JOIN (', $sql );
		$this->assertStringContainsString( ') AS "it" ON "o"."option_name" = "it"."TABLE_NAME"', $sql );
		$this->assertStringContainsString( 'WHERE "it"."TABLE_SCHEMA" = \'wptests\'', $sql );
		$this->assertStringContainsString( 'ORDER BY "it"."TABLE_NAME"', $sql );
		$this->assertStringContainsString( '"o".ctid = "mysql_update_values"."mysql_update_target_ctid"', $sql );
		$this->assertStringContainsString( '"o"."option_value" IS DISTINCT FROM ("mysql_update_values"."mysql_update_value_0")', $sql );
	}

	/**
