	/**
	 * Tests MySQL multi-target DELETE statements translate to PostgreSQL writable CTEs.
	 */
	public function test_mysql_multi_target_delete_is_translated_to_writable_ctes(): void {
		$driver = $this->create_driver();

		$delete = "DELETE p, c
			FROM wptests_delete_multi_parent AS p
			JOIN wptests_delete_multi_child AS c ON c.parent_id = p.id
			WHERE p.status = 'stale'";

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_delete_query',
			$delete
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'WITH mysql_delete_rows AS MATERIALIZED', $sql );
		$this->assertStringContainsString( 'SELECT "p".ctid AS "mysql_delete_target_0_ctid", "c".ctid AS "mysql_delete_target_1_ctid"', $sql );
		$this->assertStringContainsString( 'DELETE FROM "wptests_delete_multi_parent" AS "p"', $sql );
		$this->assertStringContainsString( 'DELETE FROM "wptests_delete_multi_child" AS "c"', $sql );
		$this->assertStringContainsString( 'SELECT (SELECT COUNT(*) FROM mysql_delete_target_0) + (SELECT COUNT(*) FROM mysql_delete_target_1) AS affected_rows', $sql );

		$ordered_delete = "DELETE p, c
			FROM wptests_delete_multi_parent AS p
			JOIN wptests_delete_multi_child AS c ON c.parent_id = p.id
			WHERE p.status = 'stale'
			ORDER BY LENGTH(c.reason), p.id DESC";

		$ordered_sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_delete_query',
			$ordered_delete
		);

		$this->assertNotNull( $ordered_sql );
		$this->assertStringContainsString( 'WITH mysql_delete_rows AS MATERIALIZED', $ordered_sql );
		$this->assertStringContainsString( "WHERE p.status = 'stale' ORDER BY CASE WHEN ", $ordered_sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST(c.reason AS text), 'UTF8')) END, p.id DESC", $ordered_sql );

		$limited_delete = "DELETE p, c
			FROM wptests_delete_multi_parent AS p
			JOIN wptests_delete_multi_child AS c ON c.parent_id = p.id
			WHERE p.status = 'stale'
			ORDER BY c.reason ASC, p.id DESC
			LIMIT 1, 2";

		$limited_sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_delete_query',
			$limited_delete
		);

		$this->assertNotNull( $limited_sql );
		$this->assertStringContainsString( 'WITH mysql_delete_rows AS MATERIALIZED', $limited_sql );
		$this->assertStringContainsString( "WHERE p.status = 'stale' ORDER BY c.reason ASC, p.id DESC LIMIT 2 OFFSET 1", $limited_sql );

		$limit_only_delete = "DELETE p, c
			FROM wptests_delete_multi_parent AS p
			JOIN wptests_delete_multi_child AS c ON c.parent_id = p.id
			WHERE p.status = 'stale'
			LIMIT 2";

		$limit_only_sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_multi_target_delete_query',
			$limit_only_delete
		);

		$this->assertNotNull( $limit_only_sql );
		$this->assertStringContainsString( "WHERE p.status = 'stale' LIMIT 2", $limit_only_sql );
		$this->assertStringNotContainsString( 'ORDER BY', $limit_only_sql );
	}

