	/**
	 * Tests CONVERT(expr, CHAR/BINARY) expressions translate in predicates and ordering.
	 */
	public function test_convert_char_and_binary_column_references_translate_in_predicates_and_ordering(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_convert_typed (value TEXT NOT NULL)' );
		$driver->query( "INSERT INTO wptests_convert_typed (value) VALUES ('abc')" );
		$driver->query( "INSERT INTO wptests_convert_typed (value) VALUES ('ABC')" );

		$rows = $driver->query(
			"SELECT CONVERT(value, CHAR) AS value_text
			FROM wptests_convert_typed
			WHERE CONVERT(value, BINARY) = 'abc'
			ORDER BY CONVERT(value, CHAR)"
		);

		$this->assertCount( 1, $rows );
		$this->assertSame( 'abc', $rows[0]->value_text );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'SELECT CAST(value AS text) AS value_text', $sql );
		$this->assertStringContainsString( "WHERE CAST(value AS text) = 'abc'", $sql );
		$this->assertStringContainsString( 'ORDER BY CAST(value AS text)', $sql );
		$this->assertStringNotContainsString( 'CONVERT', $sql );
	}

	/**
	 * Tests CAST(expr AS DATE) expressions use explicit PostgreSQL semantics.
	 */
	public function test_cast_date_expressions_are_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$date_sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT CAST('2025-10-05 14:05:28' AS DATE) AS date_value"
		);

		$this->assertNotNull( $date_sql );
		$this->assertStringContainsString( 'TO_CHAR', $date_sql );
		$this->assertStringContainsString( ' AS date_value', $date_sql );
		$this->assertStringNotContainsString( 'CAST(' . "'2025-10-05 14:05:28'" . ' AS DATE)', $date_sql );
	}

	/**
	 * Tests unsupported CONVERT(expr, type) forms fail before backend execution.
	 */
	public function test_unsupported_convert_typed_forms_fail_closed_before_backend_execution(): void {
		$queries = array(
			"SELECT CONVERT('12:34:56', TIME) AS time_value",
			"SELECT CONVERT('2025-10-05 14:05:28', DATETIME) AS datetime_value",
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			$this->assertNull(
				$this->translate_driver_query_with_private_method(
					$driver,
					'translate_mysql_compatible_query',
					$query
				),
				$query
			);

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported CONVERT() runtime form to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported MySQL runtime function form.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

	/**
	 * Tests MySQL FIELD() expressions are translated for PostgreSQL ordering.
	 */
	public function test_field_function_is_translated_to_postgresql_case_expression(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_posts ("ID" INTEGER PRIMARY KEY, post_name TEXT NOT NULL)' );
		$driver->query( 'INSERT INTO wptests_posts ("ID", post_name) VALUES (1, \'alpha\')' );
		$driver->query( 'INSERT INTO wptests_posts ("ID", post_name) VALUES (2, \'beta\')' );

		$select = 'SELECT ID FROM wptests_posts WHERE ID IN (1, 2) ORDER BY FIELD(ID, 2, 1)';
		$rows   = $driver->query( $select );

		$this->assertSame( '2', $rows[0]->ID );
		$this->assertSame( '1', $rows[1]->ID );
		$this->assertSame(
			array(
				array(
					'sql'    => 'SELECT "ID" FROM wptests_posts WHERE "ID" IN (1, 2) ORDER BY CASE WHEN "ID" IS NULL THEN 0 WHEN CAST("ID" AS text) = CAST(2 AS text) THEN 1 WHEN CAST("ID" AS text) = CAST(1 AS text) THEN 2 ELSE 0 END',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);
	}

	/**
	 * Tests lowercase field() calls trigger PostgreSQL compatibility translation.
	 */
	public function test_lowercase_field_function_triggers_postgresql_rewrite(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_posts (post_name TEXT NOT NULL)' );
		$driver->query( 'INSERT INTO wptests_posts (post_name) VALUES (\'alpha\')' );
		$driver->query( 'INSERT INTO wptests_posts (post_name) VALUES (\'beta\')' );

		$rows = $driver->query( "SELECT post_name FROM wptests_posts ORDER BY field(post_name, 'beta', 'alpha')" );

		$this->assertSame( 'beta', $rows[0]->post_name );
		$this->assertSame( 'alpha', $rows[1]->post_name );
		$this->assertSame(
			array(
				array(
					'sql'    => 'SELECT post_name FROM wptests_posts ORDER BY CASE WHEN post_name IS NULL THEN 0 WHEN CAST(post_name AS text) = CAST(\'beta\' AS text) THEN 1 WHEN CAST(post_name AS text) = CAST(\'alpha\' AS text) THEN 2 ELSE 0 END',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);
	}

	/**
