	/**
	 * Tests JSON_VALID() runtime calls fold constants and use native dynamic fallback.
	 */
	public function test_json_valid_runtime_function_folds_constants_and_uses_native_fallback_for_dynamic_values(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT JSON_VALID(\'{"ok":true}\') AS object_valid,
				JSON_VALID(CONCAT(\'{"ok":\', \'true}\')) AS concat_object_valid,
				JSON_VALID(CONCAT_WS(\'\', \'[\', \'1\', \']\')) AS concat_array_valid,
				JSON_VALID(REPLACE(\'{"bad":true}\', \'bad\', \'ok\')) AS replace_object_valid,
				JSON_VALID(SUBSTRING(\'xx[1]\', 3)) AS substring_array_valid,
				JSON_VALID(IFNULL(NULL, \'{"fallback":true}\')) AS ifnull_object_valid,
				JSON_VALID(CONCAT(\'{\', NULL, \'}\')) AS concat_null_valid,
				JSON_VALID(NULLIF(\'[1]\', \'[1]\')) AS nullif_null_valid,
				JSON_VALID(\'not json\') AS invalid_json,
				JSON_VALID(NULL) AS null_valid,
				JSON_VALID(payload) AS payload_valid
			FROM runtime_names'
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( '1 AS object_valid', $sql );
		$this->assertStringContainsString( '1 AS concat_object_valid', $sql );
		$this->assertStringContainsString( '1 AS concat_array_valid', $sql );
		$this->assertStringContainsString( '1 AS replace_object_valid', $sql );
		$this->assertStringContainsString( '1 AS substring_array_valid', $sql );
		$this->assertStringContainsString( '1 AS ifnull_object_valid', $sql );
		$this->assertStringContainsString( 'NULL AS concat_null_valid', $sql );
		$this->assertStringContainsString( 'NULL AS nullif_null_valid', $sql );
		$this->assertStringContainsString( '0 AS invalid_json', $sql );
		$this->assertStringContainsString( 'NULL AS null_valid', $sql );
		$this->assertStringContainsString( 'CASE WHEN payload IS NULL THEN NULL ELSE json_valid(CAST(payload AS text)) END AS payload_valid', $sql );
		$this->assertStringNotContainsString( '__wp_pg_mysql_json_valid', $sql );
		$this->assertStringNotContainsString( 'JSON_VALID', $sql );
		$this->assertStringNotContainsString( 'pg_input_is_valid', $sql );
	}

	/**
	 * Tests JSON_VALID() runtime execution preserves MySQL NULL/0/1 semantics.
	 */
	public function test_json_valid_runtime_function_executes_with_mysql_semantics(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_json_valid_runtime (id INTEGER PRIMARY KEY, payload TEXT)' );
		$driver->query( "INSERT INTO wptests_json_valid_runtime (id, payload) VALUES (1, '{\"ok\":true}'), (2, 'not json'), (3, NULL), (4, 'null')" );

		$rows = $driver->query( 'SELECT id, JSON_VALID(payload) AS payload_valid FROM wptests_json_valid_runtime ORDER BY id' );

		$this->assertSame(
			array(
				array( '1', '1' ),
				array( '2', '0' ),
				array( '3', null ),
				array( '4', '1' ),
			),
			array_map(
				static function ( $row ): array {
					return array( $row->id, $row->payload_valid );
				},
				$rows
			)
		);

		$literal_result = $driver->query(
			'SELECT JSON_VALID(\'{"ok":true}\') AS object_valid,
				JSON_VALID(\'[1,2]\') AS array_valid,
				JSON_VALID(\'not json\') AS invalid_json,
				JSON_VALID(NULL) AS null_json,
				JSON_VALID(\'null\') AS null_literal_valid,
				JSON_VALID(123) AS number_valid'
		);

		$this->assertCount( 1, $literal_result );
		$this->assertSame( '1', $literal_result[0]->object_valid );
		$this->assertSame( '1', $literal_result[0]->array_valid );
		$this->assertSame( '0', $literal_result[0]->invalid_json );
		$this->assertNull( $literal_result[0]->null_json );
		$this->assertSame( '1', $literal_result[0]->null_literal_valid );
		$this->assertSame( '1', $literal_result[0]->number_valid );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( '1 AS object_valid', $sql );
		$this->assertStringContainsString( '1 AS array_valid', $sql );
		$this->assertStringContainsString( '0 AS invalid_json', $sql );
		$this->assertStringContainsString( 'NULL AS null_json', $sql );
		$this->assertStringContainsString( '1 AS null_literal_valid', $sql );
		$this->assertStringContainsString( '1 AS number_valid', $sql );
		$this->assertStringNotContainsString( '__wp_pg_mysql_json_valid', $sql );
		$this->assertStringNotContainsString( 'JSON_VALID', $sql );
		$this->assertStringNotContainsString( 'pg_input_is_valid', $sql );
	}

	/**
	 * Tests common MySQL runtime functions trigger rewrite without literal arguments.
	 */
	public function test_common_mysql_runtime_functions_with_column_arguments_trigger_postgresql_rewrite(): void {
		$driver = $this->create_driver();

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT IFNULL(primary_value, fallback_value) AS selected_value, NULLIF(primary_value, fallback_value) AS nullif_value, CONCAT(prefix, suffix) AS joined_value, CONCAT_WS('-', prefix, NULL, suffix) AS joined_ws_value, CHAR_LENGTH(display_name) AS name_length, LENGTH(display_name) AS byte_length FROM runtime_names"
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( 'COALESCE(primary_value, fallback_value) AS selected_value', $sql );
		$this->assertStringContainsString( 'NULLIF(primary_value, fallback_value) AS nullif_value', $sql );
		$this->assertStringContainsString( '(CAST(prefix AS text) || CAST(suffix AS text)) AS joined_value', $sql );
		$this->assertStringContainsString( "CASE WHEN '-' IS NULL THEN NULL ELSE", $sql );
		$this->assertStringContainsString( "COALESCE(CAST(prefix AS text), '')", $sql );
		$this->assertStringContainsString( "COALESCE(CAST(suffix AS text), '')", $sql );
		$this->assertStringContainsString( 'END AS joined_ws_value', $sql );
		$this->assertStringContainsString( 'CHAR_LENGTH(CAST(display_name AS text)) AS name_length', $sql );
		$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST(display_name AS text), 'UTF8')) END AS byte_length", $sql );
		$this->assertStringNotContainsString( 'IFNULL', $sql );
		$this->assertStringNotContainsString( 'CONCAT(', $sql );
		$this->assertStringNotContainsString( 'CONCAT_WS', $sql );
	}

	/**
	 * Tests MySQL CONCAT_WS() skips NULL values while preserving empty strings.
	 */
	public function test_concat_ws_runtime_function_executes_mysql_null_semantics(): void {
		$driver = $this->create_driver();

		$rows = $driver->query(
			"SELECT
				CONCAT_WS('-', 'wp', NULL, 'db') AS skipped_null,
				CONCAT_WS(',', '', NULL, 'tail') AS empty_string_kept,
				CONCAT_WS(NULL, 'a', 'b') AS null_separator,
				CONCAT_WS('|', NULL, NULL) AS all_values_null"
		);

		$this->assertCount( 1, $rows );
		$this->assertSame( 'wp-db', $rows[0]->skipped_null );
		$this->assertSame( ',tail', $rows[0]->empty_string_kept );
		$this->assertNull( $rows[0]->null_separator );
		$this->assertSame( '', $rows[0]->all_values_null );

		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringNotContainsString( 'CONCAT_WS', $sql );
	}

	/**
