	/**
	 * Tests WordPress postmeta key lookups with HAVING but no GROUP BY match SQLite parity.
	 */
	public function test_wordpress_postmeta_distinct_meta_key_having_without_group_by_is_rewritten(): void {
		$driver = $this->create_driver();
		$driver->query(
			'CREATE TABLE wptests_postmeta (
				meta_id INTEGER PRIMARY KEY,
				meta_key TEXT NOT NULL
			)'
		);
		$driver->query(
			"INSERT INTO wptests_postmeta (meta_id, meta_key) VALUES
				(1, '_hidden'),
				(2, 'visible_meta_key_03'),
				(3, 'visible_meta_key_01'),
				(4, 'visible_meta_key_02'),
				(5, 'visible_meta_key_02')"
		);

		$queries = array(
			"SELECT DISTINCT meta_key FROM wptests_postmeta WHERE meta_key NOT BETWEEN '_' AND '_z' HAVING meta_key NOT LIKE '\\_%' ORDER BY meta_key LIMIT 3",
			"SELECT DISTINCT meta_key FROM wptests_postmeta WHERE meta_key NOT BETWEEN '_' AND '_z' HAVING meta_key NOT LIKE CONCAT('\\_', '%') ORDER BY meta_key LIMIT 3",
		);

		foreach ( $queries as $query ) {
			$rows = $driver->query( $query );

			$this->assertSame(
				array( 'visible_meta_key_01', 'visible_meta_key_02', 'visible_meta_key_03' ),
				array_map(
					static function ( $row ): string {
						return $row->meta_key;
					},
					$rows
				),
				$query
			);

			$sql = $this->get_last_single_postgresql_sql( $driver );
			$this->assertStringContainsString( 'SELECT DISTINCT meta_key FROM wptests_postmeta WHERE (meta_key NOT BETWEEN', $sql, $query );
			$this->assertStringContainsString( ') AND (meta_key NOT LIKE', $sql, $query );
			$this->assertStringContainsString( 'ORDER BY meta_key LIMIT 3', $sql, $query );
			$this->assertStringNotContainsString( ' HAVING ', $sql, $query );
			$this->assertStringNotContainsString( 'CONCAT(', $sql, $query );
		}
	}

	/**
	 * Tests WordPress term and post-search predicates preserve MySQL case-insensitive collation behavior.
	 */
	public function test_wordpress_term_and_post_search_text_predicates_use_case_insensitive_mysql_collation_metadata(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE wptests_posts (
				`ID` bigint(20) unsigned NOT NULL,
				`post_title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT "",
				`post_excerpt` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
				`post_content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
				PRIMARY KEY (`ID`)
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_terms (
				`term_id` bigint(20) unsigned NOT NULL,
				`name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT "",
				`slug` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT "",
				PRIMARY KEY (`term_id`)
			)'
		);
		$driver->query(
			'CREATE TABLE wptests_term_taxonomy (
				`term_taxonomy_id` bigint(20) unsigned NOT NULL,
				`term_id` bigint(20) unsigned NOT NULL,
				`taxonomy` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT "",
				`description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
				PRIMARY KEY (`term_taxonomy_id`)
			)'
		);
		$driver->query(
			"INSERT INTO wptests_posts (`ID`, `post_title`, `post_excerpt`, `post_content`) VALUES (7, 'Search & Test', '', 'Body')"
		);
		$driver->query( "INSERT INTO wptests_terms (`term_id`, `name`, `slug`) VALUES (1, 'burrito', 'burrito')" );
		$driver->query( "INSERT INTO wptests_terms (`term_id`, `name`, `slug`) VALUES (2, 'taco', 'taco')" );
		$driver->query(
			"INSERT INTO wptests_term_taxonomy (`term_taxonomy_id`, `term_id`, `taxonomy`, `description`) VALUES (10, 1, 'post_tag', 'This is a burrito.')"
		);
		$driver->query(
			"INSERT INTO wptests_term_taxonomy (`term_taxonomy_id`, `term_id`, `taxonomy`, `description`) VALUES (20, 2, 'post_tag', 'Burning man.')"
		);

		$post_rows = $driver->query(
			"SELECT ID
			FROM wptests_posts
			WHERE wptests_posts.post_title LIKE '%test%'"
		);

		$this->assertSame(
			array( '7' ),
			array_map(
				static function ( $row ): string {
					return $row->ID;
				},
				$post_rows
			)
		);
		$this->assertStringContainsString(
			"LOWER(wptests_posts.post_title) LIKE LOWER('%test%')",
			$driver->get_last_postgresql_queries()[0]['sql']
		);

		$name_rows = $driver->query(
			"SELECT t.term_id
			FROM wptests_terms AS t INNER JOIN wptests_term_taxonomy AS tt ON t.term_id = tt.term_id
			WHERE tt.taxonomy = 'post_tag' AND t.name = 'BURRITO'"
		);

		$this->assertSame(
			array( '1' ),
			array_map(
				static function ( $row ): string {
					return $row->term_id;
				},
				$name_rows
			)
		);
		$this->assertStringContainsString(
			"LOWER(t.name) = LOWER('BURRITO')",
			$driver->get_last_postgresql_queries()[0]['sql']
		);

		$name_in_rows = $driver->query(
			"SELECT t.term_id
			FROM wptests_terms AS t INNER JOIN wptests_term_taxonomy AS tt ON t.term_id = tt.term_id
			WHERE tt.taxonomy = 'post_tag' AND t.name IN ('BURRITO')"
		);

		$this->assertSame(
			array( '1' ),
			array_map(
				static function ( $row ): string {
					return $row->term_id;
				},
				$name_in_rows
			)
		);
		$this->assertStringContainsString(
			"LOWER(t.name) IN (LOWER('BURRITO'))",
			$driver->get_last_postgresql_queries()[0]['sql']
		);

		$description_rows = $driver->query(
			"SELECT t.term_id
			FROM wptests_terms AS t INNER JOIN wptests_term_taxonomy AS tt ON t.term_id = tt.term_id
			WHERE tt.taxonomy IN ('post_tag') AND tt.description LIKE '%Bur%'
			ORDER BY t.term_id ASC"
		);

		$this->assertSame(
			array( '1', '2' ),
			array_map(
				static function ( $row ): string {
					return $row->term_id;
				},
				$description_rows
			)
		);
		$this->assertStringContainsString(
			"LOWER(tt.description) LIKE LOWER('%Bur%')",
			$driver->get_last_postgresql_queries()[0]['sql']
		);
	}

