	/**
	 * Tests RAND() and literal RAND(seed) are translated for PostgreSQL.
	 */
	public function test_rand_functions_are_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE wptests_links (link_id INTEGER PRIMARY KEY)' );
		$driver->query( 'INSERT INTO wptests_links (link_id) VALUES (1)' );
		$driver->query( 'INSERT INTO wptests_links (link_id) VALUES (2)' );

		$rows = $driver->query( 'SELECT link_id FROM wptests_links ORDER BY RAND(7) LIMIT 1' );

		$this->assertCount( 1, $rows );
		$this->assertSame(
			array(
				array(
					'sql'    => 'SELECT link_id FROM wptests_links ORDER BY CAST(0.90650219368422613 AS double precision) LIMIT 1',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$rows = $driver->query(
			"SELECT RAND(0) AS r0,
				RAND(1) AS r1,
				RAND(5) AS r5,
				RAND(NULL) AS rnull,
				RAND(3.9) AS rfloat,
				RAND('5') AS rstring,
				RAND('abc') AS rbadstring"
		);
		$this->assertEqualsWithDelta( 0.15522042769493574, (float) $rows[0]->r0, 1e-12 );
		$this->assertEqualsWithDelta( 0.40540353712197724, (float) $rows[0]->r1, 1e-12 );
		$this->assertEqualsWithDelta( 0.40613597483014313, (float) $rows[0]->r5, 1e-12 );
		$this->assertEqualsWithDelta( 0.15522042769493574, (float) $rows[0]->rnull, 1e-12 );
		$this->assertEqualsWithDelta( 0.15595286540310166, (float) $rows[0]->rfloat, 1e-12 );
		$this->assertEqualsWithDelta( 0.40613597483014313, (float) $rows[0]->rstring, 1e-12 );
		$this->assertEqualsWithDelta( 0.15522042769493574, (float) $rows[0]->rbadstring, 1e-12 );
		$this->assertSame(
			'SELECT CAST(0.15522042769493574 AS double precision) AS r0, CAST(0.40540353712197724 AS double precision) AS r1, CAST(0.40613597483014313 AS double precision) AS r5, CAST(0.15522042769493574 AS double precision) AS rnull, CAST(0.15595286540310166 AS double precision) AS rfloat, CAST(0.40613597483014313 AS double precision) AS rstring, CAST(0.15522042769493574 AS double precision) AS rbadstring',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query( 'SELECT rand() AS random_value, RAND(link_id) AS seeded_value FROM wptests_links WHERE link_id = 1' );
		$this->assertEqualsWithDelta( 0.40540353712197724, (float) $rows[0]->seeded_value, 1e-12 );
		$this->assertStringContainsString( 'random() AS random_value', $this->get_last_single_postgresql_sql( $driver ) );
		$this->assertStringContainsString( '"__wp_pg_mysql_rand_seed"."seed" * 65537 + 55555555', $this->get_last_single_postgresql_sql( $driver ) );
		$this->assertStringContainsString( 'AS seeded_value', $this->get_last_single_postgresql_sql( $driver ) );
		$this->assertStringNotContainsString( 'random() AS seeded_value', $this->get_last_single_postgresql_sql( $driver ) );
	}

	/**
	 * Tests MySQL SELECT row-locking clauses are stripped before PostgreSQL execution.
	 */
	public function test_select_row_locking_clauses_are_supported_noops(): void {
		$queries = array(
			"SELECT value FROM wptests_locking WHERE name = 'test_lock' FOR UPDATE",
			"SELECT value FROM wptests_locking WHERE name = 'test_lock' FOR SHARE",
			"SELECT value FROM wptests_locking WHERE name = 'test_lock' LOCK IN SHARE MODE",
			"SELECT value FROM wptests_locking WHERE name = 'test_lock' FOR UPDATE SKIP LOCKED",
			"SELECT value FROM wptests_locking WHERE name = 'test_lock' FOR UPDATE NOWAIT",
			"SELECT value FROM wptests_locking WHERE name = 'test_lock' FOR SHARE OF wptests_locking NOWAIT",
		);

		foreach ( $queries as $query ) {
			$driver = $this->create_driver();
			$driver->query( 'CREATE TABLE wptests_locking (name VARCHAR(255), value VARCHAR(255))' );
			$driver->query( "INSERT INTO wptests_locking (name, value) VALUES ('test_lock', '123')" );

			$rows = $driver->query( $query );

			$this->assertSame( '123', $rows[0]->value, $query );
			$this->assertSame(
				array(
					array(
						'sql'    => 'SELECT value FROM wptests_locking WHERE name = \'test_lock\'',
						'params' => array(),
					),
				),
				$driver->get_last_postgresql_queries(),
				$query
			);
		}
	}

