	/**
	 * Tests MySQL date/time extraction functions are translated for PostgreSQL.
	 */
	public function test_mysql_date_time_extract_functions_are_translated_to_postgresql(): void {
		$driver = $this->create_driver();

		$select = 'SELECT YEAR(post_date) AS y, MONTH(post_date) AS m, QUARTER(post_date) AS q, DAYOFYEAR(post_date) AS doy, DAYOFMONTH(post_date) AS d, DAY(post_date) AS day_value, HOUR(post_date) AS h, MINUTE(post_date) AS i, SECOND(post_date) AS s, MICROSECOND(post_date) AS us, EXTRACT(DAY FROM post_date) AS extracted_day, EXTRACT(QUARTER FROM post_date) AS extracted_quarter, EXTRACT(DAYOFYEAR FROM post_date) AS extracted_doy, EXTRACT(MICROSECOND FROM post_date) AS extracted_us FROM wptests_posts WHERE ID = 1';
		$sql    = $this->translate_driver_query_with_private_method( $driver, 'translate_mysql_compatible_query', $select );

		$this->assertSame(
			'SELECT ' . $this->get_expected_zero_date_safe_extract_sql( 'YEAR', 'post_date' ) . ' AS y, ' . $this->get_expected_zero_date_safe_extract_sql( 'MONTH', 'post_date' ) . ' AS m, ' . $this->get_expected_zero_date_safe_extract_sql( 'QUARTER', 'post_date' ) . ' AS q, ' . $this->get_expected_zero_date_safe_extract_sql( 'DOY', 'post_date' ) . ' AS doy, ' . $this->get_expected_zero_date_safe_extract_sql( 'DAY', 'post_date' ) . ' AS d, ' . $this->get_expected_zero_date_safe_extract_sql( 'DAY', 'post_date' ) . ' AS day_value, ' . $this->get_expected_zero_date_safe_extract_sql( 'HOUR', 'post_date' ) . ' AS h, ' . $this->get_expected_zero_date_safe_extract_sql( 'MINUTE', 'post_date' ) . ' AS i, ' . $this->get_expected_zero_date_safe_extract_sql( 'SECOND', 'post_date' ) . ' AS s, ' . $this->get_expected_zero_date_safe_extract_sql( 'MICROSECOND', 'post_date' ) . ' AS us, ' . $this->get_expected_zero_date_safe_extract_sql( 'DAY', 'post_date' ) . ' AS extracted_day, ' . $this->get_expected_zero_date_safe_extract_sql( 'QUARTER', 'post_date' ) . ' AS extracted_quarter, ' . $this->get_expected_zero_date_safe_extract_sql( 'DOY', 'post_date' ) . ' AS extracted_doy, ' . $this->get_expected_zero_date_safe_extract_sql( 'MICROSECOND', 'post_date' ) . ' AS extracted_us FROM wptests_posts WHERE "ID" = 1',
			$sql
		);
	}

	/**
	 * Tests generated date/time extraction SQL is safe for MySQL zero-date values.
	 */
	public function test_mysql_date_time_extract_functions_are_zero_date_safe_for_postgresql(): void {
		$driver = $this->create_driver();

		$select = 'SELECT YEAR(post_date) AS y, MONTH(post_date) AS m, DAYOFMONTH(post_date) AS d, HOUR(post_date) AS h, MICROSECOND(post_date) AS us FROM wptests_posts WHERE post_date = \'0000-00-00 00:00:00.123456\'';
		$sql    = $this->translate_driver_query_with_private_method( $driver, 'translate_mysql_compatible_query', $select );

		$this->assertStringContainsString( "CASE WHEN CAST(post_date AS text) = '' THEN NULL WHEN CAST(post_date AS text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}'", $sql );
		$this->assertStringContainsString( "SUBSTRING(CAST(post_date AS text) FROM 1 FOR 4) = '0000'", $sql );
		$this->assertStringContainsString( "SUBSTRING(CAST(post_date AS text) FROM 6 FOR 2) = '00'", $sql );
		$this->assertStringContainsString( "SUBSTRING(CAST(post_date AS text) FROM 9 FOR 2) = '00'", $sql );
		$this->assertStringContainsString( 'THEN CAST(SUBSTRING(CAST(post_date AS text) FROM 1 FOR 4) AS integer)', $sql );
		$this->assertStringContainsString( 'THEN CAST(SUBSTRING(CAST(post_date AS text) FROM 6 FOR 2) AS integer)', $sql );
		$this->assertStringContainsString( 'THEN CAST(SUBSTRING(CAST(post_date AS text) FROM 9 FOR 2) AS integer)', $sql );
		$this->assertStringContainsString( "THEN CASE WHEN CAST(post_date AS text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}' THEN CAST(SUBSTRING(CAST(post_date AS text) FROM 12 FOR 2) AS integer) ELSE 0 END", $sql );
		$this->assertStringContainsString( "THEN CAST(CASE WHEN CAST(post_date AS text) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}[ T][0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]+' THEN LEFT(RPAD(SUBSTRING(CAST(post_date AS text) FROM '[.]([0-9]+)'), 6, '0'), 6) ELSE '000000' END AS integer)", $sql );
		$this->assertStringNotContainsString( 'SELECT CAST(EXTRACT(YEAR FROM CAST(post_date AS timestamp)) AS integer) AS y', $sql );
		$this->assertStringContainsString( 'CAST(EXTRACT(YEAR FROM CAST(CASE WHEN CAST(post_date AS text)', $sql );
		$this->assertStringContainsString( 'THEN NULL ELSE CAST(post_date AS text) END AS timestamp)', $sql );
	}

	/**
	 * Tests stored empty temporal values are safe for MySQL-compatible date functions.
	 */
	public function test_stored_empty_temporal_values_are_safe_for_mysql_date_functions(): void {
		$driver = $this->create_driver();
		$driver->query(
			'CREATE TABLE wp_acid_dates (
				id int(11) NOT NULL,
				note varchar(20) NOT NULL,
				d date DEFAULT NULL,
				dt datetime DEFAULT NULL,
				PRIMARY KEY (id)
			)'
		);
		$driver->get_connection()->query(
			"INSERT INTO wp_acid_dates (id, note, d, dt) VALUES
				(1, 'empty', '', ''),
				(2, 'zero', '0000-00-00', '0000-00-00 00:00:00'),
				(3, 'partial', '2020-00-15', '2020-00-15 13:04:05'),
				(4, 'valid', '2024-05-06', '2024-05-06 07:08:09')"
		);

		$select = "SELECT note, d, dt, DATE_FORMAT(d, '%Y-%m-%d') AS formatted, YEAR(d) AS y, MONTH(d) AS m, DAYOFMONTH(d) AS day
			FROM wp_acid_dates
			ORDER BY id";
		$sql    = $this->translate_driver_query_with_private_method( $driver, 'translate_mysql_compatible_query', $select );

		$this->assertNotNull( $sql );
		$d_text_sql              = 'CAST(d AS text)';
		$empty_temporal_sql      = $this->get_expected_empty_temporal_condition_sql( $d_text_sql );
		$zero_date_condition_sql = $this->get_expected_zero_date_condition_sql( $d_text_sql );

		$this->assertStringContainsString(
			sprintf(
				"CASE WHEN %1\$s THEN NULL WHEN %2\$s THEN SUBSTRING(%3\$s FROM 1 FOR 10) ELSE TO_CHAR(%4\$s, 'YYYY-MM-DD') END AS formatted",
				$empty_temporal_sql,
				$zero_date_condition_sql,
				$d_text_sql,
				$this->get_expected_zero_date_safe_timestamp_sql( 'd' )
			),
			$sql
		);
		$this->assertStringContainsString( $this->get_expected_zero_date_safe_extract_sql( 'YEAR', 'd' ) . ' AS y', $sql );
		$this->assertStringContainsString( $this->get_expected_zero_date_safe_extract_sql( 'MONTH', 'd' ) . ' AS m', $sql );
		$this->assertStringContainsString( $this->get_expected_zero_date_safe_extract_sql( 'DAY', 'd' ) . ' AS day', $sql );
		$this->assertStringContainsString(
			sprintf( 'CAST(CASE WHEN %1$s OR %2$s THEN NULL ELSE %3$s END AS timestamp)', $empty_temporal_sql, $zero_date_condition_sql, $d_text_sql ),
			$sql
		);
		$this->assertStringNotContainsString(
			sprintf( 'CAST(CASE WHEN %1$s THEN NULL ELSE %2$s END AS timestamp)', $zero_date_condition_sql, $d_text_sql ),
			$sql
		);
	}

	/**
	 * Tests MySQL temporal expressions compare safely against text-backed datetime columns.
	 */
	public function test_mysql_temporal_expression_comparisons_against_text_backed_datetime_columns_use_text_ordering_for_postgresql(): void {
		$driver = $this->create_driver();
		$driver->query(
			'CREATE TABLE wp_acid_dates (
				id int(11) NOT NULL,
				note varchar(20) NOT NULL,
				d date DEFAULT NULL,
				dt datetime DEFAULT NULL,
				PRIMARY KEY (id)
			)'
		);
		$driver->get_connection()->query(
			"INSERT INTO wp_acid_dates (id, note, d, dt) VALUES
				(1, 'empty', '', ''),
				(2, 'zero', '0000-00-00', '0000-00-00 00:00:00'),
				(3, 'partial', '2020-00-15', '2020-00-15 13:04:05'),
				(4, 'old', '2001-01-01', '2001-01-01 00:00:00'),
				(5, 'future', '2999-01-01', '2999-01-01 00:00:00')"
		);

		$now_sql           = "TO_CHAR(CURRENT_TIMESTAMP AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS')";
		$date_sub_sql      = $this->get_expected_date_arithmetic_sql( '-', $now_sql, '7', 'day' );
		$threshold_sql     = $this->get_expected_temporal_expression_comparison_text_sql( $date_sub_sql, true );
		$datetime_text_sql = 'CAST(dt AS text)';

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT COUNT(*) AS old_rows FROM wp_acid_dates WHERE DATE_SUB(NOW(), INTERVAL 7 DAY) > dt'
		);

		$this->assertNotNull( $sql );
		$this->assertStringContainsString( $threshold_sql . ' > ' . $datetime_text_sql, $sql );
		$this->assertStringNotContainsString( ') > dt', $sql );
		$this->assertStringNotContainsString( 'CAST(dt AS timestamp)', $sql );

		$reversed_sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			'SELECT COUNT(*) AS old_rows FROM wp_acid_dates WHERE dt < DATE_SUB(NOW(), INTERVAL 7 DAY)'
		);

		$this->assertNotNull( $reversed_sql );
		$this->assertStringContainsString( $datetime_text_sql . ' < ' . $threshold_sql, $reversed_sql );
		$this->assertStringNotContainsString( 'dt < (', $reversed_sql );
		$this->assertStringNotContainsString( 'CAST(dt AS timestamp)', $reversed_sql );
	}

	/**
	 * Tests literal MySQL zero-date extraction SQL guards the timestamp cast.
	 */
	public function test_mysql_date_time_extract_functions_guard_literal_zero_dates_for_postgresql(): void {
		$driver = $this->create_driver();

		$literals          = array(
			'0000-00-00 00:00:00',
			'0000-00-00',
			'2020-00-15 00:00:00',
			'2020-01-00 00:00:00',
			'2026-06-10 14:08:09',
		);
		$extract_functions = array(
			array(
				'name' => 'YEAR',
				'unit' => 'YEAR',
			),
			array(
				'name' => 'MONTH',
				'unit' => 'MONTH',
			),
			array(
				'name' => 'QUARTER',
				'unit' => 'QUARTER',
			),
			array(
				'name' => 'DAYOFYEAR',
				'unit' => 'DOY',
			),
			array(
				'name' => 'DAYOFMONTH',
				'unit' => 'DAY',
			),
			array(
				'name' => 'DAY',
				'unit' => 'DAY',
			),
			array(
				'name' => 'HOUR',
				'unit' => 'HOUR',
			),
			array(
				'name' => 'MINUTE',
				'unit' => 'MINUTE',
			),
			array(
				'name' => 'SECOND',
				'unit' => 'SECOND',
			),
			array(
				'name' => 'MICROSECOND',
				'unit' => 'MICROSECOND',
			),
		);

		foreach ( $literals as $literal ) {
			$expression_sql      = "'" . $literal . "'";
			$expression_text_sql = sprintf( 'CAST(%s AS text)', $expression_sql );

			foreach ( $extract_functions as $extract_function ) {
				$function_sql = sprintf( '%s(%s)', $extract_function['name'], $expression_sql );
				$sql          = $this->translate_driver_query_with_private_method(
					$driver,
					'translate_mysql_compatible_query',
					'SELECT ' . $function_sql . ' AS extracted_value'
				);
				$expected_sql = 'SELECT ' . $this->get_expected_zero_date_safe_extract_sql( $extract_function['unit'], $expression_sql ) . ' AS extracted_value';

				$this->assertSame(
					$expected_sql,
					$sql,
					$function_sql
				);
				if ( 'MICROSECOND' === $extract_function['unit'] ) {
					$this->assertStringContainsString(
						"CAST(TO_CHAR(CAST(CASE WHEN {$expression_text_sql}",
						$sql,
						$function_sql
					);
				} else {
					$this->assertStringContainsString(
						'CAST(EXTRACT(' . $extract_function['unit'] . ' FROM CAST(CASE WHEN ' . $expression_text_sql,
						$sql,
						$function_sql
					);
				}
				$this->assertStringContainsString(
					'THEN NULL ELSE ' . $expression_text_sql . ' END AS timestamp)',
					$sql,
					$function_sql
				);
				if ( 'MICROSECOND' !== $extract_function['unit'] ) {
					$this->assertStringNotContainsString(
						'CAST(EXTRACT(' . $extract_function['unit'] . ' FROM CAST(' . $expression_sql . ' AS timestamp))',
						$sql,
						$function_sql
					);
				}
			}
		}

		$sql = $this->translate_driver_query_with_private_method(
			$driver,
			'translate_mysql_compatible_query',
			"SELECT EXTRACT(DAY FROM '2020-01-00 00:00:00') AS extracted_value"
		);

		$this->assertSame(
			'SELECT ' . $this->get_expected_zero_date_safe_extract_sql( 'DAY', "'2020-01-00 00:00:00'" ) . ' AS extracted_value',
			$sql
		);
	}

	/**
	 * Tests unsupported MySQL EXTRACT units fail closed instead of passing through PostgreSQL semantics.
	 */
	public function test_mysql_extract_unsupported_units_fail_closed_for_postgresql(): void {
		$driver  = $this->create_driver();
		$queries = array(
			'SELECT EXTRACT(WEEK FROM post_date) AS extracted_value'       => 'EXTRACT(WEEK',
			'SELECT EXTRACT(YEAR_MONTH FROM post_date) AS extracted_value' => 'EXTRACT(YEAR_MONTH',
			'SELECT EXTRACT(DAY_HOUR FROM post_date) AS extracted_value'   => 'EXTRACT(DAY_HOUR',
			'SELECT EXTRACT(DAY_SECOND FROM post_date) AS extracted_value' => 'EXTRACT(DAY_SECOND',
		);

		foreach ( $queries as $query => $raw_extract_sql ) {
			$sql = $this->translate_driver_query_with_private_method(
				$driver,
				'translate_mysql_compatible_query',
				$query
			);

			$this->assertTrue( null === $sql || false === strpos( $sql, $raw_extract_sql ), $query );
			$this->assertNull( $sql, $query );
		}
	}

	/**
	 * Tests unsupported MySQL EXTRACT units are rejected before backend execution.
	 */
	public function test_mysql_extract_unsupported_units_fail_closed_before_backend_execution(): void {
		$queries = array(
			'SELECT EXTRACT(WEEK FROM post_date) AS extracted_value',
			'SELECT EXTRACT(YEAR_MONTH FROM post_date) AS extracted_value',
			'SELECT EXTRACT(DAY_HOUR FROM post_date) AS extracted_value',
			'SELECT EXTRACT(DAY_SECOND FROM post_date) AS extracted_value',
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported EXTRACT() unit to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported MySQL runtime function form.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

