	/**
	 * Tests composite interval literals with overlong microseconds fail closed.
	 */
	public function test_mysql_date_arithmetic_rejects_overlong_composite_interval_microseconds_for_postgresql(): void {
		$driver  = $this->create_driver();
		$queries = array(
			"SELECT DATE_ADD(post_date_gmt, INTERVAL '1.1234567' SECOND_MICROSECOND) AS shifted",
			"SELECT DATE_ADD(post_date_gmt, INTERVAL '1 02:03:04.1234567' DAY_MICROSECOND) AS shifted",
			"SELECT DATE_SUB(post_date_gmt, INTERVAL '1 02:03:04.1234567' DAY_MICROSECOND) AS shifted",
			"SELECT TIMESTAMPADD(SECOND_MICROSECOND, '1.1234567', post_date_gmt) AS shifted",
			"SELECT TIMESTAMPADD(DAY_MICROSECOND, '1 02:03:04.1234567', post_date_gmt) AS shifted",
		);

		foreach ( $queries as $query ) {
			$sql = $this->translate_driver_query_with_private_method(
				$driver,
				'translate_mysql_compatible_query',
				$query
			);

			$this->assertTrue( null === $sql || false === strpos( $sql, "CAST('1234567' AS double precision) * INTERVAL '1 microsecond'" ), $query );
			$this->assertNull( $sql, $query );
		}
	}

	/**
	 * Tests overlong composite interval microseconds fail before backend execution.
	 */
	public function test_mysql_date_arithmetic_overlong_composite_interval_microseconds_fail_closed_before_backend_execution(): void {
		$queries = array(
			"SELECT DATE_ADD(post_date_gmt, INTERVAL '1.1234567' SECOND_MICROSECOND) AS shifted",
			"SELECT DATE_ADD(post_date_gmt, INTERVAL '1 02:03:04.1234567' DAY_MICROSECOND) AS shifted",
			"SELECT DATE_SUB(post_date_gmt, INTERVAL '1 02:03:04.1234567' DAY_MICROSECOND) AS shifted",
			"SELECT TIMESTAMPADD(SECOND_MICROSECOND, '1.1234567', post_date_gmt) AS shifted",
			"SELECT TIMESTAMPADD(DAY_MICROSECOND, '1 02:03:04.1234567', post_date_gmt) AS shifted",
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected overlong composite interval microseconds to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported MySQL date arithmetic statement.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

