			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ON DUPLICATE KEY UPDATE statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests real PostgreSQL dbDelta identity CHANGE COLUMN uses catalogs.
	 */
	public function test_real_pgsql_dbdelta_change_column_identity_uses_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL dbDelta identity catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task917_identity' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver         = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$preserve_table = 'task917_identity_' . $suffix . '_preserve';
		$drop_table     = 'task917_identity_' . $suffix . '_drop';
		$backend_sql    = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`legacy_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							PRIMARY KEY (`legacy_id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$preserve_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE dbDelta identity preserve table',
				$backend_sql
			);

			$preserve_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s` CHANGE COLUMN `legacy_id` `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT',
						$preserve_table
					)
				)
			);
			$preserve_sql = implode( "\n", array_slice( $logged_sql, $preserve_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'CHANGE COLUMN preserves existing identity',
				$backend_sql
			);
			$this->assertStringContainsString( 'FROM information_schema.columns c', $preserve_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_get_serial_sequence', $preserve_sql );
			$this->assertStringContainsString( 'ALTER TABLE "' . $preserve_table . '" RENAME COLUMN "legacy_id" TO "id"', $preserve_sql );
			$this->assertStringNotContainsString( 'ADD GENERATED BY DEFAULT AS IDENTITY', $preserve_sql );
			$this->assertStringNotContainsString( 'DROP IDENTITY IF EXISTS', $preserve_sql );

			$preserve_columns = $driver->query( 'SHOW COLUMNS FROM `' . $preserve_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS after identity preserve CHANGE COLUMN',
				$backend_sql
			);
			$id_column = $this->find_row_by_value( $preserve_columns, 'Field', 'id' );
			$this->assertSame( 'auto_increment', $this->get_row_value( $id_column, 'Extra' ) );

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`slug`) VALUES ('generated')", $preserve_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'generated insert after identity preserve CHANGE COLUMN',
				$backend_sql
			);
			$generated_rows = $driver->query( 'SELECT `id`, `slug` FROM `' . $preserve_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read generated identity row after preserve',
				$backend_sql
			);
			$this->assertCount( 1, $generated_rows );
			$this->assertSame( '1', (string) $this->get_row_value( $generated_rows[0], 'id' ) );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$drop_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE dbDelta identity drop table',
				$backend_sql
			);

			$drop_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query( sprintf( 'ALTER TABLE `%s` CHANGE COLUMN `id` `id` int NOT NULL', $drop_table ) )
			);
			$drop_sql = implode( "\n", array_slice( $logged_sql, $drop_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'CHANGE COLUMN drops removed AUTO_INCREMENT identity',
				$backend_sql
			);
			$this->assertStringContainsString( 'FROM information_schema.columns c', $drop_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_get_serial_sequence', $drop_sql );
			$this->assertStringContainsString( 'ALTER TABLE "' . $drop_table . '" ALTER COLUMN "id" DROP IDENTITY IF EXISTS', $drop_sql );
			$this->assertStringContainsString( 'ALTER TABLE "' . $drop_table . '" ALTER COLUMN "id" DROP DEFAULT', $drop_sql );

			$drop_columns = $driver->query( 'SHOW COLUMNS FROM `' . $drop_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS after identity drop CHANGE COLUMN',
				$backend_sql
			);
			$plain_id_column = $this->find_row_by_value( $drop_columns, 'Field', 'id' );
			$this->assertSame( '', $this->get_row_value( $plain_id_column, 'Extra' ) );

			$identity_state = $pdo->prepare(
				"SELECT is_identity, column_default
				FROM information_schema.columns
				WHERE table_schema = 'public'
					AND table_name = ?
					AND column_name = 'id'"
			);
			$identity_state->execute( array( $drop_table ) );
			$identity_row = $identity_state->fetch( PDO::FETCH_ASSOC );
			$this->assertSame( 'NO', $identity_row['is_identity'] );
			$this->assertNull( $identity_row['column_default'] );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task917_identity' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task917_identity' ) );
		}
	}

