		$this->assertNull( $columns[1]['collation'] );
	}

	/**
	 * Tests ALTER TABLE ADD accepts MySQL data type aliases.
	 */
	public function test_alter_table_add_accepts_mysql_data_type_aliases(): void {
		$driver      = $this->create_driver();
		$translation = $this->translate_driver_query_data_with_private_method(
			$driver,
			'translate_mysql_dbdelta_alter_table_query',
			'ALTER TABLE wptests_alias_alter
				ADD flags BIT(10),
				ADD enabled BOOL NOT NULL DEFAULT 0,
				ADD toggled BOOLEAN,
				ADD amount DEC(10,2),
				ADD fixed_value FIXED(8,3),
				ADD real_value REAL,
				ADD payload JSON DEFAULT NULL,
				ADD notes LONG VARCHAR,
				ADD raw_data LONG VARBINARY'
		);

		$this->assertNotNull( $translation );

		$this->assertSame(
			array(
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "flags" __wp_mysql_bit_10',
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "enabled" __wp_mysql_bool NOT NULL DEFAULT \'0\'',
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "toggled" __wp_mysql_boolean',
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "amount" __wp_mysql_dec_10_2',
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "fixed_value" __wp_mysql_fixed_8_3',
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "real_value" __wp_mysql_real',
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "payload" __wp_mysql_json DEFAULT NULL',
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "notes" __wp_mysql_mediumtext',
				'ALTER TABLE "wptests_alias_alter" ADD COLUMN "raw_data" __wp_mysql_mediumblob',
			),
			$translation['statements']
		);

		$this->assertSame( 'operations', $translation['metadata']['operation'] );
		$this->assertSame( 'public', $translation['metadata']['schema'] );
		$this->assertSame( 'wptests_alias_alter', $translation['metadata']['table'] );

		$columns = array();
		foreach ( $translation['metadata']['operations'] as $operation ) {
			$this->assertSame( 'add_column', $operation['operation'] );
			$columns[] = $operation['column'];
		}
		$this->assertSame(
			array( 'bit(10)', 'bool', 'boolean', 'dec(10,2)', 'fixed(8,3)', 'real', 'json', 'mediumtext', 'mediumblob' ),
			array_column( $columns, 'type' )
		);
		$this->assertNull( $columns[6]['charset'] );
		$this->assertNull( $columns[6]['collation'] );
		$this->assertSame( 'utf8mb4', $columns[7]['charset'] );
		$this->assertSame( 'utf8mb4_unicode_ci', $columns[7]['collation'] );
		$this->assertNull( $columns[8]['charset'] );
		$this->assertNull( $columns[8]['collation'] );
	}

	/**
	 * Tests ALTER TABLE accepts current database-qualified targets and updates metadata.
	 */ /**
	 * Tests ALTER TABLE resolves existing column references case-insensitively.
	 */ /**
	 * Tests unsupported CREATE TABLE column attributes fail before backend execution.
	 */
	public function test_create_table_unsupported_column_attributes_fail_closed_before_backend_execution(): void {
		$queries = array(
			'CREATE TABLE wptests_bad_column_attribute (base int, generated_value int GENERATED ALWAYS AS (base + 1) STORED)',
			'CREATE TABLE wptests_bad_column_attribute (base int, generated_value int GENERATED ALWAYS AS (base + 1) VIRTUAL)',
			'CREATE TABLE wptests_bad_column_attribute (id int INVISIBLE)',
			'CREATE TABLE wptests_bad_column_attribute (id int VISIBLE)',
			'CREATE TABLE wptests_bad_column_attribute (id int COLUMN_FORMAT FIXED)',
			'CREATE TABLE wptests_bad_column_attribute (id int STORAGE DISK)',
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported CREATE TABLE column attribute to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported CREATE TABLE column attribute.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

	/**
	 * Tests CREATE-time metadata preseed rows exactly match real PostgreSQL catalog rows.
	 */
	public function test_create_metadata_preseed_rows_match_real_catalog_rows(): void {
		list( $driver, $connection, $schema ) = $this->create_create_metadata_preseed_capture_driver();
		$table                                = 'wptests_create_metadata_preseed_rows';

		$this->assertSame( 0, $driver->query( $this->get_create_metadata_preseed_fixture_sql( $table ) ) );

		$cache_key = $schema . "\0" . $table;
		$cache     = $this->get_driver_private_property( $driver, 'mysql_column_metadata_introspection_cache' );
		$this->assertArrayHasKey( $cache_key, $cache );

		$real_rows = $this->read_mysql_catalog_column_metadata_rows( $driver, $schema, $table );
		$this->assertSame( $real_rows, $cache[ $cache_key ] );

		$connection->clear_column_catalog_queries();
		$this->assertSame( $real_rows, $this->get_cached_mysql_catalog_column_metadata_rows( $driver, $schema, $table ) );
		$this->assertSame( array(), $connection->get_column_catalog_queries() );

		$rows_by_column = $this->index_metadata_rows_by_column_name( $real_rows );
		$this->assertSame( 'bigint(20) unsigned', $rows_by_column['id']['column_type'] );
		$this->assertSame( 'auto_increment', $rows_by_column['id']['extra'] );
		$this->assertSame( 'varchar(191)', $rows_by_column['title']['column_type'] );
		$this->assertSame( 'big5_chinese_ci', $rows_by_column['title']['collation_name'] );
		$this->assertSame( '', $rows_by_column['title']['column_default'] );
		$this->assertNull( $rows_by_column['body']['column_default'] );
		$this->assertSame( 'CURRENT_TIMESTAMP', $rows_by_column['created_at']['column_default'] );
		$this->assertSame( 'DEFAULT_GENERATED', $rows_by_column['created_at']['extra'] );
		$this->assertSame( 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP', $rows_by_column['touched_at']['extra'] );
		$this->assertSame( 'enum(\'draft\',\'published\')', $rows_by_column['status']['column_type'] );
		$this->assertSame( 'draft', $rows_by_column['status']['column_default'] );
		$this->assertSame( 'set(\'flag-a\',\'flag-b\')', $rows_by_column['flags']['column_type'] );
		$this->assertSame( 'decimal(10,2) unsigned', $rows_by_column['price']['column_type'] );
		$this->assertSame( '0.00', $rows_by_column['price']['column_default'] );
	}

	/**
	 * Tests factored catalog metadata SQL matches the previous projection shape.
	 */
	public function test_catalog_metadata_factored_sql_matches_legacy_projection_and_reduces_catalog_calls(): void {
		list( $driver, $connection, $schema ) = $this->create_create_metadata_preseed_capture_driver();
		$table                                = 'wptests_catalog_metadata_factored_rows';

		$this->assertSame( 0, $driver->query( $this->get_create_metadata_preseed_fixture_sql( $table ) ) );

		$legacy_rows = $this->read_legacy_mysql_catalog_column_metadata_rows( $driver, $schema, $table );
		$connection->clear_column_catalog_queries();
		$factored_rows   = $this->read_mysql_catalog_column_metadata_rows( $driver, $schema, $table );
		$catalog_queries = $connection->get_column_catalog_queries();

		$this->assertSame( $legacy_rows, $factored_rows );
		$this->assertCount( 1, $catalog_queries );

		$catalog_sql = $catalog_queries[0]['sql'];
		$this->assertStringContainsString( 'WITH catalog_columns AS MATERIALIZED', $catalog_sql );
		$this->assertStringContainsString( 'FROM information_schema.columns c', $catalog_sql );
		$this->assertStringContainsString( 'FROM catalog_columns c', $catalog_sql );
		$this->assertStringContainsString( 'AS column_comment', $catalog_sql );
		$this->assertStringContainsString( 'AS identity_sequence_comment', $catalog_sql );
		$this->assertStringContainsString( 'c.column_comment', $catalog_sql );
		$this->assertStringContainsString( 'c.identity_sequence_comment', $catalog_sql );
		$this->assertSame( 1, substr_count( $catalog_sql, 'pg_catalog.col_description(pc.oid, pa.attnum)' ) );
		$this->assertSame( 1, substr_count( $catalog_sql, 'pg_catalog.pg_get_serial_sequence(' ) );

		$rows_by_column = $this->index_metadata_rows_by_column_name( $factored_rows );
		$this->assertSame( 'bigint(20) unsigned', $rows_by_column['id']['column_type'] );
		$this->assertSame( 'auto_increment', $rows_by_column['id']['extra'] );
		$this->assertSame( 'varchar(191)', $rows_by_column['title']['column_type'] );
		$this->assertSame( 'big5_chinese_ci', $rows_by_column['title']['collation_name'] );
		$this->assertSame( '', $rows_by_column['title']['column_default'] );
		$this->assertSame( 'longtext', $rows_by_column['body']['column_type'] );
		$this->assertSame( 'CURRENT_TIMESTAMP', $rows_by_column['created_at']['column_default'] );
		$this->assertSame( 'DEFAULT_GENERATED', $rows_by_column['created_at']['extra'] );
		$this->assertSame( 'DEFAULT_GENERATED on update CURRENT_TIMESTAMP', $rows_by_column['touched_at']['extra'] );
		$this->assertSame( 'enum(\'draft\',\'published\')', $rows_by_column['status']['column_type'] );
		$this->assertSame( 'set(\'flag-a\',\'flag-b\')', $rows_by_column['flags']['column_type'] );
		$this->assertSame( 'decimal(10,2) unsigned', $rows_by_column['price']['column_type'] );

		$describe_rows = $driver->query( 'DESCRIBE `' . $table . '`' );
		$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $this->find_row_by_value( $describe_rows, 'Field', 'id' ), 'Type' ) );
		$this->assertSame( 'auto_increment', $this->get_row_value( $this->find_row_by_value( $describe_rows, 'Field', 'id' ), 'Extra' ) );
	}

	/**
	 * Tests CREATE metadata can preseed SHOW CREATE TABLE row shape without a backend read.
	 */
	public function test_show_create_table_metadata_preseed_shape_matches_create_builder(): void {
		$driver   = $this->create_backendless_driver();
		$table    = 'wptests_show_create_preseed_shape';
		$metadata = ( new WP_PostgreSQL_Create_Table_Translator() )->extract_schema_metadata(
			"CREATE TABLE `{$table}` (
				`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT 'ID note',
				`title` varchar(191) CHARACTER SET big5 NOT NULL DEFAULT '' COMMENT 'Title note',
				`created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
				`rating` int(11) NOT NULL DEFAULT 0,
				PRIMARY KEY (`id`),
				UNIQUE KEY `title_unique` (`title`(12) DESC) COMMENT 'Title key',
				CONSTRAINT `rating_positive` CHECK (`rating` >= 0)
			) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT='Table note'",
			true
		);
		$this->assertCount( 1, $metadata );

		$convert_metadata = Closure::bind(
			function ( array $metadata ): ?array {
				return $this->get_show_create_table_metadata_from_create_metadata( $metadata );
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);
		$build_create     = Closure::bind(
			function ( string $table, array $metadata ): string {
				return $this->get_mysql_create_table_statement_from_metadata(
					$table,
					$metadata['columns'],
					$metadata['indexes'],
					$metadata['foreign_keys'],
					$metadata['checks'],
					$metadata['table']['comment'],
					false,
					$metadata['table']['collation']
				);
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);

		if ( ! $convert_metadata instanceof Closure || ! $build_create instanceof Closure ) {
			throw new RuntimeException( 'Could not bind SHOW CREATE TABLE metadata preseed helpers.' );
		}

		$show_create_metadata = $convert_metadata( $metadata[0] );
		$this->assertIsArray( $show_create_metadata );
		$this->assertSame( array( 'id', 'title', 'created_at', 'rating' ), array_column( $show_create_metadata['columns'], 'column_name' ) );
		$this->assertSame( 'bigint(20) unsigned', $show_create_metadata['columns'][0]['column_type'] );
		$this->assertSame( 'auto_increment', $show_create_metadata['columns'][0]['extra'] );
		$this->assertSame( 'ID note', $show_create_metadata['columns'][0]['column_comment'] );
		$this->assertSame( 'big5_chinese_ci', $show_create_metadata['columns'][1]['collation_name'] );
		$this->assertSame( 'title_unique', $show_create_metadata['indexes'][1]['key_name'] );
		$this->assertSame( 'D', $show_create_metadata['indexes'][1]['collation'] );
		$this->assertSame( '12', $show_create_metadata['indexes'][1]['sub_part'] );
		$this->assertSame( 'rating_positive', $show_create_metadata['checks'][0]['constraint_name'] );
		$this->assertSame( 'big5_chinese_ci', $show_create_metadata['table']['collation'] );

		$create_sql = $build_create( $table, $show_create_metadata );
		$this->assertStringContainsString( '`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT \'ID note\'', $create_sql );
		$this->assertStringContainsString( 'UNIQUE KEY `title_unique` (`title`(12) DESC) COMMENT \'Title key\'', $create_sql );
		$this->assertStringContainsString( 'CONSTRAINT `rating_positive` CHECK ("rating" >= 0)', $create_sql );
		$this->assertStringContainsString( "COMMENT='Table note'", $create_sql );
	}

	/**
	 * Tests SHOW CREATE TABLE preseed serves the first hit without backend queries.
	 */
	public function test_show_create_table_metadata_preseed_avoids_first_hit_backend_queries(): void {
		$connection     = new WP_PostgreSQL_Query_Spy_Connection();
		$driver         = new WP_PostgreSQL_Driver( $connection, 'wptests' );
		$table          = 'wptests_show_create_preseed_hot_path';
		$metadata_query = "CREATE TABLE `{$table}` (
			`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
			`title` varchar(191) NOT NULL DEFAULT '',
			PRIMARY KEY (`id`),
			KEY `title_prefix` (`title`(12))
		) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci";
		$metadata       = ( new WP_PostgreSQL_Create_Table_Translator() )->extract_schema_metadata( $metadata_query, true );

		$seed_metadata = Closure::bind(
			function ( array $metadata_tables, string $metadata_query ): void {
				$this->seed_mysql_show_create_table_metadata_introspection_cache_for_created_tables(
					$metadata_tables,
					'public',
					$metadata_query
				);
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);

		if ( ! $seed_metadata instanceof Closure ) {
			throw new RuntimeException( 'Could not bind SHOW CREATE TABLE metadata preseed seeder.' );
		}

		$seed_metadata( $metadata, $metadata_query );

		$rows = $driver->query( 'SHOW CREATE TABLE `' . $table . '`' );

		$this->assertSame( 0, $connection->get_query_count() );
		$this->assertCount( 1, $rows );
		$this->assertStringContainsString( 'CREATE TABLE `' . $table . '`', (string) $this->get_row_value( $rows[0], 'Create Table' ) );
		$this->assertStringContainsString( 'KEY `title_prefix` (`title`(12))', (string) $this->get_row_value( $rows[0], 'Create Table' ) );
	}

	/**
	 * Tests SHOW CREATE TABLE uses preseeded metadata and matches catalog fallback.
	 */
	public function test_show_create_table_uses_preseeded_metadata_without_catalog_queries_and_matches_catalog(): void {
		list( $driver, $connection ) = $this->create_create_metadata_preseed_capture_driver();
		$table                       = 'wptests_show_create_preseed_perf';

		$this->assertSame( 0, $driver->query( $this->get_create_metadata_preseed_fixture_sql( $table ) ) );

		$connection->clear_queries();
		$preseed_rows    = $driver->query( 'SHOW CREATE TABLE `' . $table . '`' );
		$preseed_queries = $connection->get_queries();

		$this->assertCount( 1, $preseed_rows );
		$this->assertSame( array(), $preseed_queries );

		$this->clear_driver_mysql_metadata_caches( $driver );
		$connection->clear_queries();
		$catalog_rows    = $driver->query( 'SHOW CREATE TABLE `' . $table . '`' );
		$catalog_queries = $connection->get_queries();

		$this->assertEquals( $catalog_rows, $preseed_rows );
		$this->assertGreaterThanOrEqual( 5, count( $catalog_queries ) );

		$this->assertSame( 0, $driver->query( "ALTER TABLE `{$table}` ADD COLUMN `after_alter` varchar(20)" ) );
		$connection->clear_queries();
		$altered_rows    = $driver->query( 'SHOW CREATE TABLE `' . $table . '`' );
		$altered_queries = $connection->get_queries();

		$this->assertGreaterThanOrEqual( 5, count( $altered_queries ) );
		$this->assertStringContainsString( '`after_alter` varchar(20)', (string) $this->get_row_value( $altered_rows[0], 'Create Table' ) );
	}

	/**
	 * Tests factored catalog metadata keeps temp schemas and column lookup case rules.
	 */
	public function test_catalog_metadata_factored_sql_preserves_temp_table_and_column_lookup_case_rules(): void {
		list( $driver, , $schema ) = $this->create_create_metadata_preseed_capture_driver();
		$table                     = 'wptests_catalog_metadata_case_lookup';

		$this->assertSame(
			0,
			$driver->query(
				"CREATE TABLE `{$table}` (
					`id` int(11),
					`MiXeDName` varchar(20),
					`lower_name` varchar(20)
				)"
			)
		);
		$this->assertSame( 0, $driver->query( "CREATE TEMPORARY TABLE `{$table}` ( `temp_col` longtext )" ) );

		$temp_schema = $this->get_temporary_metadata_schema_for_table( $driver, $table );
		$this->assertNotSame( $schema, $temp_schema );

		$permanent_rows = $this->read_mysql_catalog_column_metadata_rows( $driver, $schema, $table );
		$this->assertSame(
			$this->read_legacy_mysql_catalog_column_metadata_rows( $driver, $schema, $table ),
			$permanent_rows
		);
		$this->assertSame( array( 'id', 'MiXeDName', 'lower_name' ), array_column( $permanent_rows, 'column_name' ) );

		$temp_rows = $this->read_mysql_catalog_column_metadata_rows( $driver, $temp_schema, $table );
		$this->assertSame(
			$this->read_legacy_mysql_catalog_column_metadata_rows( $driver, $temp_schema, $table ),
			$temp_rows
		);
		$this->assertSame( array( 'temp_col' ), array_column( $temp_rows, 'column_name' ) );
		$this->assertSame( 'longtext', $temp_rows[0]['column_type'] );

		$case_insensitive_rows = $this->read_mysql_catalog_column_metadata_rows(
			$driver,
			$schema,
			$table,
			'mixedname'
		);
		$this->assertSame(
			$this->read_legacy_mysql_catalog_column_metadata_rows( $driver, $schema, $table, 'mixedname' ),
			$case_insensitive_rows
		);
		$this->assertCount( 1, $case_insensitive_rows );
		$this->assertSame( 'MiXeDName', $case_insensitive_rows[0]['column_name'] );

		$this->assertSame(
			array(),
			$this->read_mysql_catalog_column_metadata_rows( $driver, $schema, $table, 'mixedname', true )
		);

		$case_sensitive_rows = $this->read_mysql_catalog_column_metadata_rows(
			$driver,
			$schema,
			$table,
			'MiXeDName',
			true
		);
		$this->assertCount( 1, $case_sensitive_rows );
		$this->assertSame( 'MiXeDName', $case_sensitive_rows[0]['column_name'] );
	}

	/**
	 * Tests CREATE-time metadata preseed does not survive explicit clears, DROP/CREATE, or ALTER.
	 */
	public function test_create_metadata_preseed_invalidates_on_explicit_clear_drop_create_and_alter(): void {
		list( $driver, $connection, $schema ) = $this->create_create_metadata_preseed_capture_driver();
		$table                                = 'wptests_create_metadata_preseed_invalidate';

		$this->assertSame(
			0,
			$driver->query(
				"CREATE TABLE `{$table}` (
					`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
					`title` varchar(20),
					PRIMARY KEY (`id`)
				)"
			)
		);

		$connection->clear_column_catalog_queries();
		$this->assertSame(
			array( 'id', 'title' ),
			array_column( $this->get_cached_mysql_catalog_column_metadata_rows( $driver, $schema, $table ), 'column_name' )
		);
		$this->assertSame( array(), $connection->get_column_catalog_queries() );

		$this->clear_driver_mysql_metadata_caches( $driver );
		$connection->clear_column_catalog_queries();
		$this->assertSame(
			array( 'id', 'title' ),
			array_column( $this->get_cached_mysql_catalog_column_metadata_rows( $driver, $schema, $table ), 'column_name' )
		);
		$this->assertCount( 1, $connection->get_column_catalog_queries() );

		$this->assertSame( 0, $driver->query( "DROP TABLE `{$table}`" ) );
		$this->assertSame( 0, $driver->query( "CREATE TABLE `{$table}` ( `replacement` varchar(10) )" ) );

		$connection->clear_column_catalog_queries();
		$this->assertSame(
			array( 'replacement' ),
			array_column( $this->get_cached_mysql_catalog_column_metadata_rows( $driver, $schema, $table ), 'column_name' )
		);
		$this->assertSame( array(), $connection->get_column_catalog_queries() );

		$this->assertSame( 0, $driver->query( "ALTER TABLE `{$table}` ADD COLUMN `after_alter` varchar(10)" ) );

		$connection->clear_column_catalog_queries();
		$this->assertSame(
			array( 'replacement', 'after_alter' ),
			array_column( $this->get_cached_mysql_catalog_column_metadata_rows( $driver, $schema, $table ), 'column_name' )
		);
		$this->assertCount( 1, $connection->get_column_catalog_queries() );
	}

	/**
	 * Tests explicit DEFAULT NULL falls back because translator metadata cannot disambiguate it.
	 */
	public function test_create_metadata_preseed_falls_back_for_explicit_default_null(): void {
		list( $driver, $connection, $schema ) = $this->create_create_metadata_preseed_capture_driver();
		$columns                              = array(
			'plain'             => '`value` int(11) DEFAULT NULL',
			'comment_gap'       => '`value` varchar(20) DEFAULT /*gap*/ NULL',
			'parenthesized_gap' => '`value` varchar(20) DEFAULT ( /*gap*/ NULL )',
		);

		foreach ( $columns as $suffix => $column ) {
			$table = 'wptests_create_metadata_preseed_default_null_' . $suffix;
			$this->assertSame( 0, $driver->query( "CREATE TABLE `{$table}` ( {$column} )" ), $suffix );

			$cache_key = $schema . "\0" . $table;
			$cache     = $this->get_driver_private_property( $driver, 'mysql_column_metadata_introspection_cache' );
			$this->assertArrayNotHasKey( $cache_key, $cache, $suffix );

			$connection->clear_column_catalog_queries();
			$rows = $this->get_cached_mysql_catalog_column_metadata_rows( $driver, $schema, $table );

			$this->assertSame( array( 'value' ), array_column( $rows, 'column_name' ), $suffix );
			$this->assertCount( 1, $connection->get_column_catalog_queries(), $suffix );
		}
	}

