	/**
	 * Tests explicit DEFAULT NULL skips SHOW CREATE TABLE preseed and uses catalog metadata.
	 */
	public function test_real_pgsql_show_create_table_preseed_skips_explicit_default_null(): void {
		list( $driver, $connection ) = $this->create_create_metadata_preseed_capture_driver();
		$columns                     = array(
			'plain'             => '`value` int(11) DEFAULT NULL',
			'comment_gap'       => '`value` varchar(20) DEFAULT /*gap*/ NULL',
			'parenthesized_gap' => '`value` varchar(20) DEFAULT ( /*gap*/ NULL )',
		);

		foreach ( $columns as $suffix => $column ) {
			$table = 'wptests_show_create_preseed_default_null_' . $suffix;
			$this->assertSame( 0, $driver->query( "CREATE TABLE `{$table}` ( {$column} )" ), $suffix );

			$connection->clear_queries();
			$first_rows    = $driver->query( 'SHOW CREATE TABLE `' . $table . '`' );
			$first_queries = $connection->get_queries();

			$this->assertGreaterThanOrEqual( 5, count( $first_queries ), $suffix );
			$this->assertCount( 1, $first_rows, $suffix );
			$this->assertStringContainsString( '`value` ', (string) $this->get_row_value( $first_rows[0], 'Create Table' ), $suffix );
			$this->assertStringContainsString( 'DEFAULT NULL', (string) $this->get_row_value( $first_rows[0], 'Create Table' ), $suffix );

			$this->clear_driver_mysql_metadata_caches( $driver );
			$catalog_rows = $driver->query( 'SHOW CREATE TABLE `' . $table . '`' );
			$this->assertEquals( $catalog_rows, $first_rows, $suffix );
		}
	}

	/**
	 * Tests unsupported ALTER TABLE column attributes fail before backend execution.
	 */
	public function test_alter_table_unsupported_column_attributes_fail_closed_before_backend_execution(): void {
		$queries = array(
			'ALTER TABLE wptests_bad_column_attribute ADD COLUMN generated_value int GENERATED ALWAYS AS (base + 1) STORED',
			'ALTER TABLE wptests_bad_column_attribute ADD COLUMN hidden_value int INVISIBLE',
			'ALTER TABLE wptests_bad_column_attribute ADD COLUMN stored_value int COLUMN_FORMAT FIXED',
			'ALTER TABLE wptests_bad_column_attribute ADD COLUMN disk_value int STORAGE DISK',
			'ALTER TABLE wptests_bad_column_attribute MODIFY COLUMN hidden_value int INVISIBLE',
			'ALTER TABLE wptests_bad_column_attribute CHANGE COLUMN hidden_value hidden_value int INVISIBLE',
		);

		foreach ( $queries as $query ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported ALTER TABLE column attribute to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ALTER TABLE statement.', $e->getMessage(), $query );
			}

			$this->assertSame( 0, $connection->get_query_count(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
		}
	}

	/**
	 * Tests ALTER TABLE rejects non-current schema-qualified targets before backend execution.
	 */
	public function test_alter_table_rejects_non_current_schema_qualified_targets(): void {
		$queries = array(
			'ALTER TABLE other_db.t ADD COLUMN name VARCHAR(255)'                 => 'Unsupported ALTER TABLE statement.',
			'ALTER TABLE information_schema.tables ADD COLUMN name VARCHAR(255)' => 'Unsupported information_schema query.',
		);

		foreach ( $queries as $query => $message ) {
			$driver = $this->create_driver( 'wp' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported ALTER TABLE target to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( $message, $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}

		$driver = $this->create_driver( 'wp' );
		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		try {
			$driver->query( 'ALTER TABLE tables ADD COLUMN name VARCHAR(255)' );
			$this->fail( 'Expected information_schema ALTER TABLE target to throw.' );
		} catch ( InvalidArgumentException $e ) {
			$this->assertSame( 'Unsupported information_schema query.', $e->getMessage() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		}
	}

	/**
	 * Tests ALTER TABLE RENAME TO accepts current database and public-qualified targets.
	 */ /**
	 * Tests ALTER TABLE RENAME AS and bare RENAME forms are accepted.
	 */ /**
	 * Tests ALTER COLUMN DROP DEFAULT updates backend and MySQL metadata.
	 */ /**
	 * Tests real PostgreSQL ALTER COLUMN default metadata uses catalogs.
	 */
	public function test_real_pgsql_alter_column_default_metadata_uses_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL ALTER COLUMN DEFAULT catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task917_default' );

		$database_name      = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection         = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver             = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix             = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table              = 'task917_default_' . $suffix;
		$table_literal      = $driver->get_connection()->quote( $table );
		$database_literal   = $driver->get_connection()->quote( $database_name );
		$metadata_comment   = "__wp_mysql_column_default:REFURV9BRERfREFZKDEp\n__wp_mysql_column_type:dmFyY2hhcigyMCk=\nStatus note";
		$quote_identifier   = static function ( string $identifier ): string {
			return WP_PostgreSQL_Connection::quote_identifier_value( $identifier );
		};
		$set_status_comment = function () use ( $pdo, $metadata_comment, $quote_identifier, $table ): void {
			$pdo->exec(
				'COMMENT ON COLUMN '
				. $quote_identifier( 'public' )
				. '.'
				. $quote_identifier( $table )
				. '.'
				. $quote_identifier( 'status' )
				. ' IS '
				. $pdo->quote( $metadata_comment )
			);
		};
		$backend_sql        = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`status` varchar(20) DEFAULT 'draft' COMMENT 'Status note',
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE ALTER COLUMN DEFAULT fixture table',
				$backend_sql
			);

			$set_status_comment();
			$this->assertSame(
				0,
				$driver->query( "ALTER TABLE `{$table}` ALTER COLUMN `status` SET DEFAULT 'published'" )
			);
			$set_default_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER COLUMN SET DEFAULT',
				$backend_sql
			);
			$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" ALTER COLUMN "status" SET DEFAULT \'published\'', $set_default_sql );
			$this->assertStringContainsString( 'pg_catalog.col_description(c.oid, a.attnum)', $set_default_sql );
			$this->assertStringContainsString( 'COMMENT ON COLUMN "public"."' . $table . '"."status" IS ', $set_default_sql );
			$this->assertStringNotContainsString( '__wp_mysql_column_default:', $set_default_sql );
			$this->assertStringContainsString( '__wp_mysql_column_type:dmFyY2hhcigyMCk=', $set_default_sql );
			$this->assertStringContainsString( 'Status note', $set_default_sql );

			$columns_after_set = $driver->query( 'SHOW COLUMNS FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS after SET DEFAULT',
				$backend_sql
			);
			$status_after_set = $this->find_row_by_value( $columns_after_set, 'Field', 'status' );
			$this->assertSame( 'published', $this->get_row_value( $status_after_set, 'Default' ) );

			$set_column_rows = $driver->query(
				"SELECT column_name, column_default, column_comment
				FROM information_schema.columns
				WHERE table_schema = {$database_literal}
					AND table_name = {$table_literal}
					AND column_name = 'status'"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.columns after SET DEFAULT',
				$backend_sql
			);
			$this->assertCount( 1, $set_column_rows );
			$this->assertSame( 'published', $this->get_row_value( $set_column_rows[0], 'COLUMN_DEFAULT' ) );
			$this->assertSame( 'Status note', $this->get_row_value( $set_column_rows[0], 'COLUMN_COMMENT' ) );

			$set_status_comment();
			$this->assertSame(
				0,
				$driver->query( 'ALTER TABLE `' . $table . '` ALTER COLUMN `status` DROP DEFAULT' )
			);
			$drop_default_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER COLUMN DROP DEFAULT',
				$backend_sql
			);
			$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" ALTER COLUMN "status" DROP DEFAULT', $drop_default_sql );
			$this->assertStringContainsString( 'pg_catalog.col_description(c.oid, a.attnum)', $drop_default_sql );
			$this->assertStringContainsString( 'COMMENT ON COLUMN "public"."' . $table . '"."status" IS ', $drop_default_sql );
			$this->assertStringNotContainsString( '__wp_mysql_column_default:', $drop_default_sql );
			$this->assertStringContainsString( '__wp_mysql_column_type:dmFyY2hhcigyMCk=', $drop_default_sql );

			$columns_after_drop = $driver->query( 'SHOW COLUMNS FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS after DROP DEFAULT',
				$backend_sql
			);
			$status_after_drop = $this->find_row_by_value( $columns_after_drop, 'Field', 'status' );
			$this->assertNull( $this->get_row_value( $status_after_drop, 'Default' ) );

			$drop_column_rows = $driver->query(
				"SELECT column_name, column_default, column_comment
				FROM information_schema.columns
				WHERE table_schema = {$database_literal}
					AND table_name = {$table_literal}
					AND column_name = 'status'"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.columns after DROP DEFAULT',
				$backend_sql
			);
			$this->assertCount( 1, $drop_column_rows );
			$this->assertNull( $this->get_row_value( $drop_column_rows[0], 'COLUMN_DEFAULT' ) );
			$this->assertSame( 'Status note', $this->get_row_value( $drop_column_rows[0], 'COLUMN_COMMENT' ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task917_default' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task917_default' ) );
		}
	}

