	/**
	 * Tests ALTER TABLE AUTO_INCREMENT adjusts the PostgreSQL identity sequence.
	 */
	public function test_alter_table_auto_increment_updates_postgresql_identity_sequence(): void {
		$driver = $this->create_driver();
		$driver->query(
			'CREATE TABLE wptests_alter_auto_increment (
				id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
				name varchar(191) DEFAULT NULL,
				PRIMARY KEY (id)
			)'
		);

		$this->assertSame( 0, $driver->query( 'ALTER TABLE wptests_alter_auto_increment AUTO_INCREMENT = 50' ) );
		$this->assertSame( 1, $driver->query( "INSERT INTO wptests_alter_auto_increment (name) VALUES ('first')" ) );

		$rows = $driver->query( 'SELECT id, name FROM wptests_alter_auto_increment' );
		$this->assertCount( 1, $rows );
		$this->assertSame( '50', $rows[0]->id );

		$this->assertSame( 0, $driver->query( 'ALTER TABLE wptests_alter_auto_increment AUTO_INCREMENT = 1' ) );
		$this->assertSame( 1, $driver->query( "INSERT INTO wptests_alter_auto_increment (name) VALUES ('second')" ) );

		$rows = $driver->query( 'SELECT id, name FROM wptests_alter_auto_increment ORDER BY id' );
		$this->assertSame( '50', $rows[0]->id );
		$this->assertSame( '51', $rows[1]->id );

		$driver->query(
			'CREATE TABLE wptests_alter_auto_increment_plain (
				id int(11) DEFAULT NULL,
				name varchar(191) DEFAULT NULL
			)'
		);

		$this->assertSame( 0, $driver->query( 'ALTER TABLE wptests_alter_auto_increment_plain AUTO_INCREMENT = 500' ) );
	}

	/**
	 * Tests unsupported SHOW TABLES database qualifiers fail before backend execution.
	 */
	public function test_show_tables_unsupported_database_qualification_does_not_reach_backend(): void {
		$queries = array(
			'SHOW TABLES FROM other_db',
			'SHOW TABLES FROM pg_catalog',
			'SHOW TABLES FROM other_db LIKE 1',
			'SHOW TABLES FROM other_db EXTRA',
		);

		foreach ( $queries as $query ) {
			$driver = $this->create_driver();

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported SHOW TABLES statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SHOW TABLES statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests real PostgreSQL catalog roundtrips use PostgreSQL catalog metadata.
	 */
	public function test_real_pgsql_catalog_roundtrip_uses_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL catalog roundtrip test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

			$pdo->exec( 'SET search_path TO public' );
			$this->drop_public_pgsql_views_with_prefix( $pdo, 'task813' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task813' );

		$database_name     = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection        = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver            = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix            = strtolower( bin2hex( random_bytes( 4 ) ) );
			$parent_table  = 'task813_' . $suffix . '_parent';
			$child_table   = 'task813_' . $suffix . '_child';
			$view_table    = 'task813_' . $suffix . '_view';
			$escaped_table = 'task813_' . $suffix . '_wp_e2e_users';
		$escaped_shadows   = array(
			'task813_' . $suffix . 'x_wp_e2e_users',
			'task813_' . $suffix . '_wpx_e2e_users',
			'task813_' . $suffix . '_wp_e2eXusers',
		);
		$foreign_key       = $child_table . '_parent_fk';
		$check_constraint  = $child_table . '_status_check';
		$child_literal     = $driver->get_connection()->quote( $child_table );
		$parent_literal    = $driver->get_connection()->quote( $parent_table );
		$fk_literal        = $driver->get_connection()->quote( $foreign_key );
		$check_literal     = $driver->get_connection()->quote( $check_constraint );
		$backend_sql       = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							`title` varchar(191) NOT NULL COMMENT 'Parent title note',
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_unique` (`slug`),
							KEY `title_idx` (`title`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Task 813 parent table'",
						$parent_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE parent table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
								`parent_id` bigint(20) unsigned NOT NULL,
								`slug` varchar(64) NOT NULL,
								`description` varchar(255) NOT NULL COMMENT 'Child description note',
								`created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
								`status` varchar(20) NOT NULL DEFAULT 'draft',
								PRIMARY KEY (`id`),
								UNIQUE KEY `slug_unique` (`slug`),
							KEY `parent_idx` (`parent_id`),
							KEY `description_prefix` (`description`(191)),
							CONSTRAINT `%s` FOREIGN KEY (`parent_id`) REFERENCES `%s` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
							CONSTRAINT `%s` CHECK (`status` <> 'blocked')
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Task 813 child table'",
						$child_table,
						$foreign_key,
						$parent_table,
						$check_constraint
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE child table',
				$backend_sql
			);

			foreach ( array_merge( array( $escaped_table ), $escaped_shadows ) as $show_tables_name ) {
				$pdo->exec(
					'CREATE TABLE public.'
					. WP_PostgreSQL_Connection::quote_identifier_value( $show_tables_name )
					. ' (id integer)'
				);
			}
				$pdo->exec(
					'CREATE VIEW public.'
					. WP_PostgreSQL_Connection::quote_identifier_value( $view_table )
					. ' AS SELECT id, slug FROM public.'
					. WP_PostgreSQL_Connection::quote_identifier_value( $parent_table )
				);

				$show_tables = $driver->query( 'SHOW TABLES LIKE ' . $child_literal );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TABLES LIKE',
				$backend_sql
			);
			$this->assertCount( 1, $show_tables );
			$this->assertContains( $child_table, array_values( get_object_vars( $show_tables[0] ) ) );

			$escaped_like_pattern = 'task813\\_' . $suffix . '\\_wp\\_e2e\\_users';
			$escaped_show_tables  = $driver->query( "SHOW TABLES LIKE 'task813\\\\_{$suffix}\\\\_wp\\\\_e2e\\\\_users'" );
			$escaped_queries      = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TABLES LIKE escaped underscores',
				$backend_sql
			);
			$this->assertCount( 1, $escaped_show_tables );
			$this->assertSame( 'Tables_in_' . $database_name, $driver->get_last_column_meta()[0]['name'] );
				$this->assertContains( $escaped_table, array_values( get_object_vars( $escaped_show_tables[0] ) ) );
				$this->assertCount( 1, $escaped_queries );
				$escape_sql = $connection->quote( '\\' );
				$this->assertStringContainsString( 'LIKE ? ESCAPE ' . $escape_sql, $escaped_queries[0]['sql'] );
				$this->assertStringNotContainsString( "ESCAPE '\\'", $escaped_queries[0]['sql'] );
				$this->assertSame( array( $database_name, $escaped_like_pattern ), $escaped_queries[0]['params'] );

				$table_column             = 'Tables_in_' . $database_name;
				$task_show_tables_pattern = 'task813\\_' . $suffix . '\\_%';
				$task_show_tables_literal = "'task813\\\\_{$suffix}\\\\_%'";
				$full_tables              = $driver->query( 'SHOW FULL TABLES LIKE ' . $task_show_tables_literal );
				$full_tables_queries      = $driver->get_last_postgresql_queries();
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW FULL TABLES LIKE task prefix',
					$backend_sql
				);
				$this->assertCount( 6, $full_tables );
				$this->assertSame( array( $table_column, 'Table_type' ), array_column( $driver->get_last_column_meta(), 'name' ) );
				$full_table_types = array();
			foreach ( $full_tables as $full_table ) {
				$full_table_types[ (string) $this->get_row_value( $full_table, $table_column ) ] = (string) $this->get_row_value( $full_table, 'Table_type' );
			}
				$this->assertSame( 'BASE TABLE', $full_table_types[ $parent_table ] ?? null );
				$this->assertSame( 'BASE TABLE', $full_table_types[ $child_table ] ?? null );
				$this->assertSame( 'VIEW', $full_table_types[ $view_table ] ?? null );
				$this->assertCount( 1, $full_tables_queries );
				$this->assertStringContainsString( 'FROM information_schema.tables t', $full_tables_queries[0]['sql'] );
				$this->assertStringContainsString( 'AS "' . $table_column . '"', $full_tables_queries[0]['sql'] );
				$this->assertStringContainsString( 'AS "Table_type"', $full_tables_queries[0]['sql'] );
				$this->assertStringContainsString( 'LIKE ? ESCAPE ' . $escape_sql, $full_tables_queries[0]['sql'] );
				$this->assertSame( array( $database_name, $task_show_tables_pattern ), $full_tables_queries[0]['params'] );

				$current_database_tables  = $driver->query( 'SHOW TABLES FROM `' . $database_name . '`' );
				$current_database_queries = $driver->get_last_postgresql_queries();
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW TABLES FROM current database',
					$backend_sql
				);
				$this->assertSame( array( $table_column ), array_column( $driver->get_last_column_meta(), 'name' ) );
				$this->assertNotNull( $this->find_row_by_value( $current_database_tables, $table_column, $parent_table ) );
				$this->assertNotNull( $this->find_row_by_value( $current_database_tables, $table_column, $child_table ) );
				$this->assertNotNull( $this->find_row_by_value( $current_database_tables, $table_column, $view_table ) );
				$this->assertCount( 1, $current_database_queries );
				$this->assertStringNotContainsString( 'SHOW TABLES', $current_database_queries[0]['sql'] );
				$this->assertSame( array( $database_name ), $current_database_queries[0]['params'] );

				$current_database_like_tables  = $driver->query( 'SHOW TABLES IN `' . $database_name . '` LIKE ' . $task_show_tables_literal );
				$current_database_like_queries = $driver->get_last_postgresql_queries();
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW TABLES IN current database LIKE task prefix',
					$backend_sql
				);
				$this->assertCount( 6, $current_database_like_tables );
				$this->assertSame( array( $table_column ), array_column( $driver->get_last_column_meta(), 'name' ) );
				$this->assertSame( $parent_table, $this->get_row_value( $this->find_row_by_value( $current_database_like_tables, $table_column, $parent_table ), $table_column ) );
				$this->assertCount( 1, $current_database_like_queries );
				$this->assertStringNotContainsString( 'SHOW TABLES', $current_database_like_queries[0]['sql'] );
				$this->assertSame( array( $database_name, $task_show_tables_pattern ), $current_database_like_queries[0]['params'] );

				$current_database_full_tables  = $driver->query( 'SHOW FULL TABLES FROM `' . $database_name . '` LIKE ' . $task_show_tables_literal );
				$current_database_full_queries = $driver->get_last_postgresql_queries();
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW FULL TABLES FROM current database LIKE task prefix',
					$backend_sql
				);
				$this->assertCount( 6, $current_database_full_tables );
				$this->assertSame( array( $table_column, 'Table_type' ), array_column( $driver->get_last_column_meta(), 'name' ) );
				$current_full_table_types = array();
			foreach ( $current_database_full_tables as $current_database_full_table ) {
				$current_full_table_types[ (string) $this->get_row_value( $current_database_full_table, $table_column ) ] = (string) $this->get_row_value( $current_database_full_table, 'Table_type' );
			}
					$this->assertSame( 'BASE TABLE', $current_full_table_types[ $child_table ] ?? null );
					$this->assertSame( 'VIEW', $current_full_table_types[ $view_table ] ?? null );
				$this->assertSame( array(), $current_database_full_queries );
				$this->assertEquals( $full_tables, $current_database_full_tables );

				$this->clear_driver_mysql_metadata_caches( $driver );
				$create_rows = $driver->query( 'SHOW CREATE TABLE `' . $child_table . '`' );
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW CREATE TABLE',
					$backend_sql
				);
				$show_create_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
				$this->assertCount( 1, $create_rows );
				$create_table_sql = (string) $this->get_row_value( $create_rows[0], 'Create Table' );
				$this->assertStringContainsString( 'CREATE TABLE `' . $child_table . '`', $create_table_sql );
				$this->assertStringContainsString( '`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT', $create_table_sql );
				$this->assertStringContainsString( '`created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP', $create_table_sql );
				$this->assertStringContainsString( 'UNIQUE KEY `slug_unique` (`slug`)', $create_table_sql );
				$this->assertStringContainsString( 'KEY `parent_idx` (`parent_id`)', $create_table_sql );
				$this->assertStringContainsString( 'KEY `description_prefix` (`description`(191))', $create_table_sql );
			$this->assertStringContainsString( 'CONSTRAINT `' . $foreign_key . '` FOREIGN KEY', $create_table_sql );
			$this->assertStringContainsString( 'REFERENCES `' . $parent_table . '` (`id`)', $create_table_sql );
			$this->assertStringContainsString( 'ON DELETE CASCADE', $create_table_sql );
				$this->assertStringContainsString( 'CONSTRAINT `' . $check_constraint . '` CHECK', $create_table_sql );
				$this->assertStringContainsString( 'COMMENT=\'Task 813 child table\'', $create_table_sql );
				$this->assertStringContainsString( 'COMMENT \'Child description note\'', $create_table_sql );
				$this->assertStringContainsString( 'FROM information_schema.columns c', $show_create_sql );
				$this->assertStringContainsString( 'pg_catalog.col_description(pc.oid, pa.attnum)', $show_create_sql );
				$this->assertStringContainsString( 'SUBSTRING(c.column_default FROM', $show_create_sql );
				$this->assertStringContainsString( "THEN 'CURRENT_TIMESTAMP'", $show_create_sql );
				$this->assertStringContainsString( "'CURRENT_TIMESTAMP(' || SUBSTRING(c.column_default FROM", $show_create_sql );
				$this->assertStringContainsString( 'pg_catalog.pg_index i', $show_create_sql );
				$this->assertStringContainsString( 'pg_catalog.obj_description(idx.oid, \'pg_class\')', $show_create_sql );
				$this->assertStringContainsString( '__wp_mysql_index_sub_part:', $show_create_sql );
				$this->assertStringContainsString( 'FROM information_schema.key_column_usage kcu', $show_create_sql );
				$this->assertStringContainsString( 'FROM information_schema.referential_constraints rc', $show_create_sql );
				$this->assertStringContainsString( 'FROM pg_catalog.pg_constraint con', $show_create_sql );
				$this->assertStringContainsString( "con.contype = 'c'", $show_create_sql );
				$this->assertStringContainsString( 'pg_catalog.obj_description(con.oid, \'pg_constraint\')', $show_create_sql );
				$this->assertStringContainsString( '__wp_mysql_check_clause:', $show_create_sql );
				$this->assertStringContainsString( 'AS "TABLE_COMMENT"', $show_create_sql );

				$columns = $driver->query( 'SHOW COLUMNS FROM `' . $child_table . '`' );
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW COLUMNS',
					$backend_sql
				);
				$this->assertCount( 6, $columns );
			$id_column = $this->find_row_by_value( $columns, 'Field', 'id' );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $id_column, 'Type' ) );
			$this->assertSame( 'NO', $this->get_row_value( $id_column, 'Null' ) );
			$this->assertSame( 'PRI', $this->get_row_value( $id_column, 'Key' ) );
			$this->assertSame( 'auto_increment', $this->get_row_value( $id_column, 'Extra' ) );
			$description_column = $this->find_row_by_value( $columns, 'Field', 'description' );
			$this->assertSame( 'varchar(255)', $this->get_row_value( $description_column, 'Type' ) );

			$indexes            = $driver->query( 'SHOW INDEX FROM `' . $child_table . '`' );
			$show_index_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX',
				$backend_sql
			);
			$this->assertGreaterThanOrEqual( 4, count( $indexes ) );
			$this->assertSame( 15, $driver->get_last_column_count() );
			$this->assertSame( 'Table', $driver->get_last_column_meta()[0]['name'] );
			$this->assertSame( 'Key_name', $driver->get_last_column_meta()[2]['name'] );

			$primary_index = $this->find_row_by_value( $indexes, 'Key_name', 'PRIMARY' );
			$this->assertCount( 15, get_object_vars( $primary_index ) );
			$this->assertSame( $child_table, $this->get_row_value( $primary_index, 'Table' ) );
			$this->assertSame( '0', $this->get_row_value( $primary_index, 'Non_unique' ) );
			$this->assertSame( '1', $this->get_row_value( $primary_index, 'Seq_in_index' ) );
			$this->assertSame( 'id', $this->get_row_value( $primary_index, 'Column_name' ) );
			$this->assertSame( 'A', $this->get_row_value( $primary_index, 'Collation' ) );
			$this->assertSame( '0', $this->get_row_value( $primary_index, 'Cardinality' ) );
			$this->assertNull( $this->get_row_value( $primary_index, 'Sub_part' ) );
			$this->assertNull( $this->get_row_value( $primary_index, 'Packed' ) );
			$this->assertSame( '', $this->get_row_value( $primary_index, 'Null' ) );
			$this->assertSame( 'BTREE', $this->get_row_value( $primary_index, 'Index_type' ) );
			$this->assertSame( '', $this->get_row_value( $primary_index, 'Comment' ) );
			$this->assertSame( '', $this->get_row_value( $primary_index, 'Index_comment' ) );
			$this->assertSame( 'YES', $this->get_row_value( $primary_index, 'Visible' ) );
			$this->assertNull( $this->get_row_value( $primary_index, 'Expression' ) );

			$slug_index = $this->find_row_by_value( $indexes, 'Key_name', 'slug_unique' );
			$this->assertSame( 'slug', $this->get_row_value( $slug_index, 'Column_name' ) );
			$this->assertSame( '0', $this->get_row_value( $slug_index, 'Non_unique' ) );

			$parent_index = $this->find_row_by_value( $indexes, 'Key_name', 'parent_idx' );
			$this->assertSame( 'parent_id', $this->get_row_value( $parent_index, 'Column_name' ) );
			$this->assertSame( '1', $this->get_row_value( $parent_index, 'Non_unique' ) );

			$prefix_index = $this->find_row_by_value( $indexes, 'Key_name', 'description_prefix' );
			$this->assertSame( 'description', $this->get_row_value( $prefix_index, 'Column_name' ) );
			$this->assertSame( '191', $this->get_row_value( $prefix_index, 'Sub_part' ) );
			$this->assertCount( 1, $show_index_queries );
			$this->assertStringContainsString( 'pg_catalog.pg_index', $show_index_queries[0]['sql'] );
			$this->assertStringContainsString( 'pg_catalog.unnest(i.indkey)', $show_index_queries[0]['sql'] );
			$this->assertStringContainsString( 'show_index_rows', $show_index_queries[0]['sql'] );
			$this->assertStringNotContainsString( 'SHOW INDEX', $show_index_queries[0]['sql'] );
			$this->assertSame( array( 'public', $child_table ), $show_index_queries[0]['params'] );

			$keys = $driver->query( 'SHOW KEYS FROM `' . $child_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW KEYS',
				$backend_sql
			);
			$this->assertEquals( $indexes, $keys );
			$this->assertSame( 15, $driver->get_last_column_count() );
			$this->assertSame( 'Table', $driver->get_last_column_meta()[0]['name'] );
			$this->assertSame( 'Key_name', $driver->get_last_column_meta()[2]['name'] );

			$table_status_rows = $driver->query( 'SHOW TABLE STATUS LIKE ' . $child_literal );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TABLE STATUS',
				$backend_sql
			);
			$table_status_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertCount( 1, $table_status_rows );
			$this->assertSame( $child_table, $this->get_row_value( $table_status_rows[0], 'Name' ) );
			$this->assertSame( 'InnoDB', $this->get_row_value( $table_status_rows[0], 'Engine' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $table_status_rows[0], 'Collation' ) );
			$this->assertSame( 'Task 813 child table', $this->get_row_value( $table_status_rows[0], 'Comment' ) );
			$this->assertStringContainsString( 'pg_catalog.obj_description(pc.oid, \'pg_class\')', $table_status_sql );
			$this->assertStringContainsString( 'AS "TABLE_COLLATION"', $table_status_sql );
			$this->assertStringContainsString( 'FROM information_schema.columns table_collation_columns', $table_status_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_class pc', $table_status_sql );

			$table_rows = $driver->query(
				"SELECT table_name, engine, table_collation, table_comment
				FROM information_schema.tables
				WHERE table_schema = DATABASE()
					AND table_name = {$child_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables',
				$backend_sql
			);
			$this->assertCount( 1, $table_rows );
			$this->assertSame( $child_table, $this->get_row_value( $table_rows[0], 'TABLE_NAME' ) );
			$this->assertSame( 'InnoDB', $this->get_row_value( $table_rows[0], 'ENGINE' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $table_rows[0], 'TABLE_COLLATION' ) );
			$this->assertSame( 'Task 813 child table', $this->get_row_value( $table_rows[0], 'TABLE_COMMENT' ) );

			$column_rows = $driver->query(
				"SELECT column_name, column_type, column_key, extra, column_comment
				FROM information_schema.columns
				WHERE table_schema = DATABASE()
					AND table_name = {$child_literal}
				ORDER BY ordinal_position"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.columns',
				$backend_sql
			);
				$this->assertCount( 6, $column_rows );
			$id_information_schema_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'id' );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $id_information_schema_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'PRI', $this->get_row_value( $id_information_schema_column, 'COLUMN_KEY' ) );
			$this->assertSame( 'auto_increment', $this->get_row_value( $id_information_schema_column, 'EXTRA' ) );
			$description_information_schema_column = $this->find_row_by_value(
				$column_rows,
				'COLUMN_NAME',
				'description'
			);
			$this->assertSame(
				'Child description note',
				$this->get_row_value( $description_information_schema_column, 'COLUMN_COMMENT' )
			);

			$statistics_rows = $driver->query(
				"SELECT index_name, column_name, sub_part, non_unique
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$child_literal}
				ORDER BY index_name, seq_in_index"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics',
				$backend_sql
			);
			$this->assertGreaterThanOrEqual( 4, count( $statistics_rows ) );
			$this->assertNotNull( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'PRIMARY' ) );
			$this->assertNotNull( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'slug_unique' ) );
			$this->assertNotNull( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'parent_idx' ) );
			$prefix_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'description_prefix' );
			$this->assertSame( 'description', $this->get_row_value( $prefix_statistic, 'COLUMN_NAME' ) );
			$this->assertSame( '191', $this->get_row_value( $prefix_statistic, 'SUB_PART' ) );

			$table_constraints = $driver->query(
				"SELECT constraint_name, constraint_type
				FROM information_schema.table_constraints
				WHERE constraint_schema = DATABASE()
					AND table_name = {$child_literal}
					AND constraint_name IN ({$fk_literal}, {$check_literal})
				ORDER BY constraint_name"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.table_constraints',
				$backend_sql
			);
			$this->assertCount( 2, $table_constraints );
			$this->assertSame(
				'FOREIGN KEY',
				$this->get_row_value( $this->find_row_by_value( $table_constraints, 'CONSTRAINT_NAME', $foreign_key ), 'CONSTRAINT_TYPE' )
			);
			$this->assertSame(
				'CHECK',
				$this->get_row_value( $this->find_row_by_value( $table_constraints, 'CONSTRAINT_NAME', $check_constraint ), 'CONSTRAINT_TYPE' )
			);

			$key_column_usage_rows = $driver->query(
				"SELECT constraint_name, column_name, referenced_table_name, referenced_column_name
				FROM information_schema.key_column_usage
				WHERE constraint_schema = DATABASE()
					AND table_name = {$child_literal}
					AND referenced_table_name = {$parent_literal}
				ORDER BY constraint_name, ordinal_position"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.key_column_usage',
				$backend_sql
			);
			$this->assertCount( 1, $key_column_usage_rows );
			$this->assertSame( $foreign_key, $this->get_row_value( $key_column_usage_rows[0], 'CONSTRAINT_NAME' ) );
			$this->assertSame( 'parent_id', $this->get_row_value( $key_column_usage_rows[0], 'COLUMN_NAME' ) );
			$this->assertSame( $parent_table, $this->get_row_value( $key_column_usage_rows[0], 'REFERENCED_TABLE_NAME' ) );
			$this->assertSame( 'id', $this->get_row_value( $key_column_usage_rows[0], 'REFERENCED_COLUMN_NAME' ) );

			$referential_constraints = $driver->query(
				"SELECT constraint_name, update_rule, delete_rule
				FROM information_schema.referential_constraints
				WHERE constraint_schema = DATABASE()
					AND constraint_name = {$fk_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.referential_constraints',
				$backend_sql
			);
			$this->assertCount( 1, $referential_constraints );
			$this->assertSame( $foreign_key, $this->get_row_value( $referential_constraints[0], 'CONSTRAINT_NAME' ) );
			$this->assertSame( 'CASCADE', $this->get_row_value( $referential_constraints[0], 'DELETE_RULE' ) );
			$this->assertContains(
				$this->get_row_value( $referential_constraints[0], 'UPDATE_RULE' ),
				array( 'RESTRICT', 'NO ACTION' )
			);

			$check_constraints = $driver->query(
				"SELECT constraint_name, check_clause
				FROM information_schema.check_constraints
				WHERE constraint_schema = DATABASE()
					AND constraint_name = {$check_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.check_constraints',
				$backend_sql
			);
			$this->assertCount( 1, $check_constraints );
			$this->assertSame( $check_constraint, $this->get_row_value( $check_constraints[0], 'CONSTRAINT_NAME' ) );
			$this->assertStringContainsString( 'blocked', (string) $this->get_row_value( $check_constraints[0], 'CHECK_CLAUSE' ) );

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_views_with_prefix( $pdo, 'task813' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task813' );
			$this->assertSame( array(), $this->get_public_pgsql_views_with_prefix( $pdo, 'task813' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task813' ) );
		}
	}

	/**
	 * Tests real PostgreSQL DDL mutations refresh catalog readback.
	 */
	public function test_real_pgsql_ddl_mutations_refresh_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL DDL mutation catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

			$pdo->exec( 'SET search_path TO public' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task815' );

			$database_name           = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
			$connection              = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
			$driver                  = new WP_PostgreSQL_Driver( $connection, $database_name );
			$suffix                  = strtolower( bin2hex( random_bytes( 4 ) ) );
			$table                   = 'task815_' . $suffix . '_ddl';
			$no_primary_table        = 'task815_' . $suffix . '_no_primary';
			$table_literal           = $driver->get_connection()->quote( $table );
			$named_check             = 'rating_positive';
			$generated_check         = $table . '_chk_1';
			$named_check_literal     = $driver->get_connection()->quote( $named_check );
			$generated_check_literal = $driver->get_connection()->quote( $generated_check );
			$backend_sql             = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`name` varchar(64) NOT NULL,
							`status` varchar(20) NOT NULL DEFAULT 'draft',
							PRIMARY KEY (`id`),
							UNIQUE KEY `name_unique` (`name`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Task 815 base table'",
						$table
					)
				)
			);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE DDL mutation table',
					$backend_sql
				);

				$this->assertSame(
					0,
					$driver->query(
						sprintf(
							'CREATE TABLE `%s` (
								`id` int NOT NULL,
								`name` varchar(64) NOT NULL
							) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
							$no_primary_table
						)
					)
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE DDL no-primary table',
					$backend_sql
				);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"ALTER TABLE `%s`
							ADD COLUMN `rating` int NOT NULL DEFAULT 0 COMMENT 'Rating note'",
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD COLUMN rating',
				$backend_sql
			);

			$add_columns_query = sprintf(
				'ALTER TABLE `%s`
					ADD COLUMN `code` varchar(64) NULL,
					ADD COLUMN `slug` varchar(255) NULL',
				$table
			);
			$this->assertSame( 0, $driver->query( $add_columns_query ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD COLUMN code and slug',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"ALTER TABLE `%s`
							MODIFY COLUMN `code` varchar(80) NOT NULL DEFAULT 'seed' UNIQUE COMMENT 'Code note'",
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE MODIFY COLUMN code UNIQUE',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"ALTER TABLE `%s`
							MODIFY COLUMN `slug` varchar(255) KEY COMMENT 'Slug note'",
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE MODIFY COLUMN slug KEY',
				$backend_sql
			);

			$add_indexes_query = sprintf(
				'ALTER TABLE `%s`
					ADD INDEX `rating_idx` (`rating`),
					ADD UNIQUE KEY `status_unique` (`status`)',
				$table
			);
			$this->assertSame( 0, $driver->query( $add_indexes_query ) );
				$this->collect_last_postgresql_queries(
					$driver,
					'ALTER TABLE ADD INDEX and ADD UNIQUE',
					$backend_sql
				);

				$add_checks_query = sprintf(
					'ALTER TABLE `%s`
						ADD CONSTRAINT `%s` CHECK (`rating` >= 0),
						ADD CHECK (`rating` < 100)',
					$table,
					$named_check
				);
				$this->assertSame( 0, $driver->query( $add_checks_query ) );
				$this->collect_last_postgresql_queries(
					$driver,
					'ALTER TABLE ADD CHECK constraints',
					$backend_sql
				);
				$add_check_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
				$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" ADD CONSTRAINT "' . $named_check . '" CHECK ("rating" >= 0)', $add_check_sql );
				$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" ADD CONSTRAINT "' . $generated_check . '" CHECK ("rating" < 100)', $add_check_sql );

				$check_constraint_rows = $driver->query(
					"SELECT constraint_name, check_clause
					FROM information_schema.check_constraints
					WHERE constraint_schema = DATABASE()
						AND constraint_name IN ({$named_check_literal}, {$generated_check_literal})
					ORDER BY constraint_name"
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'direct information_schema.check_constraints after ADD CHECK',
					$backend_sql
				);
				$this->assertCount( 2, $check_constraint_rows );
				$named_check_row = $this->find_row_by_value( $check_constraint_rows, 'CONSTRAINT_NAME', $named_check );
				$this->assertStringContainsString( 'rating', (string) $this->get_row_value( $named_check_row, 'CHECK_CLAUSE' ) );
				$generated_check_row = $this->find_row_by_value( $check_constraint_rows, 'CONSTRAINT_NAME', $generated_check );
				$this->assertStringContainsString( '100', (string) $this->get_row_value( $generated_check_row, 'CHECK_CLAUSE' ) );

				$drop_checks_query = sprintf(
					'ALTER TABLE `%s`
						DROP CONSTRAINT `%s`,
						DROP CHECK `%s`',
					$table,
					$named_check,
					$generated_check
				);
				$this->assertSame( 0, $driver->query( $drop_checks_query ) );
				$this->collect_last_postgresql_queries(
					$driver,
					'ALTER TABLE DROP CHECK constraints',
					$backend_sql
				);
				$drop_check_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
				$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" DROP CONSTRAINT "' . $named_check . '"', $drop_check_sql );
				$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" DROP CONSTRAINT "' . $generated_check . '"', $drop_check_sql );

				$remaining_check_constraint_rows = $driver->query(
					"SELECT constraint_name
					FROM information_schema.check_constraints
					WHERE constraint_schema = DATABASE()
						AND constraint_name IN ({$named_check_literal}, {$generated_check_literal})"
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'direct information_schema.check_constraints after DROP CHECK',
					$backend_sql
				);
				$this->assertSame( array(), $remaining_check_constraint_rows );

				$this->assertSame(
					0,
					$driver->query( sprintf( 'DROP INDEX `rating_idx` ON `%s`', $table ) )
				);
			$this->collect_last_postgresql_queries(
				$driver,
				'DROP INDEX rating_idx',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"ALTER TABLE `%s`
							COMMENT = 'Task 815 mutated table'",
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE COMMENT',
				$backend_sql
			);

			$create_rows = $driver->query( 'SHOW CREATE TABLE `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE after DDL mutations',
				$backend_sql
			);
			$this->assertCount( 1, $create_rows );
			$create_table_sql = (string) $this->get_row_value( $create_rows[0], 'Create Table' );
			$this->assertStringContainsString( 'CREATE TABLE `' . $table . '`', $create_table_sql );
			$this->assertStringContainsString( '`rating` int NOT NULL DEFAULT \'0\' COMMENT \'Rating note\'', $create_table_sql );
			$this->assertStringContainsString( '`code` varchar(80) NOT NULL DEFAULT \'seed\' COMMENT \'Code note\'', $create_table_sql );
			$this->assertStringContainsString( '`slug` varchar(255) DEFAULT NULL COMMENT \'Slug note\'', $create_table_sql );
			$this->assertStringContainsString( 'UNIQUE KEY `code` (`code`)', $create_table_sql );
			$this->assertStringContainsString( 'KEY `slug` (`slug`(191))', $create_table_sql );
			$this->assertStringContainsString( 'UNIQUE KEY `status_unique` (`status`)', $create_table_sql );
			$this->assertStringNotContainsString( 'rating_idx', $create_table_sql );
			$this->assertStringContainsString( 'COMMENT=\'Task 815 mutated table\'', $create_table_sql );

			$columns = $driver->query( 'SHOW COLUMNS FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS after DDL mutations',
				$backend_sql
			);
			$this->assertCount( 6, $columns );
			$rating_column = $this->find_row_by_value( $columns, 'Field', 'rating' );
			$this->assertSame( 'int', $this->get_row_value( $rating_column, 'Type' ) );
			$this->assertSame( 'NO', $this->get_row_value( $rating_column, 'Null' ) );
			$this->assertSame( '0', $this->get_row_value( $rating_column, 'Default' ) );
			$code_column = $this->find_row_by_value( $columns, 'Field', 'code' );
			$this->assertSame( 'varchar(80)', $this->get_row_value( $code_column, 'Type' ) );
			$this->assertSame( 'UNI', $this->get_row_value( $code_column, 'Key' ) );
			$this->assertSame( 'seed', $this->get_row_value( $code_column, 'Default' ) );
			$slug_column = $this->find_row_by_value( $columns, 'Field', 'slug' );
			$this->assertSame( 'varchar(255)', $this->get_row_value( $slug_column, 'Type' ) );
			$this->assertSame( 'MUL', $this->get_row_value( $slug_column, 'Key' ) );

			$indexes = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after DDL mutations',
				$backend_sql
			);
			$index_names = array();
			foreach ( $indexes as $index ) {
				$index_names[] = (string) $this->get_row_value( $index, 'Key_name' );
			}
			$this->assertContains( 'PRIMARY', $index_names );
			$this->assertContains( 'name_unique', $index_names );
			$this->assertContains( 'code', $index_names );
			$this->assertContains( 'slug', $index_names );
			$this->assertContains( 'status_unique', $index_names );
			$this->assertNotContains( 'rating_idx', $index_names );
			$slug_index = $this->find_row_by_value( $indexes, 'Key_name', 'slug' );
			$this->assertSame( 'slug', $this->get_row_value( $slug_index, 'Column_name' ) );
			$this->assertSame( '191', $this->get_row_value( $slug_index, 'Sub_part' ) );

			$this->assertSame( 0, $driver->query( sprintf( 'ALTER TABLE `%s` DROP PRIMARY KEY', $table ) ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP PRIMARY KEY',
				$backend_sql
			);
			$drop_primary_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" DROP CONSTRAINT "' . $table . '_pkey"', $drop_primary_sql );

			$this->assertSame( 0, $driver->query( sprintf( 'ALTER TABLE `%s` ADD PRIMARY KEY (`id`)', $table ) ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD PRIMARY KEY',
				$backend_sql
			);
			$add_primary_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" ADD PRIMARY KEY ("id")', $add_primary_sql );

			try {
				$driver->query( sprintf( 'ALTER TABLE `%s` DROP PRIMARY KEY', $no_primary_table ) );
				$this->fail( 'Expected DROP PRIMARY KEY without a PostgreSQL primary-key constraint to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ALTER TABLE statement.', $e->getMessage() );
			}
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP PRIMARY KEY without primary key',
				$backend_sql
			);

			try {
				$driver->query( sprintf( 'DROP INDEX PRIMARY ON `%s`', $no_primary_table ) );
				$this->fail( 'Expected DROP INDEX PRIMARY without a PostgreSQL primary-key constraint to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported DROP INDEX statement.', $e->getMessage() );
			}
			$this->collect_last_postgresql_queries(
				$driver,
				'DROP INDEX PRIMARY without primary key',
				$backend_sql
			);

			$table_status_rows = $driver->query( 'SHOW TABLE STATUS LIKE ' . $table_literal );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TABLE STATUS after DDL mutations',
				$backend_sql
			);
			$this->assertCount( 1, $table_status_rows );
			$this->assertSame( $table, $this->get_row_value( $table_status_rows[0], 'Name' ) );
			$this->assertSame( 'InnoDB', $this->get_row_value( $table_status_rows[0], 'Engine' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $table_status_rows[0], 'Collation' ) );
			$this->assertSame( 'Task 815 mutated table', $this->get_row_value( $table_status_rows[0], 'Comment' ) );

			$table_rows = $driver->query(
				"SELECT table_name, engine, table_collation, table_comment
				FROM information_schema.tables
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables after DDL mutations',
				$backend_sql
			);
			$this->assertCount( 1, $table_rows );
			$this->assertSame( $table, $this->get_row_value( $table_rows[0], 'TABLE_NAME' ) );
			$this->assertSame( 'InnoDB', $this->get_row_value( $table_rows[0], 'ENGINE' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $table_rows[0], 'TABLE_COLLATION' ) );
			$this->assertSame( 'Task 815 mutated table', $this->get_row_value( $table_rows[0], 'TABLE_COMMENT' ) );

			$column_rows = $driver->query(
				"SELECT column_name, column_type, column_key, column_default, column_comment
				FROM information_schema.columns
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY ordinal_position"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.columns after DDL mutations',
				$backend_sql
			);
			$this->assertCount( 6, $column_rows );
			$rating_information_schema_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'rating' );
			$this->assertSame( 'int', $this->get_row_value( $rating_information_schema_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'Rating note', $this->get_row_value( $rating_information_schema_column, 'COLUMN_COMMENT' ) );
			$code_information_schema_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'code' );
			$this->assertSame( 'varchar(80)', $this->get_row_value( $code_information_schema_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'UNI', $this->get_row_value( $code_information_schema_column, 'COLUMN_KEY' ) );
			$this->assertSame( 'Code note', $this->get_row_value( $code_information_schema_column, 'COLUMN_COMMENT' ) );
			$slug_information_schema_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'slug' );
			$this->assertSame( 'varchar(255)', $this->get_row_value( $slug_information_schema_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'MUL', $this->get_row_value( $slug_information_schema_column, 'COLUMN_KEY' ) );
			$this->assertSame( 'Slug note', $this->get_row_value( $slug_information_schema_column, 'COLUMN_COMMENT' ) );

			$statistics_rows = $driver->query(
				"SELECT index_name, column_name, sub_part, non_unique
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY index_name, seq_in_index"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics after DDL mutations',
				$backend_sql
			);
			$statistics_index_names = array();
			foreach ( $statistics_rows as $statistic ) {
				$statistics_index_names[] = (string) $this->get_row_value( $statistic, 'INDEX_NAME' );
			}
			$this->assertContains( 'PRIMARY', $statistics_index_names );
			$this->assertContains( 'name_unique', $statistics_index_names );
			$this->assertContains( 'code', $statistics_index_names );
			$this->assertContains( 'slug', $statistics_index_names );
			$this->assertContains( 'status_unique', $statistics_index_names );
			$this->assertNotContains( 'rating_idx', $statistics_index_names );
			$slug_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'slug' );
			$this->assertSame( 'slug', $this->get_row_value( $slug_statistic, 'COLUMN_NAME' ) );
			$this->assertSame( '191', $this->get_row_value( $slug_statistic, 'SUB_PART' ) );

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task815' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task815' ) );
		}
	}

	/**
	 * Tests real PostgreSQL ALTER TABLE COMMENT preserves table collation catalog metadata.
	 */
	public function test_real_pgsql_alter_table_comment_preserves_collation(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL ALTER TABLE COMMENT collation test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task932' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table         = 'task932_' . $suffix . '_comment';
		$table_literal = $driver->get_connection()->quote( $table );
		$backend_sql   = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`name` varchar(64) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci COMMENT='Original table note'",
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE collated table with comment',
				$backend_sql
			);

			$alter_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"ALTER TABLE `%s` COMMENT = 'Altered table note'",
						$table
					)
				)
			);
			$alter_logged_sql = implode( "\n", array_slice( $logged_sql, $alter_start ) );
			$this->assertStringContainsString( 'AS "TABLE_COMMENT"', $alter_logged_sql );
			$this->assertStringContainsString( 'AS "TABLE_COLLATION"', $alter_logged_sql );
			$this->assertStringContainsString( 'COMMENT ON TABLE "public"."' . $table . '" IS ', $alter_logged_sql );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE COMMENT preserves collation',
				$backend_sql
			);

			$comment_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertStringContainsString( '__wp_mysql_table_collation:bGF0aW4xX3N3ZWRpc2hfY2k=', $comment_sql );
			$this->assertStringContainsString( 'Altered table note', $comment_sql );
			$this->assertStringNotContainsString( 'Original table note', $comment_sql );

			$raw_comment_stmt = $pdo->prepare(
				"SELECT pg_catalog.obj_description(t.oid, 'pg_class')
				FROM pg_catalog.pg_class t
				INNER JOIN pg_catalog.pg_namespace n
					ON n.oid = t.relnamespace
				WHERE n.nspname = 'public'
					AND t.relname = ?"
			);
			$raw_comment_stmt->execute( array( $table ) );
			$raw_comment = (string) $raw_comment_stmt->fetchColumn();
			$this->assertStringContainsString( '__wp_mysql_table_collation:bGF0aW4xX3N3ZWRpc2hfY2k=', $raw_comment );
			$this->assertStringContainsString( 'Altered table note', $raw_comment );
			$this->assertStringNotContainsString( 'Original table note', $raw_comment );

			$create_rows = $driver->query( sprintf( 'SHOW CREATE TABLE `%s`', $table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE after ALTER TABLE COMMENT preserves collation',
				$backend_sql
			);
			$this->assertCount( 1, $create_rows );
			$create_table_sql = (string) $this->get_row_value( $create_rows[0], 'Create Table' );
			$this->assertStringContainsString( ') ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci', $create_table_sql );
			$this->assertStringContainsString( "COMMENT='Altered table note'", $create_table_sql );
			$this->assertStringNotContainsString( '__wp_mysql_table_collation:', $create_table_sql );

			$table_rows = $driver->query(
				"SELECT table_name, table_collation, table_comment
				FROM information_schema.tables
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables after ALTER TABLE COMMENT preserves collation',
				$backend_sql
			);
			$this->assertCount( 1, $table_rows );
			$this->assertSame( $table, $this->get_row_value( $table_rows[0], 'TABLE_NAME' ) );
			$this->assertSame( 'latin1_swedish_ci', $this->get_row_value( $table_rows[0], 'TABLE_COLLATION' ) );
			$this->assertSame( 'Altered table note', $this->get_row_value( $table_rows[0], 'TABLE_COMMENT' ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task932' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task932' ) );
		}
	}

	/**
	 * Tests real PostgreSQL DROP COLUMN and same-name ADD INDEX use catalogs.
	 */
	public function test_real_pgsql_drop_indexed_column_readd_index_uses_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL drop-column/index catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task898' );

		$database_name  = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection     = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver         = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table          = 'task898_' . $suffix . '_drop_readd';
		$table_literal  = $driver->get_connection()->quote( $table );
		$lookup_literal = $driver->get_connection()->quote( 'lookup' );
		$backend_sql    = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`obsolete` varchar(64) NOT NULL,
							`replacement` varchar(64) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE drop-column readd-index table',
				$backend_sql
			);

			$this->assertSame( 0, $driver->query( sprintf( 'ALTER TABLE `%s` ADD INDEX `lookup` (`obsolete`)', $table ) ) );
			$add_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD lookup index on obsolete',
				$backend_sql
			);
			$this->assertStringContainsString(
				'CREATE INDEX "' . $table . '__lookup" ON "' . $table . '" ("obsolete")',
				$add_index_sql
			);

			$initial_statistics_rows = $driver->query(
				"SELECT index_name, column_name
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
					AND index_name = {$lookup_literal}
				ORDER BY seq_in_index"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics before DROP COLUMN',
				$backend_sql
			);
			$this->assertCount( 1, $initial_statistics_rows );
			$this->assertSame( 'obsolete', $this->get_row_value( $initial_statistics_rows[0], 'COLUMN_NAME' ) );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							DROP COLUMN `obsolete`,
							ADD INDEX `lookup` (`replacement`)',
						$table
					)
				)
			);
			$drop_readd_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP COLUMN and readd same index name',
				$backend_sql
			);
			$this->assertStringContainsString( 'WITH index_columns AS', $drop_readd_sql );
			$this->assertStringContainsString( 'FROM pg_catalog.pg_class t', $drop_readd_sql );
			$this->assertStringContainsString( 'ALTER TABLE "' . $table . '" DROP COLUMN "obsolete"', $drop_readd_sql );
			$this->assertStringContainsString(
				'CREATE INDEX "' . $table . '__lookup" ON "' . $table . '" ("replacement")',
				$drop_readd_sql
			);

			$columns = $driver->query( 'SHOW COLUMNS FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS after DROP COLUMN and readd index',
				$backend_sql
			);
			$column_names = array_map(
				function ( $column ): string {
					return (string) $this->get_row_value( $column, 'Field' );
				},
				$columns
			);
			$this->assertContains( 'replacement', $column_names );
			$this->assertNotContains( 'obsolete', $column_names );

			$indexes = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after DROP COLUMN and readd index',
				$backend_sql
			);
			$lookup_index = $this->find_row_by_value( $indexes, 'Key_name', 'lookup' );
			$this->assertSame( 'replacement', $this->get_row_value( $lookup_index, 'Column_name' ) );

			$final_statistics_rows = $driver->query(
				"SELECT index_name, column_name
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
					AND index_name = {$lookup_literal}
				ORDER BY seq_in_index"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics after DROP COLUMN and readd index',
				$backend_sql
			);
			$this->assertCount( 1, $final_statistics_rows );
			$this->assertSame( 'replacement', $this->get_row_value( $final_statistics_rows[0], 'COLUMN_NAME' ) );

			$column_rows = $driver->query(
				"SELECT column_name
				FROM information_schema.columns
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY ordinal_position"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.columns after DROP COLUMN and readd index',
				$backend_sql
			);
			$information_schema_column_names = array_map(
				function ( $column ): string {
					return (string) $this->get_row_value( $column, 'COLUMN_NAME' );
				},
				$column_rows
			);
			$this->assertContains( 'replacement', $information_schema_column_names );
			$this->assertNotContains( 'obsolete', $information_schema_column_names );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task898' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task898' ) );
		}
	}

	/**
	 * Tests real PostgreSQL RENAME TABLE renames catalog-backed physical indexes.
	 */
	public function test_real_pgsql_rename_table_renames_catalog_indexes(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL rename-table index catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task902' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$old_table     = 'task902_' . $suffix . '_old';
		$new_table     = 'task902_' . $suffix . '_new';
		$child_table   = 'task902_' . $suffix . '_child';
		$new_literal   = $driver->get_connection()->quote( $new_table );
		$child_literal = $driver->get_connection()->quote( $child_table );
		$fk_literal    = $driver->get_connection()->quote( 'parent_fk' );
		$backend_sql   = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							`value` varchar(64) NOT NULL,
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_unique` (`slug`),
							KEY `value_idx` (`value`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$old_table
					)
				)
			);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE rename-table index table',
					$backend_sql
				);

				$this->assertSame(
					0,
					$driver->query(
						sprintf(
							'CREATE TABLE `%s` (
								`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
								`parent_id` bigint(20) unsigned NOT NULL,
								PRIMARY KEY (`id`),
								KEY `parent_idx` (`parent_id`),
								CONSTRAINT `parent_fk` FOREIGN KEY (`parent_id`) REFERENCES `%s` (`id`)
							) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
							$child_table,
							$old_table
						)
					)
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE rename-table child foreign-key table',
					$backend_sql
				);

				$initial_indexes = $driver->query( 'SHOW INDEX FROM `' . $old_table . '`' );
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW INDEX before RENAME TABLE',
					$backend_sql
				);
			$this->assertNotNull( $this->find_row_by_value( $initial_indexes, 'Key_name', 'slug_unique' ) );
			$this->assertNotNull( $this->find_row_by_value( $initial_indexes, 'Key_name', 'value_idx' ) );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'RENAME TABLE `%s` TO `%s`', $old_table, $new_table ) )
			);
			$rename_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'RENAME TABLE with catalog-backed index rename',
				$backend_sql
			);
			$this->assertStringContainsString( 'ALTER TABLE "public"."' . $old_table . '" RENAME TO "' . $new_table . '"', $rename_sql );
				$this->assertStringContainsString( 'ALTER INDEX "public"."' . $old_table . '__slug_unique" RENAME TO "' . $new_table . '__slug_unique"', $rename_sql );
				$this->assertStringContainsString( 'ALTER INDEX "public"."' . $old_table . '__value_idx" RENAME TO "' . $new_table . '__value_idx"', $rename_sql );

				$this->assertSame( array( $child_table, $new_table ), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task902' ) );

			$physical_indexes = $this->get_public_pgsql_index_names_for_table( $pdo, $new_table );
			$this->assertContains( $new_table . '__slug_unique', $physical_indexes );
			$this->assertContains( $new_table . '__value_idx', $physical_indexes );
			$this->assertNotContains( $old_table . '__slug_unique', $physical_indexes );
			$this->assertNotContains( $old_table . '__value_idx', $physical_indexes );

			$renamed_indexes = $driver->query( 'SHOW INDEX FROM `' . $new_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after RENAME TABLE',
				$backend_sql
			);
			$slug_index = $this->find_row_by_value( $renamed_indexes, 'Key_name', 'slug_unique' );
			$this->assertSame( 'slug', $this->get_row_value( $slug_index, 'Column_name' ) );
			$this->assertSame( '0', $this->get_row_value( $slug_index, 'Non_unique' ) );
			$value_index = $this->find_row_by_value( $renamed_indexes, 'Key_name', 'value_idx' );
			$this->assertSame( 'value', $this->get_row_value( $value_index, 'Column_name' ) );
			$this->assertSame( '1', $this->get_row_value( $value_index, 'Non_unique' ) );

			$statistics_rows = $driver->query(
				"SELECT index_name, column_name, non_unique
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$new_literal}
				ORDER BY index_name, seq_in_index"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics after RENAME TABLE',
				$backend_sql
			);
			$this->assertNotNull( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'slug_unique' ) );
			$this->assertNotNull( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'value_idx' ) );

			$foreign_key_rows = $driver->query(
				"SELECT constraint_name, table_name, referenced_table_name
				FROM information_schema.referential_constraints
				WHERE constraint_schema = DATABASE()
					AND table_name = {$child_literal}
					AND constraint_name = {$fk_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.referential_constraints after RENAME TABLE',
				$backend_sql
			);
			$this->assertCount( 1, $foreign_key_rows );
			$this->assertSame( 'parent_fk', $this->get_row_value( $foreign_key_rows[0], 'CONSTRAINT_NAME' ) );
			$this->assertSame( $child_table, $this->get_row_value( $foreign_key_rows[0], 'TABLE_NAME' ) );
			$this->assertSame( $new_table, $this->get_row_value( $foreign_key_rows[0], 'REFERENCED_TABLE_NAME' ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task902' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task902' ) );
		}
	}

	/**
	 * Tests real PostgreSQL ON UPDATE trigger rename/drop use catalogs.
	 */
	public function test_real_pgsql_on_update_trigger_rename_and_drop_use_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL ON UPDATE rename/drop catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task906' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver       = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix       = strtolower( bin2hex( random_bytes( 4 ) ) );
		$old_table    = 'task906_' . $suffix . '_old';
		$new_table    = 'task906_' . $suffix . '_new';
		$old_hash     = md5( "public\0{$old_table}\0updated_at" );
		$new_hash     = md5( "public\0{$new_table}\0updated_at" );
		$old_trigger  = '__wp_pg_on_update_' . $old_hash;
		$new_trigger  = '__wp_pg_on_update_' . $new_hash;
		$old_function = '__wp_pg_on_update_fn_' . $old_hash;
		$new_function = '__wp_pg_on_update_fn_' . $new_hash;
		$backend_sql  = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`payload` varchar(64) NOT NULL,
							`updated_at` timestamp NULL ON UPDATE CURRENT_TIMESTAMP,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$old_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE ON UPDATE table',
				$backend_sql
			);
			$this->assertTrue( $this->public_pgsql_trigger_exists( $pdo, $old_table, $old_trigger ) );
			$this->assertTrue( $this->public_pgsql_function_exists( $pdo, $old_function ) );

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`payload`) VALUES ('seed')", $old_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'INSERT ON UPDATE row',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "UPDATE `%s` SET `payload` = 'before-rename' WHERE `id` = 1", $old_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'UPDATE ON UPDATE row before rename',
				$backend_sql
			);

			$updated_rows = $driver->query( sprintf( 'SELECT `updated_at` FROM `%s` WHERE `id` = 1', $old_table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SELECT ON UPDATE timestamp before rename',
				$backend_sql
			);
			$this->assertCount( 1, $updated_rows );
			$this->assertNotSame( '', (string) $this->get_row_value( $updated_rows[0], 'updated_at' ) );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'RENAME TABLE `%s` TO `%s`', $old_table, $new_table ) )
			);
			$rename_sql = implode( "\n", $logged_sql );
			$this->collect_last_postgresql_queries(
				$driver,
				'RENAME TABLE ON UPDATE trigger',
				$backend_sql
			);
			$this->assertStringContainsString( 'FROM pg_catalog.pg_class t', $rename_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_trigger tr', $rename_sql );
			$this->assertStringContainsString( 'ALTER TABLE "public"."' . $old_table . '" RENAME TO "' . $new_table . '"', $rename_sql );
			$this->assertStringContainsString( 'DROP TRIGGER IF EXISTS "' . $old_trigger . '" ON "public"."' . $new_table . '"', $rename_sql );
			$this->assertStringContainsString( 'DROP FUNCTION IF EXISTS "public"."' . $old_function . '"()', $rename_sql );
			$this->assertStringContainsString( 'CREATE OR REPLACE FUNCTION "public"."' . $new_function . '"()', $rename_sql );
			$this->assertStringContainsString( 'CREATE TRIGGER "' . $new_trigger . '" BEFORE UPDATE ON "public"."' . $new_table . '"', $rename_sql );
			$this->assertFalse( $this->public_pgsql_trigger_exists( $pdo, $new_table, $old_trigger ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $old_function ) );
			$this->assertTrue( $this->public_pgsql_trigger_exists( $pdo, $new_table, $new_trigger ) );
			$this->assertTrue( $this->public_pgsql_function_exists( $pdo, $new_function ) );

			$this->assertSame(
				1,
				$driver->query( sprintf( "UPDATE `%s` SET `payload` = 'after-rename' WHERE `id` = 1", $new_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'UPDATE ON UPDATE row after rename',
				$backend_sql
			);

			$renamed_rows = $driver->query( sprintf( 'SELECT `payload`, `updated_at` FROM `%s` WHERE `id` = 1', $new_table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SELECT ON UPDATE timestamp after rename',
				$backend_sql
			);
			$this->assertCount( 1, $renamed_rows );
			$this->assertSame( 'after-rename', $this->get_row_value( $renamed_rows[0], 'payload' ) );
			$this->assertNotSame( '', (string) $this->get_row_value( $renamed_rows[0], 'updated_at' ) );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'DROP TABLE `public`.`%s`', $new_table ) )
			);
			$drop_sql = implode( "\n", $logged_sql );
			$this->collect_last_postgresql_queries(
				$driver,
				'DROP TABLE ON UPDATE trigger',
				$backend_sql
			);
			$this->assertStringContainsString( 'FROM pg_catalog.pg_class t', $drop_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_trigger tr', $drop_sql );
			$this->assertStringContainsString( 'DROP TRIGGER IF EXISTS "' . $new_trigger . '" ON "public"."' . $new_table . '"', $drop_sql );
			$this->assertStringContainsString( 'DROP FUNCTION IF EXISTS "public"."' . $new_function . '"()', $drop_sql );
			$this->assertStringContainsString( 'DROP TABLE "' . $new_table . '"', $drop_sql );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task906' ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $new_function ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task906' );
			$this->drop_public_pgsql_function( $pdo, $old_function );
			$this->drop_public_pgsql_function( $pdo, $new_function );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task906' ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $old_function ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $new_function ) );
		}
	}

	/**
	 * Tests real PostgreSQL current-schema DROP TABLE cleans ON UPDATE triggers.
	 */
	public function test_real_pgsql_current_schema_drop_table_cleans_on_update_trigger(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL current-schema DROP TABLE ON UPDATE cleanup test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task999' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name   = 'task999_' . $suffix;
		$table_name    = 'drop_target';
		$hash          = md5( "{$schema_name}\0{$table_name}\0updated_at" );
		$trigger_name  = '__wp_pg_on_update_' . $hash;
		$function_name = '__wp_pg_on_update_fn_' . $hash;
		$schema_sql    = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$backend_sql   = array();

		$trigger_exists = function ( string $schema, string $table, string $trigger ) use ( $pdo ): bool {
			$stmt = $pdo->prepare(
				'SELECT 1
				FROM pg_catalog.pg_trigger tr
				INNER JOIN pg_catalog.pg_class t
					ON t.oid = tr.tgrelid
				INNER JOIN pg_catalog.pg_namespace n
					ON n.oid = t.relnamespace
				WHERE n.nspname = ?
					AND t.relname = ?
					AND tr.tgname = ?
					AND NOT tr.tgisinternal
				LIMIT 1'
			);
			$stmt->execute( array( $schema, $table, $trigger ) );

			return false !== $stmt->fetchColumn();
		};

		$function_exists = function ( string $schema, string $function_name_to_check ) use ( $pdo ): bool {
			$stmt = $pdo->prepare(
				"SELECT 1
				FROM pg_catalog.pg_proc p
				INNER JOIN pg_catalog.pg_namespace n
					ON n.oid = p.pronamespace
				WHERE n.nspname = ?
					AND p.prokind = 'f'
					AND p.proname = ?
				LIMIT 1"
			);
			$stmt->execute( array( $schema, $function_name_to_check ) );

			return false !== $stmt->fetchColumn();
		};

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE task999 non-public schema',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`payload` varchar(64) NOT NULL,
							`updated_at` timestamp NULL ON UPDATE CURRENT_TIMESTAMP,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$table_name
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE current-schema ON UPDATE table',
				$backend_sql
			);
			$this->assertTrue( $trigger_exists( $schema_name, $table_name, $trigger_name ) );
			$this->assertTrue( $function_exists( $schema_name, $function_name ) );

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`payload`) VALUES ('seed')", $table_name ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'INSERT current-schema ON UPDATE row',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "UPDATE `%s` SET `payload` = 'updated' WHERE `id` = 1", $table_name ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'UPDATE current-schema ON UPDATE row',
				$backend_sql
			);

			$updated_rows = $driver->query( sprintf( 'SELECT `updated_at` FROM `%s` WHERE `id` = 1', $table_name ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SELECT current-schema ON UPDATE timestamp',
				$backend_sql
			);
			$this->assertCount( 1, $updated_rows );
			$this->assertNotSame( '', (string) $this->get_row_value( $updated_rows[0], 'updated_at' ) );

			$drop_log_start = count( $logged_sql );
			$this->assertSame( 0, $driver->query( 'DROP TABLE `' . $table_name . '`' ) );
			$drop_sql = implode( "\n", array_slice( $logged_sql, $drop_log_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'DROP current-schema ON UPDATE table',
				$backend_sql
			);
			$this->assertStringContainsString( 'FROM pg_catalog.pg_class t', $drop_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_trigger tr', $drop_sql );
			$this->assertStringContainsString( 'DROP TRIGGER IF EXISTS "' . $trigger_name . '" ON "' . $schema_name . '"."' . $table_name . '"', $drop_sql );
			$this->assertStringContainsString( 'DROP FUNCTION IF EXISTS "' . $schema_name . '"."' . $function_name . '"()', $drop_sql );
			$this->assertStringContainsString( 'DROP TABLE "' . $schema_name . '"."' . $table_name . '"', $drop_sql );
			$this->assertFalse( $function_exists( $schema_name, $function_name ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task999' ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$pdo->exec( 'SET search_path TO public' );
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task999' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task999' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task999' ) );
			$this->assertFalse( $function_exists( $schema_name, $function_name ) );
		}
	}

	/**
	 * Tests real PostgreSQL ON UPDATE column rename/change use catalogs.
	 */
	public function test_real_pgsql_on_update_trigger_column_rename_and_change_use_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL ON UPDATE column catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task930' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver       = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix       = strtolower( bin2hex( random_bytes( 4 ) ) );
		$rename_table = 'task930_' . $suffix . '_rename';
		$change_table = 'task930_' . $suffix . '_change';

		$rename_old_hash     = md5( "public\0{$rename_table}\0old_updated" );
		$rename_new_hash     = md5( "public\0{$rename_table}\0renamed_updated" );
		$rename_old_trigger  = '__wp_pg_on_update_' . $rename_old_hash;
		$rename_new_trigger  = '__wp_pg_on_update_' . $rename_new_hash;
		$rename_old_function = '__wp_pg_on_update_fn_' . $rename_old_hash;
		$rename_new_function = '__wp_pg_on_update_fn_' . $rename_new_hash;

		$change_old_hash         = md5( "public\0{$change_table}\0old_touched" );
		$change_touched_hash     = md5( "public\0{$change_table}\0touched_at" );
		$change_plain_hash       = md5( "public\0{$change_table}\0touched_plain" );
		$change_old_trigger      = '__wp_pg_on_update_' . $change_old_hash;
		$change_touched_trigger  = '__wp_pg_on_update_' . $change_touched_hash;
		$change_plain_trigger    = '__wp_pg_on_update_' . $change_plain_hash;
		$change_old_function     = '__wp_pg_on_update_fn_' . $change_old_hash;
		$change_touched_function = '__wp_pg_on_update_fn_' . $change_touched_hash;
		$change_plain_function   = '__wp_pg_on_update_fn_' . $change_plain_hash;
		$backend_sql             = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`payload` varchar(64) NOT NULL,
							`old_updated` timestamp NULL ON UPDATE CURRENT_TIMESTAMP,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$rename_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE ON UPDATE column rename table',
				$backend_sql
			);
			$this->assertTrue( $this->public_pgsql_trigger_exists( $pdo, $rename_table, $rename_old_trigger ) );
			$this->assertTrue( $this->public_pgsql_function_exists( $pdo, $rename_old_function ) );

			$rename_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s` RENAME COLUMN `old_updated` TO `renamed_updated`',
						$rename_table
					)
				)
			);
			$rename_sql = implode( "\n", array_slice( $logged_sql, $rename_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'RENAME COLUMN ON UPDATE trigger',
				$backend_sql
			);
			$this->assertStringContainsString( 'FROM pg_catalog.pg_trigger tr', $rename_sql );
			$this->assertStringContainsString( 'ALTER TABLE "' . $rename_table . '" RENAME COLUMN "old_updated" TO "renamed_updated"', $rename_sql );
			$this->assertStringContainsString( 'DROP TRIGGER IF EXISTS "' . $rename_old_trigger . '" ON "public"."' . $rename_table . '"', $rename_sql );
			$this->assertStringContainsString( 'DROP FUNCTION IF EXISTS "public"."' . $rename_old_function . '"()', $rename_sql );
			$this->assertStringContainsString( 'CREATE OR REPLACE FUNCTION "public"."' . $rename_new_function . '"()', $rename_sql );
			$this->assertStringContainsString( 'CREATE TRIGGER "' . $rename_new_trigger . '" BEFORE UPDATE ON "public"."' . $rename_table . '"', $rename_sql );
			$this->assertFalse( $this->public_pgsql_trigger_exists( $pdo, $rename_table, $rename_old_trigger ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $rename_old_function ) );
			$this->assertTrue( $this->public_pgsql_trigger_exists( $pdo, $rename_table, $rename_new_trigger ) );
			$this->assertTrue( $this->public_pgsql_function_exists( $pdo, $rename_new_function ) );

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`payload`) VALUES ('seed')", $rename_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'INSERT ON UPDATE column rename row',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "UPDATE `%s` SET `payload` = 'after-column-rename' WHERE `id` = 1", $rename_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'UPDATE ON UPDATE column rename row',
				$backend_sql
			);

			$renamed_rows = $driver->query( sprintf( 'SELECT `payload`, `renamed_updated` FROM `%s` WHERE `id` = 1', $rename_table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SELECT ON UPDATE column rename timestamp',
				$backend_sql
			);
			$this->assertCount( 1, $renamed_rows );
			$this->assertSame( 'after-column-rename', $this->get_row_value( $renamed_rows[0], 'payload' ) );
			$this->assertNotSame( '', (string) $this->get_row_value( $renamed_rows[0], 'renamed_updated' ) );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`payload` varchar(64) NOT NULL,
							`old_touched` timestamp NULL ON UPDATE CURRENT_TIMESTAMP,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$change_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE ON UPDATE change column table',
				$backend_sql
			);
			$this->assertTrue( $this->public_pgsql_trigger_exists( $pdo, $change_table, $change_old_trigger ) );
			$this->assertTrue( $this->public_pgsql_function_exists( $pdo, $change_old_function ) );

			$change_set_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"ALTER TABLE `%s` CHANGE COLUMN `old_touched` `touched_at` timestamp NULL ON UPDATE CURRENT_TIMESTAMP COMMENT 'Touched note'",
						$change_table
					)
				)
			);
			$change_set_sql = implode( "\n", array_slice( $logged_sql, $change_set_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'CHANGE COLUMN preserves ON UPDATE trigger',
				$backend_sql
			);
			$this->assertStringContainsString( 'FROM pg_catalog.pg_trigger tr', $change_set_sql );
			$this->assertStringContainsString( 'ALTER TABLE "' . $change_table . '" RENAME COLUMN "old_touched" TO "touched_at"', $change_set_sql );
			$this->assertStringContainsString( 'DROP TRIGGER IF EXISTS "' . $change_old_trigger . '" ON "public"."' . $change_table . '"', $change_set_sql );
			$this->assertStringContainsString( 'DROP FUNCTION IF EXISTS "public"."' . $change_old_function . '"()', $change_set_sql );
			$this->assertStringContainsString( 'CREATE OR REPLACE FUNCTION "public"."' . $change_touched_function . '"()', $change_set_sql );
			$this->assertStringContainsString( 'CREATE TRIGGER "' . $change_touched_trigger . '" BEFORE UPDATE ON "public"."' . $change_table . '"', $change_set_sql );
			$this->assertFalse( $this->public_pgsql_trigger_exists( $pdo, $change_table, $change_old_trigger ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $change_old_function ) );
			$this->assertTrue( $this->public_pgsql_trigger_exists( $pdo, $change_table, $change_touched_trigger ) );
			$this->assertTrue( $this->public_pgsql_function_exists( $pdo, $change_touched_function ) );

			$columns_after_set = $driver->query( sprintf( 'SHOW COLUMNS FROM `%s`', $change_table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS after preserving ON UPDATE trigger',
				$backend_sql
			);
			$touched_at_column = $this->find_row_by_value( $columns_after_set, 'Field', 'touched_at' );
			$this->assertStringContainsString( 'on update CURRENT_TIMESTAMP', (string) $this->get_row_value( $touched_at_column, 'Extra' ) );

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`payload`) VALUES ('seed')", $change_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'INSERT ON UPDATE change column row',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "UPDATE `%s` SET `payload` = 'after-change' WHERE `id` = 1", $change_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'UPDATE ON UPDATE change column row',
				$backend_sql
			);

			$changed_rows = $driver->query( sprintf( 'SELECT `payload`, `touched_at` FROM `%s` WHERE `id` = 1', $change_table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SELECT ON UPDATE change column timestamp',
				$backend_sql
			);
			$this->assertCount( 1, $changed_rows );
			$this->assertSame( 'after-change', $this->get_row_value( $changed_rows[0], 'payload' ) );
			$this->assertNotSame( '', (string) $this->get_row_value( $changed_rows[0], 'touched_at' ) );

			$change_drop_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"ALTER TABLE `%s` CHANGE COLUMN `touched_at` `touched_plain` timestamp NULL COMMENT 'Plain note'",
						$change_table
					)
				)
			);
			$change_drop_sql = implode( "\n", array_slice( $logged_sql, $change_drop_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'CHANGE COLUMN removes ON UPDATE trigger',
				$backend_sql
			);
			$this->assertStringContainsString( 'FROM pg_catalog.pg_trigger tr', $change_drop_sql );
			$this->assertStringContainsString( 'ALTER TABLE "' . $change_table . '" RENAME COLUMN "touched_at" TO "touched_plain"', $change_drop_sql );
			$this->assertStringContainsString( 'DROP TRIGGER IF EXISTS "' . $change_touched_trigger . '" ON "public"."' . $change_table . '"', $change_drop_sql );
			$this->assertStringContainsString( 'DROP FUNCTION IF EXISTS "public"."' . $change_touched_function . '"()', $change_drop_sql );
			$this->assertStringNotContainsString( 'CREATE TRIGGER "' . $change_plain_trigger . '"', $change_drop_sql );
			$this->assertFalse( $this->public_pgsql_trigger_exists( $pdo, $change_table, $change_touched_trigger ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $change_touched_function ) );
			$this->assertFalse( $this->public_pgsql_trigger_exists( $pdo, $change_table, $change_plain_trigger ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $change_plain_function ) );

			$columns_after_drop = $driver->query( sprintf( 'SHOW COLUMNS FROM `%s`', $change_table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS after removing ON UPDATE trigger',
				$backend_sql
			);
			$touched_plain_column = $this->find_row_by_value( $columns_after_drop, 'Field', 'touched_plain' );
			$this->assertStringNotContainsString( 'on update CURRENT_TIMESTAMP', (string) $this->get_row_value( $touched_plain_column, 'Extra' ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task930' );
			$this->drop_public_pgsql_function( $pdo, $rename_old_function );
			$this->drop_public_pgsql_function( $pdo, $rename_new_function );
			$this->drop_public_pgsql_function( $pdo, $change_old_function );
			$this->drop_public_pgsql_function( $pdo, $change_touched_function );
			$this->drop_public_pgsql_function( $pdo, $change_plain_function );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task930' ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $rename_old_function ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $rename_new_function ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $change_old_function ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $change_touched_function ) );
			$this->assertFalse( $this->public_pgsql_function_exists( $pdo, $change_plain_function ) );
		}
	}

	/**
	 * Tests real PostgreSQL metadata-only index rename/drop uses catalogs.
	 */
	public function test_real_pgsql_metadata_only_index_rename_and_drop_use_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL metadata-only DROP INDEX catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task910' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table         = 'task910_' . $suffix . '_indexes';
		$table_literal = $driver->get_connection()->quote( $table );
		$backend_sql   = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							`body` text,
							`shape` point,
							PRIMARY KEY (`id`),
							KEY `slug_idx` (`slug`),
							FULLTEXT KEY `body_fulltext` (`body`),
							SPATIAL KEY `shape_spatial` (`shape`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE metadata-only DROP INDEX table',
				$backend_sql
			);

			$initial_indexes = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX before metadata-only DROP INDEX',
				$backend_sql
			);
			$this->assertSame( 'BTREE', $this->get_row_value( $this->find_row_by_value( $initial_indexes, 'Key_name', 'slug_idx' ), 'Index_type' ) );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $initial_indexes, 'Key_name', 'body_fulltext' ), 'Index_type' ) );
			$this->assertSame( 'SPATIAL', $this->get_row_value( $this->find_row_by_value( $initial_indexes, 'Key_name', 'shape_spatial' ), 'Index_type' ) );

			$metadata_rename_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query( 'ALTER TABLE `' . $table . '` RENAME INDEX `body_fulltext` TO `body_search`' )
			);
			$metadata_rename_sql = implode( "\n", array_slice( $logged_sql, $metadata_rename_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'RENAME metadata-only FULLTEXT index',
				$backend_sql
			);
			$this->assertStringContainsString( 'ALTER INDEX "public"."' . $table . '__body_fulltext" RENAME TO "' . $table . '__body_search"', $metadata_rename_sql );

			$indexes_after_metadata_rename = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after metadata-only RENAME INDEX',
				$backend_sql
			);
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_metadata_rename, 'Key_name', 'body_fulltext' ) );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $indexes_after_metadata_rename, 'Key_name', 'body_search' ), 'Index_type' ) );
			$this->assertNotNull( $this->find_row_by_value( $indexes_after_metadata_rename, 'Key_name', 'slug_idx' ) );
			$this->assertNotNull( $this->find_row_by_value( $indexes_after_metadata_rename, 'Key_name', 'shape_spatial' ) );

			$statistics_after_metadata_rename = $driver->query(
				"SELECT index_name, index_type
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY index_name"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics after metadata-only RENAME INDEX',
				$backend_sql
			);
			$this->assertNull( $this->find_optional_row_by_value( $statistics_after_metadata_rename, 'INDEX_NAME', 'body_fulltext' ) );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $statistics_after_metadata_rename, 'INDEX_NAME', 'body_search' ), 'INDEX_TYPE' ) );

			$metadata_drop_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query( 'DROP INDEX `body_search` ON `' . $table . '`' )
			);
			$metadata_drop_sql = implode( "\n", array_slice( $logged_sql, $metadata_drop_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'DROP metadata-only FULLTEXT index',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP INDEX "public"."' . $table . '__body_search"', $metadata_drop_sql );

			$indexes_after_metadata_drop = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after metadata-only DROP INDEX',
				$backend_sql
			);
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_metadata_drop, 'Key_name', 'body_fulltext' ) );
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_metadata_drop, 'Key_name', 'body_search' ) );
			$this->assertNotNull( $this->find_row_by_value( $indexes_after_metadata_drop, 'Key_name', 'slug_idx' ) );
			$this->assertNotNull( $this->find_row_by_value( $indexes_after_metadata_drop, 'Key_name', 'shape_spatial' ) );

			$metadata_alter_drop_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query( 'ALTER TABLE `' . $table . '` DROP INDEX `shape_spatial`' )
			);
			$metadata_alter_drop_sql = implode( "\n", array_slice( $logged_sql, $metadata_alter_drop_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP metadata-only SPATIAL index',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP INDEX "public"."' . $table . '__shape_spatial"', $metadata_alter_drop_sql );

			$indexes_after_metadata_alter_drop = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after metadata-only ALTER TABLE DROP INDEX',
				$backend_sql
			);
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_metadata_alter_drop, 'Key_name', 'body_search' ) );
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_metadata_alter_drop, 'Key_name', 'shape_spatial' ) );
			$this->assertNotNull( $this->find_row_by_value( $indexes_after_metadata_alter_drop, 'Key_name', 'slug_idx' ) );

			$create_rows = $driver->query( 'SHOW CREATE TABLE `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE after metadata-only DROP INDEXes',
				$backend_sql
			);
			$create_table_sql = (string) $this->get_row_value( $create_rows[0], 'Create Table' );
			$this->assertStringNotContainsString( 'FULLTEXT KEY `body_fulltext`', $create_table_sql );
			$this->assertStringNotContainsString( 'FULLTEXT KEY `body_search`', $create_table_sql );
			$this->assertStringNotContainsString( 'SPATIAL KEY `shape_spatial`', $create_table_sql );

			$statistics_after_metadata_drop = $driver->query(
				"SELECT index_name, index_type
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY index_name"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics after metadata-only DROP INDEX',
				$backend_sql
			);
			$this->assertNull( $this->find_optional_row_by_value( $statistics_after_metadata_drop, 'INDEX_NAME', 'body_fulltext' ) );
			$this->assertNull( $this->find_optional_row_by_value( $statistics_after_metadata_drop, 'INDEX_NAME', 'body_search' ) );
			$this->assertSame( 'BTREE', $this->get_row_value( $this->find_row_by_value( $statistics_after_metadata_drop, 'INDEX_NAME', 'slug_idx' ), 'INDEX_TYPE' ) );
			$this->assertNull( $this->find_optional_row_by_value( $statistics_after_metadata_drop, 'INDEX_NAME', 'shape_spatial' ) );

			$regular_drop_start = count( $logged_sql );
			$this->assertSame(
				0,
				$driver->query( 'DROP INDEX `slug_idx` ON `' . $table . '`' )
			);
			$regular_drop_sql = implode( "\n", array_slice( $logged_sql, $regular_drop_start ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'DROP regular BTREE index',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP INDEX "public"."' . $table . '__slug_idx"', $regular_drop_sql );

			$indexes_after_regular_drop = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after regular DROP INDEX',
				$backend_sql
			);
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_regular_drop, 'Key_name', 'body_fulltext' ) );
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_regular_drop, 'Key_name', 'body_search' ) );
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_regular_drop, 'Key_name', 'slug_idx' ) );
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_regular_drop, 'Key_name', 'shape_spatial' ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task910' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task910' ) );
		}
	}

	/**
	 * Tests real PostgreSQL metadata-only index creation uses catalog placeholders.
	 */
	public function test_real_pgsql_metadata_only_index_creation_uses_catalog_placeholders(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL metadata-only index creation catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task944' );

		$database_name    = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection       = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver           = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix           = strtolower( bin2hex( random_bytes( 4 ) ) );
		$inline_table     = 'task944_' . $suffix . '_inline';
		$standalone_table = 'task944_' . $suffix . '_standalone';
		$alter_table      = 'task944_' . $suffix . '_alter';
		$backend_sql      = array();

		$assert_placeholder_sql = function ( string $sql, string $table_name, string $index_name, string $column_name, int $sub_part, string $type_marker ): void {
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__' . $index_name . '"', $sql );
			$this->assertStringContainsString( 'SUBSTR(CAST("' . $column_name . '" AS text), 1, ' . $sub_part . ')', $sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "public"."' . $table_name . '__' . $index_name . '" IS', $sql );
			$this->assertStringContainsString( $type_marker, $sql );
		};

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`body` text,
							`shape` point,
							FULLTEXT KEY `inline_body_fulltext` (`body`),
							SPATIAL KEY `inline_shape_spatial` (`shape`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$inline_table
					)
				)
			);
			$inline_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'public CREATE TABLE metadata-only indexes',
				$backend_sql
			);
			$assert_placeholder_sql( $inline_sql, $inline_table, 'inline_body_fulltext', 'body', 191, '__wp_mysql_index_type:RlVMTFRFWFQ=' );
			$assert_placeholder_sql( $inline_sql, $inline_table, 'inline_shape_spatial', 'shape', 32, '__wp_mysql_index_type:U1BBVElBTA==' );

			foreach ( array( $standalone_table, $alter_table ) as $table_name ) {
				$this->assertSame(
					0,
					$driver->query(
						sprintf(
							'CREATE TABLE `%s` (
								`id` int NOT NULL,
								`body` text,
								`shape` point
							) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
							$table_name
						)
					)
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'public CREATE TABLE metadata-only target',
					$backend_sql
				);
			}

			$this->assertSame(
				0,
				$driver->query( sprintf( 'CREATE FULLTEXT INDEX `standalone_body_fulltext` ON `%s` (`body`)', $standalone_table ) )
			);
			$standalone_fulltext_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'public CREATE FULLTEXT INDEX metadata-only placeholder',
				$backend_sql
			);
			$assert_placeholder_sql( $standalone_fulltext_sql, $standalone_table, 'standalone_body_fulltext', 'body', 191, '__wp_mysql_index_type:RlVMTFRFWFQ=' );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'CREATE SPATIAL INDEX `standalone_shape_spatial` ON `%s` (`shape`)', $standalone_table ) )
			);
			$standalone_spatial_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'public CREATE SPATIAL INDEX metadata-only placeholder',
				$backend_sql
			);
			$assert_placeholder_sql( $standalone_spatial_sql, $standalone_table, 'standalone_shape_spatial', 'shape', 32, '__wp_mysql_index_type:U1BBVElBTA==' );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							ADD FULLTEXT KEY `alter_body_fulltext` (`body`) COMMENT "Search docs",
							ADD SPATIAL INDEX `alter_shape_spatial` (`shape`)',
						$alter_table
					)
				)
			);
			$alter_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'public ALTER TABLE ADD metadata-only indexes',
				$backend_sql
			);
			$assert_placeholder_sql( $alter_sql, $alter_table, 'alter_body_fulltext', 'body', 191, '__wp_mysql_index_type:RlVMTFRFWFQ=' );
			$assert_placeholder_sql( $alter_sql, $alter_table, 'alter_shape_spatial', 'shape', 32, '__wp_mysql_index_type:U1BBVElBTA==' );
			$this->assertStringContainsString( 'Search docs', $alter_sql );

			foreach (
				array(
					$inline_table     => array( 'inline_body_fulltext', 'inline_shape_spatial' ),
					$standalone_table => array( 'standalone_body_fulltext', 'standalone_shape_spatial' ),
					$alter_table      => array( 'alter_body_fulltext', 'alter_shape_spatial' ),
				) as $table_name => $index_names
			) {
				$indexes = $driver->query( 'SHOW INDEX FROM `' . $table_name . '`' );
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW INDEX after public metadata-only placeholder creation',
					$backend_sql
				);
				$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $indexes, 'Key_name', $index_names[0] ), 'Index_type' ) );
				$this->assertSame( 'SPATIAL', $this->get_row_value( $this->find_row_by_value( $indexes, 'Key_name', $index_names[1] ), 'Index_type' ) );
			}

			$table_names_sql = implode(
				', ',
				array_map(
					array( $driver->get_connection(), 'quote' ),
					array( $inline_table, $standalone_table, $alter_table )
				)
			);
			$statistics_rows = $driver->query(
				"SELECT table_name, index_name, index_type, sub_part, index_comment
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name IN ({$table_names_sql})
				ORDER BY table_name, index_name"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics after public metadata-only placeholder creation',
				$backend_sql
			);
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'inline_body_fulltext' ), 'INDEX_TYPE' ) );
			$this->assertSame( 'SPATIAL', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'inline_shape_spatial' ), 'INDEX_TYPE' ) );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'standalone_body_fulltext' ), 'INDEX_TYPE' ) );
			$this->assertSame( 'SPATIAL', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'standalone_shape_spatial' ), 'INDEX_TYPE' ) );
			$alter_fulltext = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'alter_body_fulltext' );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $alter_fulltext, 'INDEX_TYPE' ) );
			$this->assertSame( 'Search docs', $this->get_row_value( $alter_fulltext, 'INDEX_COMMENT' ) );
			$this->assertSame( '32', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'alter_shape_spatial' ), 'SUB_PART' ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task944' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task944' ) );
		}
	}

	/**
	 * Tests real PostgreSQL unrecoverable index metadata fails.
	 */
	public function test_real_pgsql_unrecoverable_index_metadata_fails(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL unrecoverable index metadata test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1017' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql, array $params = array() ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver               = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix               = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table                = 'task1017_' . $suffix . '_target';
		$table_literal        = $driver->get_connection()->quote( $table );
		$failed_index         = 'uniq_shape_auto_spatial';
		$failed_index_literal = $driver->get_connection()->quote( $failed_index );
		$backend_sql          = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`body` text,
							`shape` point NOT NULL
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE unrecoverable index metadata target table',
				$backend_sql
			);

			$alter_start = count( $logged_sql );
			try {
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							ADD UNIQUE KEY `uniq_shape_auto_spatial` (`shape`)',
						$table
					)
				);
				$this->fail( 'Expected unrecoverable index metadata to fail closed.' );
			} catch ( PDOException $e ) {
				$this->fail( 'Expected recoverability exception, got raw PDOException: ' . $e->getMessage() );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported PostgreSQL catalog metadata for index statement.', $e->getMessage() );
				$this->assertNotSame( 'Unsupported ALTER TABLE statement.', $e->getMessage() );
				$this->assertNotSame( 'Unsupported CREATE INDEX statement.', $e->getMessage() );
			}

			$alter_sql = implode( "\n", array_slice( $logged_sql, $alter_start ) );
			$this->assertStringNotContainsString( '__wp_mysql_index_type:', $alter_sql );
			$this->assertStringNotContainsString( 'COMMENT ON INDEX', $alter_sql );
			$this->assertStringNotContainsString( 'CREATE INDEX "' . $table . '__' . $failed_index . '"', $alter_sql );
			$this->assertStringNotContainsString( 'CREATE UNIQUE INDEX "' . $table . '__' . $failed_index . '"', $alter_sql );

			$show_index_rows = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after unrecoverable index metadata failure',
				$backend_sql
			);
			$this->assertNull( $this->find_optional_row_by_value( $show_index_rows, 'Key_name', $failed_index ) );

			$statistics_rows = $driver->query(
				"SELECT index_name, index_comment
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
					AND index_name = {$failed_index_literal}
				ORDER BY index_name"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics after unrecoverable index metadata failure',
				$backend_sql
			);
			$this->assertSame( array(), $statistics_rows );

			$stmt = $pdo->prepare(
				"SELECT
					idx.relname,
					pg_catalog.obj_description(idx.oid, 'pg_class') AS index_comment
				FROM pg_catalog.pg_index i
				INNER JOIN pg_catalog.pg_class t
					ON t.oid = i.indrelid
				INNER JOIN pg_catalog.pg_namespace n
					ON n.oid = t.relnamespace
				INNER JOIN pg_catalog.pg_class idx
					ON idx.oid = i.indexrelid
				WHERE n.nspname = 'public'
					AND t.relname = ?
				ORDER BY idx.relname"
			);
			$stmt->execute( array( $table ) );
			$raw_catalog_index_rows = $stmt->fetchAll( PDO::FETCH_ASSOC );
			$this->assertSame( array(), $raw_catalog_index_rows );
			$this->assertNotContains( $table . '__' . $failed_index, $this->get_public_pgsql_index_names_for_table( $pdo, $table ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1017' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task1017' ) );
		}
	}

	/**
	 * Tests real PostgreSQL index-existence paths use catalogs.
	 */
	public function test_real_pgsql_index_existence_paths_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL index catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task892' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table         = 'task892_' . $suffix . '_indexes';
		$table_literal = $driver->get_connection()->quote( $table );
		$backend_sql   = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`value` varchar(255) NOT NULL,
							`status` varchar(20) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE index-existence table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							ADD INDEX `value_idx` (`value`(16)) COMMENT "Lookup",
							ADD INDEX `plain_idx` (`value`),
							ADD UNIQUE KEY `status_unique` (`status`)',
						$table
					)
				)
			);
			$add_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD INDEX and UNIQUE for index-existence paths',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE INDEX "' . $table . '__value_idx" ON "' . $table . '" (SUBSTR(CAST("value" AS text), 1, 16))', $add_index_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "public"."' . $table . '__value_idx" IS', $add_index_sql );
			$this->assertStringContainsString( '__wp_mysql_index_sub_part:1:16', $add_index_sql );
			$this->assertStringContainsString( 'Lookup', $add_index_sql );
			$this->assertStringContainsString( 'CREATE INDEX "' . $table . '__plain_idx" ON "' . $table . '" ("value")', $add_index_sql );
			$this->assertStringContainsString( 'CREATE UNIQUE INDEX "' . $table . '__status_unique" ON "' . $table . '" ("status")', $add_index_sql );

			try {
				$driver->query( sprintf( 'ALTER TABLE `%s` ADD INDEX `status_unique` (`status`)', $table ) );
				$this->fail( 'Expected duplicate ADD INDEX to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( "Duplicate key name 'status_unique'.", $e->getMessage() );
			}
			$duplicate_add_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'duplicate ALTER TABLE ADD INDEX',
				$backend_sql
			);
			$this->assertStringNotContainsString( 'CREATE INDEX', $duplicate_add_sql );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'ALTER TABLE `%s` RENAME INDEX `value_idx` TO `value_lookup`', $table ) )
			);
			$rename_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE RENAME INDEX value_idx',
				$backend_sql
			);
			$this->assertStringContainsString( 'ALTER INDEX "public"."' . $table . '__value_idx" RENAME TO "' . $table . '__value_lookup"', $rename_index_sql );

			try {
				$driver->query( sprintf( 'ALTER TABLE `%s` RENAME INDEX `missing_idx` TO `missing_lookup`', $table ) );
				$this->fail( 'Expected RENAME INDEX with a missing source to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ALTER TABLE statement.', $e->getMessage() );
			}
			$missing_rename_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE RENAME INDEX missing source',
				$backend_sql
			);
			$this->assertStringNotContainsString( 'ALTER INDEX', $missing_rename_sql );

			try {
				$driver->query( sprintf( 'ALTER TABLE `%s` RENAME INDEX `value_lookup` TO `status_unique`', $table ) );
				$this->fail( 'Expected RENAME INDEX with a duplicate target to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ALTER TABLE statement.', $e->getMessage() );
			}
			$duplicate_rename_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE RENAME INDEX duplicate target',
				$backend_sql
			);
			$this->assertStringNotContainsString( 'ALTER INDEX', $duplicate_rename_sql );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'ALTER TABLE `%s` DROP INDEX `plain_idx`', $table ) )
			);
			$drop_plain_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP INDEX plain_idx',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP INDEX "public"."' . $table . '__plain_idx"', $drop_plain_index_sql );

			try {
				$driver->query( sprintf( 'ALTER TABLE `%s` DROP CONSTRAINT `value_lookup`', $table ) );
				$this->fail( 'Expected DROP CONSTRAINT on a non-unique index to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ALTER TABLE statement.', $e->getMessage() );
			}
			$non_unique_drop_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP CONSTRAINT non-unique index',
				$backend_sql
			);
			$this->assertStringNotContainsString( 'DROP INDEX', $non_unique_drop_sql );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'ALTER TABLE `%s` DROP CONSTRAINT `status_unique`', $table ) )
			);
			$unique_drop_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP CONSTRAINT unique index',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP INDEX "public"."' . $table . '__status_unique"', $unique_drop_sql );

			$indexes = $driver->query( 'SHOW INDEX FROM `' . $table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after index-existence mutations',
				$backend_sql
			);
			$index_names = array();
			foreach ( $indexes as $index ) {
				$index_names[] = (string) $this->get_row_value( $index, 'Key_name' );
			}
			$this->assertContains( 'PRIMARY', $index_names );
			$this->assertContains( 'value_lookup', $index_names );
			$this->assertNotContains( 'value_idx', $index_names );
			$this->assertNotContains( 'plain_idx', $index_names );
			$this->assertNotContains( 'status_unique', $index_names );
			$value_lookup_index = $this->find_row_by_value( $indexes, 'Key_name', 'value_lookup' );
			$this->assertSame( 'value', $this->get_row_value( $value_lookup_index, 'Column_name' ) );
			$this->assertSame( '16', (string) $this->get_row_value( $value_lookup_index, 'Sub_part' ) );
			$this->assertSame( 'Lookup', $this->get_row_value( $value_lookup_index, 'Index_comment' ) );

			$statistics_rows = $driver->query(
				"SELECT index_name, column_name, sub_part, index_comment, non_unique
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY index_name, seq_in_index"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics after index-existence mutations',
				$backend_sql
			);
			$statistics_index_names = array();
			foreach ( $statistics_rows as $statistic ) {
				$statistics_index_names[] = (string) $this->get_row_value( $statistic, 'INDEX_NAME' );
			}
			$this->assertContains( 'PRIMARY', $statistics_index_names );
			$this->assertContains( 'value_lookup', $statistics_index_names );
			$this->assertNotContains( 'value_idx', $statistics_index_names );
			$this->assertNotContains( 'plain_idx', $statistics_index_names );
			$this->assertNotContains( 'status_unique', $statistics_index_names );
			$value_lookup_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'value_lookup' );
			$this->assertSame( 'value', $this->get_row_value( $value_lookup_statistic, 'COLUMN_NAME' ) );
			$this->assertSame( '16', (string) $this->get_row_value( $value_lookup_statistic, 'SUB_PART' ) );
			$this->assertSame( 'Lookup', $this->get_row_value( $value_lookup_statistic, 'INDEX_COMMENT' ) );
			$this->assertSame( '1', (string) $this->get_row_value( $value_lookup_statistic, 'NON_UNIQUE' ) );

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task892' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task892' ) );
		}
	}

	/**
	 * Tests real PostgreSQL current-schema index DDL/readback uses selected schema.
	 */
	public function test_real_pgsql_current_schema_index_and_describe_paths_use_selected_schema(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL current-schema index catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task994' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name   = 'task994_' . $suffix;
		$table_name    = 'index_target';
		$schema_sql    = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$table_sql     = $schema_sql . '.' . WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$table_literal = $driver->get_connection()->quote( $table_name );
		$backend_sql   = array();

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );
			$pdo->exec(
				'CREATE TABLE ' . $table_sql . ' (
					id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
					value varchar(64) NOT NULL,
					body text
				)'
			);

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$use_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'USE task994 non-public schema',
				$backend_sql
			);
			$this->assertCount( 1, $use_queries );
			$this->assertStringContainsString( 'FROM information_schema.schemata s', $use_queries[0]['sql'] );
			$this->assertSame( array( $schema_name ), $use_queries[0]['params'] );

			$this->assertSame(
				0,
				$driver->query( 'CREATE INDEX `value_idx` ON `' . $table_name . '` (`value`) COMMENT "Lookup"' )
			);
			$create_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema CREATE INDEX',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__value_idx" ON "' . $schema_name . '"."' . $table_name . '" ("value")', $create_index_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__value_idx" IS', $create_index_sql );
			$this->assertStringContainsString( 'Lookup', $create_index_sql );
			$this->assertStringNotContainsString( '"public"."' . $table_name . '"', $create_index_sql );

			$this->assertSame(
				0,
				$driver->query( 'CREATE INDEX `explicit_idx` ON `' . $schema_name . '`.`' . $table_name . '` (`value`) COMMENT "Explicit"' )
			);
			$explicit_create_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit same-schema CREATE INDEX',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__explicit_idx" ON "' . $schema_name . '"."' . $table_name . '" ("value")', $explicit_create_index_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__explicit_idx" IS', $explicit_create_index_sql );
			$this->assertStringContainsString( 'Explicit', $explicit_create_index_sql );

			$indexes = $driver->query( 'SHOW INDEX FROM `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after current-schema CREATE INDEX',
				$backend_sql
			);
			$value_index = $this->find_row_by_value( $indexes, 'Key_name', 'value_idx' );
			$this->assertSame( $table_name, $this->get_row_value( $value_index, 'Table' ) );
			$this->assertSame( 'value', $this->get_row_value( $value_index, 'Column_name' ) );
			$this->assertSame( 'Lookup', $this->get_row_value( $value_index, 'Index_comment' ) );
			$explicit_index = $this->find_row_by_value( $indexes, 'Key_name', 'explicit_idx' );
			$this->assertSame( $table_name, $this->get_row_value( $explicit_index, 'Table' ) );
			$this->assertSame( 'value', $this->get_row_value( $explicit_index, 'Column_name' ) );
			$this->assertSame( 'Explicit', $this->get_row_value( $explicit_index, 'Index_comment' ) );

			$statistics_rows = $driver->query(
				"SELECT table_schema, table_name, index_name, column_name, index_comment
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
					AND index_name IN ('value_idx', 'explicit_idx')
				ORDER BY index_name"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics for current-schema indexes',
				$backend_sql
			);
			$this->assertCount( 2, $statistics_rows );
			foreach ( $statistics_rows as $statistics_row ) {
				$this->assertSame( $schema_name, $this->get_row_value( $statistics_row, 'TABLE_SCHEMA' ) );
				$this->assertSame( $table_name, $this->get_row_value( $statistics_row, 'TABLE_NAME' ) );
				$this->assertSame( 'value', $this->get_row_value( $statistics_row, 'COLUMN_NAME' ) );
			}
			$this->assertSame( 'Explicit', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'explicit_idx' ), 'INDEX_COMMENT' ) );
			$this->assertSame( 'Lookup', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'value_idx' ), 'INDEX_COMMENT' ) );

			$describe_rows = $driver->query( 'DESCRIBE `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'DESCRIBE current-schema table',
				$backend_sql
			);
			$this->assertNotNull( $this->find_row_by_value( $describe_rows, 'Field', 'id' ) );
			$value_column = $this->find_row_by_value( $describe_rows, 'Field', 'value' );
			$this->assertSame( 'varchar(64)', $this->get_row_value( $value_column, 'Type' ) );
			$this->assertNotNull( $this->find_row_by_value( $describe_rows, 'Field', 'body' ) );

			$this->assertSame( 0, $driver->query( 'DROP INDEX `value_idx` ON `' . $table_name . '`' ) );
			$drop_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema DROP INDEX',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP INDEX "' . $schema_name . '"."' . $table_name . '__value_idx"', $drop_index_sql );
			$this->assertStringNotContainsString( '"public"."' . $table_name . '__value_idx"', $drop_index_sql );

			$this->assertSame( 0, $driver->query( 'DROP INDEX `explicit_idx` ON `' . $schema_name . '`.`' . $table_name . '`' ) );
			$explicit_drop_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit same-schema DROP INDEX',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP INDEX "' . $schema_name . '"."' . $table_name . '__explicit_idx"', $explicit_drop_index_sql );

			$indexes_after_drop = $driver->query( 'SHOW INDEX FROM `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after current-schema DROP INDEX',
				$backend_sql
			);
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_drop, 'Key_name', 'value_idx' ) );
			$this->assertNull( $this->find_optional_row_by_value( $indexes_after_drop, 'Key_name', 'explicit_idx' ) );
			$this->assertNotNull( $this->find_row_by_value( $indexes_after_drop, 'Key_name', 'PRIMARY' ) );

			foreach (
				array(
					'CREATE INDEX `blocked_idx` ON `pg_catalog`.`pg_class` (`relname`)' => 'Unsupported CREATE INDEX statement.',
					'DROP INDEX `blocked_idx` ON `pg_catalog`.`pg_class`' => 'Unsupported DROP INDEX statement.',
					'DESCRIBE `pg_catalog`.`pg_class`' => 'Unsupported DESCRIBE statement.',
				) as $query => $message
			) {
				try {
					$driver->query( $query );
					$this->fail( 'Expected internal PostgreSQL schema DDL/readback to fail closed.' );
				} catch ( InvalidArgumentException $e ) {
					$this->assertSame( $message, $e->getMessage(), $query );
					$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
				}
			}

			$all_backend_sql = implode( "\n", $backend_sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $all_backend_sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$pdo->exec( 'SET search_path TO public' );
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task994' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task994' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task994' ) );
		}
	}

	/**
	 * Tests real PostgreSQL schema identifiers and temporary drops use PostgreSQL syntax.
	 */
	public function test_real_pgsql_schema_identifier_and_temporary_drop_paths_use_postgresql_identifiers(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL schema identifier and temporary drop test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task1042' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1042' );

		$database_name         = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection            = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver                = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix                = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name           = 'task1042_' . $suffix;
		$public_table          = 'task1042_' . $suffix . '_public';
		$shadow_table          = 'task1042_' . $suffix . '_shadow';
		$selected_table        = 'selected_target';
		$schema_drop_table     = 'drop_target';
		$schema_sql            = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$shadow_table_sql      = WP_PostgreSQL_Connection::quote_identifier_value( 'public' ) . '.' . WP_PostgreSQL_Connection::quote_identifier_value( $shadow_table );
		$schema_drop_table_sql = $schema_sql . '.' . WP_PostgreSQL_Connection::quote_identifier_value( $schema_drop_table );
		$backend_sql           = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`value` varchar(20) NOT NULL,
							PRIMARY KEY (`id`)
						)',
						$public_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE public task1042 table',
				$backend_sql
			);

			$this->assertSame( 0, $driver->query( 'CREATE INDEX `value_lookup` ON `public`.`' . $public_table . '` (`value`)' ) );
			$create_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit public CREATE INDEX',
				$backend_sql
			);
			$this->assertStringContainsString(
				'CREATE INDEX "' . $public_table . '__value_lookup" ON "public"."' . $public_table . '" ("value")',
				$create_index_sql
			);
			$this->assertContains( $public_table . '__value_lookup', $this->get_public_pgsql_index_names_for_table( $pdo, $public_table ) );

			$this->assertSame( 0, $driver->query( 'DROP INDEX `value_lookup` ON `public`.`' . $public_table . '`' ) );
			$drop_index_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit public DROP INDEX',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP INDEX "public"."' . $public_table . '__value_lookup"', $drop_index_sql );
			$this->assertNotContains( $public_table . '__value_lookup', $this->get_public_pgsql_index_names_for_table( $pdo, $public_table ) );

			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$use_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'USE task1042 non-public schema',
				$backend_sql
			);
			$this->assertCount( 1, $use_queries );
			$this->assertStringContainsString( 'FROM information_schema.schemata s', $use_queries[0]['sql'] );
			$this->assertSame( array( $schema_name ), $use_queries[0]['params'] );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`value` varchar(20) NOT NULL,
							PRIMARY KEY (`id`)
						)',
						$selected_table
					)
				)
			);
			$selected_create_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'selected-schema CREATE TABLE',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TABLE "' . $schema_name . '"."' . $selected_table . '"', $selected_create_sql );

			$this->assertSame( 1, $driver->query( "INSERT INTO `{$selected_table}` (`id`, `value`) VALUES (1, 'selected')" ) );
			$selected_insert_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'selected-schema unqualified INSERT',
				$backend_sql
			);
			$this->assertStringContainsString( 'INSERT INTO "' . $schema_name . '"."' . $selected_table . '"', $selected_insert_sql );

			$selected_rows       = $driver->query( 'SELECT `id`, `value` FROM `' . $selected_table . '`' );
			$selected_select_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'selected-schema unqualified SELECT',
				$backend_sql
			);
			$this->assertCount( 1, $selected_rows );
			$this->assertSame( 'selected', $this->get_row_value( $selected_rows[0], 'value' ) );
			$this->assertStringContainsString( 'FROM "' . $schema_name . '"."' . $selected_table . '"', $selected_select_sql );

			$pdo->exec(
				'CREATE TABLE ' . $schema_drop_table_sql . ' (
					id integer NOT NULL
				)'
			);
			$this->assertSame( 0, $driver->query( 'DROP TABLE `' . $schema_name . '`.`' . $schema_drop_table . '`' ) );
			$schema_drop_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit non-public DROP TABLE',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP TABLE "' . $schema_name . '"."' . $schema_drop_table . '"', $schema_drop_sql );
			$this->assertSame(
				'0',
				(string) $pdo->query( 'SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = ' . $pdo->quote( $schema_name ) . ' AND table_name = ' . $pdo->quote( $schema_drop_table ) )->fetchColumn()
			);

			$this->assertSame( 0, $driver->query( 'USE public' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE public before temporary shadow table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`value` varchar(20) NOT NULL,
							PRIMARY KEY (`id`)
						)',
						$shadow_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE permanent shadow table',
				$backend_sql
			);

			$this->assertSame( 1, $driver->query( "INSERT INTO `{$shadow_table}` (`id`, `value`) VALUES (1, 'permanent')" ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'seed permanent shadow table',
				$backend_sql
			);
			$this->assertSame( array( 'permanent' ), $pdo->query( 'SELECT value FROM ' . $shadow_table_sql . ' ORDER BY id' )->fetchAll( PDO::FETCH_COLUMN ) );

			$this->assertSame( 0, $driver->query( 'CREATE TEMPORARY TABLE `' . $shadow_table . '` (`id` int NOT NULL, `value` varchar(20) NOT NULL)' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE temporary shadow table',
				$backend_sql
			);

			$this->assertSame( 1, $driver->query( "INSERT INTO `{$shadow_table}` (`id`, `value`) VALUES (2, 'temporary')" ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'seed temporary shadow table',
				$backend_sql
			);

			$temporary_rows = $driver->query( 'SELECT `value` FROM `' . $shadow_table . '` ORDER BY `id`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read temporary shadow table before DROP TEMPORARY',
				$backend_sql
			);
			$this->assertCount( 1, $temporary_rows );
			$this->assertSame( 'temporary', $this->get_row_value( $temporary_rows[0], 'value' ) );

			$this->assertSame( 0, $driver->query( 'DROP TEMPORARY TABLE `' . $shadow_table . '`' ) );
			$drop_temporary_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'DROP TEMPORARY TABLE with active temp table',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP TABLE pg_temp."' . $shadow_table . '"', $drop_temporary_sql );
			$this->assertSame( array( 'permanent' ), $pdo->query( 'SELECT value FROM ' . $shadow_table_sql . ' ORDER BY id' )->fetchAll( PDO::FETCH_COLUMN ) );

			try {
				$driver->query( 'DROP TEMPORARY TABLE `' . $shadow_table . '`' );
				$this->fail( 'DROP TEMPORARY TABLE without an active temp table should fail.' );
			} catch ( PDOException $e ) {
				$this->assertNotSame( '', $e->getMessage() );
			}
			$this->assertSame( array( 'permanent' ), $pdo->query( 'SELECT value FROM ' . $shadow_table_sql . ' ORDER BY id' )->fetchAll( PDO::FETCH_COLUMN ) );

			$this->assertSame( 0, $driver->query( 'DROP TEMPORARY TABLE IF EXISTS `' . $shadow_table . '`' ) );
			$drop_temporary_if_exists_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'DROP TEMPORARY TABLE IF EXISTS without active temp table',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP TABLE IF EXISTS pg_temp."' . $shadow_table . '"', $drop_temporary_if_exists_sql );
			$this->assertSame( array( 'permanent' ), $pdo->query( 'SELECT value FROM ' . $shadow_table_sql . ' ORDER BY id' )->fetchAll( PDO::FETCH_COLUMN ) );

			$all_backend_sql = implode( "\n", $backend_sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $all_backend_sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$pdo->exec( 'DROP TABLE IF EXISTS pg_temp.' . WP_PostgreSQL_Connection::quote_identifier_value( $shadow_table ) );
			$pdo->exec( 'SET search_path TO public' );
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task1042' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1042' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task1042' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task1042' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task1042' ) );
		}
	}

	/**
	 * Tests public table reads skip repeated per-table temporary schema probes.
	 */
	public function test_real_pgsql_public_table_resolution_skips_per_table_temporary_probe(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL public table schema cache test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1042_cache' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name    = 'task1042_cache_' . $suffix;
		$dummy_name    = 'task1042_cache_dummy_' . $suffix;
		$logged_sql    = array();

		$connection->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`value` varchar(20) NOT NULL,
							PRIMARY KEY (`id`)
						)',
						$table_name
					)
				)
			);
			$this->assertSame( 1, $driver->query( "INSERT INTO `{$table_name}` (`id`, `value`) VALUES (1, 'public')" ) );

			/*
			 * DDL clears metadata caches. The following read should still avoid
			 * the expensive per-table temporary schema lookup when no temporary
			 * table exists on the connection.
			 */
			$this->assertSame( 0, $driver->query( "CREATE TABLE `{$dummy_name}` (`id` int NOT NULL)" ) );
			$this->assertSame( 0, $driver->query( "DROP TABLE `{$dummy_name}`" ) );

			$logged_sql = array();
			$rows       = $driver->query( 'SELECT `value` FROM `' . $table_name . '` WHERE `id` = 1' );

			$this->assertCount( 1, $rows );
			$this->assertSame( 'public', $this->get_row_value( $rows[0], 'value' ) );
			$this->assertStringNotContainsString(
				'SELECT n.nspname',
				implode( "\n", $logged_sql )
			);
		} finally {
			$pdo->exec( 'SET search_path TO public' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1042_cache' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task1042_cache' ) );
		}
	}

	/**
	 * Tests the direct column metadata API returns SHOW COLUMNS-compatible rows.
	 */
	public function test_real_pgsql_column_charset_metadata_api_matches_show_columns_and_resolves_temporary_tables(): void {
		$driver     = $this->create_real_pgsql_driver();
		$pdo        = $driver->get_connection()->get_pdo();
		$suffix     = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name = 'task_direct_meta_' . $suffix;

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task_direct_meta' );

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
							`body` text CHARACTER SET big5,
							`views` int NOT NULL
						)',
						$table_name
					)
				)
			);

			$metadata_rows = $driver->get_mysql_column_charset_metadata_for_table( $table_name );
			$show_rows     = $driver->query( 'SHOW FULL COLUMNS FROM `' . $table_name . '`', PDO::FETCH_ASSOC );

			$this->assertSame(
				array_map(
					static function ( array $row ): array {
						return array(
							'column_name'    => $row['Field'],
							'column_type'    => $row['Type'],
							'collation_name' => $row['Collation'],
						);
					},
					$show_rows
				),
				$metadata_rows
			);

			$title_metadata = $this->find_row_by_value( $metadata_rows, 'column_name', 'title' );
			$this->assertSame( 'varchar(64)', $this->get_row_value( $title_metadata, 'column_type' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $title_metadata, 'collation_name' ) );
			$views_metadata = $this->find_row_by_value( $metadata_rows, 'column_name', 'views' );
			$this->assertNull( $this->get_row_value( $views_metadata, 'collation_name' ) );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TEMPORARY TABLE `%s` (
							`title` text CHARACTER SET big5,
							`views` int NOT NULL
						)',
						$table_name
					)
				)
			);

			$temporary_metadata_rows = $driver->get_mysql_column_charset_metadata_for_table( $table_name );
			$temporary_show_rows     = $driver->query( 'SHOW FULL COLUMNS FROM `' . $table_name . '`', PDO::FETCH_ASSOC );

			$this->assertSame( array( 'title', 'views' ), array_column( $temporary_metadata_rows, 'column_name' ) );
			$temp_title_metadata = $this->find_row_by_value( $temporary_metadata_rows, 'column_name', 'title' );
			$this->assertSame( 'text', $this->get_row_value( $temp_title_metadata, 'column_type' ) );
			$this->assertSame( 'big5_chinese_ci', $this->get_row_value( $temp_title_metadata, 'collation_name' ) );
			$this->assertSame(
				array_map(
					static function ( array $row ): array {
						return array(
							'column_name'    => $row['Field'],
							'column_type'    => $row['Type'],
							'collation_name' => $row['Collation'],
						);
					},
					$temporary_show_rows
				),
				$temporary_metadata_rows
			);
		} finally {
			$pdo->exec( 'DROP TABLE IF EXISTS pg_temp.' . WP_PostgreSQL_Connection::quote_identifier_value( $table_name ) );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task_direct_meta' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task_direct_meta' ) );
		}
	}

	/**
	 * Tests real PostgreSQL current-schema CREATE TABLE and VIEW DDL use selected schema.
	 */
	public function test_real_pgsql_current_schema_create_table_and_view_ddl_use_selected_schema(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL current-schema CREATE TABLE and VIEW DDL test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task1003' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1003' );
		$this->drop_public_pgsql_views_with_prefix( $pdo, 'task1003' );

		$database_name      = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection         = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver             = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix             = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name        = 'task1003_' . $suffix;
		$table_name         = 'task1003_' . $suffix . '_table';
		$view_name          = 'task1003_' . $suffix . '_view';
		$explicit_view_name = 'task1003_' . $suffix . '_explicit_view';
		$schema_sql         = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$backend_sql        = array();

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$use_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'USE task1003 non-public schema',
				$backend_sql
			);
			$this->assertCount( 1, $use_queries );
			$this->assertStringContainsString( 'FROM information_schema.schemata s', $use_queries[0]['sql'] );
			$this->assertSame( array( $schema_name ), $use_queries[0]['params'] );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` int NOT NULL,
							`slug` varchar(191) NOT NULL DEFAULT 'draft' COMMENT 'Slug note',
							`title` varchar(191) NOT NULL,
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_lookup` (`slug`) COMMENT 'Slug lookup note'
						) COMMENT='Catalog table note'",
						$table_name
					)
				)
			);
			$create_table_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema CREATE TABLE with comments and unique index',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TABLE "' . $schema_name . '"."' . $table_name . '"', $create_table_sql );
			$this->assertStringContainsString( 'CREATE UNIQUE INDEX "' . $table_name . '__slug_lookup" ON "' . $schema_name . '"."' . $table_name . '" ("slug")', $create_table_sql );
			$this->assertStringContainsString( 'COMMENT ON TABLE "' . $schema_name . '"."' . $table_name . '" IS', $create_table_sql );
			$this->assertStringContainsString( 'COMMENT ON COLUMN "' . $schema_name . '"."' . $table_name . '"."slug" IS', $create_table_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__slug_lookup" IS', $create_table_sql );
			$this->assertStringContainsString( 'Catalog table note', $create_table_sql );
			$this->assertStringContainsString( 'Slug note', $create_table_sql );
			$this->assertStringContainsString( 'Slug lookup note', $create_table_sql );
			$this->assertStringNotContainsString( '"public"."' . $table_name . '"', $create_table_sql );

			$catalog_stmt = $pdo->prepare(
				"SELECT
					n.nspname,
					c.relname,
					pg_catalog.obj_description(c.oid, 'pg_class') AS table_comment,
					pg_catalog.col_description(c.oid, a.attnum) AS slug_comment,
					pg_catalog.obj_description(idx.oid, 'pg_class') AS index_comment,
					idx.relname AS index_name
				FROM pg_catalog.pg_class c
				INNER JOIN pg_catalog.pg_namespace n
					ON n.oid = c.relnamespace
				INNER JOIN pg_catalog.pg_attribute a
					ON a.attrelid = c.oid
					AND a.attname = 'slug'
				INNER JOIN pg_catalog.pg_index i
					ON i.indrelid = c.oid
					AND i.indisunique
				INNER JOIN pg_catalog.pg_class idx
					ON idx.oid = i.indexrelid
					AND idx.relname = ?
				WHERE n.nspname = ?
					AND c.relname = ?
					AND c.relkind IN ('r', 'p')"
			);
			$catalog_stmt->execute( array( $table_name . '__slug_lookup', $schema_name, $table_name ) );
			$catalog_row = $catalog_stmt->fetch( PDO::FETCH_ASSOC );
			$this->assertIsArray( $catalog_row );
			$this->assertSame( $schema_name, $catalog_row['nspname'] );
			$this->assertSame( $table_name, $catalog_row['relname'] );
			$this->assertSame( 'Catalog table note', $catalog_row['table_comment'] );
			$this->assertSame( 'Slug note', $catalog_row['slug_comment'] );
			$this->assertSame( 'Slug lookup note', $catalog_row['index_comment'] );
			$this->assertSame( $table_name . '__slug_lookup', $catalog_row['index_name'] );

			$public_table_count = (int) $pdo->query(
				'SELECT COUNT(*)
				FROM information_schema.tables
				WHERE table_schema = ' . $pdo->quote( 'public' ) . '
					AND table_name = ' . $pdo->quote( $table_name )
			)->fetchColumn();
			$this->assertSame( 0, $public_table_count );

			$show_create_rows = $driver->query( 'SHOW CREATE TABLE `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE after current-schema CREATE TABLE',
				$backend_sql
			);
			$this->assertCount( 1, $show_create_rows );
			$show_create_sql = (string) $this->get_row_value( $show_create_rows[0], 'Create Table' );
			$this->assertStringContainsString( 'CREATE TABLE `' . $table_name . '`', $show_create_sql );
			$this->assertStringContainsString( 'UNIQUE KEY `slug_lookup` (`slug`)', $show_create_sql );
			$this->assertStringContainsString( 'COMMENT=\'Catalog table note\'', $show_create_sql );
			$this->assertStringContainsString( 'COMMENT \'Slug note\'', $show_create_sql );

			$indexes = $driver->query( 'SHOW INDEX FROM `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX after current-schema CREATE TABLE',
				$backend_sql
			);
			$slug_index = $this->find_row_by_value( $indexes, 'Key_name', 'slug_lookup' );
			$this->assertSame( $table_name, $this->get_row_value( $slug_index, 'Table' ) );
			$this->assertSame( 'slug', $this->get_row_value( $slug_index, 'Column_name' ) );
			$this->assertSame( 'Slug lookup note', $this->get_row_value( $slug_index, 'Index_comment' ) );

			$this->assertSame(
				0,
				$driver->query( 'CREATE VIEW `' . $view_name . '` AS SELECT `id`, `slug` FROM `' . $table_name . '`' )
			);
			$create_view_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema CREATE VIEW',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE VIEW "' . $schema_name . '"."' . $view_name . '" AS SELECT', $create_view_sql );
			$this->assertStringContainsString( 'FROM "' . $schema_name . '"."' . $table_name . '"', $create_view_sql );
			$this->assertStringNotContainsString( '"public"."' . $view_name . '"', $create_view_sql );

			$this->assertSame(
				0,
				$driver->query( 'CREATE OR REPLACE VIEW `' . $schema_name . '`.`' . $explicit_view_name . '` AS SELECT `id` FROM `' . $schema_name . '`.`' . $table_name . '`' )
			);
			$explicit_create_view_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit same-schema CREATE OR REPLACE VIEW',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE OR REPLACE VIEW "' . $schema_name . '"."' . $explicit_view_name . '" AS SELECT', $explicit_create_view_sql );
			$this->assertStringContainsString( 'FROM "' . $schema_name . '"."' . $table_name . '"', $explicit_create_view_sql );

			$view_stmt = $pdo->prepare(
				'SELECT table_name
				FROM information_schema.views
				WHERE table_schema = ?
					AND table_name IN (?, ?)
				ORDER BY table_name'
			);
			$view_stmt->execute( array( $schema_name, $explicit_view_name, $view_name ) );
			$this->assertSame( array( $explicit_view_name, $view_name ), $view_stmt->fetchAll( PDO::FETCH_COLUMN ) );

			$public_view_stmt = $pdo->prepare(
				'SELECT table_name
				FROM information_schema.views
				WHERE table_schema = ?
					AND table_name IN (?, ?)
				ORDER BY table_name'
			);
			$public_view_stmt->execute( array( 'public', $explicit_view_name, $view_name ) );
			$this->assertSame( array(), $public_view_stmt->fetchAll( PDO::FETCH_COLUMN ) );

			$this->assertSame(
				0,
				$driver->query( 'DROP VIEW IF EXISTS `' . $view_name . '`, `' . $schema_name . '`.`' . $explicit_view_name . '` RESTRICT' )
			);
			$drop_view_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema and explicit DROP VIEW',
				$backend_sql
			);
			$this->assertStringContainsString( 'DROP VIEW IF EXISTS "' . $schema_name . '"."' . $view_name . '"', $drop_view_sql );
			$this->assertStringContainsString( 'DROP VIEW IF EXISTS "' . $schema_name . '"."' . $explicit_view_name . '"', $drop_view_sql );
			$this->assertStringNotContainsString( '"public"."' . $view_name . '"', $drop_view_sql );

			$view_stmt->execute( array( $schema_name, $explicit_view_name, $view_name ) );
			$this->assertSame( array(), $view_stmt->fetchAll( PDO::FETCH_COLUMN ) );

			$all_backend_sql = implode( "\n", $backend_sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $all_backend_sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$pdo->exec( 'SET search_path TO public' );
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task1003' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1003' );
			$this->drop_public_pgsql_views_with_prefix( $pdo, 'task1003' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task1003' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task1003' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task1003' ) );
			$this->assertSame( array(), $this->get_public_pgsql_views_with_prefix( $pdo, 'task1003' ) );
		}
	}

	/**
	 * Tests real PostgreSQL foreign-key existence paths use catalogs.
	 */
	public function test_real_pgsql_foreign_key_existence_paths_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL foreign-key catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task896' );

		$database_name        = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection           = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver               = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix               = strtolower( bin2hex( random_bytes( 4 ) ) );
		$parent_table         = 'task896_' . $suffix . '_parent';
		$child_table          = 'task896_' . $suffix . '_child';
		$child_table_literal  = $driver->get_connection()->quote( $child_table );
		$named_fk             = 'fk_catalog_parent';
		$inline_generated_fk  = $child_table . '_ibfk_1';
		$generated_fk_one     = $child_table . '_ibfk_2';
		$generated_fk_two     = $child_table . '_ibfk_3';
		$expected_constraints = array( $generated_fk_one, $generated_fk_two, $inline_generated_fk, $named_fk );
		$quoted_constraints   = implode(
			', ',
			array_map(
				array( $driver->get_connection(), 'quote' ),
				$expected_constraints
			)
		);
		$backend_sql          = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$parent_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE foreign-key parent table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`parent_id` int DEFAULT NULL,
							`alt_parent_id` int DEFAULT NULL,
							`third_parent_id` int DEFAULT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$child_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE foreign-key child table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							ADD CONSTRAINT `%s` FOREIGN KEY (`parent_id`)
							REFERENCES `%s` (`id`)
							ON DELETE CASCADE ON UPDATE SET NULL',
						$child_table,
						$named_fk,
						$parent_table
					)
				)
			);
			$add_named_fk_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD named foreign key',
				$backend_sql
			);
			$this->assertStringContainsString(
				'ALTER TABLE "' . $child_table . '" ADD CONSTRAINT "' . $named_fk . '" FOREIGN KEY ("parent_id") REFERENCES "' . $parent_table . '" ("id") ON DELETE CASCADE ON UPDATE SET NULL',
				$add_named_fk_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							ADD COLUMN `inline_parent_id` int REFERENCES `%s` (`id`)
							ON DELETE CASCADE ON UPDATE SET NULL',
						$child_table,
						$parent_table
					)
				)
			);
			$add_inline_fk_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD COLUMN inline foreign key',
				$backend_sql
			);
			$this->assertStringContainsString(
				'ALTER TABLE "' . $child_table . '" ADD COLUMN "inline_parent_id" integer CONSTRAINT "' . $inline_generated_fk . '" REFERENCES "' . $parent_table . '" ("id") ON DELETE CASCADE ON UPDATE SET NULL',
				$add_inline_fk_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							ADD FOREIGN KEY (`alt_parent_id`)
							REFERENCES `%s` (`id`)',
						$child_table,
						$parent_table
					)
				)
			);
			$add_generated_fk_one_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD first generated foreign key',
				$backend_sql
			);
			$this->assertStringContainsString(
				'ALTER TABLE "' . $child_table . '" ADD CONSTRAINT "' . $generated_fk_one . '" FOREIGN KEY ("alt_parent_id") REFERENCES "' . $parent_table . '" ("id")',
				$add_generated_fk_one_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							ADD FOREIGN KEY (`third_parent_id`)
							REFERENCES `%s` (`id`)',
						$child_table,
						$parent_table
					)
				)
			);
			$add_generated_fk_two_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE ADD second generated foreign key',
				$backend_sql
			);
			$this->assertStringContainsString(
				'ALTER TABLE "' . $child_table . '" ADD CONSTRAINT "' . $generated_fk_two . '" FOREIGN KEY ("third_parent_id") REFERENCES "' . $parent_table . '" ("id")',
				$add_generated_fk_two_sql
			);

			$referential_rows = $driver->query(
				"SELECT constraint_name, update_rule, delete_rule, table_name, referenced_table_name
				FROM information_schema.referential_constraints
				WHERE constraint_schema = DATABASE()
					AND table_name = {$child_table_literal}
					AND constraint_name IN ({$quoted_constraints})
				ORDER BY constraint_name"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.referential_constraints after ADD FOREIGN KEY',
				$backend_sql
			);
			$this->assertCount( 4, $referential_rows );
			$named_row = $this->find_row_by_value( $referential_rows, 'CONSTRAINT_NAME', $named_fk );
			$this->assertSame( $child_table, $this->get_row_value( $named_row, 'TABLE_NAME' ) );
			$this->assertSame( $parent_table, $this->get_row_value( $named_row, 'REFERENCED_TABLE_NAME' ) );
			$this->assertSame( 'SET NULL', $this->get_row_value( $named_row, 'UPDATE_RULE' ) );
			$this->assertSame( 'CASCADE', $this->get_row_value( $named_row, 'DELETE_RULE' ) );
			$this->find_row_by_value( $referential_rows, 'CONSTRAINT_NAME', $inline_generated_fk );
			$this->find_row_by_value( $referential_rows, 'CONSTRAINT_NAME', $generated_fk_one );
			$this->find_row_by_value( $referential_rows, 'CONSTRAINT_NAME', $generated_fk_two );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'ALTER TABLE `%s` DROP FOREIGN KEY `%s`', $child_table, $generated_fk_one ) )
			);
			$drop_generated_fk_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP FOREIGN KEY generated constraint',
				$backend_sql
			);
			$this->assertStringContainsString( 'ALTER TABLE "' . $child_table . '" DROP CONSTRAINT "' . $generated_fk_one . '"', $drop_generated_fk_sql );

			$this->assertSame(
				0,
				$driver->query( sprintf( 'ALTER TABLE `%s` DROP CONSTRAINT `%s`', $child_table, $named_fk ) )
			);
			$drop_named_fk_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP CONSTRAINT named foreign key',
				$backend_sql
			);
			$this->assertStringContainsString( 'ALTER TABLE "' . $child_table . '" DROP CONSTRAINT "' . $named_fk . '"', $drop_named_fk_sql );

			try {
				$driver->query( sprintf( 'ALTER TABLE `%s` DROP FOREIGN KEY `missing_fk`', $child_table ) );
				$this->fail( 'Expected DROP FOREIGN KEY with missing PostgreSQL constraint to fail closed.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported ALTER TABLE statement.', $e->getMessage() );
			}
			$missing_drop_fk_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER TABLE DROP FOREIGN KEY missing constraint',
				$backend_sql
			);
			$this->assertStringNotContainsString( 'DROP CONSTRAINT', $missing_drop_fk_sql );

			$key_column_rows = $driver->query(
				"SELECT constraint_name, column_name, referenced_table_name, referenced_column_name
				FROM information_schema.key_column_usage
				WHERE table_schema = DATABASE()
					AND table_name = {$child_table_literal}
					AND referenced_table_name IS NOT NULL
				ORDER BY constraint_name, ordinal_position"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.key_column_usage after DROP FOREIGN KEY',
				$backend_sql
			);
			$this->assertCount( 2, $key_column_rows );
			$inline_key_column = $this->find_row_by_value( $key_column_rows, 'CONSTRAINT_NAME', $inline_generated_fk );
			$this->assertSame( 'inline_parent_id', $this->get_row_value( $inline_key_column, 'COLUMN_NAME' ) );
			$this->assertSame( $parent_table, $this->get_row_value( $inline_key_column, 'REFERENCED_TABLE_NAME' ) );
			$this->assertSame( 'id', $this->get_row_value( $inline_key_column, 'REFERENCED_COLUMN_NAME' ) );
			$generated_key_column = $this->find_row_by_value( $key_column_rows, 'CONSTRAINT_NAME', $generated_fk_two );
			$this->assertSame( 'third_parent_id', $this->get_row_value( $generated_key_column, 'COLUMN_NAME' ) );
			$this->assertSame( $parent_table, $this->get_row_value( $generated_key_column, 'REFERENCED_TABLE_NAME' ) );
			$this->assertSame( 'id', $this->get_row_value( $generated_key_column, 'REFERENCED_COLUMN_NAME' ) );

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task896' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task896' ) );
		}
	}

	/**
	 * Tests non-public PostgreSQL catalog roundtrips for metadata-only index types.
	 */
	public function test_real_pgsql_schema_qualified_metadata_only_catalog_roundtrip_uses_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL schema metadata catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task819' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task819' );

		$database_name  = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection     = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver         = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name    = 'task819_' . $suffix;
		$table_name     = 'catalog_roundtrip';
		$view_name      = 'catalog_roundtrip_view';
		$schema_sql     = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$table_literal  = $driver->get_connection()->quote( $table_name );
		$schema_literal = $driver->get_connection()->quote( $schema_name );
		$backend_sql    = array();

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE non-public schema',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s`.`%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							`body` text,
							`shape` point,
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_unique` (`slug`),
							FULLTEXT KEY `body_fulltext` (`body`),
							SPATIAL KEY `shape_spatial` (`shape`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Task 819 table'",
						$schema_name,
						$table_name
					)
				)
			);
			$create_table_backend_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__body_fulltext"', $create_table_backend_sql );
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__shape_spatial"', $create_table_backend_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__body_fulltext"', $create_table_backend_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__shape_spatial"', $create_table_backend_sql );
			$this->collect_last_postgresql_queries(
				$driver,
				'schema-qualified CREATE TABLE with metadata-only indexes',
				$backend_sql
			);

			$pdo->exec(
				'CREATE VIEW '
				. $schema_sql
				. '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( $view_name )
				. ' AS SELECT id, slug FROM '
				. $schema_sql
				. '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( $table_name )
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE FULLTEXT INDEX `body_fulltext_created` ON `%s`.`%s` (`body`)',
						$schema_name,
						$table_name
					)
				)
			);
			$create_fulltext_backend_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__body_fulltext_created"', $create_fulltext_backend_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__body_fulltext_created"', $create_fulltext_backend_sql );
			$this->collect_last_postgresql_queries(
				$driver,
				'schema-qualified CREATE FULLTEXT INDEX',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE SPATIAL INDEX `shape_spatial_created` ON `%s` (`shape`)',
						$table_name
					)
				)
			);
			$create_spatial_backend_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__shape_spatial_created"', $create_spatial_backend_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__shape_spatial_created"', $create_spatial_backend_sql );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema CREATE SPATIAL INDEX',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'ALTER TABLE `%s`
							ADD FULLTEXT KEY `body_fulltext_alter` (`body`) COMMENT "Search docs",
							ADD SPATIAL INDEX `shape_spatial_alter` (`shape`)',
						$table_name
					)
				)
			);
			$alter_backend_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__body_fulltext_alter"', $alter_backend_sql );
			$this->assertStringContainsString( 'CREATE INDEX "' . $table_name . '__shape_spatial_alter"', $alter_backend_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__body_fulltext_alter"', $alter_backend_sql );
			$this->assertStringContainsString( 'COMMENT ON INDEX "' . $schema_name . '"."' . $table_name . '__shape_spatial_alter"', $alter_backend_sql );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema ALTER TABLE ADD metadata-only indexes',
				$backend_sql
			);

			$show_tables = $driver->query( 'SHOW TABLES LIKE ' . $table_literal );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TABLES LIKE non-public table',
				$backend_sql
			);
			$this->assertCount( 1, $show_tables );
			$this->assertContains( $table_name, array_values( get_object_vars( $show_tables[0] ) ) );

			$non_public_table_column = 'Tables_in_' . $schema_name;
			$non_public_full_tables  = $driver->query( 'SHOW FULL TABLES FROM `' . $schema_name . '`' );
			$show_full_queries       = $driver->get_last_postgresql_queries();
			$show_full_backend_sql   = implode( "\n", array_column( $show_full_queries, 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW FULL TABLES FROM non-public schema',
				$backend_sql
			);
			$this->assertSame(
				array( $non_public_table_column, 'Table_type' ),
				array_keys( get_object_vars( $non_public_full_tables[0] ) )
			);
			$non_public_table_types = array();
			foreach ( $non_public_full_tables as $non_public_full_table ) {
				$non_public_table_types[ $this->get_row_value( $non_public_full_table, $non_public_table_column ) ] = $this->get_row_value( $non_public_full_table, 'Table_type' );
			}
			$this->assertSame( 'BASE TABLE', $non_public_table_types[ $table_name ] ?? null );
			$this->assertSame( 'VIEW', $non_public_table_types[ $view_name ] ?? null );
			$this->assertCount( 1, $show_full_queries );
			$this->assertStringContainsString( 'FROM information_schema.tables t', $show_full_backend_sql );
			$this->assertStringNotContainsString( 'SHOW TABLES', $show_full_backend_sql );
			$this->assertSame( array( $schema_name ), $show_full_queries[0]['params'] );

				$qualified_create_rows    = $driver->query( 'SHOW CREATE TABLE `' . $schema_name . '`.`' . $table_name . '`' );
				$qualified_create_queries = $driver->get_last_postgresql_queries();
				$qualified_create_sql     = implode( "\n", array_column( $qualified_create_queries, 'sql' ) );
				$this->collect_last_postgresql_queries(
					$driver,
					'schema-qualified SHOW CREATE TABLE non-public table',
					$backend_sql
				);
				$this->assertCount( 1, $qualified_create_rows );
				$this->assertSame( $table_name, $this->get_row_value( $qualified_create_rows[0], 'Table' ) );
				$qualified_create_table_sql = (string) $this->get_row_value( $qualified_create_rows[0], 'Create Table' );
				$this->assertStringContainsString( 'CREATE TABLE `' . $table_name . '`', $qualified_create_table_sql );
				$this->assertStringContainsString( 'UNIQUE KEY `slug_unique` (`slug`)', $qualified_create_table_sql );
				$this->assertStringContainsString( 'FULLTEXT KEY `body_fulltext` (`body`)', $qualified_create_table_sql );
				$this->assertStringContainsString( 'SPATIAL KEY `shape_spatial` (`shape`(32))', $qualified_create_table_sql );
				$this->assertStringContainsString( 'FULLTEXT KEY `body_fulltext_created` (`body`)', $qualified_create_table_sql );
				$this->assertStringContainsString( 'SPATIAL KEY `shape_spatial_created` (`shape`(32))', $qualified_create_table_sql );
				$this->assertStringContainsString( 'FULLTEXT KEY `body_fulltext_alter` (`body`) COMMENT \'Search docs\'', $qualified_create_table_sql );
				$this->assertStringContainsString( 'SPATIAL KEY `shape_spatial_alter` (`shape`(32))', $qualified_create_table_sql );
				$this->assertStringContainsString( 'COMMENT=\'Task 819 table\'', $qualified_create_table_sql );
				$this->assertCount( 5, $qualified_create_queries );
			foreach ( $qualified_create_queries as $qualified_create_query ) {
				$this->assertContains( $schema_name, $qualified_create_query['params'] );
				$this->assertContains( $table_name, $qualified_create_query['params'] );
			}
				$this->assertStringContainsString( 'FROM information_schema.columns c', $qualified_create_sql );
				$this->assertStringContainsString( 'pg_catalog.pg_index', $qualified_create_sql );
				$this->assertStringContainsString( 'information_schema.key_column_usage', $qualified_create_sql );
				$this->assertStringContainsString( 'information_schema.referential_constraints', $qualified_create_sql );
				$this->assertStringContainsString( 'pg_catalog.pg_constraint', $qualified_create_sql );
				$this->assertStringContainsString( 'AS "TABLE_COMMENT"', $qualified_create_sql );

				$create_rows = $driver->query( 'SHOW CREATE TABLE `' . $table_name . '`' );
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW CREATE TABLE non-public table',
					$backend_sql
				);
				$this->assertCount( 1, $create_rows );
				$create_table_sql = (string) $this->get_row_value( $create_rows[0], 'Create Table' );
				$this->assertStringContainsString( 'CREATE TABLE `' . $table_name . '`', $create_table_sql );
				$this->assertStringContainsString( 'UNIQUE KEY `slug_unique` (`slug`)', $create_table_sql );
				$this->assertStringContainsString( 'FULLTEXT KEY `body_fulltext` (`body`)', $create_table_sql );
				$this->assertStringContainsString( 'SPATIAL KEY `shape_spatial` (`shape`(32))', $create_table_sql );
				$this->assertStringContainsString( 'FULLTEXT KEY `body_fulltext_created` (`body`)', $create_table_sql );
				$this->assertStringContainsString( 'SPATIAL KEY `shape_spatial_created` (`shape`(32))', $create_table_sql );
				$this->assertStringContainsString( 'FULLTEXT KEY `body_fulltext_alter` (`body`) COMMENT \'Search docs\'', $create_table_sql );
				$this->assertStringContainsString( 'SPATIAL KEY `shape_spatial_alter` (`shape`(32))', $create_table_sql );
				$this->assertStringContainsString( 'COMMENT=\'Task 819 table\'', $create_table_sql );

			try {
				$driver->query( 'SHOW CREATE TABLE pg_catalog.pg_class' );
				$this->fail( 'Expected internal PostgreSQL schema SHOW CREATE TABLE statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SHOW CREATE TABLE statement.', $e->getMessage() );
				$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			}

			$qualified_columns         = $driver->query( 'SHOW COLUMNS FROM `' . $schema_name . '`.`' . $table_name . '`' );
			$qualified_columns_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'schema-qualified SHOW COLUMNS non-public table',
				$backend_sql
			);
			$this->assertCount( 4, $qualified_columns );
			$this->assertSame( array( $schema_name, $table_name ), $qualified_columns_queries[0]['params'] );
			$this->assertStringContainsString( 'information_schema.columns c', $qualified_columns_queries[0]['sql'] );
			$qualified_id_column = $this->find_row_by_value( $qualified_columns, 'Field', 'id' );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $qualified_id_column, 'Type' ) );
			$this->assertSame( 'PRI', $this->get_row_value( $qualified_id_column, 'Key' ) );
			$this->assertSame( 'auto_increment', $this->get_row_value( $qualified_id_column, 'Extra' ) );

			try {
				$driver->query( 'SHOW COLUMNS FROM pg_catalog.pg_class' );
				$this->fail( 'Expected internal PostgreSQL schema SHOW COLUMNS statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SHOW COLUMNS statement.', $e->getMessage() );
				$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			}

				$columns = $driver->query( 'SHOW COLUMNS FROM `' . $table_name . '`' );
				$this->collect_last_postgresql_queries(
					$driver,
					'SHOW COLUMNS non-public table',
					$backend_sql
				);
			$this->assertCount( 4, $columns );
			$id_column = $this->find_row_by_value( $columns, 'Field', 'id' );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $id_column, 'Type' ) );
			$this->assertSame( 'PRI', $this->get_row_value( $id_column, 'Key' ) );
			$this->assertSame( 'auto_increment', $this->get_row_value( $id_column, 'Extra' ) );
			$this->assertSame( 'UNI', $this->get_row_value( $this->find_row_by_value( $columns, 'Field', 'slug' ), 'Key' ) );
			$this->assertSame( 'MUL', $this->get_row_value( $this->find_row_by_value( $columns, 'Field', 'body' ), 'Key' ) );
			$this->assertSame( 'point', $this->get_row_value( $this->find_row_by_value( $columns, 'Field', 'shape' ), 'Type' ) );

			$qualified_indexes         = $driver->query( 'SHOW INDEX FROM `' . $schema_name . '`.`' . $table_name . '`' );
			$qualified_indexes_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'schema-qualified SHOW INDEX non-public table',
				$backend_sql
			);
			$this->assertGreaterThanOrEqual( 8, count( $qualified_indexes ) );
			$this->assertSame( array( $schema_name, $table_name ), $qualified_indexes_queries[0]['params'] );
			$this->assertStringContainsString( 'pg_catalog.pg_index', $qualified_indexes_queries[0]['sql'] );
			$this->assertStringContainsString( 'AS show_index_rows', $qualified_indexes_queries[0]['sql'] );
			$qualified_primary_index = $this->find_row_by_value( $qualified_indexes, 'Key_name', 'PRIMARY' );
			$this->assertSame( $table_name, $this->get_row_value( $qualified_primary_index, 'Table' ) );
			$this->assertSame( 'PRIMARY', $this->get_row_value( $qualified_primary_index, 'Key_name' ) );
			$this->assertSame( 'id', $this->get_row_value( $qualified_primary_index, 'Column_name' ) );

			try {
				$driver->query( 'SHOW INDEX FROM pg_catalog.pg_class' );
				$this->fail( 'Expected internal PostgreSQL schema SHOW INDEX statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SHOW INDEX statement.', $e->getMessage() );
				$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			}

			$indexes = $driver->query( 'SHOW INDEX FROM `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX non-public table',
				$backend_sql
			);
			$this->assertGreaterThanOrEqual( 8, count( $indexes ) );
			$this->assertSame( 'BTREE', $this->get_row_value( $this->find_row_by_value( $indexes, 'Key_name', 'PRIMARY' ), 'Index_type' ) );
			$this->assertSame( 'BTREE', $this->get_row_value( $this->find_row_by_value( $indexes, 'Key_name', 'slug_unique' ), 'Index_type' ) );
			$fulltext_index = $this->find_row_by_value( $indexes, 'Key_name', 'body_fulltext_alter' );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $fulltext_index, 'Index_type' ) );
			$this->assertNull( $this->get_row_value( $fulltext_index, 'Sub_part' ) );
			$this->assertSame( 'Search docs', $this->get_row_value( $fulltext_index, 'Index_comment' ) );
			$spatial_index = $this->find_row_by_value( $indexes, 'Key_name', 'shape_spatial_alter' );
			$this->assertSame( 'SPATIAL', $this->get_row_value( $spatial_index, 'Index_type' ) );
			$this->assertSame( '32', $this->get_row_value( $spatial_index, 'Sub_part' ) );

			$unfiltered_table_status_rows    = $driver->query( 'SHOW TABLE STATUS FROM `' . $schema_name . '`' );
			$unfiltered_table_status_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'unfiltered schema-qualified SHOW TABLE STATUS non-public table',
				$backend_sql
			);
			$this->assertCount( 1, $unfiltered_table_status_rows );
			$this->assertSame( $table_name, $this->get_row_value( $unfiltered_table_status_rows[0], 'Name' ) );
			$this->assertSame( 'InnoDB', $this->get_row_value( $unfiltered_table_status_rows[0], 'Engine' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $unfiltered_table_status_rows[0], 'Collation' ) );
			$this->assertSame( 'Task 819 table', $this->get_row_value( $unfiltered_table_status_rows[0], 'Comment' ) );
			$this->assertSame( array( $schema_name, 'BASE TABLE' ), $unfiltered_table_status_queries[0]['params'] );
			$this->assertStringContainsString( 'FROM information_schema.tables t', $unfiltered_table_status_queries[0]['sql'] );
			$this->assertStringContainsString( 'pg_catalog.obj_description(pc.oid, \'pg_class\')', $unfiltered_table_status_queries[0]['sql'] );

			$qualified_table_status_rows    = $driver->query( 'SHOW TABLE STATUS FROM `' . $schema_name . '` LIKE ' . $table_literal );
			$qualified_table_status_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'schema-qualified SHOW TABLE STATUS non-public table',
				$backend_sql
			);
			$this->assertCount( 1, $qualified_table_status_rows );
			$this->assertSame( $table_name, $this->get_row_value( $qualified_table_status_rows[0], 'Name' ) );
			$this->assertSame( 'InnoDB', $this->get_row_value( $qualified_table_status_rows[0], 'Engine' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $qualified_table_status_rows[0], 'Collation' ) );
			$this->assertSame( 'Task 819 table', $this->get_row_value( $qualified_table_status_rows[0], 'Comment' ) );
			$this->assertSame( array( $schema_name, 'BASE TABLE' ), $qualified_table_status_queries[0]['params'] );
			$this->assertStringContainsString( 'FROM information_schema.tables t', $qualified_table_status_queries[0]['sql'] );
			$this->assertStringContainsString( 'pg_catalog.obj_description(pc.oid, \'pg_class\')', $qualified_table_status_queries[0]['sql'] );

			try {
				$driver->query( 'SHOW TABLE STATUS FROM pg_catalog' );
				$this->fail( 'Expected internal PostgreSQL schema SHOW TABLE STATUS statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SHOW TABLE STATUS statement.', $e->getMessage() );
				$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			}

			$table_status_rows = $driver->query( 'SHOW TABLE STATUS LIKE ' . $table_literal );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TABLE STATUS non-public table',
				$backend_sql
			);
			$this->assertCount( 1, $table_status_rows );
			$this->assertSame( $table_name, $this->get_row_value( $table_status_rows[0], 'Name' ) );
			$this->assertSame( 'InnoDB', $this->get_row_value( $table_status_rows[0], 'Engine' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $table_status_rows[0], 'Collation' ) );
			$this->assertSame( 'Task 819 table', $this->get_row_value( $table_status_rows[0], 'Comment' ) );

			$fulltext_indexes = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Index_type = 'FULLTEXT'" );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX WHERE FULLTEXT',
				$backend_sql
			);
			$this->assertCount( 3, $fulltext_indexes );
			$this->assertNotNull( $this->find_row_by_value( $fulltext_indexes, 'Key_name', 'body_fulltext' ) );
			$this->assertNotNull( $this->find_row_by_value( $fulltext_indexes, 'Key_name', 'body_fulltext_created' ) );
			$this->assertNotNull( $this->find_row_by_value( $fulltext_indexes, 'Key_name', 'body_fulltext_alter' ) );

			$spatial_indexes = $driver->query( 'SHOW INDEX FROM `' . $table_name . '` WHERE Sub_part = 32' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX WHERE SPATIAL sub_part',
				$backend_sql
			);
			$this->assertCount( 3, $spatial_indexes );
			$this->assertNotNull( $this->find_row_by_value( $spatial_indexes, 'Key_name', 'shape_spatial' ) );
			$this->assertNotNull( $this->find_row_by_value( $spatial_indexes, 'Key_name', 'shape_spatial_created' ) );
			$this->assertNotNull( $this->find_row_by_value( $spatial_indexes, 'Key_name', 'shape_spatial_alter' ) );

			$table_rows = $driver->query(
				"SELECT table_schema, table_name, table_comment
				FROM information_schema.tables
				WHERE table_schema = {$schema_literal}
					AND table_name = {$table_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables non-public schema',
				$backend_sql
			);
			$this->assertCount( 1, $table_rows );
			$this->assertSame( $schema_name, $this->get_row_value( $table_rows[0], 'TABLE_SCHEMA' ) );
			$this->assertSame( $table_name, $this->get_row_value( $table_rows[0], 'TABLE_NAME' ) );
			$this->assertSame( 'Task 819 table', $this->get_row_value( $table_rows[0], 'TABLE_COMMENT' ) );

			$column_rows = $driver->query(
				"SELECT table_schema, table_name, column_name, column_type, column_key, extra
				FROM information_schema.columns
				WHERE table_schema = {$schema_literal}
					AND table_name = {$table_literal}
				ORDER BY ordinal_position"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.columns non-public schema',
				$backend_sql
			);
			$this->assertCount( 4, $column_rows );
			foreach ( $column_rows as $column_row ) {
				$this->assertSame( $schema_name, $this->get_row_value( $column_row, 'TABLE_SCHEMA' ) );
				$this->assertSame( $table_name, $this->get_row_value( $column_row, 'TABLE_NAME' ) );
			}
			$id_information_schema_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'id' );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $id_information_schema_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'PRI', $this->get_row_value( $id_information_schema_column, 'COLUMN_KEY' ) );
			$this->assertSame( 'auto_increment', $this->get_row_value( $id_information_schema_column, 'EXTRA' ) );

			$statistics_rows = $driver->query(
				"SELECT table_schema, table_name, index_name, column_name, sub_part, index_type, index_comment
				FROM information_schema.statistics
				WHERE table_schema = {$schema_literal}
					AND table_name = {$table_literal}
				ORDER BY index_name, seq_in_index"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics non-public schema',
				$backend_sql
			);
			$this->assertGreaterThanOrEqual( 8, count( $statistics_rows ) );
			foreach ( $statistics_rows as $statistics_row ) {
				$this->assertSame( $schema_name, $this->get_row_value( $statistics_row, 'TABLE_SCHEMA' ) );
				$this->assertSame( $table_name, $this->get_row_value( $statistics_row, 'TABLE_NAME' ) );
			}
			$this->assertSame( 'BTREE', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'PRIMARY' ), 'INDEX_TYPE' ) );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'body_fulltext' ), 'INDEX_TYPE' ) );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'body_fulltext_created' ), 'INDEX_TYPE' ) );
			$alter_fulltext_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'body_fulltext_alter' );
			$this->assertSame( 'FULLTEXT', $this->get_row_value( $alter_fulltext_statistic, 'INDEX_TYPE' ) );
			$this->assertSame( 'Search docs', $this->get_row_value( $alter_fulltext_statistic, 'INDEX_COMMENT' ) );
			$this->assertSame( 'SPATIAL', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'shape_spatial' ), 'INDEX_TYPE' ) );
			$this->assertSame( '32', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'shape_spatial_created' ), 'SUB_PART' ) );
			$this->assertSame( '32', $this->get_row_value( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'shape_spatial_alter' ), 'SUB_PART' ) );

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task819' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task819' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task819' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task819' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task819' ) );
		}
	}

	/**
	 * Tests real PostgreSQL columnless REPLACE metadata paths use catalogs.
	 */
	public function test_real_pgsql_columnless_replace_metadata_paths_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL columnless REPLACE metadata catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task841' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task841' );

		$database_name         = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection            = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver                = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix                = strtolower( bin2hex( random_bytes( 4 ) ) );
		$public_values_target  = 'task841_' . $suffix . '_values_target';
		$public_select_target  = 'task841_' . $suffix . '_select_target';
		$public_select_source  = 'task841_' . $suffix . '_select_source';
		$schema_name           = 'task841_' . $suffix;
		$schema_values_target  = 'task841_' . $suffix . '_schema_values_target';
		$schema_sql            = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$backend_sql           = array();
		$get_rows              = static function ( PDO $pdo, string $schema, string $table ): array {
			return $pdo->query(
				'SELECT pk, slug, value FROM '
				. WP_PostgreSQL_Connection::quote_identifier_value( $schema )
				. '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( $table )
				. ' ORDER BY slug'
			)->fetchAll( PDO::FETCH_ASSOC );
		};
		$expected_replace_rows = array(
			array(
				'pk'    => '3',
				'slug'  => 'other',
				'value' => 'created',
			),
			array(
				'pk'    => '2',
				'slug'  => 'same',
				'value' => 'new',
			),
		);

		try {
			foreach ( array( $public_values_target, $public_select_target, $public_select_source ) as $table_name ) {
				$this->assertSame(
					0,
					$driver->query(
						sprintf(
							'CREATE TABLE `%s` (
								`pk` int NOT NULL,
								`slug` varchar(64) NOT NULL,
								`value` varchar(64) NOT NULL,
								PRIMARY KEY (`pk`),
								UNIQUE KEY `slug_unique` (`slug`)
							) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
							$table_name
						)
					)
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE public REPLACE table',
					$backend_sql
				);
			}

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`pk`, `slug`, `value`) VALUES (1, 'same', 'old')", $public_values_target ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed public REPLACE VALUES target',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`pk`, `slug`, `value`) VALUES (1, 'same', 'old')", $public_select_target ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed public REPLACE SELECT target',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( sprintf( "INSERT INTO `%s` (`pk`, `slug`, `value`) VALUES (2, 'same', 'new'), (3, 'other', 'created')", $public_select_source ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed public REPLACE SELECT source',
				$backend_sql
			);

			$this->assertSame(
				3,
				$driver->query( sprintf( "REPLACE INTO `%s` VALUES (2, 'same', 'new'), (3, 'other', 'created')", $public_values_target ) )
			);
			$public_values_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'public columnless REPLACE VALUES',
				$backend_sql
			);
			$this->assertStringContainsString( 'DELETE FROM "' . $public_values_target . '" WHERE', $public_values_sql );
			$this->assertStringContainsString( '"slug" = \'same\'', $public_values_sql );
			$this->assertStringContainsString(
				'INSERT INTO "' . $public_values_target . '" ("pk", "slug", "value") VALUES',
				$public_values_sql
			);
			$this->assertSame( $expected_replace_rows, $get_rows( $pdo, 'public', $public_values_target ) );

			$this->assertSame(
				3,
				$driver->query( sprintf( 'REPLACE INTO `%s` SELECT `pk`, `slug`, `value` FROM `%s`', $public_select_target, $public_select_source ) )
			);
			$public_select_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'public columnless REPLACE SELECT',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TEMPORARY TABLE "__wp_pg_replace_select_', $public_select_sql );
			$this->assertStringContainsString( 'DELETE FROM "' . $public_select_target . '" AS "__wp_pg_replace_target"', $public_select_sql );
			$this->assertStringContainsString( '"__wp_pg_replace_target"."slug" = "__wp_pg_replace_rows"."slug"', $public_select_sql );
			$this->assertStringContainsString(
				'INSERT INTO "' . $public_select_target . '" ("pk", "slug", "value") SELECT "__wp_pg_replace_rows"."pk", "__wp_pg_replace_rows"."slug", "__wp_pg_replace_rows"."value"',
				$public_select_sql
			);
			$this->assertSame( $expected_replace_rows, $get_rows( $pdo, 'public', $public_select_target ) );

			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE current schema for columnless REPLACE',
				$backend_sql
			);

			foreach ( array( $schema_values_target ) as $table_name ) {
				$this->assertSame(
					0,
					$driver->query(
						sprintf(
							'CREATE TABLE `%s` (
								`pk` int NOT NULL,
								`slug` varchar(64) NOT NULL,
								`value` varchar(64) NOT NULL,
								PRIMARY KEY (`pk`),
								UNIQUE KEY `slug_unique` (`slug`)
							) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
							$table_name
						)
					)
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE current-schema REPLACE table',
					$backend_sql
				);
			}

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`pk`, `slug`, `value`) VALUES (1, 'same', 'old')", $schema_values_target ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed current-schema REPLACE VALUES target',
				$backend_sql
			);

			$this->assertSame(
				3,
				$driver->query( sprintf( "REPLACE INTO `%s` VALUES (2, 'same', 'new'), (3, 'other', 'created')", $schema_values_target ) )
			);
			$schema_values_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema columnless REPLACE VALUES',
				$backend_sql
			);
			$this->assertStringContainsString( 'DELETE FROM "' . $schema_name . '"."' . $schema_values_target . '" WHERE', $schema_values_sql );
			$this->assertStringContainsString(
				'INSERT INTO "' . $schema_name . '"."' . $schema_values_target . '" ("pk", "slug", "value") VALUES',
				$schema_values_sql
			);
			$this->assertSame( $expected_replace_rows, $get_rows( $pdo, $schema_name, $schema_values_target ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task841' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task841' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task841' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task841' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task841' ) );
		}
	}

	/**
	 * Tests real PostgreSQL current-schema REPLACE SELECT uses the selected schema.
	 */
	public function test_real_pgsql_current_schema_replace_select_uses_selected_schema(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL current-schema REPLACE SELECT catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task858' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task858' );

		$database_name    = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection       = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver           = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix           = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name      = 'task858_' . $suffix;
		$schema_sql       = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$target_no_shadow = 'task858_' . $suffix . '_target_no_shadow';
		$source_no_shadow = 'task858_' . $suffix . '_source_no_shadow';
		$target_shadow    = 'task858_' . $suffix . '_target_shadow';
		$source_shadow    = 'task858_' . $suffix . '_source_shadow';
		$backend_sql      = array();
		$get_rows         = static function ( PDO $pdo, string $schema, string $table ): array {
			return $pdo->query(
				'SELECT pk, slug, value FROM '
				. WP_PostgreSQL_Connection::quote_identifier_value( $schema )
				. '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( $table )
				. ' ORDER BY slug'
			)->fetchAll( PDO::FETCH_ASSOC );
		};
		$create_table     = static function ( WP_PostgreSQL_Driver $driver, string $table_name ): int {
			return $driver->query(
				sprintf(
					'CREATE TABLE `%s` (
						`pk` int NOT NULL,
						`slug` varchar(64) NOT NULL,
						`value` varchar(64) NOT NULL,
						PRIMARY KEY (`pk`),
						UNIQUE KEY `slug_unique` (`slug`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
					$table_name
				)
			);
		};

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE current schema for REPLACE SELECT source qualification',
				$backend_sql
			);

			foreach ( array( $target_no_shadow, $source_no_shadow, $target_shadow, $source_shadow ) as $table_name ) {
				$this->assertSame( 0, $create_table( $driver, $table_name ) );
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE current-schema REPLACE SELECT table',
					$backend_sql
				);
			}

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`pk`, `slug`, `value`) VALUES (1, 'same', 'schema-old')", $target_no_shadow ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed current-schema no-shadow REPLACE SELECT target',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( sprintf( "INSERT INTO `%s` (`pk`, `slug`, `value`) VALUES (2, 'same', 'schema-new'), (3, 'schema-other', 'schema-created')", $source_no_shadow ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed current-schema no-shadow REPLACE SELECT source',
				$backend_sql
			);

			$this->assertSame(
				3,
				$driver->query( sprintf( 'REPLACE INTO `%s` SELECT `pk`, `slug`, `value` FROM `%s`', $target_no_shadow, $source_no_shadow ) )
			);
			$no_shadow_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema no-shadow columnless REPLACE SELECT',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TEMPORARY TABLE "__wp_pg_replace_select_', $no_shadow_sql );
			$this->assertStringContainsString( 'FROM "' . $schema_name . '"."' . $source_no_shadow . '"', $no_shadow_sql );
			$this->assertSame(
				array(
					array(
						'pk'    => '2',
						'slug'  => 'same',
						'value' => 'schema-new',
					),
					array(
						'pk'    => '3',
						'slug'  => 'schema-other',
						'value' => 'schema-created',
					),
				),
				$get_rows( $pdo, $schema_name, $target_no_shadow )
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`pk`, `slug`, `value`) VALUES (1, 'same', 'schema-old')", $target_shadow ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed current-schema shadow REPLACE SELECT target',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( sprintf( "INSERT INTO `%s` (`pk`, `slug`, `value`) VALUES (4, 'same', 'schema-new'), (5, 'schema-other', 'schema-created')", $source_shadow ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed current-schema shadow REPLACE SELECT source',
				$backend_sql
			);

			$pdo->exec(
				'CREATE TABLE public.'
				. WP_PostgreSQL_Connection::quote_identifier_value( $source_shadow )
				. ' (
					pk integer NOT NULL,
					slug varchar(64) NOT NULL,
					value varchar(64) NOT NULL,
					PRIMARY KEY (pk),
					UNIQUE (slug)
				)'
			);
			$pdo->exec(
				'INSERT INTO public.'
				. WP_PostgreSQL_Connection::quote_identifier_value( $source_shadow )
				. " (pk, slug, value) VALUES (6, 'same', 'public-new'), (7, 'public-other', 'public-created')"
			);

			$this->assertSame(
				3,
				$driver->query( sprintf( 'REPLACE INTO `%s` SELECT `pk`, `slug`, `value` FROM `%s`', $target_shadow, $source_shadow ) )
			);
			$shadow_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema shadow columnless REPLACE SELECT',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TEMPORARY TABLE "__wp_pg_replace_select_', $shadow_sql );
			$this->assertStringContainsString( 'FROM "' . $schema_name . '"."' . $source_shadow . '"', $shadow_sql );
			$this->assertSame(
				array(
					array(
						'pk'    => '4',
						'slug'  => 'same',
						'value' => 'schema-new',
					),
					array(
						'pk'    => '5',
						'slug'  => 'schema-other',
						'value' => 'schema-created',
					),
				),
				$get_rows( $pdo, $schema_name, $target_shadow )
			);
			$this->assertSame(
				array(
					array(
						'pk'    => '7',
						'slug'  => 'public-other',
						'value' => 'public-created',
					),
					array(
						'pk'    => '6',
						'slug'  => 'same',
						'value' => 'public-new',
					),
				),
				$get_rows( $pdo, 'public', $source_shadow )
			);
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task858' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task858' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task858' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task858' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task858' ) );
		}
	}

	/**
	 * Tests real PostgreSQL LAST_INSERT_ID(id) upserts use catalogs.
	 */
	public function test_real_pgsql_last_insert_id_upserts_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL LAST_INSERT_ID upsert metadata catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task849' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task849' );

		$database_name  = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection     = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver         = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$explicit_table = 'task849_' . $suffix . '_lid_explicit';
		$select_table   = 'task849_' . $suffix . '_lid_select';
		$source_target  = 'task849_' . $suffix . '_lid_source_target';
		$source_table   = 'task849_' . $suffix . '_lid_source';
		$backend_sql    = array();
		$get_row        = static function ( PDO $pdo, string $table_name ): array {
			$stmt = $pdo->query(
				'SELECT id, slug, hits, updated_at FROM public.'
				. WP_PostgreSQL_Connection::quote_identifier_value( $table_name )
				. ' ORDER BY slug'
			);
			return $stmt->fetchAll( PDO::FETCH_ASSOC );
		};

		try {
			foreach ( array( $explicit_table, $select_table, $source_target ) as $table_name ) {
				$this->assertSame(
					0,
					$driver->query(
						sprintf(
							'CREATE TABLE `%s` (
									`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
									`slug` varchar(64) NOT NULL,
									`hits` int NOT NULL DEFAULT 0,
									`updated_at` varchar(32) NOT NULL,
									PRIMARY KEY (`id`),
									UNIQUE KEY `slug_unique` (`slug`)
								) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
							$table_name
						)
					)
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE LAST_INSERT_ID upsert table',
					$backend_sql
				);

				$this->assertSame(
					1,
					$driver->query( sprintf( "INSERT INTO `%s` (`id`, `slug`, `hits`, `updated_at`) VALUES (7, 'same', 1, '0000-00-00 00:00:00')", $table_name ) )
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'seed LAST_INSERT_ID upsert table',
					$backend_sql
				);
			}

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`seq` int NOT NULL,
							`slug` varchar(64) NOT NULL,
							`hits` int NOT NULL,
							`updated_at` varchar(32) NOT NULL
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE LAST_INSERT_ID source table',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s` (`seq`, `slug`, `hits`, `updated_at`) VALUES (1, 'same', 2, '2001-01-01 00:00:00')",
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed LAST_INSERT_ID source table',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s` (`slug`, `hits`, `updated_at`) VALUES ('same', 2, '2001-01-01 00:00:00')
							ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id`), `hits` = `hits` + VALUES(`hits`), `updated_at` = VALUES(`updated_at`)",
						$explicit_table
					)
				)
			);
			$this->assertSame( 7, $driver->get_insert_id() );
			$explicit_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit-column LAST_INSERT_ID upsert',
				$backend_sql
			);
			$this->assertStringContainsString( 'ON CONFLICT ("slug") DO UPDATE', $explicit_sql );
			$this->assertStringContainsString( '"id" = "' . $explicit_table . '"."id"', $explicit_sql );
			$this->assertStringContainsString( '"hits" = "' . $explicit_table . '"."hits" + excluded."hits"', $explicit_sql );
			$this->assertStringContainsString( '"updated_at" = excluded."updated_at"', $explicit_sql );

			$explicit_readback = $driver->query(
				sprintf(
					"SELECT LAST_INSERT_ID() AS last_id, ROW_COUNT() AS row_count_value, `hits`, `updated_at`
					FROM `%s`
					WHERE `slug` = 'same'",
					$explicit_table
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'read explicit-column LAST_INSERT_ID upsert row',
				$backend_sql
			);
			$this->assertCount( 1, $explicit_readback );
			$this->assertSame( '7', (string) $this->get_row_value( $explicit_readback[0], 'last_id' ) );
			$this->assertSame( '1', (string) $this->get_row_value( $explicit_readback[0], 'row_count_value' ) );
			$this->assertSame( '3', (string) $this->get_row_value( $explicit_readback[0], 'hits' ) );
			$this->assertSame( '2001-01-01 00:00:00', $this->get_row_value( $explicit_readback[0], 'updated_at' ) );
			$this->assertSame(
				array(
					array(
						'id'         => '7',
						'slug'       => 'same',
						'hits'       => '3',
						'updated_at' => '2001-01-01 00:00:00',
					),
				),
				$get_row( $pdo, $explicit_table )
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s`
							SELECT NULL, 'same', 2, '2001-01-01 00:00:00' FROM DUAL
							ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id`), `hits` = `hits` + VALUES(`hits`), `updated_at` = VALUES(`updated_at`)",
						$select_table
					)
				)
			);
			$this->assertSame( 7, $driver->get_insert_id() );
			$select_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'columnless SELECT LAST_INSERT_ID upsert',
				$backend_sql
			);
			$this->assertStringContainsString( 'INSERT INTO "' . $select_table . '" ("id", "slug", "hits", "updated_at") SELECT', $select_sql );
			$this->assertStringContainsString( 'nextval(pg_get_serial_sequence', $select_sql );
			$this->assertStringNotContainsString( 'SELECT NULL, \'same\'', $select_sql );
			$this->assertStringContainsString( 'ON CONFLICT ("slug") DO UPDATE', $select_sql );
			$this->assertStringContainsString( '"id" = "' . $select_table . '"."id"', $select_sql );
			$this->assertStringContainsString( '"hits" = "' . $select_table . '"."hits" + excluded."hits"', $select_sql );
			$this->assertStringContainsString( '"updated_at" = excluded."updated_at"', $select_sql );

			$select_readback = $driver->query(
				sprintf(
					"SELECT LAST_INSERT_ID() AS last_id, ROW_COUNT() AS row_count_value, `hits`, `updated_at`
					FROM `%s`
					WHERE `slug` = 'same'",
					$select_table
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'read columnless SELECT LAST_INSERT_ID upsert row',
				$backend_sql
			);
			$this->assertCount( 1, $select_readback );
			$this->assertSame( '7', (string) $this->get_row_value( $select_readback[0], 'last_id' ) );
			$this->assertSame( '1', (string) $this->get_row_value( $select_readback[0], 'row_count_value' ) );
			$this->assertSame( '3', (string) $this->get_row_value( $select_readback[0], 'hits' ) );
			$this->assertSame( '2001-01-01 00:00:00', $this->get_row_value( $select_readback[0], 'updated_at' ) );
			$this->assertSame(
				array(
					array(
						'id'         => '7',
						'slug'       => 'same',
						'hits'       => '3',
						'updated_at' => '2001-01-01 00:00:00',
					),
				),
				$get_row( $pdo, $select_table )
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						'INSERT INTO `%s` (`slug`, `hits`, `updated_at`)
							SELECT `slug`, `hits`, `updated_at` FROM `%s` ORDER BY `seq`
							ON DUPLICATE KEY UPDATE `id` = LAST_INSERT_ID(`id`), `hits` = `hits` + VALUES(`hits`), `updated_at` = VALUES(`updated_at`)',
						$source_target,
						$source_table
					)
				)
			);
			$this->assertSame( 7, $driver->get_insert_id() );
			$source_select_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'source-table SELECT LAST_INSERT_ID upsert',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TEMPORARY TABLE "__wp_pg_upsert_select_', $source_select_sql );
			$this->assertStringContainsString( 'FROM "' . $source_table . '"', $source_select_sql );
			$this->assertStringContainsString( 'ORDER BY "seq"', $source_select_sql );
			$this->assertStringContainsString( 'ON CONFLICT ("slug") DO UPDATE', $source_select_sql );
			$this->assertStringContainsString( '"id" = "' . $source_target . '"."id"', $source_select_sql );
			$this->assertStringContainsString( '"hits" = "' . $source_target . '"."hits" + excluded."hits"', $source_select_sql );
			$this->assertStringContainsString( '"updated_at" = excluded."updated_at"', $source_select_sql );

			$source_readback = $driver->query(
				sprintf(
					"SELECT LAST_INSERT_ID() AS last_id, ROW_COUNT() AS row_count_value, `hits`, `updated_at`
					FROM `%s`
					WHERE `slug` = 'same'",
					$source_target
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'read source-table LAST_INSERT_ID upsert row',
				$backend_sql
			);
			$this->assertCount( 1, $source_readback );
			$this->assertSame( '7', (string) $this->get_row_value( $source_readback[0], 'last_id' ) );
			$this->assertSame( '1', (string) $this->get_row_value( $source_readback[0], 'row_count_value' ) );
			$this->assertSame( '3', (string) $this->get_row_value( $source_readback[0], 'hits' ) );
			$this->assertSame( '2001-01-01 00:00:00', $this->get_row_value( $source_readback[0], 'updated_at' ) );
			$this->assertSame(
				array(
					array(
						'id'         => '7',
						'slug'       => 'same',
						'hits'       => '3',
						'updated_at' => '2001-01-01 00:00:00',
					),
				),
				$get_row( $pdo, $source_target )
			);
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task849' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task849' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task849' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task849' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task849' ) );
		}
	}

	/**
	 * Tests real PostgreSQL DML metadata paths use catalogs.
	 */
	public function test_real_pgsql_dml_metadata_paths_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL DML metadata catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task827' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task827' );

		$database_name      = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection         = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection {
			/**
			 * Captured real PostgreSQL column catalog metadata reads.
			 *
			 * @var array[]
			 */
			private $column_catalog_queries = array();

			/**
			 * Captured real PostgreSQL identity catalog metadata reads.
			 *
			 * @var array[]
			 */
			private $identity_catalog_queries = array();

			/**
			 * Captured real PostgreSQL unique-index catalog metadata reads.
			 *
			 * @var array[]
			 */
			private $unique_index_catalog_queries = array();

			/**
			 * Execute a PostgreSQL query and record DML metadata catalog reads.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					$this->column_catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);
				}

				if ( false !== strpos( $sql, 'pg_catalog.pg_get_serial_sequence' ) ) {
					$this->identity_catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);
				}

				if ( false !== strpos( $sql, 'pg_catalog.pg_index i' ) && false !== strpos( $sql, 'i.indisunique' ) ) {
					$this->unique_index_catalog_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured real PostgreSQL column catalog metadata reads.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_column_catalog_queries(): array {
				return $this->column_catalog_queries;
			}

			/**
			 * Get captured real PostgreSQL identity catalog metadata reads.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_identity_catalog_queries(): array {
				return $this->identity_catalog_queries;
			}

			/**
			 * Get captured real PostgreSQL unique-index catalog metadata reads.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_unique_index_catalog_queries(): array {
				return $this->unique_index_catalog_queries;
			}
		};
		$driver             = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix             = strtolower( bin2hex( random_bytes( 4 ) ) );
		$dml_table          = 'task827_' . $suffix . '_dml';
		$source_table       = 'task827_' . $suffix . '_source';
		$replace_source     = 'task827_' . $suffix . '_replace_source';
		$identity_table     = 'task827_' . $suffix . '_identity';
		$schema_name        = 'task827_' . $suffix;
		$schema_table       = 'dml_current_schema';
		$schema_sql         = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$schema_table_sql   = WP_PostgreSQL_Connection::quote_identifier_value( $schema_table );
		$dml_table_literal  = $driver->get_connection()->quote( $dml_table );
		$backend_sql        = array();
		$public_table_names = array( $dml_table, $source_table, $replace_source, $identity_table );

		try {
			foreach ( $public_table_names as $table_name ) {
				$this->assertStringStartsWith( 'task827_', $table_name );
			}

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							`value` varchar(64) NOT NULL DEFAULT 'seed',
							`note` varchar(64) NULL,
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_unique` (`slug`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
						$dml_table
					)
				)
			);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE DML target table',
					$backend_sql
				);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL,
							`slug` varchar(64) NOT NULL,
							`value` varchar(64) NOT NULL,
							`note` varchar(64) NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE columnless INSERT SELECT source table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`slug` varchar(64) NOT NULL,
							`value` varchar(64) NOT NULL,
							`note` varchar(64) NULL
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$replace_source
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE REPLACE SELECT source table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_unique` (`slug`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$identity_table
					)
				)
			);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE identity target table',
					$backend_sql
				);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` VALUES (1, 'alpha', 'one', 'note-a')", $dml_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'columnless INSERT VALUES',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( sprintf( "INSERT INTO `%s` VALUES (2, 'beta', 'two', 'note-b'), (3, 'delta', 'four', 'note-d')", $source_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'columnless INSERT source rows',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						'INSERT INTO `%1$s` SELECT `id`, `slug`, `value`, `note` FROM `%2$s` WHERE `id` = 2',
						$dml_table,
						$source_table
					)
				)
			);
			$columnless_insert_select_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'columnless INSERT SELECT',
				$backend_sql
			);
			$this->assertStringContainsString(
				'INSERT INTO "' . $dml_table . '" ("id", "slug", "value", "note") SELECT',
				$columnless_insert_select_sql
			);
			$this->assertStringContainsString( 'FROM "' . $source_table . '" WHERE "id" = 2', $columnless_insert_select_sql );

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s` (`slug`, `value`, `note`) VALUES ('alpha', 'one-upserted', 'note-up')
							ON DUPLICATE KEY UPDATE `value` = VALUES(`value`), `note` = VALUES(`note`)",
						$dml_table
					)
				)
			);
			$upsert_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'ON DUPLICATE KEY UPDATE catalog unique key',
				$backend_sql
			);
			$this->assertStringContainsString( 'ON CONFLICT ("slug") DO UPDATE', $upsert_sql );

			$this->assertSame(
				3,
				$driver->query(
					sprintf(
						"REPLACE INTO `%s` (`slug`, `value`, `note`) VALUES
							('beta', 'two-replaced', 'note-r'),
							('gamma', 'three', 'note-g')",
						$dml_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'REPLACE VALUES catalog unique key',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( sprintf( "INSERT INTO `%s` VALUES ('gamma', 'three-replaced', 'note-rs'), ('epsilon', 'five', 'note-e')", $replace_source ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'REPLACE SELECT source rows',
				$backend_sql
			);

			$this->assertSame(
				3,
				$driver->query(
					sprintf(
						'REPLACE INTO `%1$s` (`slug`, `value`, `note`) SELECT `slug`, `value`, `note` FROM `%2$s`',
						$dml_table,
						$replace_source
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'REPLACE SELECT catalog unique key',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`id`, `slug`) VALUES (20, 'manual')", $identity_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit identity INSERT repair',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s` (`id`, `slug`) VALUES (30, 'manual-upsert')
							ON DUPLICATE KEY UPDATE `slug` = VALUES(`slug`)",
						$identity_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit identity UPSERT repair',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`slug`) VALUES ('generated')", $identity_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'generated identity after repairs',
				$backend_sql
			);

			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE DML metadata schema',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`status` varchar(20) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$schema_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE current-schema DML table',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( sprintf( "INSERT INTO `%s` VALUES (1, 'draft'), (2, 'keep')", $schema_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema columnless INSERT',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "UPDATE `%s` SET `status` = 'published' WHERE `id` = 1", $schema_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema UPDATE',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "DELETE FROM `%s` WHERE `status` = 'keep'", $schema_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'current-schema DELETE',
				$backend_sql
			);

			$this->assertSame( 0, $driver->query( 'USE `' . $database_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE main database after current-schema DML',
				$backend_sql
			);

			$dml_rows = $driver->query(
				sprintf(
					"SELECT `slug`, `value`, `note` FROM `%s` WHERE `slug` IN ('alpha', 'beta', 'gamma', 'epsilon') ORDER BY `slug`",
					$dml_table
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'read DML metadata rows',
				$backend_sql
			);
			$this->assertCount( 4, $dml_rows );
			$this->assertSame( 'one-upserted', $this->get_row_value( $this->find_row_by_value( $dml_rows, 'slug', 'alpha' ), 'value' ) );
			$this->assertSame( 'two-replaced', $this->get_row_value( $this->find_row_by_value( $dml_rows, 'slug', 'beta' ), 'value' ) );
			$this->assertSame( 'three-replaced', $this->get_row_value( $this->find_row_by_value( $dml_rows, 'slug', 'gamma' ), 'value' ) );
			$this->assertSame( 'five', $this->get_row_value( $this->find_row_by_value( $dml_rows, 'slug', 'epsilon' ), 'value' ) );

			$identity_rows = $driver->query( sprintf( 'SELECT `id`, `slug` FROM `%s` ORDER BY `id`', $identity_table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'read identity repair rows',
				$backend_sql
			);
			$this->assertCount( 3, $identity_rows );
			$this->assertSame( '20', (string) $this->get_row_value( $identity_rows[0], 'id' ) );
			$this->assertSame( '30', (string) $this->get_row_value( $identity_rows[1], 'id' ) );
			$this->assertSame( '31', (string) $this->get_row_value( $identity_rows[2], 'id' ) );
			$this->assertSame( 'generated', $this->get_row_value( $identity_rows[2], 'slug' ) );

			$schema_rows = $pdo->query(
				'SELECT id, status FROM ' . $schema_sql . '.' . $schema_table_sql . ' ORDER BY id'
			)->fetchAll( PDO::FETCH_OBJ );
			$this->assertCount( 1, $schema_rows );
			$this->assertSame( '1', (string) $schema_rows[0]->id );
			$this->assertSame( 'published', $schema_rows[0]->status );

			$column_catalog_queries = $connection->get_column_catalog_queries();
			$this->assertNotEmpty( $column_catalog_queries );
			$column_catalog_sql = implode( "\n", array_column( $column_catalog_queries, 'sql' ) );
			$this->assertStringContainsString( 'FROM information_schema.columns c', $column_catalog_sql );
			$this->assertStringContainsString( 'c.is_identity', $column_catalog_sql );
			$this->assertStringContainsString( "c.domain_name = '__wp_mysql_datetime' THEN 'datetime'", $column_catalog_sql );
			$this->assertStringContainsString( "c.domain_name = '__wp_mysql_mediumblob' THEN 'mediumblob'", $column_catalog_sql );
			$this->assertStringContainsString( "c.domain_name LIKE '__wp_mysql_varbinary_%' THEN 'varbinary'", $column_catalog_sql );
			$this->assertStringContainsString( "c.data_type = 'numeric' AND c.numeric_precision IS NULL THEN 'numeric'", $column_catalog_sql );
			$this->assertStringContainsString( "'decimal' || CASE", $column_catalog_sql );
			$this->assertStringContainsString( "c.data_type = 'double precision' THEN 'double'", $column_catalog_sql );
			$this->assertStringContainsString( "c.data_type = 'real' THEN 'float'", $column_catalog_sql );
			$this->assertStringContainsString( 'SUBSTRING(c.column_default FROM', $column_catalog_sql );
			$this->assertStringContainsString( "THEN 'CURRENT_TIMESTAMP'", $column_catalog_sql );
			$this->assertStringContainsString( "'CURRENT_TIMESTAMP(' || SUBSTRING(c.column_default FROM", $column_catalog_sql );
			$this->assertStringContainsString( 'pg_catalog.col_description(pc.oid, pa.attnum)', $column_catalog_sql );
			$this->assertStringContainsString( 'convert_from(', $column_catalog_sql );
			$this->assertStringContainsString( 'decode(', $column_catalog_sql );
			$this->assertStringContainsString( '__wp_mysql_column_default:', $column_catalog_sql );
			$this->assertStringContainsString( '__wp_mysql_column_type:', $column_catalog_sql );
			$this->assertStringContainsString( 'DEFAULT_GENERATED', $column_catalog_sql );

			$identity_catalog_queries = $connection->get_identity_catalog_queries();
			$this->assertNotEmpty( $identity_catalog_queries );
			$identity_catalog_sql = implode( "\n", array_column( $identity_catalog_queries, 'sql' ) );
			$this->assertStringContainsString( 'pg_catalog.pg_get_serial_sequence', $identity_catalog_sql );
			$this->assertStringContainsString( 'FROM information_schema.columns c', $identity_catalog_sql );

			$unique_index_catalog_queries = $connection->get_unique_index_catalog_queries();
			$this->assertNotEmpty( $unique_index_catalog_queries );
			$unique_index_catalog_sql = implode( "\n", array_column( $unique_index_catalog_queries, 'sql' ) );
			$this->assertStringContainsString( 'pg_catalog.pg_index i', $unique_index_catalog_sql );
			$this->assertStringContainsString( 'i.indisunique', $unique_index_catalog_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_get_indexdef(i.indexrelid', $unique_index_catalog_sql );
			$this->assertStringContainsString( 'COALESCE(column_name, NULLIF(REPLACE(COALESCE(', $unique_index_catalog_sql );
			$this->assertStringContainsString( '"SUB_PART" AS "sub_part"', $unique_index_catalog_sql );

			foreach ( array_merge( $column_catalog_queries, $identity_catalog_queries, $unique_index_catalog_queries ) as $catalog_query ) {
			}

			$this->assertGreaterThan( 0, count( $backend_sql ) );
			$this->assertSame(
				1,
				(int) $pdo->query(
					"SELECT COUNT(*)
					FROM information_schema.tables
					WHERE table_schema = 'public'
						AND table_name = " . $pdo->quote( $dml_table )
				)->fetchColumn()
			);
		} finally {
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task827' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task827' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task827' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task827' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task827' ) );
		}
	}

	/**
	 * Tests real PostgreSQL complex DML metadata paths use catalogs.
	 */
	public function test_real_pgsql_complex_dml_metadata_paths_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL complex DML metadata catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task831' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task831' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new class( array( 'pdo' => $pdo ) ) extends WP_PostgreSQL_Connection {
			/**
			 * Captured real PostgreSQL catalog column lookups.
			 *
			 * @var array[]
			 */
			private $catalog_column_queries = array();

			/**
			 * Execute a PostgreSQL query and record direct column catalog metadata reads.
			 *
			 * @param string $sql    SQL query.
			 * @param array  $params Query parameters.
			 * @return PDOStatement Statement.
			 */
			public function query( string $sql, array $params = array() ): PDOStatement {
				if ( false !== strpos( $sql, 'FROM information_schema.columns c' ) ) {
					$this->catalog_column_queries[] = array(
						'sql'    => $sql,
						'params' => $params,
					);
				}

				return parent::query( $sql, $params );
			}

			/**
			 * Get captured real PostgreSQL catalog column lookups.
			 *
			 * @return array[] Catalog queries.
			 */
			public function get_catalog_column_queries(): array {
				return $this->catalog_column_queries;
			}
		};
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name   = 'task831_' . $suffix;
		$schema_sql    = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$backend_sql   = array();
		$get_column    = Closure::bind(
			function ( string $table_schema, string $table_name, string $column_name ): ?string {
				return $this->get_mysql_table_column_name( $table_schema, $table_name, $column_name );
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );
			$pdo->exec(
				'CREATE TABLE ' . $schema_sql . '.' . WP_PostgreSQL_Connection::quote_identifier_value( 'lookup_meta' ) . ' (
					"ID" bigint NOT NULL PRIMARY KEY,
					"Title" text NOT NULL
				)'
			);

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE complex DML schema',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					'CREATE TABLE `join_target` (
						`id` int NOT NULL,
						`status` varchar(20) NOT NULL,
						PRIMARY KEY (`id`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE joined UPDATE target',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					'CREATE TABLE `join_source` (
						`post_id` int NOT NULL,
						`meta_key` varchar(40) NOT NULL,
						`meta_value` varchar(40) NOT NULL
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE joined UPDATE source',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( "INSERT INTO `join_target` VALUES (1, 'draft'), (2, 'draft')" )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed joined UPDATE target',
				$backend_sql
			);

			$this->assertSame(
				3,
				$driver->query(
					"INSERT INTO `join_source` VALUES
						(1, '_status', 'publish'),
						(2, '_status', 'private'),
						(2, '_other', 'review')"
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed joined UPDATE source',
				$backend_sql
			);

				$this->assertSame(
					1,
					$driver->query(
						"UPDATE `join_target` AS p
					JOIN `join_source` AS pm ON p.id = pm.post_id
					SET p.status = pm.meta_value
					WHERE pm.meta_key = '_status'
							AND p.id = 1"
					)
				);
				$joined_update_sql = $this->get_last_single_postgresql_sql( $driver );
				$this->collect_last_postgresql_queries(
					$driver,
					'current-schema joined UPDATE',
					$backend_sql
				);
				$this->assertStringContainsString( 'UPDATE ' . $schema_sql . '."join_target" AS "p"', $joined_update_sql );
				$this->assertStringContainsString( 'FROM ' . $schema_sql . '."join_source" AS "pm" WHERE (p.id = pm.post_id)', $joined_update_sql );
				$this->assertStringContainsString( 'pm.meta_key = \'_status\'', $joined_update_sql );

				$this->assertSame(
					1,
					$driver->query(
						"UPDATE `join_target` AS p
					JOIN `join_source` AS pm ON p.id = pm.post_id
					SET p.status = pm.meta_value
					WHERE pm.meta_key IN ('_status', '_other')
						AND p.id = 2
					ORDER BY pm.meta_value ASC
						LIMIT 1"
					)
				);
				$derived_update_sql = $this->get_last_single_postgresql_sql( $driver );
				$this->collect_last_postgresql_queries(
					$driver,
					'current-schema derived joined UPDATE',
					$backend_sql
				);
				$this->assertStringContainsString( 'UPDATE ' . $schema_sql . '."join_target" AS "p"', $derived_update_sql );
				$this->assertStringContainsString( 'FROM ' . $schema_sql . '."join_target" AS "p" JOIN ' . $schema_sql . '."join_source" AS "pm" ON p.id = pm.post_id', $derived_update_sql );
				$this->assertStringContainsString( 'ORDER BY pm.meta_value ASC LIMIT 1', $derived_update_sql );

				$this->assertSame(
					0,
					$driver->query(
						'CREATE TABLE `delete_parent` (
						`id` int NOT NULL,
						`status` varchar(20) NOT NULL,
						PRIMARY KEY (`id`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'
					)
				);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE multi-target DELETE parent',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					'CREATE TABLE `delete_child` (
						`id` int NOT NULL,
						`parent_id` int NOT NULL,
						`reason` varchar(20) NOT NULL,
						PRIMARY KEY (`id`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4'
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE multi-target DELETE child',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( "INSERT INTO `delete_parent` VALUES (10, 'stale'), (11, 'keep')" )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed multi-target DELETE parent',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( "INSERT INTO `delete_child` VALUES (100, 10, 'old'), (101, 11, 'new')" )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed multi-target DELETE child',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query(
					"DELETE p, c
					FROM `delete_parent` AS p
					JOIN `delete_child` AS c ON c.parent_id = p.id
						WHERE p.status = 'stale'"
				)
			);
				$multi_target_delete_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
				$this->collect_last_postgresql_queries(
					$driver,
					'current-schema multi-target DELETE',
					$backend_sql
				);
				$this->assertStringContainsString( 'WITH mysql_delete_rows AS MATERIALIZED', $multi_target_delete_sql );
				$this->assertStringContainsString( 'FROM ' . $schema_sql . '."delete_parent" AS "p" JOIN ' . $schema_sql . '."delete_child" AS "c" ON c.parent_id = p.id', $multi_target_delete_sql );
				$this->assertStringContainsString( 'DELETE FROM ' . $schema_sql . '."delete_parent" AS "p" USING mysql_delete_rows', $multi_target_delete_sql );

				$this->assertSame(
					0,
					$driver->query(
						'CREATE TABLE `meta_sample` (
						`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
						`score` int NOT NULL DEFAULT 7,
						`title` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT \'\',
						`body` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
						PRIMARY KEY (`id`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci'
					)
				);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE defaults and coercion sample',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( "INSERT INTO `meta_sample` (`body`) VALUES ('Alpha body')" )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'insert omitted defaults sample',
				$backend_sql
			);

			$coercion_rows    = $driver->query( "SELECT `id` FROM `meta_sample` WHERE `score` = '7' ORDER BY `id`" );
			$coercion_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'numeric coercion sample',
				$backend_sql
			);
			$this->assertCount( 1, $coercion_rows );
			$this->assertSame( '1', (string) $this->get_row_value( $coercion_rows[0], 'id' ) );
			$this->assertStringContainsString(
				'SUBSTRING(CAST',
				implode( "\n", array_column( $coercion_queries, 'sql' ) )
			);

			$metadata_rows = $driver->query(
				"SELECT COLUMN_NAME, COLUMN_DEFAULT, COLUMN_TYPE, COLLATION_NAME
				FROM information_schema.columns
				WHERE table_schema = '" . str_replace( "'", "''", $schema_name ) . "'
					AND table_name = 'meta_sample'
				ORDER BY ORDINAL_POSITION"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema defaults and collation sample',
				$backend_sql
			);
			$this->assertCount( 4, $metadata_rows );
			$score_column = $this->find_row_by_value( $metadata_rows, 'COLUMN_NAME', 'score' );
			$title_column = $this->find_row_by_value( $metadata_rows, 'COLUMN_NAME', 'title' );
			$body_column  = $this->find_row_by_value( $metadata_rows, 'COLUMN_NAME', 'body' );
			$this->assertSame( '7', (string) $this->get_row_value( $score_column, 'COLUMN_DEFAULT' ) );
			$this->assertSame( 'int', $this->get_row_value( $score_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $title_column, 'COLLATION_NAME' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $body_column, 'COLLATION_NAME' ) );

			$this->assertSame( 'ID', $get_column( $schema_name, 'lookup_meta', 'id' ) );
			$this->assertSame( 'Title', $get_column( $schema_name, 'lookup_meta', 'title' ) );
			$this->assertSame( 'Title', $get_column( $schema_name, 'lookup_meta', 'Title' ) );
			$this->assertNull( $get_column( $schema_name, 'lookup_meta', 'missing_column' ) );

			$catalog_queries = $connection->get_catalog_column_queries();
			$this->assertGreaterThanOrEqual( 4, count( $catalog_queries ) );
			foreach ( $catalog_queries as $catalog_query ) {
				$sql = (string) ( $catalog_query['sql'] ?? '' );
				$this->assertStringContainsString( 'FROM information_schema.columns c', $sql );
			}

			$join_rows = $pdo->query(
				'SELECT id, status FROM ' . $schema_sql . '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( 'join_target' )
				. ' ORDER BY id'
			)->fetchAll( PDO::FETCH_OBJ );
			$this->assertCount( 2, $join_rows );
			$this->assertSame( 'publish', $join_rows[0]->status );
			$this->assertSame( 'private', $join_rows[1]->status );

			$parent_rows = $pdo->query(
				'SELECT id, status FROM ' . $schema_sql . '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( 'delete_parent' )
				. ' ORDER BY id'
			)->fetchAll( PDO::FETCH_OBJ );
			$child_rows  = $pdo->query(
				'SELECT id, parent_id, reason FROM ' . $schema_sql . '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( 'delete_child' )
				. ' ORDER BY id'
			)->fetchAll( PDO::FETCH_OBJ );
			$this->assertCount( 1, $parent_rows );
			$this->assertCount( 1, $child_rows );
			$this->assertSame( '11', (string) $parent_rows[0]->id );
			$this->assertSame( 'keep', $parent_rows[0]->status );
			$this->assertSame( '101', (string) $child_rows[0]->id );
			$this->assertSame( '11', (string) $child_rows[0]->parent_id );

			$sample_rows = $pdo->query(
				'SELECT id, score, title, body FROM ' . $schema_sql . '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( 'meta_sample' )
				. ' ORDER BY id'
			)->fetchAll( PDO::FETCH_OBJ );
			$this->assertCount( 1, $sample_rows );
			$this->assertSame( '1', (string) $sample_rows[0]->id );
			$this->assertSame( '7', (string) $sample_rows[0]->score );
			$this->assertSame( '', $sample_rows[0]->title );
			$this->assertSame( 'Alpha body', $sample_rows[0]->body );

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task831' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task831' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task831' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task831' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task831' ) );
		}
	}

	/**
	 * Tests real PostgreSQL CREATE TABLE LIKE/AS/temp paths use catalogs.
	 */
	public function test_real_pgsql_create_table_like_as_and_temporary_paths_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL CREATE TABLE LIKE/AS catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task867' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task867' );

		$database_name       = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection          = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver              = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix              = strtolower( bin2hex( random_bytes( 4 ) ) );
		$source_table        = 'task867_' . $suffix . '_source';
		$like_table          = 'task867_' . $suffix . '_like';
		$ctas_table          = 'task867_' . $suffix . '_as';
		$no_as_table         = 'task867_' . $suffix . '_no_as';
		$if_exists_table     = 'task867_' . $suffix . '_if_exists';
		$if_exists_source    = 'task867_' . $suffix . '_if_source';
		$qualified_table     = 'task867_' . $suffix . '_qualified';
		$temporary_as_table  = 'task867_' . $suffix . '_temp_as';
		$defined_table       = 'task867_' . $suffix . '_defined_as';
		$temporary_defined   = 'task867_' . $suffix . '_temp_defined_as';
		$temporary_like      = 'task867_' . $suffix . '_temp_like';
		$schema_name         = 'task867_' . $suffix . '_schema';
		$schema_source       = 'schema_source';
		$schema_like         = 'schema_like';
		$schema_ctas         = 'schema_as';
		$explicit_ctas       = 'explicit_ctas';
		$explicit_like       = 'explicit_like';
		$explicit_if_exists  = 'explicit_if_exists';
		$backend_sql         = array();
		$source_literal      = $driver->get_connection()->quote( $source_table );
		$like_literal        = $driver->get_connection()->quote( $like_table );
		$ctas_literal        = $driver->get_connection()->quote( $ctas_table );
		$defined_literal     = $driver->get_connection()->quote( $defined_table );
		$schema_sql          = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$schema_ctas_sql     = WP_PostgreSQL_Connection::quote_identifier_value( $schema_ctas );
		$explicit_ctas_sql   = WP_PostgreSQL_Connection::quote_identifier_value( $explicit_ctas );
		$explicit_like_sql   = WP_PostgreSQL_Connection::quote_identifier_value( $explicit_like );
		$explicit_exists_sql = WP_PostgreSQL_Connection::quote_identifier_value( $explicit_if_exists );

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`slug` varchar(64) NOT NULL,
							`title` varchar(191) NOT NULL DEFAULT '' COMMENT 'Title note',
							`score` int NOT NULL DEFAULT 0,
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_unique` (`slug`),
							KEY `title_prefix` (`title`(64))
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Task 867 source table'",
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE source table',
				$backend_sql
			);

			$this->assertSame(
				3,
				$driver->query(
					sprintf(
						"INSERT INTO `%s` (`slug`, `title`, `score`) VALUES
							('alpha', 'Alpha', 1),
							('beta', 'Beta', 2),
							('gamma', 'Gamma', 3)",
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed source rows',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%1$s` LIKE `%2$s`',
						$like_table,
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TABLE LIKE',
				$backend_sql
			);

			$like_create_rows = $driver->query( 'SHOW CREATE TABLE `' . $like_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE for LIKE copy',
				$backend_sql
			);
			$this->assertCount( 1, $like_create_rows );
			$like_create_sql = (string) $this->get_row_value( $like_create_rows[0], 'Create Table' );
			$this->assertStringContainsString( 'CREATE TABLE `' . $like_table . '`', $like_create_sql );
			$this->assertStringContainsString( '`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT', $like_create_sql );
			$this->assertStringContainsString( 'UNIQUE KEY `slug_unique` (`slug`)', $like_create_sql );
			$this->assertStringContainsString( 'KEY `title_prefix` (`title`(64))', $like_create_sql );
			$this->assertStringContainsString( 'COMMENT=\'Task 867 source table\'', $like_create_sql );
			$this->assertStringContainsString( 'COMMENT \'Title note\'', $like_create_sql );
			$this->assertStringContainsString( 'COLLATE=utf8mb4_unicode_ci', $like_create_sql );

			$like_columns = $driver->query( 'SHOW COLUMNS FROM `' . $like_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS for LIKE copy',
				$backend_sql
			);
			$this->assertCount( 4, $like_columns );
			$id_column = $this->find_row_by_value( $like_columns, 'Field', 'id' );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $id_column, 'Type' ) );
			$this->assertSame( 'PRI', $this->get_row_value( $id_column, 'Key' ) );
			$this->assertSame( 'auto_increment', $this->get_row_value( $id_column, 'Extra' ) );
			$title_column = $this->find_row_by_value( $like_columns, 'Field', 'title' );
			$this->assertSame( 'varchar(191)', $this->get_row_value( $title_column, 'Type' ) );
			$this->assertSame( '', $this->get_row_value( $title_column, 'Default' ) );

			$like_indexes = $driver->query( 'SHOW INDEX FROM `' . $like_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX for LIKE copy',
				$backend_sql
			);
			$this->assertNotNull( $this->find_row_by_value( $like_indexes, 'Key_name', 'PRIMARY' ) );
			$this->assertNotNull( $this->find_row_by_value( $like_indexes, 'Key_name', 'slug_unique' ) );
			$title_prefix = $this->find_row_by_value( $like_indexes, 'Key_name', 'title_prefix' );
			$this->assertSame( 'title', $this->get_row_value( $title_prefix, 'Column_name' ) );
			$this->assertSame( '64', $this->get_row_value( $title_prefix, 'Sub_part' ) );

			$table_rows = $driver->query(
				"SELECT table_name, engine, table_collation
				FROM information_schema.tables
				WHERE table_schema = DATABASE()
					AND table_name IN ({$source_literal}, {$like_literal})
				ORDER BY table_name"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables for source and LIKE copy',
				$backend_sql
			);
			$this->assertCount( 2, $table_rows );
			$this->assertSame( $like_table, $this->get_row_value( $this->find_row_by_value( $table_rows, 'TABLE_NAME', $like_table ), 'TABLE_NAME' ) );
			$this->assertSame( 'InnoDB', $this->get_row_value( $this->find_row_by_value( $table_rows, 'TABLE_NAME', $source_table ), 'ENGINE' ) );

			$statistics_rows = $driver->query(
				"SELECT index_name, column_name, sub_part
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$like_literal}
				ORDER BY index_name, seq_in_index"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics for LIKE copy',
				$backend_sql
			);
			$this->assertNotNull( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'PRIMARY' ) );
			$this->assertNotNull( $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'slug_unique' ) );
			$title_prefix_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'title_prefix' );
			$this->assertSame( 'title', $this->get_row_value( $title_prefix_statistic, 'COLUMN_NAME' ) );
			$this->assertSame( '64', $this->get_row_value( $title_prefix_statistic, 'SUB_PART' ) );

			$this->assertGreaterThanOrEqual(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%1$s` AS SELECT `id`, `slug`, `score` FROM `%2$s` WHERE `score` >= 2',
						$ctas_table,
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TABLE AS SELECT',
				$backend_sql
			);

			$ctas_rows = $driver->query( 'SELECT `id`, `slug`, `score` FROM `' . $ctas_table . '` ORDER BY `id`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read CTAS rows',
				$backend_sql
			);
			$this->assertCount( 2, $ctas_rows );
			$this->assertSame( 'beta', $this->get_row_value( $ctas_rows[0], 'slug' ) );
			$this->assertSame( 'gamma', $this->get_row_value( $ctas_rows[1], 'slug' ) );

			$ctas_columns = $driver->query( 'SHOW COLUMNS FROM `' . $ctas_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS for CTAS table',
				$backend_sql
			);
			$this->assertCount( 3, $ctas_columns );
			$this->assertNotNull( $this->find_row_by_value( $ctas_columns, 'Field', 'id' ) );
			$this->assertNotNull( $this->find_row_by_value( $ctas_columns, 'Field', 'slug' ) );
			$this->assertNotNull( $this->find_row_by_value( $ctas_columns, 'Field', 'score' ) );

			$this->assertGreaterThanOrEqual(
				0,
				$driver->query(
					sprintf(
						'CREATE TEMPORARY TABLE `%1$s` AS SELECT `slug`, `score` FROM `%2$s` WHERE `score` = 2',
						$temporary_as_table,
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TEMPORARY TABLE AS SELECT',
				$backend_sql
			);

			$temporary_rows = $driver->query( 'SELECT `slug`, `score` FROM `' . $temporary_as_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read temporary CTAS rows',
				$backend_sql
			);
			$this->assertCount( 1, $temporary_rows );
			$this->assertSame( 'beta', $this->get_row_value( $temporary_rows[0], 'slug' ) );
			$this->assertSame( '2', (string) $this->get_row_value( $temporary_rows[0], 'score' ) );

			$ctas_catalog_rows = $driver->query(
				"SELECT table_name
				FROM information_schema.tables
				WHERE table_schema = DATABASE()
					AND table_name = {$ctas_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables for CTAS table',
				$backend_sql
			);
			$this->assertCount( 1, $ctas_catalog_rows );
			$this->assertSame( $ctas_table, $this->get_row_value( $ctas_catalog_rows[0], 'TABLE_NAME' ) );

			$this->assertGreaterThanOrEqual(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE IF NOT EXISTS `%1$s` SELECT `id`, `slug` FROM `%2$s` WHERE `score` = 1',
						$no_as_table,
						$source_table
					)
				)
			);
			$no_as_sql = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TABLE SELECT without AS and with IF NOT EXISTS',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TABLE IF NOT EXISTS ', $no_as_sql );
			$this->assertStringContainsString( '"' . $no_as_table . '" AS SELECT', $no_as_sql );
			$this->assertStringContainsString( 'FROM "' . $source_table . '" WHERE "score" = 1', $no_as_sql );
			$no_as_rows = $driver->query( 'SELECT `id`, `slug` FROM `' . $no_as_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read CREATE TABLE SELECT without AS rows',
				$backend_sql
			);
			$this->assertCount( 1, $no_as_rows );
			$this->assertSame( 'alpha', $this->get_row_value( $no_as_rows[0], 'slug' ) );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int NOT NULL,
							`name` varchar(20) NOT NULL,
							KEY `name_key` (`name`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$if_exists_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE IF NOT EXISTS preservation target',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`id`, `name`) VALUES (1, 'kept')", $if_exists_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed IF NOT EXISTS preservation target',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (`changed` int NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$if_exists_source
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE IF NOT EXISTS source table',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( 'INSERT INTO `%s` (`changed`) VALUES (2)', $if_exists_source ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed IF NOT EXISTS source table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE IF NOT EXISTS `%1$s` AS SELECT `changed` FROM `%2$s`',
						$if_exists_table,
						$if_exists_source
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TABLE IF NOT EXISTS preserves existing table',
				$backend_sql
			);

			$if_exists_create_rows = $driver->query( 'SHOW CREATE TABLE `' . $if_exists_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE after IF NOT EXISTS preservation',
				$backend_sql
			);
			$if_exists_create_sql = (string) $this->get_row_value( $if_exists_create_rows[0], 'Create Table' );
			$this->assertStringContainsString( '`name` varchar(20) NOT NULL', $if_exists_create_sql );
			$this->assertStringContainsString( 'KEY `name_key` (`name`)', $if_exists_create_sql );
			$this->assertStringNotContainsString( '`changed`', $if_exists_create_sql );
			$if_exists_rows = $driver->query( 'SELECT `id`, `name` FROM `' . $if_exists_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read IF NOT EXISTS preserved rows',
				$backend_sql
			);
			$this->assertCount( 1, $if_exists_rows );
			$this->assertSame( 'kept', $this->get_row_value( $if_exists_rows[0], 'name' ) );

			$this->assertGreaterThanOrEqual(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%1$s`.`%2$s` AS SELECT `id`, `slug` FROM `%3$s` WHERE `score` = 2',
						$database_name,
						$qualified_table,
						$source_table
					)
				)
			);
			$qualified_sql = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TABLE AS SELECT with main database-qualified target',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TABLE ', $qualified_sql );
			$this->assertStringContainsString( '"' . $qualified_table . '" AS SELECT', $qualified_sql );
			$qualified_rows = $driver->query( 'SELECT `id`, `slug` FROM `' . $qualified_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read main database-qualified CTAS rows',
				$backend_sql
			);
			$this->assertCount( 1, $qualified_rows );
			$this->assertSame( 'beta', $this->get_row_value( $qualified_rows[0], 'slug' ) );

			$this->assertGreaterThanOrEqual(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` int NOT NULL,
							`name` varchar(20) NOT NULL COMMENT 'Defined name',
							PRIMARY KEY (`id`)
						) COMMENT='Task 867 defined CTAS'
						AS SELECT 10 AS id, 'ten' AS name",
						$defined_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TABLE AS SELECT with definitions',
				$backend_sql
			);

			$defined_rows = $driver->query( 'SELECT `id`, `name` FROM `' . $defined_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read defined CTAS rows',
				$backend_sql
			);
			$this->assertCount( 1, $defined_rows );
			$this->assertSame( '10', (string) $this->get_row_value( $defined_rows[0], 'id' ) );
			$this->assertSame( 'ten', $this->get_row_value( $defined_rows[0], 'name' ) );

			$defined_create_rows = $driver->query( 'SHOW CREATE TABLE `' . $defined_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE for defined CTAS',
				$backend_sql
			);
			$defined_create_sql = (string) $this->get_row_value( $defined_create_rows[0], 'Create Table' );
			$this->assertStringContainsString( 'CREATE TABLE `' . $defined_table . '`', $defined_create_sql );
			$this->assertStringContainsString( '`id` int NOT NULL', $defined_create_sql );
			$this->assertStringContainsString( 'PRIMARY KEY (`id`)', $defined_create_sql );
			$this->assertStringContainsString( 'COMMENT=\'Task 867 defined CTAS\'', $defined_create_sql );
			$this->assertStringContainsString( 'COMMENT \'Defined name\'', $defined_create_sql );

			$defined_catalog_rows = $driver->query(
				"SELECT table_name, table_comment
				FROM information_schema.tables
				WHERE table_schema = DATABASE()
					AND table_name = {$defined_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables for defined CTAS',
				$backend_sql
			);
			$this->assertCount( 1, $defined_catalog_rows );
			$this->assertSame( 'Task 867 defined CTAS', $this->get_row_value( $defined_catalog_rows[0], 'TABLE_COMMENT' ) );

			$this->assertGreaterThanOrEqual(
				0,
				$driver->query(
					sprintf(
						"CREATE TEMPORARY TABLE `%s` (
							`id` int NOT NULL,
							`name` varchar(20) NOT NULL COMMENT 'Temp defined name',
							PRIMARY KEY (`id`)
						) COMMENT='Task 867 temp defined CTAS'
						AS SELECT 20 AS id, 'twenty' AS name",
						$temporary_defined
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TEMPORARY TABLE AS SELECT with definitions',
				$backend_sql
			);

			$temporary_defined_rows = $driver->query( 'SELECT `id`, `name` FROM `' . $temporary_defined . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read temporary defined CTAS rows',
				$backend_sql
			);
			$this->assertCount( 1, $temporary_defined_rows );
			$this->assertSame( '20', (string) $this->get_row_value( $temporary_defined_rows[0], 'id' ) );
			$this->assertSame( 'twenty', $this->get_row_value( $temporary_defined_rows[0], 'name' ) );

			$temporary_defined_columns = $driver->query( 'SHOW COLUMNS FROM `' . $temporary_defined . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS for temporary defined CTAS',
				$backend_sql
			);
			$this->assertCount( 2, $temporary_defined_columns );
			$this->assertNotNull( $this->find_row_by_value( $temporary_defined_columns, 'Field', 'id' ) );
			$this->assertNotNull( $this->find_row_by_value( $temporary_defined_columns, 'Field', 'name' ) );

			$temporary_defined_create_rows = $driver->query( 'SHOW CREATE TABLE `' . $temporary_defined . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE for temporary defined CTAS',
				$backend_sql
			);
			$temporary_defined_create_sql = (string) $this->get_row_value( $temporary_defined_create_rows[0], 'Create Table' );
			$this->assertStringContainsString( 'CREATE TEMPORARY TABLE `' . $temporary_defined . '`', $temporary_defined_create_sql );
			$this->assertStringContainsString( 'PRIMARY KEY (`id`)', $temporary_defined_create_sql );
			$this->assertStringContainsString( 'COMMENT \'Temp defined name\'', $temporary_defined_create_sql );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TEMPORARY TABLE `%1$s` LIKE `%2$s`',
						$temporary_like,
						$source_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE TEMPORARY TABLE LIKE',
				$backend_sql
			);

			$temporary_like_columns = $driver->query( 'SHOW COLUMNS FROM `' . $temporary_like . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS for temporary LIKE copy',
				$backend_sql
			);
			$this->assertCount( 4, $temporary_like_columns );
			$this->assertNotNull( $this->find_row_by_value( $temporary_like_columns, 'Field', 'id' ) );
			$this->assertNotNull( $this->find_row_by_value( $temporary_like_columns, 'Field', 'slug' ) );

			$temporary_like_indexes = $driver->query( 'SHOW INDEX FROM `' . $temporary_like . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX for temporary LIKE copy',
				$backend_sql
			);
			$this->assertNotNull( $this->find_row_by_value( $temporary_like_indexes, 'Key_name', 'PRIMARY' ) );
			$this->assertNotNull( $this->find_row_by_value( $temporary_like_indexes, 'Key_name', 'slug_unique' ) );

			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );
			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE task867 schema',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` int NOT NULL,
							`slug` varchar(64) NOT NULL,
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_unique` (`slug`)
						) COMMENT='Task 867 schema source'",
						$schema_source
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE current-schema source table',
				$backend_sql
			);

			$this->assertSame(
				2,
				$driver->query( sprintf( "INSERT INTO `%s` VALUES (1, 'one'), (2, 'two')", $schema_source ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'seed current-schema source table',
				$backend_sql
			);

			$this->assertSame( 0, $driver->query( 'USE `' . $database_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE database before explicit non-public CREATE TABLE paths',
				$backend_sql
			);

			$this->assertGreaterThanOrEqual(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%1\$s`.`%2\$s` AS SELECT 7 AS `id`, 'seven' AS `slug`",
						$schema_name,
						$explicit_ctas
					)
				)
			);
			$explicit_ctas_backend_sql = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit non-public CREATE TABLE AS SELECT target',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TABLE ' . $schema_sql . '.' . $explicit_ctas_sql . ' AS SELECT', $explicit_ctas_backend_sql );

			$explicit_ctas_rows = $driver->query( 'SELECT `id`, `slug` FROM `' . $schema_name . '`.`' . $explicit_ctas . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read explicit non-public CTAS rows',
				$backend_sql
			);
			$this->assertCount( 1, $explicit_ctas_rows );
			$this->assertSame( '7', (string) $this->get_row_value( $explicit_ctas_rows[0], 'id' ) );
			$this->assertSame( 'seven', $this->get_row_value( $explicit_ctas_rows[0], 'slug' ) );

			$explicit_ctas_catalog_rows = $driver->query(
				'SELECT table_name
				FROM information_schema.tables
				WHERE table_schema = ' . $driver->get_connection()->quote( $schema_name ) . '
					AND table_name = ' . $driver->get_connection()->quote( $explicit_ctas )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables for explicit non-public CTAS',
				$backend_sql
			);
			$this->assertCount( 1, $explicit_ctas_catalog_rows );
			$this->assertSame( $explicit_ctas, $this->get_row_value( $explicit_ctas_catalog_rows[0], 'TABLE_NAME' ) );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%1$s`.`%2$s` LIKE `%1$s`.`%3$s`',
						$schema_name,
						$explicit_like,
						$schema_source
					)
				)
			);
			$explicit_like_backend_sql = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit non-public CREATE TABLE LIKE target',
				$backend_sql
			);
			$this->assertStringContainsString( 'CREATE TABLE ' . $schema_sql . '.' . $explicit_like_sql, $explicit_like_backend_sql );

			$explicit_like_columns = $driver->query( 'SHOW COLUMNS FROM `' . $schema_name . '`.`' . $explicit_like . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS for explicit non-public LIKE copy',
				$backend_sql
			);
			$this->assertCount( 2, $explicit_like_columns );
			$this->assertSame( 'int', $this->get_row_value( $this->find_row_by_value( $explicit_like_columns, 'Field', 'id' ), 'Type' ) );
			$this->assertSame( 'varchar(64)', $this->get_row_value( $this->find_row_by_value( $explicit_like_columns, 'Field', 'slug' ), 'Type' ) );

			$explicit_like_create_rows = $driver->query( 'SHOW CREATE TABLE `' . $schema_name . '`.`' . $explicit_like . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE for explicit non-public LIKE copy',
				$backend_sql
			);
			$explicit_like_create_sql = (string) $this->get_row_value( $explicit_like_create_rows[0], 'Create Table' );
			$this->assertStringContainsString( 'CREATE TABLE `' . $explicit_like . '`', $explicit_like_create_sql );
			$this->assertStringContainsString( 'UNIQUE KEY `slug_unique` (`slug`)', $explicit_like_create_sql );

			$explicit_like_indexes = $driver->query( 'SHOW INDEX FROM `' . $schema_name . '`.`' . $explicit_like . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX for explicit non-public LIKE copy',
				$backend_sql
			);
			$this->assertNotNull( $this->find_row_by_value( $explicit_like_indexes, 'Key_name', 'PRIMARY' ) );
			$this->assertNotNull( $this->find_row_by_value( $explicit_like_indexes, 'Key_name', 'slug_unique' ) );

			$pdo->exec(
				'CREATE TABLE ' . $schema_sql . '.' . $explicit_exists_sql . ' (
					id integer NOT NULL,
					slug text NOT NULL
				)'
			);
			$pdo->exec( "INSERT INTO {$schema_sql}.{$explicit_exists_sql} (id, slug) VALUES (11, 'kept')" );
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE IF NOT EXISTS `%1\$s`.`%2\$s` AS SELECT 99 AS `id`, 'changed' AS `slug`",
						$schema_name,
						$explicit_if_exists
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'explicit non-public CREATE TABLE IF NOT EXISTS target exists',
				$backend_sql
			);
			$explicit_if_exists_rows = $pdo->query( 'SELECT id, slug FROM ' . $schema_sql . '.' . $explicit_exists_sql )->fetchAll( PDO::FETCH_OBJ );
			$this->assertCount( 1, $explicit_if_exists_rows );
			$this->assertSame( '11', (string) $explicit_if_exists_rows[0]->id );
			$this->assertSame( 'kept', $explicit_if_exists_rows[0]->slug );

			foreach (
				array(
					'pg_catalog'         => 'Unsupported CREATE TABLE statement.',
					'pg_toast'           => 'Unsupported CREATE TABLE statement.',
					'information_schema' => 'Unsupported information_schema query.',
				) as $blocked_schema => $expected_message
			) {
				try {
					$driver->query( 'CREATE TABLE `' . $blocked_schema . '`.`blocked_ctas` AS SELECT 1 AS `id`' );
					$this->fail( 'Expected explicit internal schema CREATE TABLE AS SELECT to fail for ' . $blocked_schema . '.' );
				} catch ( InvalidArgumentException $e ) {
					$this->assertSame( $expected_message, $e->getMessage(), $blocked_schema );
					$this->assertSame( array(), $driver->get_last_postgresql_queries(), $blocked_schema );
				}
			}

			foreach (
				array(
					'pg_catalog'         => 'Unsupported CREATE TABLE statement.',
					'pg_toast'           => 'Unsupported CREATE TABLE statement.',
					'information_schema' => 'Unsupported information_schema query.',
				) as $blocked_schema => $expected_message
			) {
				try {
					$driver->query( 'CREATE TABLE `' . $blocked_schema . '`.`blocked_like` LIKE `' . $schema_name . '`.`' . $schema_source . '`' );
					$this->fail( 'Expected explicit internal schema CREATE TABLE LIKE to fail for ' . $blocked_schema . '.' );
				} catch ( InvalidArgumentException $e ) {
					$this->assertSame( $expected_message, $e->getMessage(), $blocked_schema );
					$this->assertSame( array(), $driver->get_last_postgresql_queries(), $blocked_schema );
				}
			}

			$this->assertSame( 0, $driver->query( 'USE `' . $schema_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE task867 schema after explicit non-public CREATE TABLE paths',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%1$s` LIKE `%2$s`',
						$schema_like,
						$schema_source
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE current-schema LIKE copy',
				$backend_sql
			);

			$this->assertGreaterThanOrEqual(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%1$s` COMMENT = \'Task 867 schema CTAS\' AS SELECT `id`, `slug` FROM `%2$s` WHERE `id` = 2',
						$schema_ctas,
						$schema_source
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE current-schema CTAS',
				$backend_sql
			);

			$schema_like_columns = $driver->query( 'SHOW COLUMNS FROM `' . $schema_like . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS for current-schema LIKE copy',
				$backend_sql
			);
			$this->assertCount( 2, $schema_like_columns );
			$this->assertNotNull( $this->find_row_by_value( $schema_like_columns, 'Field', 'id' ) );
			$this->assertNotNull( $this->find_row_by_value( $schema_like_columns, 'Field', 'slug' ) );

			$schema_like_create_rows = $driver->query( 'SHOW CREATE TABLE `' . $schema_like . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE for current-schema LIKE copy',
				$backend_sql
			);
			$schema_like_create_sql = (string) $this->get_row_value( $schema_like_create_rows[0], 'Create Table' );
			$this->assertStringContainsString( 'CREATE TABLE `' . $schema_like . '`', $schema_like_create_sql );
			$this->assertStringContainsString( 'UNIQUE KEY `slug_unique` (`slug`)', $schema_like_create_sql );
			$this->assertStringContainsString( 'COMMENT=\'Task 867 schema source\'', $schema_like_create_sql );

			$schema_rows = $driver->query( 'SELECT `id`, `slug` FROM `' . $schema_ctas . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'read current-schema CTAS rows',
				$backend_sql
			);
			$this->assertCount( 1, $schema_rows );
			$this->assertSame( '2', (string) $this->get_row_value( $schema_rows[0], 'id' ) );
			$this->assertSame( 'two', $this->get_row_value( $schema_rows[0], 'slug' ) );

			$schema_ctas_create_rows = $driver->query( 'SHOW CREATE TABLE `' . $schema_ctas . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE TABLE for current-schema CTAS',
				$backend_sql
			);
			$schema_ctas_create_sql = (string) $this->get_row_value( $schema_ctas_create_rows[0], 'Create Table' );
			$this->assertStringContainsString( 'CREATE TABLE `' . $schema_ctas . '`', $schema_ctas_create_sql );
			$this->assertStringContainsString( 'COMMENT=\'Task 867 schema CTAS\'', $schema_ctas_create_sql );

			$schema_table_count = (int) $pdo->query(
				'SELECT COUNT(*)
				FROM information_schema.tables
				WHERE table_schema = ' . $pdo->quote( $schema_name ) . '
					AND table_name IN ('
					. $pdo->quote( $schema_source ) . ', '
					. $pdo->quote( $schema_like ) . ', '
					. $pdo->quote( $schema_ctas ) . ')'
			)->fetchColumn();
			$this->assertSame( 3, $schema_table_count );

			$this->assertSame( 0, $driver->query( 'USE `' . $database_name . '`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE database after current-schema CREATE TABLE paths',
				$backend_sql
			);

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$pdo->exec( 'SET search_path TO public' );
			$pdo->exec( 'DROP TABLE IF EXISTS ' . WP_PostgreSQL_Connection::quote_identifier_value( $temporary_as_table ) . ' CASCADE' );
			$pdo->exec( 'DROP TABLE IF EXISTS ' . WP_PostgreSQL_Connection::quote_identifier_value( $temporary_defined ) . ' CASCADE' );
			$pdo->exec( 'DROP TABLE IF EXISTS ' . WP_PostgreSQL_Connection::quote_identifier_value( $temporary_like ) . ' CASCADE' );
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task867' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task867' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task867' ) );
			$this->assertSame( array(), $this->get_pgsql_tables_in_schemas_with_prefix( $pdo, 'task867' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task867' ) );

			$temporary_leftovers = $pdo->prepare(
				"SELECT c.relname
				FROM pg_catalog.pg_class c
				JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
				WHERE n.oid = pg_catalog.pg_my_temp_schema()
					AND c.relname LIKE ? ESCAPE '\\'
				ORDER BY c.relname"
			);
			$temporary_leftovers->execute( array( 'task867\\_%' ) );
			$this->assertSame( array(), $temporary_leftovers->fetchAll( PDO::FETCH_COLUMN ) );
		}
	}

	/**
	 * Tests real PostgreSQL database/schemata metadata paths use native catalogs.
	 */
	public function test_real_pgsql_database_and_schemata_metadata_paths_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL database/schemata catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task875' );

		$database_name  = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection     = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver         = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name    = 'task875_' . $suffix . '_schema';
		$schema_sql     = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$schema_literal = $driver->get_connection()->quote( $schema_name );
		$backend_sql    = array();

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );

			$databases = $driver->query( 'SHOW DATABASES' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW DATABASES',
				$backend_sql
			);
			$database_names = array_map(
				function ( $row ): string {
					return (string) $this->get_row_value( $row, 'Database' );
				},
				$databases
			);
			$this->assertContains( 'information_schema', $database_names );
			$this->assertContains( $database_name, $database_names );
			$this->assertContains( $schema_name, $database_names );
			$this->assertSame( array( 'Database' ), array_column( $driver->get_last_column_meta(), 'name' ) );

			$schema_rows = $driver->query( "SHOW DATABASES LIKE 'task875%'" );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW DATABASES LIKE',
				$backend_sql
			);
			$this->assertEquals( array( (object) array( 'Database' => $schema_name ) ), $schema_rows );

			$selected_rows = $driver->query( "SHOW SCHEMAS WHERE `Database` = {$schema_literal} OR `Database` = 'information_schema'" );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW SCHEMAS WHERE',
				$backend_sql
			);
			$this->assertEquals(
				array(
					(object) array( 'Database' => 'information_schema' ),
					(object) array( 'Database' => $schema_name ),
				),
				$selected_rows
			);
			$this->assertSame( '2', $driver->query( 'SELECT FOUND_ROWS()' )[0]->{'FOUND_ROWS()'} );

			$create_rows = $driver->query( 'SHOW CREATE SCHEMA `' . $schema_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE SCHEMA',
				$backend_sql
			);
			$this->assertCount( 1, $create_rows );
			$this->assertSame( $schema_name, $this->get_row_value( $create_rows[0], 'Database' ) );
			$this->assertSame(
				'CREATE DATABASE `' . $schema_name . '` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci',
				$this->get_row_value( $create_rows[0], 'Create Database' )
			);

			$create_if_not_exists_rows = $driver->query( 'SHOW CREATE SCHEMA IF NOT EXISTS `' . $schema_name . '`', PDO::FETCH_ASSOC );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE SCHEMA IF NOT EXISTS',
				$backend_sql
			);
			$this->assertSame(
				array(
					array(
						'Database'        => $schema_name,
						'Create Database' => 'CREATE DATABASE IF NOT EXISTS `' . $schema_name . '` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci',
					),
				),
				$create_if_not_exists_rows
			);

			$this->assertSame( array(), $driver->query( 'SHOW CREATE DATABASE `task875_missing_schema`' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW CREATE DATABASE missing schema',
				$backend_sql
			);

			$schemata = $driver->query(
				"SELECT schema_name
				FROM information_schema.schemata
				WHERE schema_name = {$schema_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.schemata',
				$backend_sql
			);
			$this->assertEquals( array( (object) array( 'SCHEMA_NAME' => $schema_name ) ), $schemata );

			$star = $driver->query(
				"SELECT *
				FROM information_schema.schemata
				WHERE schema_name = {$schema_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.schemata star',
				$backend_sql
			);
			$this->assertCount( 1, $star );
			$this->assertSame( 'def', $this->get_row_value( $star[0], 'CATALOG_NAME' ) );
			$this->assertSame( $schema_name, $this->get_row_value( $star[0], 'SCHEMA_NAME' ) );
			$this->assertSame( 'utf8mb4', $this->get_row_value( $star[0], 'DEFAULT_CHARACTER_SET_NAME' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $star[0], 'DEFAULT_COLLATION_NAME' ) );
			$this->assertNull( $this->get_row_value( $star[0], 'SQL_PATH' ) );
			$this->assertSame( 'NO', $this->get_row_value( $star[0], 'DEFAULT_ENCRYPTION' ) );

			$this->assertSame( 0, $driver->query( 'USE information_schema' ) );
			$current_database_schemata = $driver->query(
				"SELECT schema_name
				FROM schemata
				WHERE schema_name = {$schema_literal}"
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'current-database schemata relation',
				$backend_sql
			);
			$this->assertEquals( array( (object) array( 'SCHEMA_NAME' => $schema_name ) ), $current_database_schemata );

			$this->assertSame( 0, $driver->query( 'USE `' . $database_name . '`' ) );

			$all_backend_sql = implode( "\n", $backend_sql );
			$this->assertStringContainsString( 'FROM information_schema.schemata s', $all_backend_sql );
			$this->assertStringContainsString( 's.schema_name !~ \'^pg_\'', $all_backend_sql );
			$this->assertStringNotContainsString( 'UNION ALL SELECT', $all_backend_sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$pdo->exec( 'SET search_path TO public' );
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task875' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task875' ) );
		}
	}

	/**
	 * Tests real PostgreSQL SHOW PLUGINS uses native extension catalogs.
	 */
	public function test_real_pgsql_show_plugins_uses_postgresql_extension_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL SHOW PLUGINS catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$extension = $pdo->query(
			"SELECT
					name,
					installed_version,
					default_version,
					comment,
					CASE WHEN installed_version IS NULL THEN 'DISABLED' ELSE 'ACTIVE' END AS status,
					CASE WHEN installed_version IS NULL THEN 'OFF' ELSE 'ON' END AS load_option
				FROM pg_catalog.pg_available_extensions
				WHERE name ~ '^[a-z][a-z0-9_]{2,}$'
				ORDER BY installed_version IS NULL, name
			LIMIT 1"
		)->fetch( PDO::FETCH_ASSOC );
		$this->assertIsArray( $extension );

		$database_name         = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection            = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver                = new WP_PostgreSQL_Driver( $connection, $database_name );
		$plugin_name           = (string) $extension['name'];
		$plugin_status         = (string) $extension['status'];
		$plugin_version        = (string) ( $extension['installed_version'] ?? $extension['default_version'] ?? '' );
		$plugin_type_version   = (string) ( $extension['default_version'] ?? '' );
		$plugin_description    = (string) ( $extension['comment'] ?? '' );
		$plugin_load_option    = (string) $extension['load_option'];
		$plugin_name_literal   = $driver->get_connection()->quote( $plugin_name );
		$plugin_status_literal = $driver->get_connection()->quote( $plugin_status );
		$plugin_like_literal   = $driver->get_connection()->quote( substr( $plugin_name, 0, min( 4, strlen( $plugin_name ) ) ) . '%' );
		$backend_sql           = array();

		$rows = $driver->query( 'SHOW PLUGINS' );
		$this->collect_last_postgresql_queries(
			$driver,
			'SHOW PLUGINS',
			$backend_sql
		);
		$this->assertGreaterThan( 0, count( $rows ) );
		$this->assertSame( array( 'Name', 'Status', 'Type', 'Library', 'License' ), array_column( $driver->get_last_column_meta(), 'name' ) );
		$plugin_row = $this->find_row_by_value( $rows, 'Name', $plugin_name );
		$this->assertSame( $plugin_status, $this->get_row_value( $plugin_row, 'Status' ) );
		$this->assertSame( 'EXTENSION', $this->get_row_value( $plugin_row, 'Type' ) );
		$this->assertNull( $this->get_row_value( $plugin_row, 'Library' ) );
		$this->assertSame( '', $this->get_row_value( $plugin_row, 'License' ) );

		$filtered_rows = $driver->query( "SHOW PLUGINS WHERE Type = 'EXTENSION' AND Status = {$plugin_status_literal}" );
		$this->collect_last_postgresql_queries(
			$driver,
			'SHOW PLUGINS WHERE Type and Status',
			$backend_sql
		);
		$this->find_row_by_value( $filtered_rows, 'Name', $plugin_name );
		$this->assertSame( (string) count( $filtered_rows ), $driver->query( 'SELECT FOUND_ROWS()' )[0]->{'FOUND_ROWS()'} );

		$like_rows = $driver->query( "SHOW PLUGINS LIKE {$plugin_like_literal}" );
		$this->collect_last_postgresql_queries(
			$driver,
			'SHOW PLUGINS LIKE',
			$backend_sql
		);
		$this->find_row_by_value( $like_rows, 'Name', $plugin_name );

		$assoc_rows = $driver->query( "SHOW PLUGINS WHERE BINARY Name = {$plugin_name_literal}", PDO::FETCH_ASSOC );
		$this->collect_last_postgresql_queries(
			$driver,
			'SHOW PLUGINS WHERE BINARY Name',
			$backend_sql
		);
		$this->assertSame(
			array(
				array(
					'Name'    => $plugin_name,
					'Status'  => $plugin_status,
					'Type'    => 'EXTENSION',
					'Library' => null,
					'License' => '',
				),
			),
			$assoc_rows
		);

		$plugin_rows = $driver->query(
			"SELECT PLUGIN_NAME, PLUGIN_VERSION, PLUGIN_STATUS, PLUGIN_TYPE,
				PLUGIN_TYPE_VERSION, PLUGIN_LIBRARY, PLUGIN_LIBRARY_VERSION,
				PLUGIN_AUTHOR, PLUGIN_DESCRIPTION, PLUGIN_LICENSE, LOAD_OPTION
			FROM information_schema.plugins
			WHERE PLUGIN_NAME = {$plugin_name_literal}"
		);
		$plugin_sql  = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.plugins real PostgreSQL',
			$backend_sql
		);
		$this->assertCount( 1, $plugin_rows );
		$this->assertSame(
			array(
				'PLUGIN_NAME',
				'PLUGIN_VERSION',
				'PLUGIN_STATUS',
				'PLUGIN_TYPE',
				'PLUGIN_TYPE_VERSION',
				'PLUGIN_LIBRARY',
				'PLUGIN_LIBRARY_VERSION',
				'PLUGIN_AUTHOR',
				'PLUGIN_DESCRIPTION',
				'PLUGIN_LICENSE',
				'LOAD_OPTION',
			),
			array_column( $driver->get_last_column_meta(), 'name' )
		);
		$plugin_direct_row = $plugin_rows[0];
		$this->assertSame( $plugin_name, $this->get_row_value( $plugin_direct_row, 'PLUGIN_NAME' ) );
		$this->assertSame( $plugin_version, $this->get_row_value( $plugin_direct_row, 'PLUGIN_VERSION' ) );
		$this->assertSame( $plugin_status, $this->get_row_value( $plugin_direct_row, 'PLUGIN_STATUS' ) );
		$this->assertSame( 'EXTENSION', $this->get_row_value( $plugin_direct_row, 'PLUGIN_TYPE' ) );
		$this->assertSame( $plugin_type_version, $this->get_row_value( $plugin_direct_row, 'PLUGIN_TYPE_VERSION' ) );
		$this->assertNull( $this->get_row_value( $plugin_direct_row, 'PLUGIN_LIBRARY' ) );
		$this->assertNull( $this->get_row_value( $plugin_direct_row, 'PLUGIN_LIBRARY_VERSION' ) );
		$this->assertSame( '', $this->get_row_value( $plugin_direct_row, 'PLUGIN_AUTHOR' ) );
		$this->assertSame( $plugin_description, $this->get_row_value( $plugin_direct_row, 'PLUGIN_DESCRIPTION' ) );
		$this->assertSame( '', $this->get_row_value( $plugin_direct_row, 'PLUGIN_LICENSE' ) );
		$this->assertSame( $plugin_load_option, $this->get_row_value( $plugin_direct_row, 'LOAD_OPTION' ) );
		$this->assertStringContainsString( 'FROM pg_catalog.pg_available_extensions ae', $plugin_sql );
		$this->assertStringContainsString( 'ae.name AS "PLUGIN_NAME"', $plugin_sql );
		$this->assertStringContainsString( 'COALESCE(ae.installed_version, ae.default_version, \'\') AS "PLUGIN_VERSION"', $plugin_sql );
		$this->assertStringContainsString( 'CASE WHEN ae.installed_version IS NULL THEN \'DISABLED\' ELSE \'ACTIVE\' END AS "PLUGIN_STATUS"', $plugin_sql );
		$this->assertStringContainsString( 'CASE WHEN ae.installed_version IS NULL THEN \'OFF\' ELSE \'ON\' END AS "LOAD_OPTION"', $plugin_sql );
		$this->assertStringContainsString( 'NULL AS "PLUGIN_LIBRARY"', $plugin_sql );
		$this->assertStringContainsString( 'NULL AS "PLUGIN_LIBRARY_VERSION"', $plugin_sql );
		$this->assertStringNotContainsString( 'UNION ALL', $plugin_sql );

		$all_backend_sql = implode( "\n", $backend_sql );
		$this->assertStringContainsString( 'FROM pg_catalog.pg_available_extensions ae', $all_backend_sql );
		$this->assertStringContainsString( 'p."PLUGIN_NAME" AS "Name"', $all_backend_sql );
		$this->assertStringContainsString( 'ORDER BY p."PLUGIN_NAME"', $all_backend_sql );
		$this->assertGreaterThan( 0, count( $backend_sql ) );
	}

	/**
	 * Tests real PostgreSQL direct information_schema tablespace relations use native catalogs.
	 */
	public function test_real_pgsql_direct_information_schema_tablespace_relations_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema tablespace test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$tablespace = $pdo->query(
			"SELECT
					CAST(oid AS text) AS oid,
					spcname,
					NULLIF(pg_catalog.pg_tablespace_location(oid), '') AS location,
					COALESCE(pg_catalog.obj_description(oid, 'pg_tablespace'), '') AS comment
				FROM pg_catalog.pg_tablespace
				ORDER BY spcname
				LIMIT 1"
		)->fetch( PDO::FETCH_ASSOC );
		$this->assertIsArray( $tablespace );

		$database_name      = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection         = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver             = new WP_PostgreSQL_Driver( $connection, $database_name );
		$tablespace_name    = (string) $tablespace['spcname'];
		$tablespace_literal = $driver->get_connection()->quote( $tablespace_name );
		$backend_sql        = array();

		$file_rows = $driver->query(
			"SELECT FILE_ID, FILE_NAME, FILE_TYPE, TABLESPACE_NAME, ENGINE, STATUS
			FROM information_schema.files
			WHERE TABLESPACE_NAME = {$tablespace_literal}"
		);
		$file_sql  = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.files real PostgreSQL',
			$backend_sql
		);
		$this->assertCount( 1, $file_rows );
		$this->assertSame(
			array( 'FILE_ID', 'FILE_NAME', 'FILE_TYPE', 'TABLESPACE_NAME', 'ENGINE', 'STATUS' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);
		$file_row = $file_rows[0];
		$this->assertSame( (string) $tablespace['oid'], $this->get_row_value( $file_row, 'FILE_ID' ) );
		$this->assertSame( $tablespace['location'], $this->get_row_value( $file_row, 'FILE_NAME' ) );
		$this->assertSame( 'TABLESPACE', $this->get_row_value( $file_row, 'FILE_TYPE' ) );
		$this->assertSame( $tablespace_name, $this->get_row_value( $file_row, 'TABLESPACE_NAME' ) );
		$this->assertSame( 'InnoDB', $this->get_row_value( $file_row, 'ENGINE' ) );
		$this->assertSame( 'NORMAL', $this->get_row_value( $file_row, 'STATUS' ) );
		$this->assertStringContainsString( 'FROM pg_catalog.pg_tablespace ts', $file_sql );
		$this->assertStringContainsString( 'CAST(ts.oid AS bigint) AS "FILE_ID"', $file_sql );
		$this->assertStringContainsString( 'NULLIF(pg_catalog.pg_tablespace_location(ts.oid), \'\') AS "FILE_NAME"', $file_sql );
		$this->assertStringNotContainsString( 'UNION ALL', $file_sql );

		$tablespace_rows = $driver->query(
			"SELECT TABLESPACE_NAME, ENGINE, TABLESPACE_TYPE, TABLESPACE_COMMENT
			FROM information_schema.tablespaces
			WHERE TABLESPACE_NAME = {$tablespace_literal}"
		);
		$tablespace_sql  = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.tablespaces real PostgreSQL',
			$backend_sql
		);
		$this->assertCount( 1, $tablespace_rows );
		$this->assertSame(
			array( 'TABLESPACE_NAME', 'ENGINE', 'TABLESPACE_TYPE', 'TABLESPACE_COMMENT' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);
		$tablespace_row = $tablespace_rows[0];
		$this->assertSame( $tablespace_name, $this->get_row_value( $tablespace_row, 'TABLESPACE_NAME' ) );
		$this->assertSame( 'InnoDB', $this->get_row_value( $tablespace_row, 'ENGINE' ) );
		$this->assertSame( 'General', $this->get_row_value( $tablespace_row, 'TABLESPACE_TYPE' ) );
		$this->assertSame( (string) $tablespace['comment'], $this->get_row_value( $tablespace_row, 'TABLESPACE_COMMENT' ) );
		$this->assertStringContainsString( 'FROM pg_catalog.pg_tablespace ts', $tablespace_sql );
		$this->assertStringContainsString( 'ts.spcname AS "TABLESPACE_NAME"', $tablespace_sql );
		$this->assertStringContainsString( 'pg_catalog.obj_description(ts.oid, \'pg_tablespace\')', $tablespace_sql );
		$this->assertStringNotContainsString( 'UNION ALL', $tablespace_sql );

		$extension_rows = $driver->query(
			"SELECT TABLESPACE_NAME, ENGINE_ATTRIBUTE
			FROM information_schema.tablespaces_extensions
			WHERE TABLESPACE_NAME = {$tablespace_literal}"
		);
		$extension_sql  = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.tablespaces_extensions real PostgreSQL',
			$backend_sql
		);
		$this->assertCount( 1, $extension_rows );
		$this->assertSame(
			array( 'TABLESPACE_NAME', 'ENGINE_ATTRIBUTE' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);
		$this->assertSame( $tablespace_name, $this->get_row_value( $extension_rows[0], 'TABLESPACE_NAME' ) );
		$this->assertNull( $this->get_row_value( $extension_rows[0], 'ENGINE_ATTRIBUTE' ) );
		$this->assertStringContainsString( 'FROM pg_catalog.pg_tablespace ts', $extension_sql );
		$this->assertStringContainsString( 'NULL AS "ENGINE_ATTRIBUTE"', $extension_sql );
		$this->assertStringNotContainsString( 'UNION ALL', $extension_sql );

		$this->assertGreaterThan( 0, count( $backend_sql ) );
	}

	/**
	 * Tests real PostgreSQL text quote paths use native PostgreSQL.
	 */
	public function test_real_pgsql_text_quote_upsert_and_temporal_paths_use_postgresql(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL text quote catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task881' );

		$database_name      = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection         = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver             = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix             = strtolower( bin2hex( random_bytes( 4 ) ) );
		$text_table         = 'task881_' . $suffix . '_text';
		$options_table      = 'task881_' . $suffix . '_options';
		$temporal_table     = 'task881_' . $suffix . '_temporal';
		$text_table_sql     = WP_PostgreSQL_Connection::quote_identifier_value( $text_table );
		$options_table_sql  = WP_PostgreSQL_Connection::quote_identifier_value( $options_table );
		$text_with_nul      = "protected\0property";
		$length_value       = "a\0\xC3\xA9";
		$external_value     = 'pre' . "\xEE\x80\x80" . '0post';
		$serialized_payload = serialize(
			array(
				"\0*\0data" => "single ' double \" backslash \\ marker E'\nnext line",
			)
		);
		$backend_sql        = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`value` longtext NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$text_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE text quote table',
				$backend_sql
			);

			$connection->query(
				'INSERT INTO ' . $text_table_sql . ' (value) VALUES (' . $connection->quote( $text_with_nul ) . ')'
			);
			$connection->query(
				'INSERT INTO ' . $text_table_sql . ' (value) VALUES (?)',
				array( $external_value )
			);
			$connection->query(
				'INSERT INTO ' . $text_table_sql . ' (value) VALUES (' . $connection->quote( $length_value ) . ')'
			);

			$stored_rows = $connection->query( 'SELECT value FROM ' . $text_table_sql . ' ORDER BY id' )->fetchAll( PDO::FETCH_OBJ );
			$this->assertCount( 3, $stored_rows );
			$this->assertStringNotContainsString( "\0", $stored_rows[0]->value );
			$this->assertStringContainsString( 'WP_MYSQL_TEXT_V1:', $stored_rows[0]->value );
			$this->assertSame( $external_value, $stored_rows[1]->value );
			$this->assertStringContainsString( 'WP_MYSQL_TEXT_V1:', $stored_rows[2]->value );

			$decoded_rows = $driver->query( 'SELECT value FROM `' . $text_table . '` ORDER BY id' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SELECT decoded text rows',
				$backend_sql
			);
			$this->assertCount( 3, $decoded_rows );
			$this->assertSame( $text_with_nul, $decoded_rows[0]->value );
			$this->assertSame( $external_value, $decoded_rows[1]->value );
			$this->assertSame( $length_value, $decoded_rows[2]->value );

			$length_rows = $driver->query( 'SELECT LENGTH(value) AS byte_length FROM `' . $text_table . '` WHERE `id` = 3' );
			$this->collect_last_postgresql_queries(
				$driver,
				'LENGTH decoded PostgreSQL text envelope',
				$backend_sql
			);
			$this->assertCount( 1, $length_rows );
			$this->assertSame( '4', (string) $length_rows[0]->byte_length );
			$length_sql = $this->get_last_single_postgresql_sql( $driver );
			$this->assertStringContainsString( 'STRPOS(SUBSTR(CAST(value AS text),', $length_sql );
			$this->assertStringContainsString( "ELSE OCTET_LENGTH(CONVERT_TO(CAST(value AS text), 'UTF8')) END AS byte_length", $length_sql );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`option_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`option_name` varchar(191) NOT NULL DEFAULT '',
							`option_value` longtext NOT NULL,
							`autoload` varchar(20) NOT NULL DEFAULT 'yes',
							PRIMARY KEY (`option_id`),
							UNIQUE KEY `option_name` (`option_name`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
						$options_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE options quote table',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s` (`option_name`, `option_value`, `autoload`)
							VALUES ('_transient_feed_quote_test', %s, 'off')
							ON DUPLICATE KEY UPDATE `option_name` = VALUES(`option_name`),
							                        `option_value` = VALUES(`option_value`),
							                        `autoload` = VALUES(`autoload`)",
						$options_table,
						$this->quote_mysql_string_literal_for_test( $serialized_payload )
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'serialized payload upsert',
				$backend_sql
			);
			$stored_option = (string) $connection->query( 'SELECT option_value FROM ' . $options_table_sql )->fetchColumn();
			$this->assertStringContainsString( 'WP_MYSQL_TEXT_V1:', $stored_option );

			$option_rows = $driver->query( 'SELECT option_value, autoload FROM `' . $options_table . "` WHERE `option_name` = '_transient_feed_quote_test'" );
			$this->collect_last_postgresql_queries(
				$driver,
				'SELECT decoded serialized payload',
				$backend_sql
			);
			$this->assertCount( 1, $option_rows );
			$this->assertSame( $serialized_payload, $option_rows[0]->option_value );
			$this->assertSame( 'off', $option_rows[0]->autoload );

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`date_value` date DEFAULT NULL,
							`datetime_value` datetime DEFAULT NULL,
							`timestamp_value` timestamp NULL DEFAULT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$temporal_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE temporal quote table',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s` (`date_value`, `datetime_value`, `timestamp_value`)
							VALUES ('2024-01-02', '2024-01-03 04:05:06', '2024-01-04 05:06:07')",
						$temporal_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'INSERT temporal quote row',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						'UPDATE `%s`
							SET `date_value` = `datetime_value`,
								`datetime_value` = `timestamp_value`
							WHERE `id` = 1',
						$temporal_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'strict temporal update',
				$backend_sql
			);
			$temporal_sql = $this->get_last_single_postgresql_sql( $driver );
			$this->assertStringContainsString( '(SELECT CASE WHEN "__wp_pg_mysql_temporal_value"."value" IS NULL THEN NULL', $temporal_sql );
			$this->assertStringContainsString( 'FROM (SELECT CAST("datetime_value" AS text) AS "value") AS "__wp_pg_mysql_temporal_value"', $temporal_sql );
			$this->assertStringContainsString( 'FROM (SELECT CAST("timestamp_value" AS text) AS "value") AS "__wp_pg_mysql_temporal_value"', $temporal_sql );
			$this->assertStringContainsString( "'__wp_pg_invalid_temporal__' || COALESCE", $temporal_sql );
			$this->assertStringContainsString( 'BETWEEN 1 AND 9999', $temporal_sql );
			$this->assertStringNotContainsString( '__wp_pg_mysql_validate_temporal', $temporal_sql );

			$this->assertNotEmpty( $backend_sql );
		} finally {
			$pdo->exec( 'SET search_path TO public' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task881' );
		}
	}

	/**
	 * Tests unsupported SHOW TABLE STATUS WHERE clauses fail before backend execution.
	 */
	public function test_unsupported_show_table_status_where_clause_does_not_reach_backend(): void {
		$unsupported_queries = array(
			'SHOW TABLE STATUS WHERE Name LIKE wptests_%',
			'SHOW TABLE STATUS WHERE Name = wptests_options',
		);

		foreach ( $unsupported_queries as $query ) {
			$driver = $this->create_driver();

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported SHOW TABLE STATUS statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SHOW TABLE STATUS statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests real PostgreSQL SHOW TABLE STATUS WHERE Auto_increment filters match SQLite parity.
	 */
	public function test_real_pgsql_show_table_status_where_auto_increment_filters_match_sqlite_parity(): void {
		$driver = $this->create_driver();
		$suffix = strtolower( bin2hex( random_bytes( 4 ) ) );
		$low    = 'show_where_low_' . $suffix;
		$high   = 'show_where_high_' . $suffix;
		$plain  = 'show_where_plain_' . $suffix;

		foreach ( array( $low, $high ) as $table_name ) {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`name` varchar(20) DEFAULT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$table_name
					)
				)
			);
		}

		$this->assertSame(
			0,
			$driver->query(
				sprintf(
					'CREATE TABLE `%s` (
						`id` int DEFAULT NULL,
						`name` varchar(20) DEFAULT NULL
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
					$plain
				)
			)
		);

		$this->assertSame( 1, $driver->query( "INSERT INTO `{$low}` (`name`) VALUES ('a')" ) );
		$this->assertSame( 5, $driver->query( "INSERT INTO `{$high}` (`name`) VALUES ('a'), ('b'), ('c'), ('d'), ('e')" ) );

		$high_rows = $driver->query( 'SHOW TABLE STATUS WHERE Auto_increment > 3' );
		$this->assertSame( array( $high ), array_map( array( $this, 'get_show_table_status_row_name' ), $high_rows ) );

		$plain_rows = $driver->query( 'SHOW TABLE STATUS WHERE Auto_increment IS NULL' );
		$this->assertSame( array( $plain ), array_map( array( $this, 'get_show_table_status_row_name' ), $plain_rows ) );

		$high_literal = $driver->get_connection()->quote( $high );
		$and_rows     = $driver->query( 'SHOW TABLE STATUS WHERE Name = ' . $high_literal . ' AND Auto_increment > 3' );
		$this->assertSame( array( $high ), array_map( array( $this, 'get_show_table_status_row_name' ), $and_rows ) );
	}

	/**
	 * Tests real PostgreSQL SHOW INDEX WHERE pushdown filters match SQLite parity.
	 */
	public function test_real_pgsql_show_index_where_pushdown_filters_match_sqlite_parity(): void {
		$driver      = $this->create_driver();
		$schema_name = $driver->query( 'SELECT DATABASE()' )[0]->{'DATABASE()'};
		$suffix      = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name  = 'show_where_index_' . $suffix;

		$this->assertSame(
			0,
			$driver->query(
				sprintf(
					'CREATE TABLE `%s` (
						`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
						`slug` varchar(64) NOT NULL,
						`title` varchar(191) NOT NULL,
						`body` text,
						PRIMARY KEY (`id`),
						UNIQUE KEY `slug_unique` (`slug`),
						KEY `title_prefix` (`title`(32)),
						FULLTEXT KEY `body_fulltext` (`body`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
					$table_name
				)
			)
		);

			$this->clear_driver_mysql_metadata_caches( $driver );

			$primary_rows    = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Key_name = 'PRIMARY'" );
			$primary_queries = $driver->get_last_postgresql_queries();
			$this->assertCount( 1, $primary_rows );
			$this->assertSame( 'PRIMARY', $this->get_row_value( $primary_rows[0], 'Key_name' ) );
		$this->assertStringContainsString( 'CASE WHEN CAST("Key_name" AS text) ~ ', $primary_queries[0]['sql'] );
		$this->assertStringContainsString( 'translate(CAST("Key_name" AS text), ', $primary_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name, 'PRIMARY', 'PRIMARY', 'PRIMARY' ), $primary_queries[0]['params'] );

		$lower_primary_rows    = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Key_name = 'primary'" );
		$lower_primary_queries = $driver->get_last_postgresql_queries();
		$this->assertCount( 1, $lower_primary_rows );
		$this->assertSame( 'PRIMARY', $this->get_row_value( $lower_primary_rows[0], 'Key_name' ) );
		$this->assertStringContainsString( 'translate(CAST("Key_name" AS text), ', $lower_primary_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name, 'primary', 'primary', 'primary' ), $lower_primary_queries[0]['params'] );

		$unique_rows    = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Non_unique = 0" );
		$unique_queries = $driver->get_last_postgresql_queries();
		$unique_names   = array_map(
			static function ( $row ): string {
				return $row->Key_name;
			},
			$unique_rows
		);
		$this->assertCount( 2, $unique_rows );
		$this->assertContains( 'PRIMARY', $unique_names );
		$this->assertContains( 'slug_unique', $unique_names );
		$this->assertStringContainsString( 'CASE WHEN CAST("Non_unique" AS text) ~ ', $unique_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name, '0', '0', '0' ), $unique_queries[0]['params'] );

		$numeric_string_rows    = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Non_unique = '00'" );
		$numeric_string_queries = $driver->get_last_postgresql_queries();
		$numeric_string_names   = array_map(
			static function ( $row ): string {
				return $row->Key_name;
			},
			$numeric_string_rows
		);
		$this->assertCount( 2, $numeric_string_rows );
		$this->assertContains( 'PRIMARY', $numeric_string_names );
		$this->assertContains( 'slug_unique', $numeric_string_names );
		$this->assertStringContainsString( 'CASE WHEN CAST("Non_unique" AS text) ~ ', $numeric_string_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name, '00', '00', '00' ), $numeric_string_queries[0]['params'] );

		$fulltext_rows    = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Index_type = 'FULLTEXT'" );
		$fulltext_queries = $driver->get_last_postgresql_queries();
		$this->assertCount( 1, $fulltext_rows );
		$this->assertSame( 'body_fulltext', $this->get_row_value( $fulltext_rows[0], 'Key_name' ) );
		$this->assertStringContainsString( 'translate(CAST("Index_type" AS text), ', $fulltext_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name, 'FULLTEXT', 'FULLTEXT', 'FULLTEXT' ), $fulltext_queries[0]['params'] );

		$prefix_rows    = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Sub_part = 32" );
		$prefix_queries = $driver->get_last_postgresql_queries();
		$this->assertCount( 1, $prefix_rows );
		$this->assertSame( 'title_prefix', $this->get_row_value( $prefix_rows[0], 'Key_name' ) );
		$this->assertSame( '32', $this->get_row_value( $prefix_rows[0], 'Sub_part' ) );
		$this->assertStringContainsString( 'CASE WHEN CAST("Sub_part" AS text) ~ ', $prefix_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name, '32', '32', '32' ), $prefix_queries[0]['params'] );

		$like_rows    = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Key_name LIKE 'title%' AND Non_unique = 1" );
		$like_queries = $driver->get_last_postgresql_queries();
		$this->assertCount( 1, $like_rows );
		$this->assertSame( 'title_prefix', $this->get_row_value( $like_rows[0], 'Key_name' ) );
		$this->assertStringNotContainsString( ' LIKE translate(CAST(? AS text), ', $like_queries[0]['sql'] );
		$this->assertStringNotContainsString( 'CASE WHEN CAST("Non_unique" AS text) ~ ', $like_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name ), $like_queries[0]['params'] );
	}

	/**
	 * Tests real PostgreSQL SHOW COLUMNS WHERE pushdown filters match SQLite parity.
	 */
	public function test_real_pgsql_show_columns_where_pushdown_filters_match_sqlite_parity(): void {
		$driver      = $this->create_driver();
		$schema_name = $driver->query( 'SELECT DATABASE()' )[0]->{'DATABASE()'};
		$suffix      = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name  = 'show_where_columns_' . $suffix;

		$this->assertSame(
			0,
			$driver->query(
				sprintf(
					'CREATE TABLE `%s` (
						`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
						`val1` int NOT NULL,
						`val2` int NOT NULL,
						`name` varchar(64) DEFAULT NULL,
						PRIMARY KEY (`id`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
					$table_name
				)
			)
		);

		$like_columns = $driver->query( "SHOW COLUMNS FROM `{$table_name}` LIKE 'val%'" );
		$this->assertSame(
			array( 'val1', 'val2' ),
			array_map(
				static function ( $row ): string {
					return $row->Field;
				},
				$like_columns
			)
		);

		$field_rows    = $driver->query( "SHOW COLUMNS FROM `{$table_name}` WHERE Field = 'val1'" );
		$field_queries = $driver->get_last_postgresql_queries();
		$this->assertCount( 1, $field_rows );
		$this->assertSame( 'val1', $this->get_row_value( $field_rows[0], 'Field' ) );
		$this->assertStringContainsString( 'CASE WHEN CAST("COLUMN_NAME" AS text) ~ ', $field_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name, 'val1', 'val1', 'val1' ), $field_queries[0]['params'] );

		$upper_like_rows    = $driver->query( "SHOW COLUMNS FROM `{$table_name}` WHERE Field LIKE 'VAL%'" );
		$upper_like_queries = $driver->get_last_postgresql_queries();
		$this->assertSame(
			array( 'val1', 'val2' ),
			array_map(
				static function ( $row ): string {
					return $row->Field;
				},
				$upper_like_rows
			)
		);
		$this->assertStringNotContainsString( ' LIKE translate(CAST(? AS text), ', $upper_like_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name ), $upper_like_queries[0]['params'] );

		$underscore_like_rows    = $driver->query( "SHOW COLUMNS FROM `{$table_name}` WHERE Field LIKE 'val_'" );
		$underscore_like_queries = $driver->get_last_postgresql_queries();
		$this->assertSame(
			array( 'val1', 'val2' ),
			array_map(
				static function ( $row ): string {
					return $row->Field;
				},
				$underscore_like_rows
			)
		);
		$this->assertStringNotContainsString( ' LIKE translate(CAST(? AS text), ', $underscore_like_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name ), $underscore_like_queries[0]['params'] );

		$and_rows    = $driver->query( "SHOW COLUMNS FROM `{$table_name}` WHERE Field LIKE 'val%' AND Type = 'int'" );
		$and_queries = $driver->get_last_postgresql_queries();
		$this->assertSame(
			array( 'val1', 'val2' ),
			array_map(
				static function ( $row ): string {
					return $row->Field;
				},
				$and_rows
			)
		);
		$this->assertStringNotContainsString( ' LIKE translate(CAST(? AS text), ', $and_queries[0]['sql'] );
		$this->assertStringNotContainsString( 'CASE WHEN CAST("COLUMN_TYPE" AS text) ~ ', $and_queries[0]['sql'] );
		$this->assertSame( array( $schema_name, $table_name ), $and_queries[0]['params'] );
	}

	/**
	 * Tests missing current-prefix install metadata probes return empty result sets.
	 */
	public function test_real_pgsql_missing_install_state_metadata_probes_return_empty_results(): void {
		$driver         = $this->create_driver();
		$schema_name    = $driver->query( 'SELECT DATABASE()' )[0]->{'DATABASE()'};
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$existing_table = 'taskbz_' . $suffix . '_wp_options';
		$missing_table  = 'taskbz_' . $suffix . '_wp_e2e_options';
		$existing_like  = "'taskbz\\\\_{$suffix}\\\\_wp\\\\_options'";
		$missing_like   = "'taskbz\\\\_{$suffix}\\\\_wp\\\\_e2e\\\\_options'";
		$tables_column  = 'Tables_in_' . $schema_name;

		$this->assertSame(
			0,
			$driver->query(
				sprintf(
					"CREATE TABLE `%s` (
						`option_id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
						`option_name` varchar(191) NOT NULL DEFAULT '',
						`option_value` longtext NOT NULL,
						PRIMARY KEY (`option_id`),
						UNIQUE KEY `option_name` (`option_name`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
					$existing_table
				)
			)
		);
		$this->assertSame(
			1,
			$driver->query(
				sprintf(
					"INSERT INTO `%s` (`option_name`, `option_value`) VALUES ('siteurl', 'http://old-prefix.example')",
					$existing_table
				)
			)
		);

		$this->assertSame( array(), $driver->query( 'DESCRIBE `' . $missing_table . '`' ) );
		$this->assertSame( array(), $driver->query( 'SHOW COLUMNS FROM `' . $missing_table . '`' ) );
		$this->assertSame( array(), $driver->query( 'SHOW TABLES LIKE ' . $missing_like ) );

		$existing_tables = $driver->query( 'SHOW TABLES LIKE ' . $existing_like );
		$this->assertCount( 1, $existing_tables );
		$this->assertSame( $tables_column, $driver->get_last_column_meta()[0]['name'] );
		$this->assertSame( $existing_table, $existing_tables[0]->{$tables_column} );
	}

