	/**
	 * Tests real PostgreSQL SHOW DATABASES WHERE filters match SQLite parity.
	 */
	public function test_real_pgsql_show_databases_where_filters_match_sqlite_parity(): void {
		$driver         = $this->create_driver();
		$schema_name    = $driver->query( 'SELECT DATABASE()' )[0]->{'DATABASE()'};
		$schema_literal = $driver->get_connection()->quote( $schema_name );

		$equal_rows = $driver->query( 'SHOW DATABASES WHERE `Database` = ' . $schema_literal );
		$this->assertEquals( array( (object) array( 'Database' => $schema_name ) ), $equal_rows );

		$and_rows = $driver->query(
			'SHOW SCHEMAS WHERE `Database` LIKE ' .
			$driver->get_connection()->quote( 'wp_pg_test_%' ) .
			' AND `Database` = ' .
			$schema_literal
		);
		$this->assertEquals( array( (object) array( 'Database' => $schema_name ) ), $and_rows );

		$or_rows = $driver->query(
			'SHOW SCHEMAS WHERE `Database` = ' .
			$schema_literal .
			" OR `Database` = 'information_schema'"
		);
		$this->assertEquals(
			array(
				(object) array( 'Database' => 'information_schema' ),
				(object) array( 'Database' => $schema_name ),
			),
			$or_rows
		);
	}

	/**
	 * Tests real PostgreSQL SHOW WHERE function predicates stay PHP filtered.
	 */
	public function test_real_pgsql_show_where_function_predicates_stay_php_filtered(): void {
		$driver      = $this->create_driver();
		$schema_name = $driver->query( 'SELECT DATABASE()' )[0]->{'DATABASE()'};
		$suffix      = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name  = 'show_where_function_' . $suffix;

		$this->assertSame(
			0,
			$driver->query(
				sprintf(
					'CREATE TABLE `%s` (
						`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
						PRIMARY KEY (`id`)
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
					$table_name
				)
			)
		);

		$table_literal = $driver->get_connection()->quote( $table_name );
		$rows          = $driver->query( 'SHOW TABLE STATUS WHERE LOWER(Name) = LOWER(' . $table_literal . ')' );
		$queries       = $driver->get_last_postgresql_queries();

		$this->assertSame( array( $table_name ), array_map( array( $this, 'get_show_table_status_row_name' ), $rows ) );
		$this->assertCount( 1, $queries );
		$this->assertSame( array( $schema_name, 'BASE TABLE' ), $queries[0]['params'] );
		$this->assertStringNotContainsString( $table_name, $queries[0]['sql'] );
	}

	/**
	 * Tests unsupported catalog SHOW WHERE clauses still fail closed.
	 */
	public function test_unsupported_catalog_show_where_clauses_still_fail_closed(): void {
		$driver     = $this->create_driver();
		$table_name = 'unsupported_catalog_show_where';

		$this->assertSame(
			0,
			$driver->query(
				"CREATE TABLE `{$table_name}` (
					`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
					`name` varchar(20) DEFAULT NULL,
					KEY `name_prefix` (`name`(10)),
					PRIMARY KEY (`id`)
				) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
			)
		);

		$unsupported_queries = array(
			'SHOW TABLE STATUS WHERE Name LIKE wptests_%' => 'Unsupported SHOW TABLE STATUS statement.',
			'SHOW TABLE STATUS WHERE Name = wptests_options' => 'Unsupported SHOW TABLE STATUS statement.',
			"SHOW INDEX FROM `{$table_name}` WHERE Key_name LIKE 'x%' ESCAPE '!!'" => 'Unsupported SHOW INDEX statement.',
		);

		foreach ( $unsupported_queries as $query => $message ) {
			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported catalog SHOW WHERE statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( $message, $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

