	/**
	 * Tests SHOW STATUS returns bounded MySQL-shaped status rows.
	 */
	public function test_show_status_returns_bounded_mysql_shaped_rows(): void {
		$driver = $this->create_driver();

		$rows = $driver->query( 'SHOW STATUS' );

		$status = array();
		foreach ( $rows as $row ) {
			$status[ $row->Variable_name ] = $row->Value;
		}

		$this->assertSame( '0', $status['Uptime'] );
		$this->assertSame( '1', $status['Threads_connected'] );
		$this->assertSame( '0', $status['Questions'] );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		$this->assertSame( array( 'Variable_name', 'Value' ), array_column( $driver->get_last_column_meta(), 'name' ) );

		$threads = $driver->query( "SHOW GLOBAL STATUS LIKE 'Threads_%'" );
		$this->assertSame(
			array( 'Threads_cached', 'Threads_connected', 'Threads_created', 'Threads_running' ),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$threads
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$bare_threads = $driver->query( "SHOW STATUS LIKE 'Threads_%'" );
		$this->assertSame(
			array( 'Threads_cached', 'Threads_connected', 'Threads_created', 'Threads_running' ),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$bare_threads
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$uptime = $driver->query( "SHOW SESSION STATUS WHERE Variable_name = 'Uptime'" );
		$this->assertCount( 1, $uptime );
		$this->assertSame( 'Uptime', $uptime[0]->Variable_name );
		$this->assertSame( '0', $uptime[0]->Value );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$handlers = $driver->query( "SHOW STATUS WHERE Variable_name LIKE 'Handler_read_%'" );
		$this->assertSame(
			array(
				'Handler_read_first',
				'Handler_read_key',
				'Handler_read_next',
				'Handler_read_prev',
				'Handler_read_rnd',
				'Handler_read_rnd_next',
			),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$handlers
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$zero_values = $driver->query( "SHOW STATUS WHERE Value = '0'" );
		$zero_names  = array_map(
			static function ( $row ): string {
				return $row->Variable_name;
			},
			$zero_values
		);
		$this->assertContains( 'Uptime', $zero_names );
		$this->assertContains( 'Questions', $zero_names );
		$this->assertNotContains( 'Threads_connected', $zero_names );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$running_threads = $driver->query( "SHOW STATUS WHERE Variable_name LIKE 'Threads_%' AND Value = '1'" );
		$this->assertSame(
			array(
				'Threads_connected',
				'Threads_created',
				'Threads_running',
			),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$running_threads
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$non_zero_values = $driver->query( "SHOW STATUS WHERE Value <> '0'" );
		$this->assertSame(
			array(
				'Connections',
				'Threads_connected',
				'Threads_created',
				'Threads_running',
			),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$non_zero_values
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$thread_or_one_values = $driver->query( "SHOW STATUS WHERE Variable_name LIKE 'Threads_%' OR Value = '1'" );
		$this->assertSame(
			array(
				'Connections',
				'Threads_cached',
				'Threads_connected',
				'Threads_created',
				'Threads_running',
			),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$thread_or_one_values
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$case_insensitive_threads = $driver->query( "SHOW STATUS WHERE Variable_name LIKE 'threads_%'" );
		$this->assertSame(
			array(
				'Threads_cached',
				'Threads_connected',
				'Threads_created',
				'Threads_running',
			),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$case_insensitive_threads
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$binary_threads = $driver->query( "SHOW STATUS WHERE BINARY Variable_name LIKE 'threads_%'" );
		$this->assertSame( array(), $binary_threads );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$escaped_threads = $driver->query( "SHOW STATUS WHERE Variable_name LIKE 'Threads!_%' ESCAPE '!'" );
		$this->assertSame(
			array(
				'Threads_cached',
				'Threads_connected',
				'Threads_created',
				'Threads_running',
			),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$escaped_threads
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$selected_values = $driver->query( "SHOW STATUS WHERE Variable_name IN ('Uptime', 'Threads_running')" );
		$this->assertSame(
			array(
				'Threads_running',
				'Uptime',
			),
			array_map(
				static function ( $row ): string {
					return $row->Variable_name;
				},
				$selected_values
			)
		);
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$unknown_not_in_values = $driver->query( "SHOW STATUS WHERE Value NOT IN ('0', NULL)" );
		$this->assertSame( array(), $unknown_not_in_values );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$truthy_status = $driver->query( 'SHOW STATUS WHERE NOT 0' );
		$this->assertNotCount( 0, $truthy_status );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( (string) count( $truthy_status ), $found_rows[0]->{'FOUND_ROWS()'} );
	}

