	/**
	 * Tests real PostgreSQL SHOW PROCESSLIST uses native activity catalogs.
	 */
	public function test_real_pgsql_show_processlist_uses_postgresql_activity_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL SHOW PROCESSLIST catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$backend_pid   = (string) $pdo->query( 'SELECT pg_catalog.pg_backend_pid()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$backend_sql   = array();

		$rows = $driver->query( 'SHOW FULL PROCESSLIST WHERE Id = ' . $backend_pid );
		$this->collect_last_postgresql_queries(
			$driver,
			'SHOW FULL PROCESSLIST WHERE Id',
			$backend_sql
		);
		$this->assertCount( 1, $rows );
		$this->assertSame( array( 'Id', 'User', 'Host', 'db', 'Command', 'Time', 'State', 'Info' ), array_column( $driver->get_last_column_meta(), 'name' ) );
		$current_row = $rows[0];
		$this->assertSame( $backend_pid, $this->get_row_value( $current_row, 'Id' ) );
		$this->assertSame( $database_name, $this->get_row_value( $current_row, 'db' ) );
		$this->assertSame( 'Query', $this->get_row_value( $current_row, 'Command' ) );
		$this->assertRegExp( '/^[0-9]+$/', (string) $this->get_row_value( $current_row, 'Time' ) );
		$this->assertStringContainsString( 'pg_catalog.pg_stat_activity', (string) $this->get_row_value( $current_row, 'Info' ) );

		$filtered_rows = $driver->query( "SHOW PROCESSLIST WHERE Id = {$backend_pid} AND Command = 'Query' LIMIT 1" );
		$this->collect_last_postgresql_queries(
			$driver,
			'SHOW PROCESSLIST WHERE Id and Command LIMIT',
			$backend_sql
		);
		$this->assertCount( 1, $filtered_rows );
		$this->assertSame( $backend_pid, $this->get_row_value( $filtered_rows[0], 'Id' ) );
		$this->assertSame( '1', $driver->query( 'SELECT FOUND_ROWS()' )[0]->{'FOUND_ROWS()'} );

		$assoc_rows = $driver->query( 'SHOW FULL PROCESSLIST WHERE Id = ' . $backend_pid, PDO::FETCH_ASSOC );
		$this->collect_last_postgresql_queries(
			$driver,
			'SHOW FULL PROCESSLIST assoc',
			$backend_sql
		);
		$this->assertCount( 1, $assoc_rows );
		$this->assertSame( array( 'Id', 'User', 'Host', 'db', 'Command', 'Time', 'State', 'Info' ), array_keys( $assoc_rows[0] ) );
		$this->assertSame( $backend_pid, $assoc_rows[0]['Id'] );

		$direct_rows = $driver->query(
			'SELECT ID, USER, HOST, DB, COMMAND, TIME, STATE, INFO
			FROM information_schema.processlist
			WHERE ID = ' . $backend_pid
		);
		$direct_sql  = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.processlist by ID',
			$backend_sql
		);
		$this->assertCount( 1, $direct_rows );
		$this->assertSame( array( 'ID', 'USER', 'HOST', 'DB', 'COMMAND', 'TIME', 'STATE', 'INFO' ), array_column( $driver->get_last_column_meta(), 'name' ) );
		$direct_row = $direct_rows[0];
		$this->assertSame( $backend_pid, $this->get_row_value( $direct_row, 'ID' ) );
		$this->assertSame( $database_name, $this->get_row_value( $direct_row, 'DB' ) );
		$this->assertSame( 'Query', $this->get_row_value( $direct_row, 'COMMAND' ) );
		$this->assertRegExp( '/^[0-9]+$/', (string) $this->get_row_value( $direct_row, 'TIME' ) );
		$this->assertStringContainsString( 'pg_catalog.pg_stat_activity', (string) $this->get_row_value( $direct_row, 'INFO' ) );
		$this->assertStringContainsString( 'a.pid AS "ID"', $direct_sql );
		$this->assertStringContainsString( 'COALESCE(a.usename, CURRENT_USER) AS "USER"', $direct_sql );
		$this->assertStringContainsString( 'COALESCE(a.query, \'\') AS "INFO"', $direct_sql );
		$this->assertStringContainsString( 'WHERE a.datname IS NULL OR a.datname = current_database()', $direct_sql );
		$this->assertStringNotContainsString( 'UNION ALL', $direct_sql );

		$all_backend_sql = implode( "\n", $backend_sql );
		$this->assertStringContainsString( 'FROM pg_catalog.pg_stat_activity a', $all_backend_sql );
		$this->assertStringContainsString( 'CASE WHEN a.state = \'idle\' THEN \'Sleep\' ELSE \'Query\' END AS "COMMAND"', $all_backend_sql );
		$this->assertStringContainsString( 'ORDER BY p."ID"', $all_backend_sql );
		$this->assertStringNotContainsString( '\'root\' AS "USER"', $all_backend_sql );
		$this->assertGreaterThan( 0, count( $backend_sql ) );
	}

	/**
	 * Tests real PostgreSQL direct information_schema.KEYWORDS uses native keyword catalogs.
	 */
	public function test_real_pgsql_direct_information_schema_keywords_uses_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema keywords test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$backend_sql   = array();

		$rows = $driver->query(
			"SELECT WORD, RESERVED
				FROM information_schema.keywords
				WHERE WORD IN ('SELECT', 'FROM', 'WHERE')
				ORDER BY WORD"
		);
		$sql  = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.keywords real PostgreSQL',
			$backend_sql
		);

		$this->assertGreaterThanOrEqual( 3, count( $rows ) );
		$this->assertSame( array( 'WORD', 'RESERVED' ), array_column( $driver->get_last_column_meta(), 'name' ) );

		$keywords = array();
		foreach ( $rows as $row ) {
			$keywords[ $this->get_row_value( $row, 'WORD' ) ] = (string) $this->get_row_value( $row, 'RESERVED' );
		}

		$this->assertSame( '1', $keywords['FROM'] ?? null );
		$this->assertSame( '1', $keywords['SELECT'] ?? null );
		$this->assertSame( '1', $keywords['WHERE'] ?? null );
		$this->assertStringContainsString( 'FROM pg_catalog.pg_get_keywords() k', $sql );
		$this->assertStringContainsString( 'UPPER(k.word) AS "WORD"', $sql );
		$this->assertStringContainsString( 'CASE WHEN k.catcode = \'R\' THEN 1 ELSE 0 END AS "RESERVED"', $sql );
		$this->assertStringNotContainsString( 'UNION ALL', $sql );
		$this->assertStringNotContainsString( "'SELECT' AS \"WORD\"", $sql );
		$this->assertGreaterThan( 0, count( $backend_sql ) );
	}

