		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$backend_sql   = array();

		$engines = $driver->query(
			"SELECT ENGINE, SUPPORT, COMMENT, TRANSACTIONS, XA, SAVEPOINTS
			FROM information_schema.engines
			WHERE ENGINE = 'InnoDB'"
		);
		$sql     = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.engines real PostgreSQL',
			$backend_sql
		);

		$this->assertCount( 1, $engines );
		$this->assertSame(
			array( 'ENGINE', 'SUPPORT', 'COMMENT', 'TRANSACTIONS', 'XA', 'SAVEPOINTS' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);
		$engine = $engines[0];
		$this->assertSame( 'InnoDB', $this->get_row_value( $engine, 'ENGINE' ) );
		$this->assertSame( 'DEFAULT', $this->get_row_value( $engine, 'SUPPORT' ) );
		$this->assertSame( 'Supports transactions, row-level locking, and foreign keys', $this->get_row_value( $engine, 'COMMENT' ) );
		$this->assertSame( 'YES', $this->get_row_value( $engine, 'TRANSACTIONS' ) );
		$this->assertSame( 'YES', $this->get_row_value( $engine, 'XA' ) );
		$this->assertSame( 'YES', $this->get_row_value( $engine, 'SAVEPOINTS' ) );
		$this->assertStringContainsString( '\'InnoDB\' AS "ENGINE"', $sql );
		$this->assertStringContainsString( '\'DEFAULT\' AS "SUPPORT"', $sql );
		$this->assertStringContainsString( '\'Supports transactions, row-level locking, and foreign keys\' AS "COMMENT"', $sql );
		$this->assertStringContainsString( '\'YES\' AS "TRANSACTIONS"', $sql );
		$this->assertStringContainsString( '\'YES\' AS "XA"', $sql );
		$this->assertStringContainsString( '\'YES\' AS "SAVEPOINTS"', $sql );
		$this->assertStringContainsString( 'UNION ALL', $sql );
		$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
		$this->assertStringNotContainsString( 'pg_catalog.pg_available_extensions', $sql );
		$this->assertStringNotContainsString( 'pg_catalog.pg_stat_activity', $sql );
		$this->assertStringNotContainsString( 'pg_catalog.pg_get_keywords()', $sql );

		$like_engines = $driver->query(
			"SELECT ENGINE
			FROM information_schema.engines
			WHERE ENGINE LIKE 'M%'
			ORDER BY ENGINE"
		);
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.engines real PostgreSQL LIKE',
			$backend_sql
		);
		$this->assertSame(
			array( 'MEMORY', 'MyISAM' ),
			array_map(
				static function ( $row ): string {
					return $row->ENGINE;
				},
				$like_engines
			)
		);
		$this->assertGreaterThan( 0, count( $backend_sql ) );
	}

