	/**
	 * Tests real PostgreSQL SHOW FUNCTION/PROCEDURE STATUS returns empty MySQL-shaped rows.
	 */
	public function test_real_pgsql_show_routine_status_returns_empty_mysql_shaped_rows(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL empty SHOW routine status test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_procedures_with_prefix( $pdo, 'task903_empty' );
		$this->drop_public_pgsql_functions_with_prefix( $pdo, 'task903_empty' );

		$database_name  = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection     = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver         = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$function_like  = $driver->get_connection()->quote( 'task903_empty_' . $suffix . '_function_%' );
		$procedure_like = $driver->get_connection()->quote( 'task903_empty_' . $suffix . '_procedure_%' );
		$columns        = array(
			'Db',
			'Name',
			'Type',
			'Definer',
			'Modified',
			'Created',
			'Security_type',
			'Comment',
			'character_set_client',
			'collation_connection',
			'Database Collation',
		);
		$backend_sql    = array();

		try {
			$function_rows    = $driver->query( 'SHOW FUNCTION STATUS LIKE ' . $function_like );
			$function_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'empty SHOW FUNCTION STATUS LIKE',
				$backend_sql
			);

			$this->assertSame( array(), $function_rows );
			$this->assertSame( $columns, array_column( $driver->get_last_column_meta(), 'name' ) );
			$this->assert_show_routine_status_catalog_query_shape( $function_queries[0], 'FUNCTION' );

			$procedure_rows    = $driver->query( 'SHOW PROCEDURE STATUS LIKE ' . $procedure_like );
			$procedure_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'empty SHOW PROCEDURE STATUS LIKE',
				$backend_sql
			);

			$this->assertSame( array(), $procedure_rows );
			$this->assertSame( $columns, array_column( $driver->get_last_column_meta(), 'name' ) );
			$this->assert_show_routine_status_catalog_query_shape( $procedure_queries[0], 'PROCEDURE' );

			$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
			$this->assertSame( '0', $found_rows[0]->{'FOUND_ROWS()'} );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_procedures_with_prefix( $pdo, 'task903_empty' );
			$this->drop_public_pgsql_functions_with_prefix( $pdo, 'task903_empty' );
			$this->assertSame( array(), $this->get_public_pgsql_procedures_with_prefix( $pdo, 'task903_empty' ) );
			$this->assertSame( array(), $this->get_public_pgsql_functions_with_prefix( $pdo, 'task903_empty' ) );
		}
	}

	/**
	 * Tests real PostgreSQL SHOW FUNCTION/PROCEDURE STATUS uses information_schema routines.
	 */
	public function test_real_pgsql_show_routine_status_uses_postgresql_information_schema(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL SHOW routine status test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_procedures_with_prefix( $pdo, 'task903' );
		$this->drop_public_pgsql_functions_with_prefix( $pdo, 'task903' );

		$database_name    = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection       = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver           = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix           = strtolower( bin2hex( random_bytes( 4 ) ) );
		$function_name    = 'task903_' . $suffix . '_slugify';
		$procedure_name   = 'task903_' . $suffix . '_recount_terms';
		$database_literal = $driver->get_connection()->quote( $database_name );
		$function_literal = $driver->get_connection()->quote( $function_name );
		$procedure_like   = $driver->get_connection()->quote( 'task903_' . $suffix . '_%recount%' );
		$quote_identifier = static function ( string $identifier ): string {
			return WP_PostgreSQL_Connection::quote_identifier_value( $identifier );
		};
		$routine_columns  = array(
			'Db',
			'Name',
			'Type',
			'Definer',
			'Modified',
			'Created',
			'Security_type',
			'Comment',
			'character_set_client',
			'collation_connection',
			'Database Collation',
		);
		$backend_sql      = array();

		try {
			$pdo->exec(
				'CREATE FUNCTION '
				. $quote_identifier( 'public' )
				. '.'
				. $quote_identifier( $function_name )
				. '(input text) RETURNS text LANGUAGE sql SECURITY DEFINER AS $$
	SELECT lower(input);
$$'
			);
			$pdo->exec(
				'CREATE PROCEDURE '
				. $quote_identifier( 'public' )
				. '.'
				. $quote_identifier( $procedure_name )
				. '() LANGUAGE plpgsql SECURITY INVOKER AS $$
BEGIN
END;
$$'
			);

			$function_rows    = $driver->query(
				"SHOW FUNCTION STATUS WHERE Db = {$database_literal} AND Name = {$function_literal}"
			);
			$function_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW FUNCTION STATUS exact function',
				$backend_sql
			);
			$this->assertCount( 1, $function_rows );
			$this->assertSame( $routine_columns, array_column( $driver->get_last_column_meta(), 'name' ) );
			$this->assertSame( $database_name, $this->get_row_value( $function_rows[0], 'Db' ) );
			$this->assertSame( $function_name, $this->get_row_value( $function_rows[0], 'Name' ) );
			$this->assertSame( 'FUNCTION', $this->get_row_value( $function_rows[0], 'Type' ) );
			$this->assertIsString( $this->get_row_value( $function_rows[0], 'Definer' ) );
			$this->assertContains( $this->get_row_value( $function_rows[0], 'Security_type' ), array( 'DEFINER', 'INVOKER' ) );
			$this->assertSame( 'utf8mb4', $this->get_row_value( $function_rows[0], 'character_set_client' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $function_rows[0], 'collation_connection' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $function_rows[0], 'Database Collation' ) );
			$this->assert_show_routine_status_catalog_query_shape( $function_queries[0], 'FUNCTION' );

			$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
			$this->assertSame( '1', $found_rows[0]->{'FOUND_ROWS()'} );

			$procedure_rows    = $driver->query( 'SHOW PROCEDURE STATUS LIKE ' . $procedure_like );
			$procedure_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW PROCEDURE STATUS LIKE procedure',
				$backend_sql
			);
			$this->assertCount( 1, $procedure_rows );
			$this->assertSame( $procedure_name, $this->get_row_value( $procedure_rows[0], 'Name' ) );
			$this->assertSame( 'PROCEDURE', $this->get_row_value( $procedure_rows[0], 'Type' ) );
			$this->assertContains( $this->get_row_value( $procedure_rows[0], 'Security_type' ), array( 'DEFINER', 'INVOKER' ) );
			$this->assert_show_routine_status_catalog_query_shape( $procedure_queries[0], 'PROCEDURE' );

			$assoc_rows    = $driver->query( "SHOW FUNCTION STATUS WHERE BINARY Name = {$function_literal}", PDO::FETCH_ASSOC );
			$assoc_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW FUNCTION STATUS assoc function',
				$backend_sql
			);
			$this->assertCount( 1, $assoc_rows );
			$this->assertSame( $routine_columns, array_keys( $assoc_rows[0] ) );
			$this->assertSame( $function_name, $assoc_rows[0]['Name'] );
			$this->assertSame( 'FUNCTION', $assoc_rows[0]['Type'] );
			$this->assert_show_routine_status_catalog_query_shape( $assoc_queries[0], 'FUNCTION' );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_procedures_with_prefix( $pdo, 'task903' );
			$this->drop_public_pgsql_functions_with_prefix( $pdo, 'task903' );
			$this->assertSame( array(), $this->get_public_pgsql_procedures_with_prefix( $pdo, 'task903' ) );
			$this->assertSame( array(), $this->get_public_pgsql_functions_with_prefix( $pdo, 'task903' ) );
		}
	}

	/**
	 * Tests unsupported SHOW FUNCTION/PROCEDURE STATUS clauses fail before backend execution.
	 */
	public function test_unsupported_show_routine_status_clauses_fail_closed(): void {
		$cases = array(
			'SHOW FUNCTION STATUS LIMIT 1'           => 'Unsupported SHOW FUNCTION STATUS statement.',
			'SHOW FUNCTION STATUS LIKE Name'         => 'Unsupported SHOW FUNCTION STATUS statement.',
			"SHOW FUNCTION STATUS WHERE Bogus = 'x'" => 'Unsupported SHOW FUNCTION STATUS statement.',
			'SHOW PROCEDURE STATUS FROM wptests'     => 'Unsupported SHOW PROCEDURE STATUS statement.',
			'SHOW PROCEDURE STATUS LIMIT 1'          => 'Unsupported SHOW PROCEDURE STATUS statement.',
		);

		foreach ( $cases as $query => $message ) {
			$driver = $this->create_driver();

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported SHOW routine status statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( $message, $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests USE accepts main database identifiers without backend execution.
	 */
	public function test_use_statement_accepts_main_database_identifiers_without_backend_execution(): void {
		$queries = array(
			'USE wptests',
			'USE `wptests`',
		);

		foreach ( $queries as $query ) {
			$driver = $this->create_driver();

			$this->assertSame( 0, $driver->query( $query ), $query );
			$this->assertSame( $query, $driver->get_last_mysql_query(), $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			$this->assertSame( array(), $driver->get_last_column_meta(), $query );

			$database = $driver->query( 'SELECT DATABASE()' );

			$this->assertSame( 'wptests', $database[0]->{'DATABASE()'}, $query );
			$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			$this->assertSame( 'DATABASE()', $driver->get_last_column_meta()[0]['name'], $query );
		}
	}

	/**
	 * Tests real PostgreSQL USE accepts non-public catalog schemas.
	 */
	public function test_real_pgsql_use_statement_accepts_non_public_catalog_schema(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL USE catalog schema test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name   = 'task971_' . $suffix;
		$table_name    = 'plugin_options';
		$schema_sql    = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$table_sql     = $schema_sql . '.' . WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$table_column  = 'Tables_in_' . $schema_name;
		$backend_sql   = array();

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task971' );

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );
			$pdo->exec(
				'CREATE TABLE ' . $table_sql . ' (
					plugin_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
					option_name text NOT NULL
				)'
			);

			$this->assertSame( 0, $driver->query( 'USE ' . $schema_name ) );
			$use_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'real PostgreSQL USE non-public schema',
				$backend_sql
			);
			$this->assertCount( 1, $use_queries );
			$this->assertStringContainsString( 'FROM information_schema.schemata s', $use_queries[0]['sql'] );
			$this->assertSame( array( $schema_name ), $use_queries[0]['params'] );

			$database = $driver->query( 'SELECT DATABASE()' );

			$this->assertSame( $schema_name, $database[0]->{'DATABASE()'} );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );

			$tables = $driver->query( 'SHOW TABLES' );
			$this->collect_last_postgresql_queries(
				$driver,
				'real PostgreSQL SHOW TABLES after USE non-public schema',
				$backend_sql
			);

			$this->assertCount( 1, $tables );
			$this->assertSame( $table_column, $driver->get_last_column_meta()[0]['name'] );
			$this->assertSame( $table_name, $tables[0]->{$table_column} );
			$this->assertSame( array( $schema_name ), $driver->get_last_postgresql_queries()[0]['params'] );

			$columns = $driver->query( 'SHOW COLUMNS FROM ' . $table_name );
			$this->collect_last_postgresql_queries(
				$driver,
				'real PostgreSQL SHOW COLUMNS after USE non-public schema',
				$backend_sql
			);

			$this->assertCount( 2, $columns );
			$plugin_id = $this->find_row_by_value( $columns, 'Field', 'plugin_id' );
			$this->assertSame( 'NO', $this->get_row_value( $plugin_id, 'Null' ) );
			$this->assertSame( 'PRI', $this->get_row_value( $plugin_id, 'Key' ) );
			$this->assertSame( array( $schema_name, $table_name ), $driver->get_last_postgresql_queries()[0]['params'] );

			$this->assertSame( 0, $driver->query( 'USE public' ) );
			$database = $driver->query( 'SELECT DATABASE()' );
			$this->assertSame( $database_name, $database[0]->{'DATABASE()'} );

			try {
				$driver->query( 'USE pg_catalog' );
				$this->fail( 'Expected internal PostgreSQL schema USE statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported USE statement.', $e->getMessage() );
				$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			}

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$pdo->exec( 'SET search_path TO public' );
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task971' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task971' ) );
		}
	}

