	/**
	 * Tests SHOW-backed information_schema relations are available to direct metadata queries.
	 */
	public function test_direct_information_schema_static_relations_expose_show_backed_metadata(): void {
		$driver = $this->create_driver();

		$engines = $driver->query(
			"SELECT ENGINE, SUPPORT, TRANSACTIONS
			FROM information_schema.engines
			WHERE ENGINE = 'InnoDB'"
		);

		$this->assertEquals(
			array(
				(object) array(
					'ENGINE'       => 'InnoDB',
					'SUPPORT'      => 'DEFAULT',
					'TRANSACTIONS' => 'YES',
				),
			),
			$engines
		);

		$driver->query( 'USE information_schema' );
		$engine_columns = $driver->query( "SHOW COLUMNS FROM engines WHERE Field = 'ENGINE'" );

		$this->assertEquals(
			array(
				(object) array(
					'Field'   => 'ENGINE',
					'Type'    => 'varchar(512)',
					'Null'    => 'YES',
					'Key'     => '',
					'Default' => null,
					'Extra'   => '',
				),
			),
			$engine_columns
		);
	}

	/**
	 * Tests real PostgreSQL information_schema.USER_PRIVILEGES reads database ACLs.
	 */
	public function test_real_pgsql_direct_information_schema_user_privileges_uses_database_acls(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema user privileges test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$backend_sql   = array();

		$rows = $driver->query(
			"SELECT GRANTEE, TABLE_CATALOG, PRIVILEGE_TYPE, IS_GRANTABLE
			FROM information_schema.user_privileges
			WHERE TABLE_CATALOG = 'def'
			ORDER BY GRANTEE, PRIVILEGE_TYPE"
		);
		$sql  = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.user_privileges real PostgreSQL',
			$backend_sql
		);

		$this->assertNotEmpty( $rows );
		$this->assertSame(
			array( 'GRANTEE', 'TABLE_CATALOG', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);
		foreach ( $rows as $row ) {
			$this->assertStringContainsString( '@\'%\'', (string) $this->get_row_value( $row, 'GRANTEE' ) );
			$this->assertSame( 'def', $this->get_row_value( $row, 'TABLE_CATALOG' ) );
			$this->assertNotSame( '', (string) $this->get_row_value( $row, 'PRIVILEGE_TYPE' ) );
			$this->assertContains( $this->get_row_value( $row, 'IS_GRANTABLE' ), array( 'YES', 'NO' ) );
		}

		$this->assertStringContainsString( 'FROM pg_catalog.pg_database d', $sql );
		$this->assertStringContainsString( 'pg_catalog.aclexplode(COALESCE(d.datacl, pg_catalog.acldefault(\'d\', d.datdba))) acl', $sql );
		$this->assertStringContainsString( 'LEFT JOIN pg_catalog.pg_roles grantee_role', $sql );
		$this->assertStringContainsString( 'pg_catalog.quote_literal(CASE WHEN acl.grantee = 0 THEN \'PUBLIC\' ELSE grantee_role.rolname END) || \'@\'\'%\'\'\' AS "GRANTEE"', $sql );
		$this->assertStringContainsString( '\'def\' AS "TABLE_CATALOG"', $sql );
		$this->assertStringContainsString( 'acl.privilege_type AS "PRIVILEGE_TYPE"', $sql );
		$this->assertStringContainsString( 'CASE WHEN acl.is_grantable THEN \'YES\' ELSE \'NO\' END AS "IS_GRANTABLE"', $sql );
		$this->assertStringContainsString( 'WHERE d.datname = current_database()', $sql );
		$this->assertStringNotContainsString( 'UNION ALL', $sql );
		$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
		$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $sql );
		$this->assertGreaterThan( 0, count( $backend_sql ) );
	}

	/**
	 * Tests real PostgreSQL information_schema.SCHEMA_PRIVILEGES reads schema ACLs.
	 */
	public function test_real_pgsql_direct_information_schema_schema_privileges_uses_schema_acls(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema schema privileges test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name   = 'task980_' . $suffix;
		$schema_sql    = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$backend_sql   = array();

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task980' );

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );
			$pdo->exec( 'GRANT USAGE ON SCHEMA ' . $schema_sql . ' TO PUBLIC' );

			$rows = $driver->query(
				'SELECT GRANTEE, TABLE_CATALOG, TABLE_SCHEMA, PRIVILEGE_TYPE, IS_GRANTABLE
				FROM information_schema.schema_privileges
				WHERE TABLE_SCHEMA = ' . $driver->get_connection()->quote( $schema_name ) . '
				ORDER BY GRANTEE, PRIVILEGE_TYPE'
			);
			$sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.schema_privileges real PostgreSQL',
				$backend_sql
			);

			$this->assertNotEmpty( $rows );
			$this->assertSame(
				array( 'GRANTEE', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
				array_column( $driver->get_last_column_meta(), 'name' )
			);

			$public_usage_row = null;
			foreach ( $rows as $row ) {
				$this->assertStringContainsString( '@\'%\'', (string) $this->get_row_value( $row, 'GRANTEE' ) );
				$this->assertSame( 'def', $this->get_row_value( $row, 'TABLE_CATALOG' ) );
				$this->assertSame( $schema_name, $this->get_row_value( $row, 'TABLE_SCHEMA' ) );
				$this->assertNotSame( '', (string) $this->get_row_value( $row, 'PRIVILEGE_TYPE' ) );
				$this->assertContains( $this->get_row_value( $row, 'IS_GRANTABLE' ), array( 'YES', 'NO' ) );

				if (
					false !== strpos( (string) $this->get_row_value( $row, 'GRANTEE' ), 'PUBLIC' )
					&& 'USAGE' === $this->get_row_value( $row, 'PRIVILEGE_TYPE' )
				) {
					$public_usage_row = $row;
				}
			}
			$this->assertNotNull( $public_usage_row );

			$this->assertStringContainsString( 'FROM pg_catalog.pg_namespace n', $sql );
			$this->assertStringContainsString( 'pg_catalog.aclexplode(COALESCE(n.nspacl, pg_catalog.acldefault(\'n\', n.nspowner))) acl', $sql );
			$this->assertStringContainsString( 'LEFT JOIN pg_catalog.pg_roles grantee_role', $sql );
			$this->assertStringContainsString( 'pg_catalog.quote_literal(CASE WHEN acl.grantee = 0 THEN \'PUBLIC\' ELSE grantee_role.rolname END) || \'@\'\'%\'\'\' AS "GRANTEE"', $sql );
			$this->assertStringContainsString( '\'def\' AS "TABLE_CATALOG"', $sql );
			$this->assertStringContainsString( 'CASE WHEN n.nspname = \'public\' THEN', $sql );
			$this->assertStringContainsString( 'acl.privilege_type AS "PRIVILEGE_TYPE"', $sql );
			$this->assertStringContainsString( 'CASE WHEN acl.is_grantable THEN \'YES\' ELSE \'NO\' END AS "IS_GRANTABLE"', $sql );
			$this->assertStringContainsString( 'n.nspname !~ \'^(pg_|information_schema$|pg_catalog$)\'', $sql );
			$this->assertStringNotContainsString( 'UNION ALL', $sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task980' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task980' ) );
		}
	}

