		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$schema_name   = 'task982_' . $suffix;
		$table_name    = 'privilege_target';
		$schema_sql    = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$table_sql     = $schema_sql . '.' . WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$backend_sql   = array();

		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task982' );

		try {
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );
			$pdo->exec(
				'CREATE TABLE ' . $table_sql . ' (
					id integer NOT NULL,
					sample_value text NOT NULL
				)'
			);
			$pdo->exec( 'GRANT USAGE ON SCHEMA ' . $schema_sql . ' TO PUBLIC' );
			$pdo->exec( 'GRANT SELECT ON ' . $table_sql . ' TO PUBLIC' );
			$pdo->exec( 'GRANT UPDATE (sample_value) ON ' . $table_sql . ' TO PUBLIC' );

			$table_rows = $driver->query(
				'SELECT GRANTEE, TABLE_CATALOG, TABLE_SCHEMA, TABLE_NAME, PRIVILEGE_TYPE, IS_GRANTABLE
				FROM information_schema.table_privileges
				WHERE TABLE_SCHEMA = ' . $driver->get_connection()->quote( $schema_name ) . '
					AND TABLE_NAME = ' . $driver->get_connection()->quote( $table_name ) . '
				ORDER BY GRANTEE, PRIVILEGE_TYPE'
			);
			$table_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.table_privileges real PostgreSQL',
				$backend_sql
			);

			$this->assertNotEmpty( $table_rows );
			$this->assertSame(
				array( 'GRANTEE', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'TABLE_NAME', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
				array_column( $driver->get_last_column_meta(), 'name' )
			);
			$public_select_table_row = null;
			foreach ( $table_rows as $row ) {
				$this->assertStringContainsString( '@\'%\'', (string) $this->get_row_value( $row, 'GRANTEE' ) );
				$this->assertSame( 'def', $this->get_row_value( $row, 'TABLE_CATALOG' ) );
				$this->assertSame( $schema_name, $this->get_row_value( $row, 'TABLE_SCHEMA' ) );
				$this->assertSame( $table_name, $this->get_row_value( $row, 'TABLE_NAME' ) );
				$this->assertNotSame( '', (string) $this->get_row_value( $row, 'PRIVILEGE_TYPE' ) );
				$this->assertContains( $this->get_row_value( $row, 'IS_GRANTABLE' ), array( 'YES', 'NO' ) );

				if (
					false !== strpos( (string) $this->get_row_value( $row, 'GRANTEE' ), 'PUBLIC' )
					&& 'SELECT' === $this->get_row_value( $row, 'PRIVILEGE_TYPE' )
				) {
					$public_select_table_row = $row;
				}
			}
			$this->assertNotNull( $public_select_table_row );

			$this->assertStringContainsString( 'FROM information_schema.table_privileges tp', $table_sql );
			$this->assertStringContainsString( 'pg_catalog.quote_literal(tp.grantee) || \'@\'\'%\'\'\' AS "GRANTEE"', $table_sql );
			$this->assertStringContainsString( '\'def\' AS "TABLE_CATALOG"', $table_sql );
			$this->assertStringContainsString( 'tp.table_name AS "TABLE_NAME"', $table_sql );
			$this->assertStringContainsString( 'tp.privilege_type AS "PRIVILEGE_TYPE"', $table_sql );
			$this->assertStringContainsString( 'tp.is_grantable AS "IS_GRANTABLE"', $table_sql );
			$this->assertStringContainsString( 'CASE WHEN tp.table_schema = \'public\' THEN', $table_sql );
			$this->assertStringNotContainsString( 'UNION ALL', $table_sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $table_sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $table_sql );

			$column_rows = $driver->query(
				'SELECT GRANTEE, TABLE_CATALOG, TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME, PRIVILEGE_TYPE, IS_GRANTABLE
				FROM information_schema.column_privileges
				WHERE TABLE_SCHEMA = ' . $driver->get_connection()->quote( $schema_name ) . '
					AND TABLE_NAME = ' . $driver->get_connection()->quote( $table_name ) . '
				ORDER BY GRANTEE, COLUMN_NAME, PRIVILEGE_TYPE'
			);
			$column_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.column_privileges real PostgreSQL',
				$backend_sql
			);

			$this->assertNotEmpty( $column_rows );
			$this->assertSame(
				array( 'GRANTEE', 'TABLE_CATALOG', 'TABLE_SCHEMA', 'TABLE_NAME', 'COLUMN_NAME', 'PRIVILEGE_TYPE', 'IS_GRANTABLE' ),
				array_column( $driver->get_last_column_meta(), 'name' )
			);
			$public_update_column_row = null;
			foreach ( $column_rows as $row ) {
				$this->assertStringContainsString( '@\'%\'', (string) $this->get_row_value( $row, 'GRANTEE' ) );
				$this->assertSame( 'def', $this->get_row_value( $row, 'TABLE_CATALOG' ) );
				$this->assertSame( $schema_name, $this->get_row_value( $row, 'TABLE_SCHEMA' ) );
				$this->assertSame( $table_name, $this->get_row_value( $row, 'TABLE_NAME' ) );
				$this->assertContains( $this->get_row_value( $row, 'COLUMN_NAME' ), array( 'id', 'sample_value' ) );
				$this->assertNotSame( '', (string) $this->get_row_value( $row, 'PRIVILEGE_TYPE' ) );
				$this->assertContains( $this->get_row_value( $row, 'IS_GRANTABLE' ), array( 'YES', 'NO' ) );

				if (
					false !== strpos( (string) $this->get_row_value( $row, 'GRANTEE' ), 'PUBLIC' )
					&& 'sample_value' === $this->get_row_value( $row, 'COLUMN_NAME' )
					&& 'UPDATE' === $this->get_row_value( $row, 'PRIVILEGE_TYPE' )
				) {
					$public_update_column_row = $row;
				}
			}
			$this->assertNotNull( $public_update_column_row );

			$this->assertStringContainsString( 'FROM information_schema.column_privileges cp', $column_sql );
			$this->assertStringContainsString( 'pg_catalog.quote_literal(cp.grantee) || \'@\'\'%\'\'\' AS "GRANTEE"', $column_sql );
			$this->assertStringContainsString( '\'def\' AS "TABLE_CATALOG"', $column_sql );
			$this->assertStringContainsString( 'cp.table_name AS "TABLE_NAME"', $column_sql );
			$this->assertStringContainsString( 'cp.column_name AS "COLUMN_NAME"', $column_sql );
			$this->assertStringContainsString( 'cp.privilege_type AS "PRIVILEGE_TYPE"', $column_sql );
			$this->assertStringContainsString( 'cp.is_grantable AS "IS_GRANTABLE"', $column_sql );
			$this->assertStringContainsString( 'CASE WHEN cp.table_schema = \'public\' THEN', $column_sql );
			$this->assertStringNotContainsString( 'UNION ALL', $column_sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $column_sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $column_sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task982' );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task982' ) );
		}
	}

	/**
	 * Tests real PostgreSQL information_schema role membership and grants use native relations.
	 */
	public function test_real_pgsql_direct_information_schema_role_membership_and_grants_use_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema role membership and grants test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$is_superuser = $pdo->query( 'SELECT rolsuper FROM pg_catalog.pg_roles WHERE rolname = current_user' )->fetchColumn();
		if ( true !== $is_superuser && 't' !== $is_superuser && '1' !== (string) $is_superuser ) {
			$this->markTestSkipped( 'The real PostgreSQL role membership and grants test requires a superuser test role.' );
		}

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$current_user  = (string) $pdo->query( 'SELECT current_user' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$member_role   = 'task987_' . $suffix . '_member';
		$admin_role    = 'task987_' . $suffix . '_admin';
		$schema_name   = 'task987_' . $suffix . '_schema';
		$table_name    = 'grant_target';
		$function_name = 'task987_' . $suffix . '_function';
		$member_sql    = WP_PostgreSQL_Connection::quote_identifier_value( $member_role );
		$admin_sql     = WP_PostgreSQL_Connection::quote_identifier_value( $admin_role );
		$current_sql   = WP_PostgreSQL_Connection::quote_identifier_value( $current_user );
		$schema_sql    = WP_PostgreSQL_Connection::quote_identifier_value( $schema_name );
		$table_sql     = $schema_sql . '.' . WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$function_sql  = WP_PostgreSQL_Connection::quote_identifier_value( 'public' ) . '.' . WP_PostgreSQL_Connection::quote_identifier_value( $function_name );
		$backend_sql   = array();

		$this->drop_public_pgsql_functions_with_prefix( $pdo, 'task987' );
		$this->drop_pgsql_schemas_with_prefix( $pdo, 'task987' );
		$this->drop_pgsql_roles_with_prefix( $pdo, 'task987' );

		try {
			$pdo->exec( 'CREATE ROLE ' . $member_sql . ' NOLOGIN' );
			$pdo->exec( 'CREATE ROLE ' . $admin_sql . ' NOLOGIN' );
			$pdo->exec( 'GRANT ' . $member_sql . ' TO ' . $current_sql );
			$pdo->exec( 'GRANT ' . $admin_sql . ' TO ' . $current_sql . ' WITH ADMIN OPTION' );
			$pdo->exec( 'CREATE SCHEMA ' . $schema_sql );
			$pdo->exec(
				'CREATE TABLE ' . $table_sql . ' (
					id integer NOT NULL,
					sample text NOT NULL
				)'
			);
			$pdo->exec(
				'CREATE FUNCTION ' . $function_sql . '(input_value integer) RETURNS integer LANGUAGE sql AS $$
	SELECT input_value;
$$'
			);
			$pdo->exec( 'GRANT USAGE ON SCHEMA ' . $schema_sql . ' TO ' . $member_sql );
			$pdo->exec( 'GRANT SELECT ON ' . $table_sql . ' TO ' . $member_sql );
			$pdo->exec( 'GRANT UPDATE (sample) ON ' . $table_sql . ' TO ' . $member_sql );
			$pdo->exec( 'GRANT EXECUTE ON FUNCTION ' . $function_sql . '(integer) TO ' . $member_sql );

			$applicable_rows = $driver->query(
				'SELECT `USER`, HOST, GRANTEE, GRANTEE_HOST, ROLE_NAME, ROLE_HOST, IS_GRANTABLE, IS_DEFAULT, IS_MANDATORY
				FROM information_schema.applicable_roles
				WHERE ROLE_NAME IN (' . $driver->get_connection()->quote( $member_role ) . ', ' . $driver->get_connection()->quote( $admin_role ) . ')
				ORDER BY ROLE_NAME'
			);
			$applicable_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.applicable_roles real PostgreSQL',
				$backend_sql
			);
			$this->assertCount( 2, $applicable_rows );
			$applicable_member_row = $this->find_row_by_value( $applicable_rows, 'ROLE_NAME', $member_role );
			$applicable_admin_row  = $this->find_row_by_value( $applicable_rows, 'ROLE_NAME', $admin_role );
			$this->assertSame( $current_user, $this->get_row_value( $applicable_member_row, 'USER' ) );
			$this->assertSame( '%', $this->get_row_value( $applicable_member_row, 'HOST' ) );
			$this->assertSame( $current_user, $this->get_row_value( $applicable_member_row, 'GRANTEE' ) );
			$this->assertSame( '%', $this->get_row_value( $applicable_member_row, 'GRANTEE_HOST' ) );
			$this->assertSame( '%', $this->get_row_value( $applicable_member_row, 'ROLE_HOST' ) );
			$this->assertSame( 'NO', $this->get_row_value( $applicable_member_row, 'IS_GRANTABLE' ) );
			$this->assertSame( 'YES', $this->get_row_value( $applicable_admin_row, 'IS_GRANTABLE' ) );
			$this->assertSame( 'NO', $this->get_row_value( $applicable_member_row, 'IS_DEFAULT' ) );
			$this->assertSame( 'NO', $this->get_row_value( $applicable_member_row, 'IS_MANDATORY' ) );
			$this->assertStringContainsString( 'FROM information_schema.applicable_roles ar', $applicable_sql );
			$this->assertStringContainsString( 'ar.grantee AS "USER"', $applicable_sql );
			$this->assertStringNotContainsString( 'UNION ALL', $applicable_sql );

			$administrable_rows = $driver->query(
				'SELECT `USER`, HOST, GRANTEE, GRANTEE_HOST, ROLE_NAME, ROLE_HOST, IS_GRANTABLE, IS_DEFAULT, IS_MANDATORY
				FROM information_schema.administrable_role_authorizations
				WHERE ROLE_NAME = ' . $driver->get_connection()->quote( $admin_role )
			);
			$administrable_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.administrable_role_authorizations real PostgreSQL',
				$backend_sql
			);
			$this->assertCount( 1, $administrable_rows );
			$this->assertSame( $current_user, $this->get_row_value( $administrable_rows[0], 'USER' ) );
			$this->assertSame( '%', $this->get_row_value( $administrable_rows[0], 'HOST' ) );
			$this->assertSame( $admin_role, $this->get_row_value( $administrable_rows[0], 'ROLE_NAME' ) );
			$this->assertSame( 'YES', $this->get_row_value( $administrable_rows[0], 'IS_GRANTABLE' ) );
			$this->assertStringContainsString( 'FROM information_schema.administrable_role_authorizations ara', $administrable_sql );
			$this->assertStringNotContainsString( 'UNION ALL', $administrable_sql );

			$enabled_rows = $driver->query(
				'SELECT ROLE_NAME, ROLE_HOST, IS_DEFAULT, IS_MANDATORY
				FROM information_schema.enabled_roles
				WHERE ROLE_NAME IN (' . $driver->get_connection()->quote( $member_role ) . ', ' . $driver->get_connection()->quote( $admin_role ) . ')
				ORDER BY ROLE_NAME'
			);
			$enabled_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.enabled_roles real PostgreSQL',
				$backend_sql
			);
			$this->assertCount( 2, $enabled_rows );
			$enabled_member_row = $this->find_row_by_value( $enabled_rows, 'ROLE_NAME', $member_role );
			$this->assertSame( '%', $this->get_row_value( $enabled_member_row, 'ROLE_HOST' ) );
			$this->assertSame( 'NO', $this->get_row_value( $enabled_member_row, 'IS_DEFAULT' ) );
			$this->assertSame( 'NO', $this->get_row_value( $enabled_member_row, 'IS_MANDATORY' ) );
			$this->assertStringContainsString( 'FROM information_schema.enabled_roles er', $enabled_sql );
			$this->assertStringNotContainsString( 'UNION ALL', $enabled_sql );

			$table_rows = $driver->query(
				'SELECT GRANTOR, GRANTOR_HOST, GRANTEE, GRANTEE_HOST, TABLE_CATALOG, TABLE_SCHEMA, TABLE_NAME, PRIVILEGE_TYPE, IS_GRANTABLE
				FROM information_schema.role_table_grants
				WHERE TABLE_SCHEMA = ' . $driver->get_connection()->quote( $schema_name ) . '
					AND TABLE_NAME = ' . $driver->get_connection()->quote( $table_name ) . '
				ORDER BY GRANTEE, PRIVILEGE_TYPE'
			);
			$table_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.role_table_grants real PostgreSQL',
				$backend_sql
			);
			$table_member_row = null;
			foreach ( $table_rows as $row ) {
				if ( $member_role === $this->get_row_value( $row, 'GRANTEE' ) && 'SELECT' === $this->get_row_value( $row, 'PRIVILEGE_TYPE' ) ) {
					$table_member_row = $row;
					break;
				}
			}
			$this->assertNotNull( $table_member_row );
			$this->assertSame( $current_user, $this->get_row_value( $table_member_row, 'GRANTOR' ) );
			$this->assertSame( '%', $this->get_row_value( $table_member_row, 'GRANTOR_HOST' ) );
			$this->assertSame( '%', $this->get_row_value( $table_member_row, 'GRANTEE_HOST' ) );
			$this->assertSame( 'def', $this->get_row_value( $table_member_row, 'TABLE_CATALOG' ) );
			$this->assertSame( $schema_name, $this->get_row_value( $table_member_row, 'TABLE_SCHEMA' ) );
			$this->assertSame( $table_name, $this->get_row_value( $table_member_row, 'TABLE_NAME' ) );
			$this->assertSame( 'NO', $this->get_row_value( $table_member_row, 'IS_GRANTABLE' ) );
			$this->assertStringContainsString( 'FROM information_schema.role_table_grants rtg', $table_sql );
			$this->assertStringContainsString( 'rtg.table_name AS "TABLE_NAME"', $table_sql );
			$this->assertStringNotContainsString( 'UNION ALL', $table_sql );

			$column_rows = $driver->query(
				'SELECT GRANTOR, GRANTOR_HOST, GRANTEE, GRANTEE_HOST, TABLE_CATALOG, TABLE_SCHEMA, TABLE_NAME, COLUMN_NAME, PRIVILEGE_TYPE, IS_GRANTABLE
				FROM information_schema.role_column_grants
				WHERE TABLE_SCHEMA = ' . $driver->get_connection()->quote( $schema_name ) . '
					AND TABLE_NAME = ' . $driver->get_connection()->quote( $table_name ) . '
				ORDER BY GRANTEE, COLUMN_NAME, PRIVILEGE_TYPE'
			);
			$column_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.role_column_grants real PostgreSQL',
				$backend_sql
			);
			$column_member_row = null;
			foreach ( $column_rows as $row ) {
				if (
					$member_role === $this->get_row_value( $row, 'GRANTEE' )
					&& 'sample' === $this->get_row_value( $row, 'COLUMN_NAME' )
					&& 'UPDATE' === $this->get_row_value( $row, 'PRIVILEGE_TYPE' )
				) {
					$column_member_row = $row;
					break;
				}
			}
			$this->assertNotNull( $column_member_row );
			$this->assertSame( $current_user, $this->get_row_value( $column_member_row, 'GRANTOR' ) );
			$this->assertSame( '%', $this->get_row_value( $column_member_row, 'GRANTOR_HOST' ) );
			$this->assertSame( '%', $this->get_row_value( $column_member_row, 'GRANTEE_HOST' ) );
			$this->assertSame( 'def', $this->get_row_value( $column_member_row, 'TABLE_CATALOG' ) );
			$this->assertSame( $schema_name, $this->get_row_value( $column_member_row, 'TABLE_SCHEMA' ) );
			$this->assertSame( $table_name, $this->get_row_value( $column_member_row, 'TABLE_NAME' ) );
			$this->assertSame( 'NO', $this->get_row_value( $column_member_row, 'IS_GRANTABLE' ) );
			$this->assertStringContainsString( 'FROM information_schema.role_column_grants rcg', $column_sql );
			$this->assertStringContainsString( 'rcg.column_name AS "COLUMN_NAME"', $column_sql );
			$this->assertStringNotContainsString( 'UNION ALL', $column_sql );

			$routine_rows = $driver->query(
				'SELECT GRANTOR, GRANTOR_HOST, GRANTEE, GRANTEE_HOST, SPECIFIC_SCHEMA, SPECIFIC_NAME, ROUTINE_SCHEMA, ROUTINE_NAME, PRIVILEGE_TYPE, IS_GRANTABLE
				FROM information_schema.role_routine_grants
				WHERE ROUTINE_NAME = ' . $driver->get_connection()->quote( $function_name ) . '
				ORDER BY GRANTEE, PRIVILEGE_TYPE'
			);
			$routine_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.role_routine_grants real PostgreSQL',
				$backend_sql
			);
			$routine_member_row = null;
			foreach ( $routine_rows as $row ) {
				if ( $member_role === $this->get_row_value( $row, 'GRANTEE' ) && 'EXECUTE' === $this->get_row_value( $row, 'PRIVILEGE_TYPE' ) ) {
					$routine_member_row = $row;
					break;
				}
			}
			$this->assertNotNull( $routine_member_row );
			$this->assertSame( $current_user, $this->get_row_value( $routine_member_row, 'GRANTOR' ) );
			$this->assertSame( '%', $this->get_row_value( $routine_member_row, 'GRANTOR_HOST' ) );
			$this->assertSame( '%', $this->get_row_value( $routine_member_row, 'GRANTEE_HOST' ) );
			$this->assertSame( $database_name, $this->get_row_value( $routine_member_row, 'SPECIFIC_SCHEMA' ) );
			$this->assertSame( $database_name, $this->get_row_value( $routine_member_row, 'ROUTINE_SCHEMA' ) );
			$this->assertSame( $function_name, $this->get_row_value( $routine_member_row, 'ROUTINE_NAME' ) );
			$this->assertSame( 'NO', $this->get_row_value( $routine_member_row, 'IS_GRANTABLE' ) );
			$this->assertStringContainsString( 'FROM information_schema.role_routine_grants rrg', $routine_sql );
			$this->assertStringContainsString( 'rrg.routine_name AS "ROUTINE_NAME"', $routine_sql );
			$this->assertStringNotContainsString( 'UNION ALL', $routine_sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_functions_with_prefix( $pdo, 'task987' );
			$this->drop_pgsql_schemas_with_prefix( $pdo, 'task987' );
			$this->drop_pgsql_roles_with_prefix( $pdo, 'task987' );
			$this->assertSame( array(), $this->get_public_pgsql_functions_with_prefix( $pdo, 'task987' ) );
			$this->assertSame( array(), $this->get_pgsql_schemas_with_prefix( $pdo, 'task987' ) );
			$this->assertSame( array(), $this->get_pgsql_roles_with_prefix( $pdo, 'task987' ) );
		}
	}

	/**
	 * Tests real PostgreSQL information_schema.COLUMN_STATISTICS reads pg_stats.
	 */
	public function test_real_pgsql_direct_information_schema_column_statistics_uses_pg_stats(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema column statistics test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name    = 'task965_' . $suffix;
		$table_sql     = WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$backend_sql   = array();

		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task965' );

		try {
			$pdo->exec(
				'CREATE TABLE ' . $table_sql . ' (
					id integer NOT NULL,
					sample_value text NOT NULL
				)'
			);

			$insert = $pdo->prepare( 'INSERT INTO ' . $table_sql . ' (id, sample_value) VALUES (?, ?)' );
			for ( $i = 1; $i <= 200; ++$i ) {
				$insert->execute( array( $i, 'sample-' . str_pad( (string) $i, 3, '0', STR_PAD_LEFT ) ) );
			}

			$pdo->exec( 'ANALYZE ' . $table_sql );

			$rows = $driver->query(
				'SELECT schema_name, table_name, column_name, histogram
				FROM information_schema.column_statistics
				WHERE schema_name = DATABASE()
					AND table_name = ' . $driver->get_connection()->quote( $table_name ) . '
					AND column_name = \'sample_value\'
				ORDER BY column_name'
			);
			$sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.column_statistics real PostgreSQL',
				$backend_sql
			);

			$this->assertGreaterThanOrEqual( 1, count( $rows ) );
			$this->assertSame(
				array( 'SCHEMA_NAME', 'TABLE_NAME', 'COLUMN_NAME', 'HISTOGRAM' ),
				array_column( $driver->get_last_column_meta(), 'name' )
			);

			$row = $this->find_row_by_value( $rows, 'COLUMN_NAME', 'sample_value' );
			$this->assertSame( $database_name, $this->get_row_value( $row, 'SCHEMA_NAME' ) );
			$this->assertSame( $table_name, $this->get_row_value( $row, 'TABLE_NAME' ) );

			$histogram = json_decode( (string) $this->get_row_value( $row, 'HISTOGRAM' ), true );
			$this->assertIsArray( $histogram );
			$this->assertArrayHasKey( 'buckets', $histogram );
			$this->assertArrayHasKey( 'null-values', $histogram );
			$this->assertArrayHasKey( 'last-updated', $histogram );

			$this->assertStringContainsString( 'FROM pg_catalog.pg_stats stats', $sql );
			$this->assertStringContainsString( 'stats.tablename AS "TABLE_NAME"', $sql );
			$this->assertStringContainsString( 'stats.attname AS "COLUMN_NAME"', $sql );
			$this->assertStringContainsString( 'pg_catalog.json_build_object', $sql );
			$this->assertStringContainsString( 'pg_catalog.to_json(stats.histogram_bounds)', $sql );
			$this->assertStringNotContainsString( 'UNION ALL', $sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task965' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task965' ) );
		}
	}

