	/**
	 * Tests real PostgreSQL information_schema.TABLES joins tablespace catalog relations.
	 */
	public function test_real_pgsql_direct_information_schema_tables_tablespaces_join_uses_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema tables/tablespaces join test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$tablespace = $pdo->query(
			'SELECT spcname
			FROM pg_catalog.pg_tablespace
			ORDER BY spcname
			LIMIT 1'
		)->fetch( PDO::FETCH_ASSOC );
		$this->assertIsArray( $tablespace );

		$database_name      = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection         = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver             = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix             = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name         = 'task970_' . $suffix;
		$table_identifier   = WP_PostgreSQL_Connection::quote_identifier_value( 'public' )
			. '.'
			. WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$tablespace_name    = (string) $tablespace['spcname'];
		$tablespace_literal = $driver->get_connection()->quote( $tablespace_name );
		$backend_sql        = array();

		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task970' );

		try {
			$pdo->exec(
				'CREATE TABLE ' . $table_identifier . ' (
					id integer NOT NULL,
					sample_value text NOT NULL
				)'
			);

			$rows = $driver->query(
				'SELECT t.TABLE_NAME, ts.TABLESPACE_NAME
				FROM information_schema.tables AS t
				JOIN information_schema.tablespaces AS ts ON TRUE
				WHERE t.TABLE_SCHEMA = DATABASE()
					AND t.TABLE_NAME = ' . $driver->get_connection()->quote( $table_name ) . '
					AND ts.TABLESPACE_NAME = ' . $tablespace_literal . '
				ORDER BY t.TABLE_NAME, ts.TABLESPACE_NAME'
			);
			$sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.tables/tablespaces join real PostgreSQL',
				$backend_sql
			);

			$this->assertCount( 1, $rows );
			$this->assertSame(
				array( 'TABLE_NAME', 'TABLESPACE_NAME' ),
				array_column( $driver->get_last_column_meta(), 'name' )
			);
			$this->assertSame( $table_name, $this->get_row_value( $rows[0], 'TABLE_NAME' ) );
			$this->assertSame( $tablespace_name, $this->get_row_value( $rows[0], 'TABLESPACE_NAME' ) );

			$this->assertStringContainsString( 'FROM information_schema.tables t', $sql );
			$this->assertStringContainsString( 'FROM pg_catalog.pg_tablespace ts', $sql );
			$this->assertStringContainsString( 'ts.spcname AS "TABLESPACE_NAME"', $sql );
			$this->assertStringContainsString( 'AS "ts"', $sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task970' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task970' ) );
		}
	}

