	/**
	 * Tests main database-qualified application table writes still route after USE information_schema.
	 */
	public function test_use_statement_information_schema_allows_main_database_qualified_writes(): void {
		$driver = $this->create_driver();

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );
		$this->assertSame( 0, $driver->query( 'CREATE TABLE wptests.use_info_main_write (id INTEGER PRIMARY KEY, value TEXT)' ) );

		$this->assertSame( 1, $driver->query( "INSERT INTO wptests.use_info_main_write (id, value) VALUES (1, 'inserted')" ) );
		$this->assertSame( 1, $driver->query( "REPLACE INTO wptests.use_info_main_write (id, value) VALUES (2, 'replaced')" ) );
		$this->assertSame( 1, $driver->query( "UPDATE wptests.use_info_main_write SET value = 'updated' WHERE id = 1" ) );
		$this->assertSame( 1, $driver->query( 'DELETE FROM wptests.use_info_main_write WHERE id = 2' ) );

		$this->assertSame( 1, $driver->query( 'ALTER TABLE wptests.use_info_main_write ADD COLUMN extra VARCHAR(20)' ) );
		$this->assertSame( 0, $driver->query( 'CREATE INDEX idx_use_info_main_write_value ON wptests.use_info_main_write (value)' ) );

		$check = $driver->query( 'CHECK TABLE wptests.use_info_main_write' );
		$this->assertEquals(
			array(
				(object) array(
					'Table'    => 'wptests.use_info_main_write',
					'Op'       => 'check',
					'Msg_type' => 'status',
					'Msg_text' => 'OK',
				),
			),
			$check
		);

		$this->assertSame( 0, $driver->query( 'LOCK TABLES wptests.use_info_main_write READ' ) );
		$this->assertSame( 0, $driver->query( 'UNLOCK TABLES' ) );
		$this->assertSame( 0, $driver->query( 'DROP INDEX idx_use_info_main_write_value ON wptests.use_info_main_write' ) );

		$driver->query( 'USE wptests' );
		$rows = $driver->query( 'SELECT id, value, extra FROM use_info_main_write' );
		$this->assertEquals(
			array(
				(object) array(
					'id'    => '1',
					'value' => 'updated',
					'extra' => null,
				),
			),
			$rows
		);

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );
		$this->assertSame( 0, $driver->query( 'DROP TABLE wptests.use_info_main_write' ) );
	}

	/**
	 * Tests simple main database-qualified SELECT reads still route after USE information_schema.
	 */
	public function test_use_statement_information_schema_allows_simple_main_database_qualified_selects(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE use_info_main_read (id INTEGER PRIMARY KEY, label TEXT)' );
		$driver->query( 'CREATE TABLE use_info_main_read_two (id INTEGER PRIMARY KEY, label TEXT)' );
		$driver->query( "INSERT INTO use_info_main_read (id, label) VALUES (1, 'one'), (2, 'two')" );
		$driver->query( "INSERT INTO use_info_main_read_two (id, label) VALUES (1, 'first'), (2, 'second')" );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$rows = $driver->query(
			'SELECT label
			FROM wptests.use_info_main_read
			WHERE id = 1
			ORDER BY label
			LIMIT 1'
		);

		$this->assertEquals(
			array(
				(object) array(
					'label' => 'one',
				),
			),
			$rows
		);
		$this->assertSame(
			'SELECT label FROM use_info_main_read WHERE id = 1 ORDER BY label LIMIT 1',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query(
			'SELECT r.label
			FROM wptests.use_info_main_read AS r
			WHERE r.id = 2
			ORDER BY r.label
			LIMIT 1'
		);

		$this->assertEquals(
			array(
				(object) array(
					'label' => 'two',
				),
			),
			$rows
		);
		$this->assertSame(
			'SELECT r.label FROM use_info_main_read AS "r" WHERE r.id = 2 ORDER BY r.label LIMIT 1',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query(
			'SELECT r.label
			FROM wptests.use_info_main_read r
			WHERE r.id = 1
			ORDER BY r.label
			LIMIT 1'
		);

		$this->assertEquals(
			array(
				(object) array(
					'label' => 'one',
				),
			),
			$rows
		);
		$this->assertSame(
			'SELECT r.label FROM use_info_main_read AS "r" WHERE r.id = 1 ORDER BY r.label LIMIT 1',
			$this->get_last_single_postgresql_sql( $driver )
		);

		$rows = $driver->query(
			'SELECT r.label, r2.label AS two_label
			FROM wptests.use_info_main_read AS r
			JOIN wptests.use_info_main_read_two AS r2 ON r2.id = r.id
			WHERE r.id = 2
			ORDER BY r2.label'
		);

		$this->assertEquals(
			array(
				(object) array(
					'label'     => 'two',
					'two_label' => 'second',
				),
			),
			$rows
		);
		$this->assertSame(
			'SELECT r.label, r2.label AS two_label FROM use_info_main_read AS r JOIN use_info_main_read_two AS r2 ON r2.id = r.id WHERE r.id = 2 ORDER BY r2.label',
			$this->get_last_single_postgresql_sql( $driver )
		);
	}

	/**
	 * Tests nested main database-qualified SELECT reads still route after USE information_schema.
	 */
	public function test_use_statement_information_schema_allows_nested_main_database_qualified_selects(): void {
		$driver = $this->create_driver();

		$driver->query( 'CREATE TABLE use_info_main_read (id INTEGER PRIMARY KEY, label TEXT)' );
		$driver->query( 'CREATE TABLE use_info_main_read_two (id INTEGER PRIMARY KEY, label TEXT)' );
		$driver->query( "INSERT INTO use_info_main_read (id, label) VALUES (1, 'one'), (2, 'two')" );
		$driver->query( "INSERT INTO use_info_main_read_two (id, label) VALUES (1, 'first'), (2, 'second')" );

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$derived_rows = $driver->query(
			'SELECT r.label
			FROM (
				SELECT label
				FROM wptests.use_info_main_read
				WHERE id = 1
			) AS r'
		);

		$this->assertEquals(
			array(
				(object) array(
					'label' => 'one',
				),
			),
			$derived_rows
		);
		$derived_sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'SELECT label FROM use_info_main_read WHERE id = 1', $derived_sql );
		$this->assertStringNotContainsString( 'wptests.use_info_main_read', $derived_sql );

		$scalar_rows = $driver->query(
			'SELECT (
				SELECT label
				FROM public.use_info_main_read
				WHERE id = 2
			) AS label'
		);

		$this->assertEquals(
			array(
				(object) array(
					'label' => 'two',
				),
			),
			$scalar_rows
		);
		$scalar_sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'SELECT label FROM use_info_main_read WHERE id = 2', $scalar_sql );
		$this->assertStringNotContainsString( 'public.use_info_main_read', $scalar_sql );

		$predicate_rows = $driver->query(
			"SELECT label
			FROM wptests.use_info_main_read
			WHERE id IN (
				SELECT id
				FROM wptests.use_info_main_read_two
				WHERE label = 'second'
			)"
		);

		$this->assertEquals(
			array(
				(object) array(
					'label' => 'two',
				),
			),
			$predicate_rows
		);
		$predicate_sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'SELECT id FROM use_info_main_read_two WHERE label = \'second\'', $predicate_sql );
		$this->assertStringNotContainsString( 'wptests.use_info_main_read_two', $predicate_sql );
	}

