				$this->assertSame( 'Unsupported table administration statement.', $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests real PostgreSQL SHOW OPEN TABLES uses pg_catalog relation and lock rows.
	 */
	public function test_real_pgsql_show_open_tables_uses_postgresql_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL SHOW OPEN TABLES test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task897' );

		$database_name    = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection       = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver           = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix           = strtolower( bin2hex( random_bytes( 4 ) ) );
		$options_table    = 'task897_' . $suffix . '_options';
		$posts_table      = 'task897_' . $suffix . '_posts';
		$database_literal = $driver->get_connection()->quote( $database_name );
		$options_literal  = $driver->get_connection()->quote( $options_table );
		$like_literal     = $driver->get_connection()->quote( 'task897_' . $suffix . '%posts' );
		$database_ident   = '`' . str_replace( '`', '``', $database_name ) . '`';
		$backend_sql      = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`name` varchar(64) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$options_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE SHOW OPEN TABLES options table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`title` varchar(191) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$posts_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE SHOW OPEN TABLES posts table',
				$backend_sql
			);

			$rows                     = $driver->query(
				"SHOW OPEN TABLES WHERE `Database` = {$database_literal} AND `Table` = {$options_literal}"
			);
			$exact_open_table_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW OPEN TABLES exact table',
				$backend_sql
			);
			$this->assertCount( 1, $rows );
			$this->assertSame( array( 'Database', 'Table', 'In_use', 'Name_locked' ), array_column( $driver->get_last_column_meta(), 'name' ) );
			$this->assertSame( $database_name, $this->get_row_value( $rows[0], 'Database' ) );
			$this->assertSame( $options_table, $this->get_row_value( $rows[0], 'Table' ) );
			$this->assertContains( $this->get_row_value( $rows[0], 'In_use' ), array( '0', '1' ) );
			$this->assertContains( $this->get_row_value( $rows[0], 'Name_locked' ), array( '0', '1' ) );
			$this->assert_show_open_tables_catalog_query_shape( $exact_open_table_queries[0] );

			$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
			$this->assertSame( '1', $found_rows[0]->{'FOUND_ROWS()'} );

			$like_rows               = $driver->query( "SHOW OPEN TABLES FROM {$database_ident} LIKE {$like_literal}" );
			$like_open_table_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW OPEN TABLES LIKE posts table',
				$backend_sql
			);
			$this->assertCount( 1, $like_rows );
			$this->assertSame( $database_name, $this->get_row_value( $like_rows[0], 'Database' ) );
			$this->assertSame( $posts_table, $this->get_row_value( $like_rows[0], 'Table' ) );
			$this->assert_show_open_tables_catalog_query_shape( $like_open_table_queries[0] );

			$assoc_rows               = $driver->query( "SHOW OPEN TABLES WHERE BINARY `Table` = {$options_literal}", PDO::FETCH_ASSOC );
			$assoc_open_table_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW OPEN TABLES assoc fetch',
				$backend_sql
			);
			$this->assertCount( 1, $assoc_rows );
			$this->assertSame( array( 'Database', 'Table', 'In_use', 'Name_locked' ), array_keys( $assoc_rows[0] ) );
			$this->assertSame( $options_table, $assoc_rows[0]['Table'] );
			$this->assert_show_open_tables_catalog_query_shape( $assoc_open_table_queries[0] );

			try {
				$driver->query( 'SHOW OPEN TABLES FROM pg_catalog' );
				$this->fail( 'Expected internal PostgreSQL schema SHOW OPEN TABLES statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SHOW OPEN TABLES statement.', $e->getMessage() );
				$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			}

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task897' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task897' ) );
		}
	}

