		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task901' );
		$this->drop_public_pgsql_functions_with_prefix( $pdo, 'task901' );

		$database_name           = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection              = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver                  = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix                  = strtolower( bin2hex( random_bytes( 4 ) ) );
		$options_table           = 'task901_' . $suffix . '_options';
		$posts_table             = 'task901_' . $suffix . '_posts';
		$options_function        = 'task901_' . $suffix . '_options_trigger_fn';
		$posts_function          = 'task901_' . $suffix . '_posts_trigger_fn';
		$options_trigger         = 'task901_' . $suffix . '_options_insert';
		$posts_trigger           = 'task901_' . $suffix . '_posts_update';
		$options_literal         = $driver->get_connection()->quote( $options_table );
		$options_trigger_literal = $driver->get_connection()->quote( $options_trigger );
		$posts_trigger_like      = $driver->get_connection()->quote( 'task901_' . $suffix . '_%posts%' );
		$database_ident          = '`' . str_replace( '`', '``', $database_name ) . '`';
		$trigger_columns         = array(
			'Trigger',
			'Event',
			'Table',
			'Statement',
			'Timing',
			'Created',
			'sql_mode',
			'Definer',
			'character_set_client',
			'collation_connection',
			'Database Collation',
		);
		$quote_identifier        = static function ( string $identifier ): string {
			return WP_PostgreSQL_Connection::quote_identifier_value( $identifier );
		};
		$backend_sql             = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`name` varchar(64) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$options_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE SHOW TRIGGERS options table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`title` varchar(191) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$posts_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE SHOW TRIGGERS posts table',
				$backend_sql
			);

			foreach ( array( $options_function, $posts_function ) as $function_name ) {
				$pdo->exec(
					'CREATE FUNCTION '
					. $quote_identifier( 'public' )
					. '.'
					. $quote_identifier( $function_name )
					. '() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	RETURN NEW;
END;
$$'
				);
			}

			$pdo->exec(
				'CREATE TRIGGER '
				. $quote_identifier( $options_trigger )
				. ' BEFORE INSERT ON '
				. $quote_identifier( 'public' )
				. '.'
				. $quote_identifier( $options_table )
				. ' FOR EACH ROW EXECUTE FUNCTION '
				. $quote_identifier( 'public' )
				. '.'
				. $quote_identifier( $options_function )
				. '()'
			);
			$pdo->exec(
				'CREATE TRIGGER '
				. $quote_identifier( $posts_trigger )
				. ' AFTER UPDATE ON '
				. $quote_identifier( 'public' )
				. '.'
				. $quote_identifier( $posts_table )
				. ' FOR EACH ROW EXECUTE FUNCTION '
				. $quote_identifier( 'public' )
				. '.'
				. $quote_identifier( $posts_function )
				. '()'
			);

			$rows                  = $driver->query(
				"SHOW TRIGGERS WHERE Event = 'INSERT' AND `Table` = {$options_literal}"
			);
			$exact_trigger_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TRIGGERS exact trigger',
				$backend_sql
			);
			$this->assertCount( 1, $rows );
			$this->assertSame( $trigger_columns, array_column( $driver->get_last_column_meta(), 'name' ) );
			$this->assertSame( $options_trigger, $this->get_row_value( $rows[0], 'Trigger' ) );
			$this->assertSame( 'INSERT', $this->get_row_value( $rows[0], 'Event' ) );
			$this->assertSame( $options_table, $this->get_row_value( $rows[0], 'Table' ) );
			$this->assertStringContainsString( $options_function, (string) $this->get_row_value( $rows[0], 'Statement' ) );
			$this->assertSame( 'BEFORE', $this->get_row_value( $rows[0], 'Timing' ) );
			$this->assertIsString( $this->get_row_value( $rows[0], 'sql_mode' ) );
			$this->assertIsString( $this->get_row_value( $rows[0], 'Definer' ) );
			$this->assertSame( 'utf8mb4', $this->get_row_value( $rows[0], 'character_set_client' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $rows[0], 'collation_connection' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $rows[0], 'Database Collation' ) );
			$this->assert_show_triggers_catalog_query_shape( $exact_trigger_queries[0], $database_name );

			$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
			$this->assertSame( '1', $found_rows[0]->{'FOUND_ROWS()'} );

			$like_rows            = $driver->query( "SHOW TRIGGERS FROM {$database_ident} LIKE {$posts_trigger_like}" );
			$like_trigger_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TRIGGERS LIKE posts trigger',
				$backend_sql
			);
			$this->assertCount( 1, $like_rows );
			$this->assertSame( $posts_trigger, $this->get_row_value( $like_rows[0], 'Trigger' ) );
			$this->assertSame( 'UPDATE', $this->get_row_value( $like_rows[0], 'Event' ) );
			$this->assertSame( $posts_table, $this->get_row_value( $like_rows[0], 'Table' ) );
			$this->assertStringContainsString( $posts_function, (string) $this->get_row_value( $like_rows[0], 'Statement' ) );
			$this->assertSame( 'AFTER', $this->get_row_value( $like_rows[0], 'Timing' ) );
			$this->assert_show_triggers_catalog_query_shape( $like_trigger_queries[0], $database_name );

			$assoc_rows            = $driver->query( "SHOW TRIGGERS WHERE BINARY `Trigger` = {$options_trigger_literal}", PDO::FETCH_ASSOC );
			$assoc_trigger_queries = $driver->get_last_postgresql_queries();
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW TRIGGERS assoc trigger',
				$backend_sql
			);
			$this->assertCount( 1, $assoc_rows );
			$this->assertSame( $trigger_columns, array_keys( $assoc_rows[0] ) );
			$this->assertSame( $options_trigger, $assoc_rows[0]['Trigger'] );
			$this->assertSame( 'INSERT', $assoc_rows[0]['Event'] );
			$this->assertSame( $options_table, $assoc_rows[0]['Table'] );
			$this->assert_show_triggers_catalog_query_shape( $assoc_trigger_queries[0], $database_name );

			try {
				$driver->query( 'SHOW TRIGGERS FROM pg_catalog' );
				$this->fail( 'Expected internal PostgreSQL schema SHOW TRIGGERS statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( 'Unsupported SHOW TRIGGERS statement.', $e->getMessage() );
				$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			}

			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			foreach (
				array(
					array( $options_trigger, $options_table ),
					array( $posts_trigger, $posts_table ),
				) as $trigger
			) {
				$pdo->exec(
					'DROP TRIGGER IF EXISTS '
					. $quote_identifier( $trigger[0] )
					. ' ON '
					. $quote_identifier( 'public' )
					. '.'
					. $quote_identifier( $trigger[1] )
				);
			}
			$this->drop_public_pgsql_functions_with_prefix( $pdo, 'task901' );
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task901' );
			$trigger_stmt = $pdo->prepare(
				"SELECT trigger_name
				FROM information_schema.triggers
				WHERE trigger_schema = 'public'
					AND trigger_name LIKE ? ESCAPE '\\'
				ORDER BY trigger_name"
			);
			$trigger_stmt->execute( array( 'task901\\_%' ) );
			$this->assertSame( array(), $trigger_stmt->fetchAll( PDO::FETCH_COLUMN ) );
			$this->assertSame( array(), $this->get_public_pgsql_functions_with_prefix( $pdo, 'task901' ) );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task901' ) );
		}
	}

	/**
