	/**
	 * Tests real PostgreSQL information_schema.PARTITIONS uses native partition catalogs.
	 */
	public function test_real_pgsql_direct_information_schema_partitions_uses_partition_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema partitions test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name  = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection     = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver         = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$parent_table   = 'task968_' . $suffix . '_parent';
		$low_partition  = 'task968_' . $suffix . '_p_low';
		$high_partition = 'task968_' . $suffix . '_p_high';
		$plain_table    = 'task968_' . $suffix . '_plain';
		$backend_sql    = array();

		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task968' );

		try {
			$pdo->exec(
				'CREATE TABLE public.' . WP_PostgreSQL_Connection::quote_identifier_value( $parent_table ) . ' (
					id integer NOT NULL,
					sample_value text NOT NULL
				) PARTITION BY RANGE (id)'
			);
			$pdo->exec(
				'CREATE TABLE public.' . WP_PostgreSQL_Connection::quote_identifier_value( $low_partition )
				. ' PARTITION OF public.' . WP_PostgreSQL_Connection::quote_identifier_value( $parent_table )
				. ' FOR VALUES FROM (0) TO (100)'
			);
			$pdo->exec(
				'CREATE TABLE public.' . WP_PostgreSQL_Connection::quote_identifier_value( $high_partition )
				. ' PARTITION OF public.' . WP_PostgreSQL_Connection::quote_identifier_value( $parent_table )
				. ' FOR VALUES FROM (100) TO (200)'
			);
			$pdo->exec(
				'CREATE TABLE public.' . WP_PostgreSQL_Connection::quote_identifier_value( $plain_table ) . ' (
					id integer NOT NULL,
					sample_value text NOT NULL
				)'
			);

			$parent_insert = $pdo->prepare(
				'INSERT INTO public.' . WP_PostgreSQL_Connection::quote_identifier_value( $parent_table ) . ' (id, sample_value) VALUES (?, ?)'
			);
			foreach ( array( 1, 25, 125, 175 ) as $id ) {
				$parent_insert->execute( array( $id, 'partition-' . $id ) );
			}

			$plain_insert = $pdo->prepare(
				'INSERT INTO public.' . WP_PostgreSQL_Connection::quote_identifier_value( $plain_table ) . ' (id, sample_value) VALUES (?, ?)'
			);
			foreach ( array( 1, 2, 3 ) as $id ) {
				$plain_insert->execute( array( $id, 'plain-' . $id ) );
			}

			$pdo->exec( 'ANALYZE public.' . WP_PostgreSQL_Connection::quote_identifier_value( $parent_table ) );
			$pdo->exec( 'ANALYZE public.' . WP_PostgreSQL_Connection::quote_identifier_value( $plain_table ) );

			$rows = $driver->query(
				'SELECT TABLE_SCHEMA, TABLE_NAME, PARTITION_NAME,
					PARTITION_ORDINAL_POSITION, PARTITION_METHOD, PARTITION_EXPRESSION,
					PARTITION_DESCRIPTION, TABLE_ROWS, PARTITION_COMMENT, NODEGROUP, TABLESPACE_NAME
				FROM information_schema.partitions
				WHERE TABLE_SCHEMA = DATABASE()
					AND TABLE_NAME IN ('
					. $driver->get_connection()->quote( $parent_table ) . ', '
					. $driver->get_connection()->quote( $plain_table ) . ')
				ORDER BY TABLE_NAME, PARTITION_ORDINAL_POSITION, PARTITION_NAME'
			);
			$sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.partitions real PostgreSQL',
				$backend_sql
			);

			$this->assertSame(
				array(
					'TABLE_SCHEMA',
					'TABLE_NAME',
					'PARTITION_NAME',
					'PARTITION_ORDINAL_POSITION',
					'PARTITION_METHOD',
					'PARTITION_EXPRESSION',
					'PARTITION_DESCRIPTION',
					'TABLE_ROWS',
					'PARTITION_COMMENT',
					'NODEGROUP',
					'TABLESPACE_NAME',
				),
				array_column( $driver->get_last_column_meta(), 'name' )
			);

			$parent_rows = array_values(
				array_filter(
					$rows,
					function ( $row ) use ( $parent_table ): bool {
						return $parent_table === $this->get_row_value( $row, 'TABLE_NAME' );
					}
				)
			);
			$this->assertCount( 2, $parent_rows );
			$this->assertSame(
				array( $high_partition, $low_partition ),
				array_map(
					function ( $row ): string {
						return (string) $this->get_row_value( $row, 'PARTITION_NAME' );
					},
					$parent_rows
				)
			);

			foreach ( $parent_rows as $index => $partition_row ) {
				$this->assertSame( $database_name, $this->get_row_value( $partition_row, 'TABLE_SCHEMA' ) );
				$this->assertSame( $parent_table, $this->get_row_value( $partition_row, 'TABLE_NAME' ) );
				$this->assertSame( (string) ( $index + 1 ), (string) $this->get_row_value( $partition_row, 'PARTITION_ORDINAL_POSITION' ) );
				$this->assertSame( 'RANGE', $this->get_row_value( $partition_row, 'PARTITION_METHOD' ) );
				$this->assertStringContainsString( 'id', strtolower( (string) $this->get_row_value( $partition_row, 'PARTITION_EXPRESSION' ) ) );
				$this->assertNotSame( '', (string) $this->get_row_value( $partition_row, 'PARTITION_DESCRIPTION' ) );
				$this->assertRegExp( '/^[0-9]+$/', (string) $this->get_row_value( $partition_row, 'TABLE_ROWS' ) );
				$this->assertSame( '', $this->get_row_value( $partition_row, 'PARTITION_COMMENT' ) );
				$this->assertSame( 'default', $this->get_row_value( $partition_row, 'NODEGROUP' ) );
				$this->assertSame( 'DEFAULT', $this->get_row_value( $partition_row, 'TABLESPACE_NAME' ) );
			}

			$plain_row = $this->find_row_by_value( $rows, 'TABLE_NAME', $plain_table );
			$this->assertNotNull( $plain_row );
			$this->assertSame( $database_name, $this->get_row_value( $plain_row, 'TABLE_SCHEMA' ) );
			$this->assertNull( $this->get_row_value( $plain_row, 'PARTITION_NAME' ) );
			$this->assertNull( $this->get_row_value( $plain_row, 'PARTITION_ORDINAL_POSITION' ) );
			$this->assertNull( $this->get_row_value( $plain_row, 'PARTITION_METHOD' ) );
			$this->assertSame( 'DEFAULT', $this->get_row_value( $plain_row, 'TABLESPACE_NAME' ) );

			$this->assertStringContainsString( 'FROM pg_catalog.pg_inherits inh', $sql );
			$this->assertStringContainsString( 'JOIN pg_catalog.pg_class child_class', $sql );
			$this->assertStringContainsString( 'JOIN pg_catalog.pg_class parent_class', $sql );
			$this->assertStringContainsString( 'pg_catalog.pg_get_partkeydef(parent_class.oid)', $sql );
			$this->assertStringContainsString( 'pg_catalog.pg_get_expr(child_class.relpartbound, child_class.oid) AS "PARTITION_DESCRIPTION"', $sql );
			$this->assertStringContainsString( 'FROM information_schema.tables t', $sql );
			$this->assertStringContainsString( 't.table_type = \'BASE TABLE\'', $sql );
			$this->assertStringContainsString( 'UNION ALL', $sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task968' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task968' ) );
		}
	}

	/**
	 * Tests SHOW EVENTS returns empty MySQL-shaped rows without side metadata.
	 */
	public function test_show_events_returns_empty_mysql_shaped_rows(): void {
		$driver  = $this->create_driver();
		$columns = array(
			'Db',
			'Name',
			'Definer',
			'Time zone',
			'Type',
			'Execute at',
			'Interval value',
			'Interval field',
			'Starts',
			'Ends',
			'Status',
			'Originator',
			'character_set_client',
			'collation_connection',
			'Database Collation',
		);

		$rows = $driver->query( 'SHOW EVENTS' );

		$this->assertSame( array(), $rows );
		$this->assertSame( $columns, array_column( $driver->get_last_column_meta(), 'name' ) );

		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$like_rows = $driver->query( "SHOW EVENTS LIKE 'ev_%'" );
		$this->assertSame( array(), $like_rows );
		$this->assertSame( $columns, array_column( $driver->get_last_column_meta(), 'name' ) );

		$where_rows = $driver->query( "SHOW EVENTS WHERE Status = 'ENABLED' AND Name = 'ev_options'" );
		$this->assertSame( array(), $where_rows );
		$this->assertSame( $columns, array_column( $driver->get_last_column_meta(), 'name' ) );

		$assoc_rows = $driver->query( "SHOW EVENTS FROM wptests WHERE BINARY Name = 'ev_options'", PDO::FETCH_ASSOC );
		$this->assertSame( array(), $assoc_rows );
		$this->assertSame( $columns, array_column( $driver->get_last_column_meta(), 'name' ) );

		$found_rows = $driver->query( 'SELECT FOUND_ROWS()' );
		$this->assertSame( '0', $found_rows[0]->{'FOUND_ROWS()'} );
	}

	/**
	 * Tests unsupported SHOW EVENTS clauses fail before backend execution.
	 */
	public function test_unsupported_show_events_clauses_fail_closed(): void {
		$cases = array(
			'SHOW EVENTS LIMIT 1'           => 'Unsupported SHOW EVENTS statement.',
			'SHOW EVENTS LIKE Name'         => 'Unsupported SHOW EVENTS statement.',
			"SHOW EVENTS WHERE Bogus = 'x'" => 'Unsupported SHOW EVENTS statement.',
			'SHOW EVENTS FROM pg_catalog'   => 'Unsupported SHOW EVENTS statement.',
		);

		foreach ( $cases as $query => $message ) {
			$driver = $this->create_driver();

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported SHOW EVENTS statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( $message, $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests account/plugin/log administration statements do not reach the backend fallback.
	 */
	public function test_unsupported_mysql_account_and_plugin_administration_statements_do_not_reach_backend(): void {
		$cases = array(
			'GRANT SELECT ON *.* TO plugin_user'    => 'Unsupported GRANT statement.',
			'REVOKE SELECT ON *.* FROM plugin_user' => 'Unsupported REVOKE statement.',
			'ALTER USER plugin_user IDENTIFIED BY "secret"' => 'Unsupported ALTER USER statement.',
			'RESET PERSIST'                         => 'Unsupported RESET statement.',
			'PURGE BINARY LOGS BEFORE "2024-01-01"' => 'Unsupported PURGE statement.',
			'INSTALL PLUGIN plugin_name SONAME "plugin.so"' => 'Unsupported INSTALL statement.',
			'UNINSTALL PLUGIN plugin_name'          => 'Unsupported UNINSTALL statement.',
		);

		foreach ( $cases as $query => $message ) {
			$connection = new WP_PostgreSQL_Query_Spy_Connection();
			$driver     = new WP_PostgreSQL_Driver( $connection, 'wptests' );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported MySQL administration statement to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( $message, $e->getMessage(), $query );
				$this->assertSame( 0, $connection->get_query_count(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

