	/**
	 * Tests real PostgreSQL Site Health grouped information_schema.TABLES uses catalogs.
	 */
	public function test_real_pgsql_site_health_information_schema_tables_grouped_rows_use_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL Site Health information_schema.TABLES test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task915' );

		$database_name    = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection       = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver           = new WP_PostgreSQL_Driver( $connection, $database_name );
		$database_literal = $driver->get_connection()->quote( $database_name );
		$suffix           = strtolower( bin2hex( random_bytes( 4 ) ) );
		$tables           = array(
			'task915_' . $suffix . '_options',
			'task915_' . $suffix . '_posts',
			'task915_' . $suffix . '_users',
		);
		$table_literals   = array_map( array( $driver->get_connection(), 'quote' ), $tables );
		$backend_sql      = array();

		try {
			foreach ( $tables as $table ) {
				$this->assertSame(
					0,
					$driver->query(
						sprintf(
							'CREATE TABLE `%s` (
								`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
								`title` varchar(255) NOT NULL,
								PRIMARY KEY (`id`)
							) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
							$table
						)
					)
				);
				$this->collect_last_postgresql_queries(
					$driver,
					'CREATE Site Health information_schema.TABLES fixture table',
					$backend_sql
				);

				$quoted_table = WP_PostgreSQL_Connection::quote_identifier_value( $table );
				$pdo->exec( 'INSERT INTO public.' . $quoted_table . " (title) VALUES ('one'), ('two')" );
				$pdo->exec( 'ANALYZE public.' . $quoted_table );
			}

			$rows = $driver->query(
				"SELECT TABLE_NAME AS 'table', TABLE_ROWS AS 'rows', SUM(data_length + index_length) as 'bytes'
				FROM information_schema.TABLES
				WHERE TABLE_SCHEMA = {$database_literal}
					AND TABLE_NAME IN (" . implode( ',', $table_literals ) . ')
				GROUP BY TABLE_NAME
				ORDER BY TABLE_NAME'
			);
			$sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'real PostgreSQL Site Health grouped information_schema.TABLES query',
				$backend_sql
			);

			$this->assertCount( 3, $rows );
			$this->assertSame( $tables, array_map( 'strval', array_column( $rows, 'table' ) ) );
			foreach ( $rows as $row ) {
				$this->assertTrue( is_numeric( $this->get_row_value( $row, 'rows' ) ) );
				$this->assertGreaterThanOrEqual( 0, (int) $this->get_row_value( $row, 'rows' ) );
				$this->assertTrue( is_numeric( $this->get_row_value( $row, 'bytes' ) ) );
				$this->assertGreaterThanOrEqual( 0, (int) $this->get_row_value( $row, 'bytes' ) );
			}

			$this->assertStringContainsString( 'FROM information_schema.tables t', $sql );
			$this->assertStringContainsString( 'AS "table"', $sql );
			$this->assertStringContainsString( 'AS "rows"', $sql );
			$this->assertStringContainsString( 'as "bytes"', $sql );
			$this->assertStringContainsString( 'GROUP BY "TABLE_NAME"', $sql );
			$this->assertStringContainsString( 'SUM ( "DATA_LENGTH" + "INDEX_LENGTH" ) as "bytes"', $sql );
			$this->assertStringContainsString( 'pg_catalog.pg_stat_all_tables pg_stat', $sql );
			$this->assertStringContainsString( 'pg_stat.n_live_tup', $sql );
			$this->assertRegExp( '/MAX\(\s*"tables"\."TABLE_ROWS"\s*\) AS "rows"/', $sql );
			$this->assertStringNotContainsString( '"TABLE_ROWS" AS "rows"', $sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task915' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task915' ) );
		}
	}

	/**
	 * Tests real PostgreSQL runtime helper domains and enum/set helpers use catalogs.
	 */
	public function test_real_pgsql_runtime_helper_domains_and_enum_set_helpers_use_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL runtime helper catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1009' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql, array $params = array() ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$domains_table = 'task1009_' . $suffix . '_domains';
		$helpers_table = 'task1009_' . $suffix . '_helpers';
		$alter_table   = 'task1009_' . $suffix . '_alter_helpers';
		$backend_sql   = array();

		$assert_logged_sql_before = function ( array $sql_log, string $before, string $after ): void {
			$before_index = null;
			$after_index  = null;

			foreach ( $sql_log as $index => $sql ) {
				if ( null === $before_index && false !== strpos( $sql, $before ) ) {
					$before_index = $index;
				}
				if ( null === $after_index && false !== strpos( $sql, $after ) ) {
					$after_index = $index;
				}
			}

			$this->assertNotNull( $before_index, 'Expected logged SQL containing: ' . $before );
			$this->assertNotNull( $after_index, 'Expected logged SQL containing: ' . $after );
			$this->assertLessThan( $after_index, $before_index, $before . ' should run before ' . $after );
		};

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int(11) NOT NULL,
							`flags` bit(10),
							`enabled` bool,
							`toggled` boolean,
							`object_id` bigint(20) unsigned NOT NULL DEFAULT 0,
							`tiny_flag` tinyint(1) unsigned DEFAULT NULL,
							`alias_count` int4 unsigned DEFAULT NULL,
							`alias_big` int8 DEFAULT NULL,
							`created_date` date,
							`created_at` datetime(6),
							`updated_at` timestamp,
							`touched_at` time(3),
							`year_seen` year,
							`hash` binary(32),
							`payload` varbinary(16),
							`plain_blob` blob,
							`raw_data` mediumblob,
							`shape` point,
							`amount` dec(10,2),
							`fixed_value` fixed(8,3),
							`ratio` float(5,2),
							`score` double(5,2),
							`measurement` numeric(8,4),
							`real_value` real,
							PRIMARY KEY (`id`),
							KEY `object_lookup` (`object_id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$domains_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE task1009 helper domain table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` int(11) NOT NULL,
							`status` enum('draft','published') NOT NULL DEFAULT 'draft',
							`flags` set('featured','archived') DEFAULT 'featured',
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
						$helpers_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE task1009 enum/set helper table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'CREATE TABLE `%s` (
							`id` int(11) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
						$alter_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE task1009 ALTER helper table',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"ALTER TABLE `%s`
							ADD `status` enum('draft','published') NOT NULL DEFAULT 'draft',
							ADD `flags` set('featured','archived') DEFAULT 'featured'",
						$alter_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'ALTER task1009 ADD enum/set helper columns',
				$backend_sql
			);

			$assert_logged_sql_before( $logged_sql, 'DO $wp_mysql_integer_domain$', 'CREATE TABLE "' . $domains_table . '"' );
			$assert_logged_sql_before( $logged_sql, 'DO $wp_mysql_text_domain$', 'CREATE TABLE "' . $domains_table . '"' );
			$assert_logged_sql_before( $logged_sql, 'DO $wp_mysql_binary_domain$', 'CREATE TABLE "' . $domains_table . '"' );
			$assert_logged_sql_before( $logged_sql, 'DO $wp_mysql_numeric_domain$', 'CREATE TABLE "' . $domains_table . '"' );
			$assert_logged_sql_before( $logged_sql, 'DO $wp_mysql_enum_type$', 'CREATE TABLE "' . $helpers_table . '"' );
			$assert_logged_sql_before( $logged_sql, 'DO $wp_mysql_set_domain$', 'CREATE TABLE "' . $helpers_table . '"' );
			$assert_logged_sql_before( $logged_sql, 'COMMENT ON DOMAIN "__wp_mysql_set_3c255ba5f59d3194"', 'CREATE TABLE "' . $helpers_table . '"' );
			$assert_logged_sql_before( $logged_sql, 'CREATE TYPE "__wp_mysql_enum_02ccf983d79439de"', 'ALTER TABLE "' . $alter_table . '" ADD COLUMN "status"' );
			$assert_logged_sql_before( $logged_sql, 'COMMENT ON DOMAIN "__wp_mysql_set_3c255ba5f59d3194"', 'ALTER TABLE "' . $alter_table . '" ADD COLUMN "flags"' );

			$type_rows = $this->get_pgsql_type_rows_by_name(
				$pdo,
				'public',
				array(
					'__wp_mysql_int_11',
					'__wp_mysql_bit_10',
					'__wp_mysql_bool',
					'__wp_mysql_boolean',
					'__wp_mysql_bigint_20_unsigned',
					'__wp_mysql_tinyint_1_unsigned',
					'__wp_mysql_int4_unsigned',
					'__wp_mysql_int8',
					'__wp_mysql_date',
					'__wp_mysql_datetime_6',
					'__wp_mysql_timestamp',
					'__wp_mysql_time_3',
					'__wp_mysql_year',
					'__wp_mysql_binary_32',
					'__wp_mysql_varbinary_16',
					'__wp_mysql_blob',
					'__wp_mysql_mediumblob',
					'__wp_mysql_point',
					'__wp_mysql_dec_10_2',
					'__wp_mysql_fixed_8_3',
					'__wp_mysql_float_5_2',
					'__wp_mysql_double_5_2',
					'__wp_mysql_numeric_8_4',
					'__wp_mysql_real',
					'__wp_mysql_enum_02ccf983d79439de',
					'__wp_mysql_set_3c255ba5f59d3194',
				)
			);

			foreach ( array( '__wp_mysql_int_11', '__wp_mysql_bit_10', '__wp_mysql_bool', '__wp_mysql_boolean', '__wp_mysql_tinyint_1_unsigned', '__wp_mysql_int4_unsigned' ) as $domain_name ) {
				$this->assertSame( 'd', $type_rows[ $domain_name ]['typtype'] ?? null, $domain_name );
				$this->assertSame( 'integer', $type_rows[ $domain_name ]['base_type'] ?? null, $domain_name );
			}
			foreach ( array( '__wp_mysql_bigint_20_unsigned', '__wp_mysql_int8' ) as $domain_name ) {
				$this->assertSame( 'd', $type_rows[ $domain_name ]['typtype'] ?? null, $domain_name );
				$this->assertSame( 'bigint', $type_rows[ $domain_name ]['base_type'] ?? null, $domain_name );
			}
			foreach ( array( '__wp_mysql_date', '__wp_mysql_datetime_6', '__wp_mysql_timestamp', '__wp_mysql_time_3', '__wp_mysql_year', '__wp_mysql_point' ) as $domain_name ) {
				$this->assertSame( 'd', $type_rows[ $domain_name ]['typtype'] ?? null, $domain_name );
				$this->assertSame( 'text', $type_rows[ $domain_name ]['base_type'] ?? null, $domain_name );
			}
			foreach ( array( '__wp_mysql_binary_32', '__wp_mysql_varbinary_16', '__wp_mysql_blob', '__wp_mysql_mediumblob' ) as $domain_name ) {
				$this->assertSame( 'd', $type_rows[ $domain_name ]['typtype'] ?? null, $domain_name );
				$this->assertSame( 'bytea', $type_rows[ $domain_name ]['base_type'] ?? null, $domain_name );
			}
			foreach (
				array(
					'__wp_mysql_dec_10_2'    => 'numeric(10,2)',
					'__wp_mysql_fixed_8_3'   => 'numeric(8,3)',
					'__wp_mysql_float_5_2'   => 'numeric(5,2)',
					'__wp_mysql_double_5_2'  => 'numeric(5,2)',
					'__wp_mysql_numeric_8_4' => 'numeric(8,4)',
					'__wp_mysql_real'        => 'double precision',
				) as $domain_name => $base_type
			) {
				$this->assertSame( 'd', $type_rows[ $domain_name ]['typtype'] ?? null, $domain_name );
				$this->assertSame( $base_type, $type_rows[ $domain_name ]['base_type'] ?? null, $domain_name );
			}
			$this->assertSame( 'e', $type_rows['__wp_mysql_enum_02ccf983d79439de']['typtype'] ?? null );
			$this->assertSame(
				'__wp_mysql_column_type:c2V0KCdmZWF0dXJlZCcsJ2FyY2hpdmVkJyk=',
				$type_rows['__wp_mysql_set_3c255ba5f59d3194']['type_comment'] ?? null
			);
			$this->assertSame(
				array( 'draft', 'published' ),
				$this->get_pgsql_enum_labels( $pdo, 'public', '__wp_mysql_enum_02ccf983d79439de' )
			);

			$column_stmt = $pdo->prepare(
				'SELECT table_name, column_name, udt_name, domain_name
				FROM information_schema.columns
				WHERE table_schema = ?
					AND table_name IN (?, ?, ?)
				ORDER BY table_name, ordinal_position'
			);
			$column_stmt->execute( array( 'public', $domains_table, $helpers_table, $alter_table ) );
			$catalog_columns = array();
			foreach ( $column_stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
				$catalog_columns[ $row['table_name'] ][ $row['column_name'] ] = $row;
			}
			$this->assertSame( '__wp_mysql_int_11', $catalog_columns[ $domains_table ]['id']['domain_name'] ?? null );
			$this->assertSame( '__wp_mysql_datetime_6', $catalog_columns[ $domains_table ]['created_at']['domain_name'] ?? null );
			$this->assertSame( '__wp_mysql_mediumblob', $catalog_columns[ $domains_table ]['raw_data']['domain_name'] ?? null );
			$this->assertSame( '__wp_mysql_varbinary_16', $catalog_columns[ $domains_table ]['payload']['domain_name'] ?? null );
			$this->assertSame( '__wp_mysql_dec_10_2', $catalog_columns[ $domains_table ]['amount']['domain_name'] ?? null );
			$this->assertSame( '__wp_mysql_fixed_8_3', $catalog_columns[ $domains_table ]['fixed_value']['domain_name'] ?? null );
			$this->assertSame( '__wp_mysql_real', $catalog_columns[ $domains_table ]['real_value']['domain_name'] ?? null );
			$this->assertSame( '__wp_mysql_enum_02ccf983d79439de', $catalog_columns[ $helpers_table ]['status']['udt_name'] ?? null );
			$this->assertSame( '__wp_mysql_set_3c255ba5f59d3194', $catalog_columns[ $helpers_table ]['flags']['domain_name'] ?? null );
			$this->assertSame( '__wp_mysql_enum_02ccf983d79439de', $catalog_columns[ $alter_table ]['status']['udt_name'] ?? null );
			$this->assertSame( '__wp_mysql_set_3c255ba5f59d3194', $catalog_columns[ $alter_table ]['flags']['domain_name'] ?? null );

			$domain_columns = $driver->query( 'SHOW COLUMNS FROM `' . $domains_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS task1009 helper domain table',
				$backend_sql
			);
			foreach (
				array(
					'id'           => 'int(11)',
					'flags'        => 'bit(10)',
					'enabled'      => 'bool',
					'toggled'      => 'bool(an)',
					'object_id'    => 'bigint(20) unsigned',
					'tiny_flag'    => 'tinyint(1) unsigned',
					'alias_count'  => 'int() unsigned',
					'alias_big'    => 'int()',
					'created_date' => 'date',
					'created_at'   => 'datetime(6)',
					'updated_at'   => 'timestamp',
					'touched_at'   => 'time(3)',
					'year_seen'    => 'year',
					'hash'         => 'binary(32)',
					'payload'      => 'varbinary(16)',
					'plain_blob'   => 'blob',
					'raw_data'     => 'mediumblob',
					'shape'        => 'point',
					'amount'       => 'dec(10,2)',
					'fixed_value'  => 'fixed(8,3)',
					'ratio'        => 'float(5,2)',
					'score'        => 'double(5,2)',
					'measurement'  => 'numeric(8,4)',
					'real_value'   => 'real',
				) as $column_name => $column_type
			) {
				$this->assertSame(
					$column_type,
					$this->get_row_value( $this->find_row_by_value( $domain_columns, 'Field', $column_name ), 'Type' ),
					$column_name
				);
			}

			$helper_columns = $driver->query( 'SHOW COLUMNS FROM `' . $helpers_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS task1009 enum/set helper table',
				$backend_sql
			);
			$this->assertSame(
				"enum('draft','published')",
				$this->get_row_value( $this->find_row_by_value( $helper_columns, 'Field', 'status' ), 'Type' )
			);
			$this->assertSame(
				"set('featured','archived')",
				$this->get_row_value( $this->find_row_by_value( $helper_columns, 'Field', 'flags' ), 'Type' )
			);

			$alter_columns = $driver->query( 'SHOW COLUMNS FROM `' . $alter_table . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS task1009 ALTER helper table',
				$backend_sql
			);
			$this->assertSame(
				"enum('draft','published')",
				$this->get_row_value( $this->find_row_by_value( $alter_columns, 'Field', 'status' ), 'Type' )
			);
			$this->assertSame(
				"set('featured','archived')",
				$this->get_row_value( $this->find_row_by_value( $alter_columns, 'Field', 'flags' ), 'Type' )
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s` (`id`, `status`, `flags`) VALUES (1, 'published', 'featured,archived')",
						$helpers_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'INSERT task1009 enum/set helper row',
				$backend_sql
			);
			$roundtrip_rows = $driver->query( 'SELECT `status`, `flags` FROM `' . $helpers_table . '` WHERE `id` = 1' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SELECT task1009 enum/set helper row',
				$backend_sql
			);
			$this->assertSame( 'published', $roundtrip_rows[0]->status );
			$this->assertSame( 'featured,archived', $roundtrip_rows[0]->flags );

			foreach ( $logged_sql as $sql ) {
				$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
			}
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1009' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task1009' ) );
		}
	}

	/**
	 * Tests real PostgreSQL information_schema columns/statistics and SHOW wrappers use catalogs.
	 */
	public function test_real_pgsql_direct_information_schema_columns_statistics_and_show_wrappers_use_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL columns/statistics catalog test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task989' );

		$database_name  = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection     = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver         = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix         = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name     = 'task989_' . $suffix . '_meta';
		$table_literal  = $driver->get_connection()->quote( $table_name );
		$table_sql      = WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$expression_sql = WP_PostgreSQL_Connection::quote_identifier_value( $table_name . '__title_lower_expr' );
		$backend_sql    = array();

		try {
			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						"CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`object_id` bigint(20) unsigned NOT NULL DEFAULT 0,
							`slug` varchar(64) NOT NULL,
							`title` varchar(191) NOT NULL COMMENT 'Title note',
							`status` enum('draft','published') NOT NULL DEFAULT 'draft' COMMENT 'Status note',
							`flags` set('featured','archived') DEFAULT NULL COMMENT 'Flags note',
							`created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
							`payload` mediumblob DEFAULT NULL,
							`amount` decimal(10,2) NOT NULL DEFAULT 0.00,
							PRIMARY KEY (`id`),
							UNIQUE KEY `slug_unique` (`slug`),
							KEY `title_prefix` (`title`(32)) COMMENT 'Title prefix note',
							KEY `created_desc` (`created_at` DESC)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Task 989 metadata table'",
						$table_name
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE task989 columns/statistics table',
				$backend_sql
			);

			$pdo->exec( 'CREATE INDEX ' . $expression_sql . ' ON public.' . $table_sql . ' ((lower(title)))' );
			$pdo->exec( 'COMMENT ON INDEX public.' . $expression_sql . " IS 'Title expression note'" );

			$type_rows = $this->get_pgsql_type_rows_by_name(
				$pdo,
				'public',
				array(
					'__wp_mysql_bigint_20_unsigned',
					'__wp_mysql_datetime_6',
					'__wp_mysql_mediumblob',
					'__wp_mysql_enum_02ccf983d79439de',
					'__wp_mysql_set_3c255ba5f59d3194',
				)
			);
			foreach ( array( '__wp_mysql_bigint_20_unsigned', '__wp_mysql_datetime_6', '__wp_mysql_mediumblob', '__wp_mysql_set_3c255ba5f59d3194' ) as $domain_type ) {
				$this->assertSame( 'd', $type_rows[ $domain_type ]['typtype'] ?? null, $domain_type );
			}
			$this->assertSame( 'e', $type_rows['__wp_mysql_enum_02ccf983d79439de']['typtype'] ?? null );
			$this->assertSame(
				'__wp_mysql_column_type:c2V0KCdmZWF0dXJlZCcsJ2FyY2hpdmVkJyk=',
				$type_rows['__wp_mysql_set_3c255ba5f59d3194']['type_comment'] ?? null
			);
			$this->assertSame(
				array( 'draft', 'published' ),
				$this->get_pgsql_enum_labels( $pdo, 'public', '__wp_mysql_enum_02ccf983d79439de' )
			);

			$column_rows = $driver->query(
				"SELECT column_name, ordinal_position, data_type, column_type, column_key,
					column_default, is_nullable, extra, character_set_name, collation_name,
					column_comment
				FROM information_schema.columns
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY ordinal_position"
			);
			$columns_sql = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.columns real PostgreSQL',
				$backend_sql
			);
			$this->assertCount( 9, $column_rows );
			$id_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'id' );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $id_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'PRI', $this->get_row_value( $id_column, 'COLUMN_KEY' ) );
			$this->assertSame( 'auto_increment', $this->get_row_value( $id_column, 'EXTRA' ) );
			$this->assertSame( 'NO', $this->get_row_value( $id_column, 'IS_NULLABLE' ) );
			$object_id_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'object_id' );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $object_id_column, 'COLUMN_TYPE' ) );
			$slug_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'slug' );
			$this->assertSame( 'varchar(64)', $this->get_row_value( $slug_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'UNI', $this->get_row_value( $slug_column, 'COLUMN_KEY' ) );
			$this->assertSame( 'utf8mb4', $this->get_row_value( $slug_column, 'CHARACTER_SET_NAME' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $slug_column, 'COLLATION_NAME' ) );
			$title_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'title' );
			$this->assertSame( 'varchar(191)', $this->get_row_value( $title_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'MUL', $this->get_row_value( $title_column, 'COLUMN_KEY' ) );
			$this->assertSame( 'Title note', $this->get_row_value( $title_column, 'COLUMN_COMMENT' ) );
			$status_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'status' );
			$this->assertSame( 'enum', $this->get_row_value( $status_column, 'DATA_TYPE' ) );
			$this->assertSame( "enum('draft','published')", $this->get_row_value( $status_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'draft', $this->get_row_value( $status_column, 'COLUMN_DEFAULT' ) );
			$this->assertSame( 'Status note', $this->get_row_value( $status_column, 'COLUMN_COMMENT' ) );
			$flags_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'flags' );
			$this->assertSame( 'set', $this->get_row_value( $flags_column, 'DATA_TYPE' ) );
			$this->assertSame( "set('featured','archived')", $this->get_row_value( $flags_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'Flags note', $this->get_row_value( $flags_column, 'COLUMN_COMMENT' ) );
			$created_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'created_at' );
			$this->assertSame( 'datetime(6)', $this->get_row_value( $created_column, 'COLUMN_TYPE' ) );
			$this->assertSame( 'CURRENT_TIMESTAMP(6)', $this->get_row_value( $created_column, 'COLUMN_DEFAULT' ) );
			$payload_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'payload' );
			$this->assertSame( 'mediumblob', $this->get_row_value( $payload_column, 'DATA_TYPE' ) );
			$this->assertSame( 'mediumblob', $this->get_row_value( $payload_column, 'COLUMN_TYPE' ) );
			$amount_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'amount' );
			$this->assertSame( 'decimal(10,2)', $this->get_row_value( $amount_column, 'COLUMN_TYPE' ) );
			$this->assertStringContainsString( 'FROM information_schema.columns c', $columns_sql );
			$this->assertStringContainsString( 'pg_catalog.col_description(pc.oid, pa.attnum)', $columns_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_index i', $columns_sql );
			$this->assertStringContainsString( 'pg_catalog.pg_enum e', $columns_sql );
			$this->assertStringContainsString( '__wp_mysql_column_type:', $columns_sql );

			$describe_rows = $driver->query( 'DESCRIBE `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'DESCRIBE task989 table',
				$backend_sql
			);
			$this->assertSame( array( 'Field', 'Type', 'Null', 'Key', 'Default', 'Extra' ), array_column( $driver->get_last_column_meta(), 'name' ) );
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $this->find_row_by_value( $describe_rows, 'Field', 'id' ), 'Type' ) );
			$this->assertSame( "enum('draft','published')", $this->get_row_value( $this->find_row_by_value( $describe_rows, 'Field', 'status' ), 'Type' ) );

			$show_columns = $driver->query( 'SHOW COLUMNS FROM `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW COLUMNS task989 table',
				$backend_sql
			);
			$this->assertEquals( $describe_rows, $show_columns );

			$show_full_columns = $driver->query( 'SHOW FULL COLUMNS FROM `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW FULL COLUMNS task989 table',
				$backend_sql
			);
			$this->assertSame( array( 'Field', 'Type', 'Collation', 'Null', 'Key', 'Default', 'Extra', 'Privileges', 'Comment' ), array_column( $driver->get_last_column_meta(), 'name' ) );
			$full_title_column = $this->find_row_by_value( $show_full_columns, 'Field', 'title' );
			$this->assertSame( 'varchar(191)', $this->get_row_value( $full_title_column, 'Type' ) );
			$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $full_title_column, 'Collation' ) );
			$this->assertSame( 'select,insert,update,references', $this->get_row_value( $full_title_column, 'Privileges' ) );
			$this->assertSame( 'Title note', $this->get_row_value( $full_title_column, 'Comment' ) );
			$this->assertSame( "set('featured','archived')", $this->get_row_value( $this->find_row_by_value( $show_full_columns, 'Field', 'flags' ), 'Type' ) );

			$join_rows = $driver->query(
				"SELECT t.table_name, c.column_name, c.column_type, c.column_key
				FROM information_schema.tables AS t
				JOIN information_schema.columns AS c
					ON c.table_schema = t.table_schema
					AND c.table_name = t.table_name
				WHERE t.table_schema = DATABASE()
					AND t.table_name = {$table_literal}
					AND c.column_name IN ('id', 'title', 'status')
				ORDER BY c.ordinal_position"
			);
			$join_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema tables/columns join real PostgreSQL',
				$backend_sql
			);
			$this->assertSame( array( 'id', 'title', 'status' ), array_map( 'strval', array_column( $join_rows, 'COLUMN_NAME' ) ) );
			foreach ( $join_rows as $join_row ) {
				$this->assertSame( $table_name, $this->get_row_value( $join_row, 'TABLE_NAME' ) );
			}
			$this->assertSame( 'bigint(20) unsigned', $this->get_row_value( $this->find_row_by_value( $join_rows, 'COLUMN_NAME', 'id' ), 'COLUMN_TYPE' ) );
			$this->assertSame( "enum('draft','published')", $this->get_row_value( $this->find_row_by_value( $join_rows, 'COLUMN_NAME', 'status' ), 'COLUMN_TYPE' ) );
			$this->assertStringContainsString( 'FROM information_schema.tables t', $join_sql );
			$this->assertStringContainsString( 'FROM information_schema.columns c', $join_sql );

			$statistics_rows = $driver->query(
				"SELECT index_name, seq_in_index, column_name, collation, sub_part,
					non_unique, index_type, index_comment, expression
				FROM information_schema.statistics
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY index_name, seq_in_index"
			);
			$statistics_sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'direct information_schema.statistics real PostgreSQL',
				$backend_sql
			);
			$primary_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'PRIMARY' );
			$this->assertSame( 'id', $this->get_row_value( $primary_statistic, 'COLUMN_NAME' ) );
			$this->assertSame( '1', (string) $this->get_row_value( $primary_statistic, 'SEQ_IN_INDEX' ) );
			$this->assertSame( '0', (string) $this->get_row_value( $primary_statistic, 'NON_UNIQUE' ) );
			$this->assertSame( 'A', $this->get_row_value( $primary_statistic, 'COLLATION' ) );
			$this->assertNull( $this->get_row_value( $primary_statistic, 'SUB_PART' ) );
			$this->assertSame( 'BTREE', $this->get_row_value( $primary_statistic, 'INDEX_TYPE' ) );
			$this->assertSame( '', $this->get_row_value( $primary_statistic, 'INDEX_COMMENT' ) );
			$this->assertNull( $this->get_row_value( $primary_statistic, 'EXPRESSION' ) );
			$slug_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'slug_unique' );
			$this->assertSame( 'slug', $this->get_row_value( $slug_statistic, 'COLUMN_NAME' ) );
			$this->assertSame( '0', (string) $this->get_row_value( $slug_statistic, 'NON_UNIQUE' ) );
			$title_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'title_prefix' );
			$this->assertSame( 'title', $this->get_row_value( $title_statistic, 'COLUMN_NAME' ) );
			$this->assertSame( '1', (string) $this->get_row_value( $title_statistic, 'NON_UNIQUE' ) );
			$this->assertSame( '32', (string) $this->get_row_value( $title_statistic, 'SUB_PART' ) );
			$this->assertSame( 'Title prefix note', $this->get_row_value( $title_statistic, 'INDEX_COMMENT' ) );
			$created_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'created_desc' );
			$this->assertSame( 'created_at', $this->get_row_value( $created_statistic, 'COLUMN_NAME' ) );
			$this->assertSame( 'D', $this->get_row_value( $created_statistic, 'COLLATION' ) );
			$expression_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'title_lower_expr' );
			$this->assertNull( $this->get_row_value( $expression_statistic, 'COLUMN_NAME' ) );
			$this->assertStringContainsString( 'lower', strtolower( (string) $this->get_row_value( $expression_statistic, 'EXPRESSION' ) ) );
			$this->assertStringContainsString( 'title', strtolower( (string) $this->get_row_value( $expression_statistic, 'EXPRESSION' ) ) );
			$this->assertSame( 'Title expression note', $this->get_row_value( $expression_statistic, 'INDEX_COMMENT' ) );
			$this->assertStringContainsString( 'pg_catalog.pg_index', $statistics_sql );
			$this->assertStringContainsString( 'pg_catalog.unnest(i.indkey)', $statistics_sql );
			$this->assertStringContainsString( 'pg_catalog.obj_description(idx.oid, \'pg_class\')', $statistics_sql );
			$this->assertStringContainsString( 'AS "INDEX_COMMENT"', $statistics_sql );
			$this->assertStringContainsString( 'AS "EXPRESSION"', $statistics_sql );

			$show_index_rows = $driver->query( 'SHOW INDEX FROM `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX task989 table',
				$backend_sql
			);
			$this->assertSame( 15, $driver->get_last_column_count() );
			$this->assertSame(
				array( 'Table', 'Non_unique', 'Key_name', 'Seq_in_index', 'Column_name', 'Collation', 'Cardinality', 'Sub_part', 'Packed', 'Null', 'Index_type', 'Comment', 'Index_comment', 'Visible', 'Expression' ),
				array_column( $driver->get_last_column_meta(), 'name' )
			);
			$this->assertSame( 'id', $this->get_row_value( $this->find_row_by_value( $show_index_rows, 'Key_name', 'PRIMARY' ), 'Column_name' ) );
			$this->assertSame( '32', $this->get_row_value( $this->find_row_by_value( $show_index_rows, 'Key_name', 'title_prefix' ), 'Sub_part' ) );
			$this->assertSame( 'D', $this->get_row_value( $this->find_row_by_value( $show_index_rows, 'Key_name', 'created_desc' ), 'Collation' ) );

			$show_key_rows = $driver->query( 'SHOW KEYS FROM `' . $table_name . '`' );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW KEYS task989 table',
				$backend_sql
			);
			$this->assertEquals( $show_index_rows, $show_key_rows );

			$title_prefix_rows = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Key_name = 'title_prefix'" );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX task989 Key_name filter',
				$backend_sql
			);
			$this->assertCount( 1, $title_prefix_rows );
			$this->assertSame( '32', $this->get_row_value( $title_prefix_rows[0], 'Sub_part' ) );

			$descending_rows = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Collation = 'D'" );
			$this->collect_last_postgresql_queries(
				$driver,
				'SHOW INDEX task989 Collation filter',
				$backend_sql
			);
			$this->assertCount( 1, $descending_rows );
			$this->assertSame( 'created_desc', $this->get_row_value( $descending_rows[0], 'Key_name' ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task989' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task989' ) );
		}
	}

	/**
	 * Tests real PostgreSQL SHOW metadata projections keep existing MySQL-shaped output.
	 */
	public function test_real_pgsql_show_metadata_projection_arrays_preserve_existing_output(): void {
		$driver        = $this->create_driver();
		$table_name    = 'projection_map_metadata';
		$table_literal = $driver->get_connection()->quote( $table_name );

		$this->assertSame(
			0,
			$driver->query(
				sprintf(
					"CREATE TABLE `%s` (
						`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
						`title` varchar(80) NOT NULL DEFAULT 'untitled' COMMENT 'Title note',
						`status` varchar(20) NOT NULL DEFAULT 'draft',
						PRIMARY KEY (`id`),
						KEY `title_prefix` (`title`(12)) COMMENT 'Title prefix note'
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Projection map table note'",
					$table_name
				)
			)
		);

		$show_full_columns = $driver->query( 'SHOW FULL COLUMNS FROM `' . $table_name . '`' );
		$full_columns_sql  = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertSame( array( 'Field', 'Type', 'Collation', 'Null', 'Key', 'Default', 'Extra', 'Privileges', 'Comment' ), array_column( $driver->get_last_column_meta(), 'name' ) );
		$title_column = $this->find_row_by_value( $show_full_columns, 'Field', 'title' );
		$this->assertSame( 'varchar(80)', $this->get_row_value( $title_column, 'Type' ) );
		$this->assertSame( 'NO', $this->get_row_value( $title_column, 'Null' ) );
		$this->assertSame( 'untitled', $this->get_row_value( $title_column, 'Default' ) );
		$this->assertSame( 'Title note', $this->get_row_value( $title_column, 'Comment' ) );
		$this->assertStringNotContainsString( '__wp_mysql_information_schema', $full_columns_sql );

		$table_status_rows = $driver->query( 'SHOW TABLE STATUS LIKE ' . $table_literal );
		$table_status_sql  = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertSame( $this->get_show_table_status_column_names(), array_column( $driver->get_last_column_meta(), 'name' ) );
		$this->assertCount( 1, $table_status_rows );
		$this->assertSame( $table_name, $this->get_row_value( $table_status_rows[0], 'Name' ) );
		$this->assertSame( 'InnoDB', $this->get_row_value( $table_status_rows[0], 'Engine' ) );
		$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $table_status_rows[0], 'Collation' ) );
		$this->assertSame( 'Projection map table note', $this->get_row_value( $table_status_rows[0], 'Comment' ) );
		$this->assertStringNotContainsString( '__wp_mysql_information_schema', $table_status_sql );

		$show_index_rows = $driver->query( "SHOW INDEX FROM `{$table_name}` WHERE Key_name = 'title_prefix'" );
		$show_index_sql  = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$this->assertCount( 1, $show_index_rows );
		$this->assertSame( 'title_prefix', $this->get_row_value( $show_index_rows[0], 'Key_name' ) );
		$this->assertSame( 'title', $this->get_row_value( $show_index_rows[0], 'Column_name' ) );
		$this->assertSame( '12', $this->get_row_value( $show_index_rows[0], 'Sub_part' ) );
		$this->assertSame( 'Title prefix note', $this->get_row_value( $show_index_rows[0], 'Index_comment' ) );
		$this->assertStringNotContainsString( '__wp_mysql_information_schema', $show_index_sql );

		$create_table_rows = $driver->query( 'SHOW CREATE TABLE `' . $table_name . '`' );
		$show_create_sql   = implode( "\n", array_column( $driver->get_last_postgresql_queries(), 'sql' ) );
		$create_table_sql  = (string) $this->get_row_value( $create_table_rows[0], 'Create Table' );
		$this->assertStringContainsString( '`title` varchar(80) NOT NULL DEFAULT \'untitled\' COMMENT \'Title note\'', $create_table_sql );
		$this->assertStringContainsString( 'KEY `title_prefix` (`title`(12)) COMMENT \'Title prefix note\'', $create_table_sql );
		$this->assertStringContainsString( "COMMENT='Projection map table note'", $create_table_sql );
		$this->assertStringNotContainsString( '__wp_mysql_information_schema', $show_create_sql );
	}

	/**
	 * Tests marker-looking user comments stay comments in catalog-backed metadata.
	 */
	public function test_real_pgsql_catalog_marker_user_comments_are_escaped_and_preserved(): void {
		$driver        = $this->create_driver();
		$table_name    = 'wptests_marker_comment_collision';
		$table_literal = $driver->get_connection()->quote( $table_name );

		$table_comment          = '__wp_mysql_table_collation:not-base64 table note';
		$column_invalid_comment = '__wp_mysql_column_type:not-base64 column note';
		$column_valid_comment   = '__wp_mysql_column_default:Q1VSUkVOVF9USU1FU1RBTVA=';
		$column_type_comment    = '__wp_mysql_column_type:ZGVjaW1hbCgxMCwyKSB1bnNpZ25lZA==';
		$index_invalid_comment  = '__wp_mysql_index_type:not-base64 index note';
		$index_valid_comment    = '__wp_mysql_index_type:QlRSRUU=';

		$this->assertSame(
			0,
			$driver->query(
				sprintf(
					"CREATE TABLE `%s` (
						`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
						`title` varchar(191) NOT NULL COMMENT '%s',
						`body` text NOT NULL COMMENT '%s',
						`amount` decimal(10,2) unsigned NOT NULL DEFAULT 0 COMMENT '%s',
						`created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
						PRIMARY KEY (`id`),
						KEY `title_prefix` (`title`(10)) COMMENT '%s'
					) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='%s'",
					$table_name,
					$column_invalid_comment,
					$column_valid_comment,
					$column_type_comment,
					$index_invalid_comment,
					$table_comment
				)
			)
		);
		$this->assertSame(
			0,
			$driver->query(
				sprintf(
					'ALTER TABLE `%s` ADD FULLTEXT KEY `body_fulltext` (`body`) COMMENT "%s"',
					$table_name,
					$index_valid_comment
				)
			)
		);

		$table_rows = $driver->query(
			"SELECT table_comment, table_collation
				FROM information_schema.tables
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}"
		);
		$this->assertCount( 1, $table_rows );
		$this->assertSame( $table_comment, $this->get_row_value( $table_rows[0], 'TABLE_COMMENT' ) );
		$this->assertSame( 'utf8mb4_bin', $this->get_row_value( $table_rows[0], 'TABLE_COLLATION' ) );

		$column_rows = $driver->query(
			"SELECT column_name, column_type, column_default, column_comment
			FROM information_schema.columns
			WHERE table_schema = DATABASE()
				AND table_name = {$table_literal}
			ORDER BY ordinal_position"
		);
		$this->assertSame( $column_invalid_comment, $this->get_row_value( $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'title' ), 'COLUMN_COMMENT' ) );
		$this->assertSame( $column_valid_comment, $this->get_row_value( $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'body' ), 'COLUMN_COMMENT' ) );
		$amount_column = $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'amount' );
		$this->assertSame( 'decimal(10,2) unsigned', $this->get_row_value( $amount_column, 'COLUMN_TYPE' ) );
		$this->assertSame( $column_type_comment, $this->get_row_value( $amount_column, 'COLUMN_COMMENT' ) );
		$this->assertSame( 'CURRENT_TIMESTAMP(6)', $this->get_row_value( $this->find_row_by_value( $column_rows, 'COLUMN_NAME', 'created_at' ), 'COLUMN_DEFAULT' ) );

		$full_columns = $driver->query( 'SHOW FULL COLUMNS FROM `' . $table_name . '`' );
		$this->assertSame( $column_invalid_comment, $this->get_row_value( $this->find_row_by_value( $full_columns, 'Field', 'title' ), 'Comment' ) );
		$this->assertSame( $column_valid_comment, $this->get_row_value( $this->find_row_by_value( $full_columns, 'Field', 'body' ), 'Comment' ) );
		$this->assertSame( 'decimal(10,2) unsigned', $this->get_row_value( $this->find_row_by_value( $full_columns, 'Field', 'amount' ), 'Type' ) );

		$statistics_rows        = $driver->query(
			"SELECT index_name, index_type, sub_part, index_comment
			FROM information_schema.statistics
			WHERE table_schema = DATABASE()
				AND table_name = {$table_literal}
			ORDER BY index_name, seq_in_index"
		);
		$title_prefix_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'title_prefix' );
		$this->assertSame( '10', (string) $this->get_row_value( $title_prefix_statistic, 'SUB_PART' ) );
		$this->assertSame( $index_invalid_comment, $this->get_row_value( $title_prefix_statistic, 'INDEX_COMMENT' ) );
		$body_fulltext_statistic = $this->find_row_by_value( $statistics_rows, 'INDEX_NAME', 'body_fulltext' );
		$this->assertSame( 'FULLTEXT', $this->get_row_value( $body_fulltext_statistic, 'INDEX_TYPE' ) );
		$this->assertSame( $index_valid_comment, $this->get_row_value( $body_fulltext_statistic, 'INDEX_COMMENT' ) );

		$show_index_rows = $driver->query( 'SHOW INDEX FROM `' . $table_name . '`' );
		$this->assertSame( $index_invalid_comment, $this->get_row_value( $this->find_row_by_value( $show_index_rows, 'Key_name', 'title_prefix' ), 'Index_comment' ) );
		$this->assertSame( 'FULLTEXT', $this->get_row_value( $this->find_row_by_value( $show_index_rows, 'Key_name', 'body_fulltext' ), 'Index_type' ) );
		$this->assertSame( $index_valid_comment, $this->get_row_value( $this->find_row_by_value( $show_index_rows, 'Key_name', 'body_fulltext' ), 'Index_comment' ) );

		$show_table_status = $driver->query( "SHOW TABLE STATUS LIKE '{$table_name}'" );
		$this->assertCount( 1, $show_table_status );
		$this->assertSame( $table_comment, $this->get_row_value( $show_table_status[0], 'Comment' ) );

		$create_table_rows = $driver->query( 'SHOW CREATE TABLE `' . $table_name . '`' );
		$create_table_sql  = (string) $this->get_row_value( $create_table_rows[0], 'Create Table' );
		foreach ( array( $table_comment, $column_invalid_comment, $column_valid_comment, $column_type_comment, $index_invalid_comment, $index_valid_comment ) as $comment ) {
			$this->assertStringContainsString( $comment, $create_table_sql );
		}
		$this->assertStringNotContainsString( 'WP_MYSQL_COMMENT_ESCAPE:', $create_table_sql );
	}

	/**
	 * Tests real PostgreSQL direct information_schema.TABLES inline sources use catalogs.
	 */
	public function test_real_pgsql_direct_information_schema_tables_inline_source_uses_catalog(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL information_schema.TABLES inline source test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1018' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name    = 'task1018_' . $suffix . '_tables_inline';
		$table_sql     = WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$table_literal = $driver->get_connection()->quote( $table_name );
		$backend_sql   = array();

		try {
			$pdo->exec( 'CREATE TABLE public.' . $table_sql . ' (id integer PRIMARY KEY, title text NOT NULL)' );

			$rows = $driver->query(
				"SELECT table_schema, table_name, table_type
				FROM information_schema.tables
				WHERE table_schema = DATABASE()
					AND table_name = {$table_literal}
				ORDER BY table_name"
			);
			$sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'real PostgreSQL direct information_schema.TABLES inline source',
				$backend_sql
			);

			$this->assertCount( 1, $rows );
			$this->assertSame( $database_name, $this->get_row_value( $rows[0], 'TABLE_SCHEMA' ) );
			$this->assertSame( $table_name, $this->get_row_value( $rows[0], 'TABLE_NAME' ) );
			$this->assertSame( 'BASE TABLE', $this->get_row_value( $rows[0], 'TABLE_TYPE' ) );
			$this->assertStringContainsString( 'FROM information_schema.tables t', $sql );
			$this->assertStringContainsString( 'pg_catalog.obj_description(pc.oid, \'pg_class\')', $sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', implode( "\n", $backend_sql ) );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1018' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task1018' ) );
		}
	}

	/**
	 * Tests real PostgreSQL direct information_schema joins use catalog column metadata.
	 */
	public function test_real_pgsql_direct_information_schema_mixed_application_join_uses_catalog_column_metadata(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL mixed information_schema join test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1018' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql, array $params = array() ) use ( &$logged_sql ): void {
				$logged_sql[] = array(
					'sql'    => $sql,
					'params' => $params,
				);
			}
		);
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix        = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name    = 'task1018_' . $suffix . '_schema_names';
		$table_sql     = WP_PostgreSQL_Connection::quote_identifier_value( $table_name );
		$table_literal = $driver->get_connection()->quote( $table_name );
		$backend_sql   = array();

		try {
			$pdo->exec( 'CREATE TABLE public.' . $table_sql . ' (id integer PRIMARY KEY, db_name text NOT NULL)' );
			$stmt = $pdo->prepare( 'INSERT INTO public.' . $table_sql . ' (id, db_name) VALUES (1, ?)' );
			$stmt->execute( array( $database_name ) );

			$rows = $driver->query(
				"SELECT app.id, app.db_name, c.table_schema, c.table_name, c.column_name, c.data_type
				FROM information_schema.columns AS c
				JOIN `{$table_name}` AS app
					ON app.db_name = c.table_schema
				WHERE c.table_schema = DATABASE()
					AND c.table_name = {$table_literal}
					AND c.column_name = CONCAT('db', '_name')
				ORDER BY app.id, c.ordinal_position"
			);
			$sql  = $this->get_last_single_postgresql_sql( $driver );
			$this->collect_last_postgresql_queries(
				$driver,
				'real PostgreSQL direct information_schema mixed application join',
				$backend_sql
			);

			$this->assertCount( 1, $rows );
			$this->assertSame( '1', (string) $this->get_row_value( $rows[0], 'id' ) );
			$this->assertSame( $database_name, $this->get_row_value( $rows[0], 'db_name' ) );
			$this->assertSame( $database_name, $this->get_row_value( $rows[0], 'TABLE_SCHEMA' ) );
			$this->assertSame( $table_name, $this->get_row_value( $rows[0], 'TABLE_NAME' ) );
			$this->assertSame( 'db_name', $this->get_row_value( $rows[0], 'COLUMN_NAME' ) );
			$this->assertSame( 'text', $this->get_row_value( $rows[0], 'DATA_TYPE' ) );
			$this->assertStringContainsString( 'FROM information_schema.columns c', $sql );
			$this->assertStringContainsString( '"' . $table_name . '" AS "app"', $sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', implode( "\n", $backend_sql ) );

			$column_catalog_query = null;
			foreach ( $logged_sql as $query ) {
				$query_sql = (string) ( $query['sql'] ?? '' );
				if (
					false !== strpos( $query_sql, 'FROM information_schema.columns c' )
					&& false !== strpos( $query_sql, 'ORDER BY c.ordinal_position' )
				) {
					$column_catalog_query = $query;
					break;
				}
			}

			$this->assertNotNull( $column_catalog_query );
			$this->assertSame( array( 'public', $table_name ), $column_catalog_query['params'] );
			$this->assertStringContainsString( 'pg_catalog.col_description(pc.oid, pa.attnum)', $column_catalog_query['sql'] );
			foreach ( $logged_sql as $query ) {
			}
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1018' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task1018' ) );
		}
	}

	/**
	 * Tests direct information_schema charset and collation SELECTs return MySQL-shaped rows.
	 */
	public function test_direct_information_schema_character_sets_and_collations_selects_return_mysql_shape(): void {
		$driver = $this->create_driver();

		$character_sets = $driver->query( 'SELECT * FROM INFORMATION_SCHEMA.CHARACTER_SETS ORDER BY CHARACTER_SET_NAME' );

		$this->assertEquals(
			array(
				(object) array(
					'CHARACTER_SET_NAME'   => 'binary',
					'DEFAULT_COLLATE_NAME' => 'binary',
					'DESCRIPTION'          => 'Binary pseudo charset',
					'MAXLEN'               => '1',
				),
				(object) array(
					'CHARACTER_SET_NAME'   => 'utf8',
					'DEFAULT_COLLATE_NAME' => 'utf8_general_ci',
					'DESCRIPTION'          => 'UTF-8 Unicode',
					'MAXLEN'               => '3',
				),
				(object) array(
					'CHARACTER_SET_NAME'   => 'utf8mb4',
					'DEFAULT_COLLATE_NAME' => 'utf8mb4_0900_ai_ci',
					'DESCRIPTION'          => 'UTF-8 Unicode',
					'MAXLEN'               => '4',
				),
			),
			$character_sets
		);

		$collations = $driver->query( 'SELECT * FROM INFORMATION_SCHEMA.COLLATIONS ORDER BY COLLATION_NAME' );

		$this->assertEquals(
			array(
				(object) array(
					'COLLATION_NAME'     => 'binary',
					'CHARACTER_SET_NAME' => 'binary',
					'ID'                 => '63',
					'IS_DEFAULT'         => 'Yes',
					'IS_COMPILED'        => 'Yes',
					'SORTLEN'            => '1',
					'PAD_ATTRIBUTE'      => 'NO PAD',
				),
				(object) array(
					'COLLATION_NAME'     => 'utf8_bin',
					'CHARACTER_SET_NAME' => 'utf8',
					'ID'                 => '83',
					'IS_DEFAULT'         => '',
					'IS_COMPILED'        => 'Yes',
					'SORTLEN'            => '1',
					'PAD_ATTRIBUTE'      => 'PAD SPACE',
				),
				(object) array(
					'COLLATION_NAME'     => 'utf8_general_ci',
					'CHARACTER_SET_NAME' => 'utf8',
					'ID'                 => '33',
					'IS_DEFAULT'         => 'Yes',
					'IS_COMPILED'        => 'Yes',
					'SORTLEN'            => '1',
					'PAD_ATTRIBUTE'      => 'PAD SPACE',
				),
				(object) array(
					'COLLATION_NAME'     => 'utf8_unicode_ci',
					'CHARACTER_SET_NAME' => 'utf8',
					'ID'                 => '192',
					'IS_DEFAULT'         => '',
					'IS_COMPILED'        => 'Yes',
					'SORTLEN'            => '8',
					'PAD_ATTRIBUTE'      => 'PAD SPACE',
				),
				(object) array(
					'COLLATION_NAME'     => 'utf8mb4_0900_ai_ci',
					'CHARACTER_SET_NAME' => 'utf8mb4',
					'ID'                 => '255',
					'IS_DEFAULT'         => 'Yes',
					'IS_COMPILED'        => 'Yes',
					'SORTLEN'            => '0',
					'PAD_ATTRIBUTE'      => 'NO PAD',
				),
				(object) array(
					'COLLATION_NAME'     => 'utf8mb4_bin',
					'CHARACTER_SET_NAME' => 'utf8mb4',
					'ID'                 => '46',
					'IS_DEFAULT'         => '',
					'IS_COMPILED'        => 'Yes',
					'SORTLEN'            => '1',
					'PAD_ATTRIBUTE'      => 'PAD SPACE',
				),
				(object) array(
					'COLLATION_NAME'     => 'utf8mb4_unicode_ci',
					'CHARACTER_SET_NAME' => 'utf8mb4',
					'ID'                 => '224',
					'IS_DEFAULT'         => '',
					'IS_COMPILED'        => 'Yes',
					'SORTLEN'            => '8',
					'PAD_ATTRIBUTE'      => 'PAD SPACE',
				),
			),
			$collations
		);

		$this->assertSame( 0, $driver->query( 'USE information_schema' ) );

		$defaults = $driver->query(
			"SELECT cs.character_set_name, c.collation_name
			FROM character_sets AS cs
			JOIN collations AS c ON c.character_set_name = cs.character_set_name
			WHERE c.is_default = 'Yes'
			ORDER BY c.collation_name"
		);

		$this->assertEquals(
			array(
				(object) array(
					'CHARACTER_SET_NAME' => 'binary',
					'COLLATION_NAME'     => 'binary',
				),
				(object) array(
					'CHARACTER_SET_NAME' => 'utf8',
					'COLLATION_NAME'     => 'utf8_general_ci',
				),
				(object) array(
					'CHARACTER_SET_NAME' => 'utf8mb4',
					'COLLATION_NAME'     => 'utf8mb4_0900_ai_ci',
				),
			),
			$defaults
		);
	}

	/**
	 * Tests real PostgreSQL direct charset/collation information_schema relations use static compatibility rows.
	 */
	public function test_real_pgsql_direct_information_schema_charset_and_collation_relations_use_static_rows(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL direct information_schema charset/collation test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$driver        = new WP_PostgreSQL_Driver( $connection, $database_name );
		$backend_sql   = array();

		$character_sets     = $driver->query(
			"SELECT CHARACTER_SET_NAME, DEFAULT_COLLATE_NAME, DESCRIPTION, MAXLEN
			FROM information_schema.character_sets
			WHERE CHARACTER_SET_NAME LIKE 'utf8%'
			ORDER BY CHARACTER_SET_NAME"
		);
		$character_sets_sql = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.character_sets real PostgreSQL',
			$backend_sql
		);

		$this->assertCount( 2, $character_sets );
		$this->assertSame(
			array( 'CHARACTER_SET_NAME', 'DEFAULT_COLLATE_NAME', 'DESCRIPTION', 'MAXLEN' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);
		$this->assertSame( 'utf8', $this->get_row_value( $character_sets[0], 'CHARACTER_SET_NAME' ) );
		$this->assertSame( 'utf8_general_ci', $this->get_row_value( $character_sets[0], 'DEFAULT_COLLATE_NAME' ) );
		$this->assertSame( 'UTF-8 Unicode', $this->get_row_value( $character_sets[0], 'DESCRIPTION' ) );
		$this->assertSame( '3', (string) $this->get_row_value( $character_sets[0], 'MAXLEN' ) );
		$this->assertSame( 'utf8mb4', $this->get_row_value( $character_sets[1], 'CHARACTER_SET_NAME' ) );
		$this->assertSame( 'utf8mb4_0900_ai_ci', $this->get_row_value( $character_sets[1], 'DEFAULT_COLLATE_NAME' ) );
		$this->assertSame( 'UTF-8 Unicode', $this->get_row_value( $character_sets[1], 'DESCRIPTION' ) );
		$this->assertSame( '4', (string) $this->get_row_value( $character_sets[1], 'MAXLEN' ) );
		$this->assertStringContainsString( "'utf8' AS \"CHARACTER_SET_NAME\"", $character_sets_sql );
		$this->assertStringContainsString( "'utf8_general_ci' AS \"DEFAULT_COLLATE_NAME\"", $character_sets_sql );
		$this->assertStringContainsString( "'utf8mb4' AS \"CHARACTER_SET_NAME\"", $character_sets_sql );
		$this->assertStringContainsString( "'utf8mb4_0900_ai_ci' AS \"DEFAULT_COLLATE_NAME\"", $character_sets_sql );
		$this->assertStringContainsString( 'UNION ALL', $character_sets_sql );

		$collations     = $driver->query(
			"SELECT COLLATION_NAME, CHARACTER_SET_NAME, IS_DEFAULT, SORTLEN, PAD_ATTRIBUTE
			FROM information_schema.collations
			WHERE CHARACTER_SET_NAME = 'utf8mb4'
			ORDER BY COLLATION_NAME"
		);
		$collations_sql = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.collations real PostgreSQL',
			$backend_sql
		);

		$this->assertCount( 3, $collations );
		$this->assertSame(
			array( 'COLLATION_NAME', 'CHARACTER_SET_NAME', 'IS_DEFAULT', 'SORTLEN', 'PAD_ATTRIBUTE' ),
			array_column( $driver->get_last_column_meta(), 'name' )
		);
		$this->assertSame( 'utf8mb4_0900_ai_ci', $this->get_row_value( $collations[0], 'COLLATION_NAME' ) );
		$this->assertSame( 'utf8mb4', $this->get_row_value( $collations[0], 'CHARACTER_SET_NAME' ) );
		$this->assertSame( 'Yes', $this->get_row_value( $collations[0], 'IS_DEFAULT' ) );
		$this->assertSame( '0', (string) $this->get_row_value( $collations[0], 'SORTLEN' ) );
		$this->assertSame( 'NO PAD', $this->get_row_value( $collations[0], 'PAD_ATTRIBUTE' ) );
		$this->assertSame( 'utf8mb4_bin', $this->get_row_value( $collations[1], 'COLLATION_NAME' ) );
		$this->assertSame( 'utf8mb4', $this->get_row_value( $collations[1], 'CHARACTER_SET_NAME' ) );
		$this->assertSame( '', $this->get_row_value( $collations[1], 'IS_DEFAULT' ) );
		$this->assertSame( '1', (string) $this->get_row_value( $collations[1], 'SORTLEN' ) );
		$this->assertSame( 'PAD SPACE', $this->get_row_value( $collations[1], 'PAD_ATTRIBUTE' ) );
		$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $collations[2], 'COLLATION_NAME' ) );
		$this->assertSame( 'utf8mb4', $this->get_row_value( $collations[2], 'CHARACTER_SET_NAME' ) );
		$this->assertSame( '', $this->get_row_value( $collations[2], 'IS_DEFAULT' ) );
		$this->assertSame( '8', (string) $this->get_row_value( $collations[2], 'SORTLEN' ) );
		$this->assertSame( 'PAD SPACE', $this->get_row_value( $collations[2], 'PAD_ATTRIBUTE' ) );
		$this->assertStringContainsString( "'utf8mb4_0900_ai_ci' AS \"COLLATION_NAME\"", $collations_sql );
		$this->assertStringContainsString( "'utf8mb4_bin' AS \"COLLATION_NAME\"", $collations_sql );
		$this->assertStringContainsString( "'utf8mb4_unicode_ci' AS \"COLLATION_NAME\"", $collations_sql );
		$this->assertStringContainsString( 'UNION ALL', $collations_sql );

		$applicability     = $driver->query(
			"SELECT COLLATION_NAME, CHARACTER_SET_NAME
			FROM information_schema.collation_character_set_applicability
			WHERE CHARACTER_SET_NAME = 'utf8mb4'
			ORDER BY COLLATION_NAME"
		);
		$applicability_sql = $this->get_last_single_postgresql_sql( $driver );
		$this->collect_last_postgresql_queries(
			$driver,
			'direct information_schema.collation_character_set_applicability real PostgreSQL',
			$backend_sql
		);

		$this->assertCount( 3, $applicability );
		$this->assertSame( array( 'COLLATION_NAME', 'CHARACTER_SET_NAME' ), array_column( $driver->get_last_column_meta(), 'name' ) );
		$this->assertSame( 'utf8mb4_0900_ai_ci', $this->get_row_value( $applicability[0], 'COLLATION_NAME' ) );
		$this->assertSame( 'utf8mb4', $this->get_row_value( $applicability[0], 'CHARACTER_SET_NAME' ) );
		$this->assertSame( 'utf8mb4_bin', $this->get_row_value( $applicability[1], 'COLLATION_NAME' ) );
		$this->assertSame( 'utf8mb4', $this->get_row_value( $applicability[1], 'CHARACTER_SET_NAME' ) );
		$this->assertSame( 'utf8mb4_unicode_ci', $this->get_row_value( $applicability[2], 'COLLATION_NAME' ) );
		$this->assertSame( 'utf8mb4', $this->get_row_value( $applicability[2], 'CHARACTER_SET_NAME' ) );
		$this->assertStringContainsString( "'utf8mb4_0900_ai_ci' AS \"COLLATION_NAME\"", $applicability_sql );
		$this->assertStringContainsString( "'utf8mb4_bin' AS \"COLLATION_NAME\"", $applicability_sql );
		$this->assertStringContainsString( "'utf8mb4_unicode_ci' AS \"COLLATION_NAME\"", $applicability_sql );
		$this->assertStringContainsString( 'UNION ALL', $applicability_sql );

		foreach ( array( $character_sets_sql, $collations_sql, $applicability_sql ) as $sql ) {
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $sql );
			$this->assertStringNotContainsString( 'pg_catalog.pg_available_extensions', $sql );
			$this->assertStringNotContainsString( 'pg_catalog.pg_stat_activity', $sql );
			$this->assertStringNotContainsString( 'pg_catalog.pg_get_keywords()', $sql );
			$this->assertStringNotContainsString( 'pg_catalog.pg_tablespace', $sql );
			$this->assertStringNotContainsString( 'information_schema.columns c', $sql );
		}
		$this->assertGreaterThan( 0, count( $backend_sql ) );
	}

	/**
	 * Tests unsupported simple DML subquery predicates fail before backend execution.
	 */
	public function test_simple_dml_subquery_predicates_fail_closed(): void {
		$queries = array(
			'UPDATE wptests_options SET option_value = "updated" WHERE option_name IN (
				SELECT option_name FROM wptests_options
			)' => 'Unsupported UPDATE statement.',
			'DELETE FROM wptests_options WHERE option_name IN (
				SELECT option_name FROM wptests_options
			)' => 'Unsupported DELETE statement.',
		);

		foreach ( $queries as $query => $expected_message ) {
			$driver = $this->create_driver();
			$driver->query(
				'CREATE TABLE wptests_options (
					option_name TEXT NOT NULL,
					option_value TEXT NOT NULL
				)'
			);
			$driver->query( "INSERT INTO wptests_options (option_name, option_value) VALUES ('wptests_options', 'before')" );

			try {
				$driver->query( $query );
				$this->fail( 'Expected unsupported simple DML subquery to throw.' );
			} catch ( InvalidArgumentException $e ) {
				$this->assertSame( $expected_message, $e->getMessage(), $query );
				$this->assertSame( array(), $driver->get_last_postgresql_queries(), $query );
			}
		}
	}

	/**
	 * Tests ambiguous unqualified information_schema columns are unresolved.
	 */
	public function test_direct_information_schema_ambiguous_unqualified_column_reference_returns_null(): void {
		$driver        = ( new ReflectionClass( WP_PostgreSQL_Driver::class ) )->newInstanceWithoutConstructor();
		$get_reference = Closure::bind(
			function ( array $tokens, array $context ): ?array {
				return $this->get_direct_information_schema_column_reference_for_expression( $tokens, 0, 1, $context );
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);

		$tokens  = array(
			new WP_MySQL_Token( WP_MySQL_Lexer::NAME_SYMBOL, 0, 10, 'TABLE_NAME', false ),
		);
		$context = array(
			'sources'       => array(
				array(
					'alias'        => 't',
					'column_map'   => array( 'table_name' => 'TABLE_NAME' ),
					'source_start' => 0,
					'source_end'   => 1,
				),
				array(
					'alias'        => 'c',
					'column_map'   => array( 'table_name' => 'TABLE_NAME' ),
					'source_start' => 2,
					'source_end'   => 3,
				),
			),
			'using_columns' => array(),
		);

		$this->assertNull( $get_reference( $tokens, $context ) );
	}

	/**
	 * Fetch a dynamic field value for the FETCH_FUNC introspection cache test.
	 *
	 * @param mixed ...$values Fetched row values.
	 * @return string Dynamic field value.
	 */
	public static function fetch_dynamic_field_for_introspection_cache_test( ...$values ): string {
		++self::$mysql_introspection_fetch_func_invocations;
		return self::$mysql_introspection_fetch_func_invocations . ':' . $values[0];
	}

	/**
	 * Tests MySQL-only runtime SET statements are handled before reaching PDO.
	 */
	public function test_mysql_runtime_set_statements_are_noops(): void {
		$driver = $this->create_driver();

		$queries = array(
			'SET autocommit = 0',
			'SET autocommit = 1;',
			'SET default_storage_engine = InnoDB',
			'SET storage_engine = InnoDB',
			'SET foreign_key_checks = 0',
			'SET foreign_key_checks = 1',
			"SET SESSION sql_mode = ''",
			"SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';",
		);

		foreach ( $queries as $query ) {
			$driver->query( 'SELECT 1 AS previous_value' );

			$this->assertSame( 0, $driver->query( $query ) );
			$this->assertSame( $query, $driver->get_last_mysql_query() );
			$this->assertSame( array(), $driver->get_last_postgresql_queries() );
			$this->assertSame( array(), $driver->get_last_column_meta() );
			$this->assertSame( 0, $driver->get_last_column_count() );
			$this->assertSame( 0, $driver->get_last_return_value() );
		}
	}

	/**
	 * Tests simple MySQL transaction-control statements use direct backend statements.
	 */
	public function test_mysql_transaction_control_statements_use_fast_backend_path(): void {
		$driver = $this->create_driver();

		$this->assertSame( 0, $driver->query( 'START TRANSACTION;' ) );
		$this->assertSame( 'START TRANSACTION;', $driver->get_last_mysql_query() );
		$this->assertSame(
			array(
				array(
					'sql'    => 'BEGIN',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$driver->query( 'CREATE TABLE transaction_test (id INTEGER)' );
		$driver->query( 'INSERT INTO transaction_test (id) VALUES (1)' );

		$this->assertSame( 0, $driver->query( 'ROLLBACK' ) );
		$this->assertSame(
			array(
				array(
					'sql'    => 'ROLLBACK',
					'params' => array(),
				),
			),
			$driver->get_last_postgresql_queries()
		);

		$this->assertFalse( $this->postgresql_relation_exists( $driver, 'transaction_test' ) );

		$this->assertSame( 0, $driver->query( 'COMMIT' ) );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
		$this->assertSame( 0, $driver->get_last_column_count() );
	}

	/**
	 * Tests public SAVEPOINT statements return MySQL-compatible results.
	 */
	public function test_mysql_savepoint_statements_use_public_query_path(): void {
		$driver = $this->create_driver();
		$driver->set_sql_mode( 'STRICT_TRANS_TABLES' );

		$this->assertSame( 0, $driver->query( 'START TRANSACTION' ) );
		$driver->query( 'CREATE TABLE savepoint_public (id INTEGER)' );

		$this->assertSame( 0, $driver->query( 'SAVEPOINT s1' ) );
		$this->assertSame( 0, $driver->get_last_column_count() );
		$this->assertSame( array(), $driver->get_last_column_meta() );
		$this->assertSame( 'SAVEPOINT "s1"', $this->get_last_single_postgresql_sql( $driver ) );

		$driver->query( 'INSERT INTO savepoint_public VALUES (1)' );
		$driver->query( 'SELECT 1 AS warm_read' );

		$this->assertSame( 0, $driver->query( 'ROLLBACK TO SAVEPOINT s1' ) );
		$this->assertSame( 0, $driver->get_last_column_count() );
		$this->assertSame( array(), $driver->get_last_column_meta() );
		$this->assertSame( 'ROLLBACK TO SAVEPOINT "s1"', $this->get_last_single_postgresql_sql( $driver ) );

		$this->assertSame( 0, $driver->query( 'SAVEPOINT s2' ) );
		$driver->query( 'INSERT INTO savepoint_public VALUES (2)' );
		$this->assertSame( 0, $driver->query( 'ROLLBACK WORK TO s2' ) );
		$this->assertSame( 'ROLLBACK TO SAVEPOINT "s2"', $this->get_last_single_postgresql_sql( $driver ) );
		$this->assertSame( 0, $driver->query( 'RELEASE SAVEPOINT s2' ) );

		$this->assertSame( 0, $driver->query( 'SAVEPOINT s3' ) );
		$driver->query( 'INSERT INTO savepoint_public VALUES (3)' );
		$this->assertSame( 0, $driver->query( 'ROLLBACK WORK TO SAVEPOINT s3' ) );
		$this->assertSame( 'ROLLBACK TO SAVEPOINT "s3"', $this->get_last_single_postgresql_sql( $driver ) );
		$this->assertSame( 0, $driver->query( 'RELEASE SAVEPOINT s3' ) );

		$this->assertSame( 0, $driver->query( 'RELEASE SAVEPOINT s1' ) );
		$this->assertSame( 0, $driver->get_last_column_count() );
		$this->assertSame( array(), $driver->get_last_column_meta() );
		$this->assertSame( 'RELEASE SAVEPOINT "s1"', $this->get_last_single_postgresql_sql( $driver ) );

		$rows = $driver->query( 'SELECT COUNT(*) AS row_count FROM savepoint_public' );

		$this->assertSame( '0', $rows[0]->row_count );
	}

