	/**
	 * Tests real PostgreSQL TRUNCATE TABLE restarts identity.
	 */
	public function test_real_pgsql_truncate_table_restarts_identity(): void {
		$dsn = getenv( 'PGSQL_TEST_DSN' );
		if ( false === $dsn || '' === $dsn ) {
			$this->markTestSkipped( 'Set PGSQL_TEST_DSN to run the real PostgreSQL TRUNCATE identity test.' );
		}

		$user     = getenv( 'PGSQL_TEST_USER' );
		$password = getenv( 'PGSQL_TEST_PASSWORD' );
		$pdo      = new PDO(
			$dsn,
			false === $user ? null : $user,
			false === $password ? null : $password
		);
		$pdo->setAttribute( PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION );

		$this->assertSame(
			'pgsql',
			$pdo->getAttribute( PDO::ATTR_DRIVER_NAME ),
			'PGSQL_TEST_DSN must use the pgsql PDO driver.'
		);

		$pdo->exec( 'SET search_path TO public' );
		$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1036_truncate' );

		$database_name = (string) $pdo->query( 'SELECT current_database()' )->fetchColumn();
		$connection    = new WP_PostgreSQL_Connection( array( 'pdo' => $pdo ) );
		$logged_sql    = array();
		$connection->set_query_logger(
			static function ( string $sql ) use ( &$logged_sql ): void {
				$logged_sql[] = $sql;
			}
		);
		$driver          = new WP_PostgreSQL_Driver( $connection, $database_name );
		$suffix          = strtolower( bin2hex( random_bytes( 4 ) ) );
		$table_name      = 'task1036_truncate_' . $suffix;
		$qualified_table = 'task1036_truncate_' . $suffix . '_qualified';
		$backend_sql     = array();
		$create_table    = static function ( WP_PostgreSQL_Driver $driver, string $table_name ): int {
			return $driver->query(
				sprintf(
					'CREATE TABLE `%s` (
							`id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
							`label` varchar(64) NOT NULL,
							PRIMARY KEY (`id`)
						) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4',
					$table_name
				)
			);
		};

		try {
			$this->assertSame( 0, $create_table( $driver, $table_name ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE unqualified TRUNCATE table',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`label`) VALUES ('before')", $table_name ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'insert first unqualified TRUNCATE row',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`label`) VALUES ('again')", $table_name ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'insert second unqualified TRUNCATE row',
				$backend_sql
			);

			$rows = $driver->query( sprintf( 'SELECT `id`, `label` FROM `%s` ORDER BY `id`', $table_name ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'read unqualified rows before TRUNCATE',
				$backend_sql
			);
			$this->assertEquals(
				array(
					(object) array(
						'id'    => '1',
						'label' => 'before',
					),
					(object) array(
						'id'    => '2',
						'label' => 'again',
					),
				),
				$rows
			);

			$this->assertSame( 0, $driver->query( sprintf( 'TRUNCATE TABLE `%s`', $table_name ) ) );
			$this->assertSame( 0, $driver->get_last_column_count() );
			$this->assertSame( array(), $driver->get_last_column_meta() );
			$this->assertSame(
				'TRUNCATE TABLE "' . $table_name . '" RESTART IDENTITY',
				$this->get_last_single_postgresql_sql( $driver )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'unqualified TRUNCATE',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`label`) VALUES ('after')", $table_name ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'insert unqualified row after TRUNCATE',
				$backend_sql
			);
			$rows = $driver->query( sprintf( 'SELECT `id`, `label` FROM `%s`', $table_name ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'read unqualified rows after TRUNCATE',
				$backend_sql
			);
			$this->assertEquals(
				array(
					(object) array(
						'id'    => '1',
						'label' => 'after',
					),
				),
				$rows
			);

			$this->assertSame( 0, $create_table( $driver, $qualified_table ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'CREATE qualified TRUNCATE table',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`label`) VALUES ('qualified_before')", $qualified_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'insert first qualified TRUNCATE row',
				$backend_sql
			);
			$this->assertSame(
				1,
				$driver->query( sprintf( "INSERT INTO `%s` (`label`) VALUES ('qualified_again')", $qualified_table ) )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'insert second qualified TRUNCATE row',
				$backend_sql
			);

			$this->assertSame( 0, $driver->query( 'USE information_schema' ) );
			$this->collect_last_postgresql_queries(
				$driver,
				'USE information_schema before qualified TRUNCATE',
				$backend_sql
			);

			$this->assertSame(
				0,
				$driver->query(
					sprintf(
						'TRUNCATE TABLE `%s`.`%s`',
						$database_name,
						$qualified_table
					)
				)
			);
			$this->assertSame( 0, $driver->get_last_column_count() );
			$this->assertSame( array(), $driver->get_last_column_meta() );
			$this->assertSame(
				'TRUNCATE TABLE "' . $qualified_table . '" RESTART IDENTITY',
				$this->get_last_single_postgresql_sql( $driver )
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'main database-qualified TRUNCATE after USE information_schema',
				$backend_sql
			);

			$this->assertSame(
				1,
				$driver->query(
					sprintf(
						"INSERT INTO `%s`.`%s` (`label`) VALUES ('qualified_after')",
						$database_name,
						$qualified_table
					)
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'insert qualified row after TRUNCATE',
				$backend_sql
			);
			$rows = $driver->query(
				sprintf(
					'SELECT `id`, `label` FROM `%s`.`%s`',
					$database_name,
					$qualified_table
				)
			);
			$this->collect_last_postgresql_queries(
				$driver,
				'read qualified rows after TRUNCATE',
				$backend_sql
			);
			$this->assertEquals(
				array(
					(object) array(
						'id'    => '1',
						'label' => 'qualified_after',
					),
				),
				$rows
			);

			$all_logged_sql = implode( "\n", $logged_sql );
			$this->assertStringContainsString( 'TRUNCATE TABLE "' . $table_name . '" RESTART IDENTITY', $all_logged_sql );
			$this->assertStringContainsString( 'TRUNCATE TABLE "' . $qualified_table . '" RESTART IDENTITY', $all_logged_sql );
			$this->assertStringNotContainsString( 'DELETE FROM', $all_logged_sql );
			$this->assertStringNotContainsString( 'sqlite' . '_sequence', $all_logged_sql );
			$this->assertStringNotContainsString( '__wp_mysql_information_schema', $all_logged_sql );
			$this->assertStringNotContainsString( 'CREATE OR REPLACE VIEW', $all_logged_sql );
			$this->assertGreaterThan( 0, count( $backend_sql ) );
		} finally {
			$this->drop_public_pgsql_tables_with_prefix( $pdo, 'task1036_truncate' );
			$this->assertSame( array(), $this->get_public_pgsql_tables_with_prefix( $pdo, 'task1036_truncate' ) );
		}
	}

