	/**
	 * Tests GROUP_CONCAT length SET state is emulated for PostgreSQL.
	 */
	public function test_group_concat_max_len_can_be_set_selected_and_restored(): void {
		$driver = $this->create_driver();

		$default = $driver->query( "SHOW VARIABLES LIKE 'group_concat_max_len'" );
		$this->assertCount( 1, $default );
		$this->assertSame( 'group_concat_max_len', $default[0]->Variable_name );
		$this->assertSame( '1024', $default[0]->Value );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );

		$this->assertSame( 0, $driver->query( 'SET @old_group_concat_max_len = @@SESSION.group_concat_max_len' ) );
		$this->assertSame( 0, $driver->query( 'SET SESSION group_concat_max_len = 1000000' ) );

		$rows = $driver->query( 'SELECT @@SESSION.group_concat_max_len' );
		$this->assertSame( '1000000', $rows[0]->{'@@SESSION.group_concat_max_len'} );

		$rows = $driver->query( "SHOW VARIABLES WHERE Variable_name = 'group_concat_max_len'" );
		$this->assertCount( 1, $rows );
		$this->assertSame( '1000000', $rows[0]->Value );

		$this->assertSame( 0, $driver->query( 'SET group_concat_max_len = @old_group_concat_max_len' ) );
		$rows = $driver->query( 'SELECT @@group_concat_max_len' );
		$this->assertSame( '1024', $rows[0]->{'@@group_concat_max_len'} );
		$this->assertSame( array(), $driver->get_last_postgresql_queries() );
	}

	/**
	 * Tests the default GROUP_CONCAT length limit is enforced for supported translations.
	 */
	public function test_group_concat_uses_default_group_concat_max_len(): void {
		$driver = $this->create_driver();
		$this->create_group_concat_values_table(
			$driver,
			array(
				1 => str_repeat( 'a', 600 ),
				2 => str_repeat( 'b', 600 ),
			)
		);

		$rows = $driver->query( "SELECT GROUP_CONCAT(value ORDER BY id SEPARATOR '') AS combined FROM group_concat_values" );

		$this->assertSame( str_repeat( 'a', 600 ) . str_repeat( 'b', 424 ), $rows[0]->combined );
		$this->assertSame( 1024, strlen( $rows[0]->combined ) );
		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'STRING_AGG', $sql );
		$this->assertStringContainsString( ', 1024', $sql );
	}

	/**
	 * Tests small GROUP_CONCAT length limits truncate standard ORDER/SEPARATOR forms.
	 */
	public function test_group_concat_max_len_truncates_supported_group_concat_shapes(): void {
		$driver = $this->create_driver();
		$this->create_group_concat_values_table(
			$driver,
			array(
				2 => 'two',
				1 => 'one',
				3 => 'three',
			)
		);

		$this->assertSame( 0, $driver->query( 'SET SESSION group_concat_max_len = 5' ) );
		$rows = $driver->query( "SELECT GROUP_CONCAT(value ORDER BY id SEPARATOR '|') AS combined FROM group_concat_values" );

		$this->assertSame( 'one|t', $rows[0]->combined );
		$this->assertStringContainsString( ', 5', $this->get_last_single_postgresql_sql( $driver ) );

		$rows = $driver->query( 'SELECT GROUP_CONCAT(value ORDER BY id) AS combined FROM group_concat_values' );
		$this->assertSame( 'one,t', $rows[0]->combined );

		$rows = $driver->query( 'SELECT GROUP_CONCAT(value) AS combined FROM group_concat_values WHERE id = 1' );
		$this->assertSame( 'one', $rows[0]->combined );
	}

	/**
	 * Tests SET group_concat_max_len = DEFAULT restores the default runtime behavior.
	 */
	public function test_group_concat_max_len_default_restore_updates_group_concat_output(): void {
		$driver = $this->create_driver();
		$this->create_group_concat_values_table(
			$driver,
			array(
				1 => 'alpha',
				2 => 'beta',
			)
		);

		$query = "SELECT GROUP_CONCAT(value ORDER BY id SEPARATOR '|') AS combined FROM group_concat_values";

		$this->assertSame( 0, $driver->query( 'SET SESSION group_concat_max_len = 5' ) );
		$rows = $driver->query( $query );
		$this->assertSame( 'alpha', $rows[0]->combined );

		$this->assertSame( 0, $driver->query( 'SET SESSION group_concat_max_len = DEFAULT' ) );
		$rows = $driver->query( $query );
		$this->assertSame( 'alpha|beta', $rows[0]->combined );

		$variable = $driver->query( 'SELECT @@group_concat_max_len' );
		$this->assertSame( '1024', $variable[0]->{'@@group_concat_max_len'} );
	}

	/**
	 * Tests GROUP_CONCAT translations do not reuse stale group_concat_max_len state.
	 */
	public function test_group_concat_max_len_translation_does_not_use_stale_cached_state(): void {
		$driver = $this->create_driver();
		$this->create_group_concat_values_table(
			$driver,
			array(
				1 => 'alpha',
				2 => 'beta',
			)
		);

		$query = "SELECT GROUP_CONCAT(value ORDER BY id SEPARATOR '|') AS combined FROM group_concat_values";

		$this->assertSame( 0, $driver->query( 'SET SESSION group_concat_max_len = 5' ) );
		$rows = $driver->query( $query );
		$this->assertSame( 'alpha', $rows[0]->combined );
		$this->assertStringContainsString( ', 5', $this->get_last_single_postgresql_sql( $driver ) );

		$this->assertSame( 0, $driver->query( 'SET SESSION group_concat_max_len = 9' ) );
		$rows = $driver->query( $query );
		$this->assertSame( 'alpha|bet', $rows[0]->combined );
		$this->assertStringContainsString( ', 9', $this->get_last_single_postgresql_sql( $driver ) );
	}

	/**
	 * Tests GROUP_CONCAT(expr, expr, ...) concatenates row expressions before aggregation.
	 */
	public function test_group_concat_multi_expression_rows_are_concatenated_before_aggregation(): void {
		$driver = $this->create_driver();
		$this->create_group_concat_values_table(
			$driver,
			array(
				2 => 'two',
				1 => 'one',
				3 => 'three',
			)
		);

		$rows = $driver->query( "SELECT GROUP_CONCAT(id, ':', value ORDER BY id SEPARATOR '|') AS combined FROM group_concat_values" );

		$this->assertSame( '1:one|2:two|3:three', $rows[0]->combined );
		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( "CAST(id AS text) || CAST(':' AS text) || CAST(value AS text)", $sql );
		$this->assertStringContainsString( "STRING_AGG(CAST(CAST(id AS text) || CAST(':' AS text) || CAST(value AS text) AS text), CAST('|' AS text) ORDER BY id)", $sql );
		$this->assertStringNotContainsString( 'GROUP_CONCAT', $sql );
	}

	/**
	 * Tests GROUP_CONCAT multi-expression rows preserve NULL skip semantics.
	 */
	public function test_group_concat_multi_expression_rows_skip_null_composites(): void {
		$driver = $this->create_driver();

		$driver->query(
			'CREATE TABLE group_concat_multi_values (
				id INTEGER PRIMARY KEY,
				prefix TEXT NOT NULL,
				suffix TEXT NULL
			)'
		);
		$driver->query(
			"INSERT INTO group_concat_multi_values (id, prefix, suffix) VALUES
				(1, 'a', '1'),
				(2, 'b', NULL),
				(3, 'c', '3')"
		);

		$rows = $driver->query( "SELECT GROUP_CONCAT(prefix, suffix ORDER BY id SEPARATOR ',') AS combined FROM group_concat_multi_values" );

		$this->assertSame( 'a1,c3', $rows[0]->combined );
	}

	/**
	 * Tests GROUP_CONCAT(DISTINCT expr) deduplicates values and keeps group_concat_max_len behavior.
	 */
	public function test_group_concat_distinct_default_separator_deduplicates_values(): void {
		$driver = $this->create_driver();
		$this->create_group_concat_values_table(
			$driver,
			array(
				1 => 'alpha',
				2 => 'beta',
				3 => 'alpha',
				4 => 'beta',
			)
		);

		$rows  = $driver->query( 'SELECT GROUP_CONCAT(DISTINCT value) AS combined FROM group_concat_values' );
		$parts = explode( ',', $rows[0]->combined );
		sort( $parts );

		$this->assertSame( array( 'alpha', 'beta' ), $parts );
		$sql = $this->get_last_single_postgresql_sql( $driver );
		$this->assertStringContainsString( 'GROUP_CONCAT(DISTINCT CAST(value AS text))', $sql );
		$this->assertStringContainsString( ', 1024', $sql );
	}

