	/**
	 * Store MySQL-facing metadata using private driver catalog helpers.
	 *
	 * @param WP_PostgreSQL_Driver $driver Driver under test.
	 * @param string               $query  MySQL CREATE TABLE query.
	 */
	private function install_mysql_schema_metadata_fixture( WP_PostgreSQL_Driver $driver, string $query ): void {
		$store_metadata = Closure::bind(
			function ( string $query ): void {
				$tokens = $this->get_mysql_tokens( $query );
				$prefix = $this->get_mysql_create_table_prefix( $tokens );
				if ( null === $prefix ) {
					throw new InvalidArgumentException( 'Unsupported PostgreSQL catalog metadata fixture.' );
				}

				if ( $prefix['temporary'] ) {
					return;
				}

				$position        = $prefix['position'];
				$table_reference = $this->get_mysql_table_administration_table_reference( $tokens, $position, true );
				if (
					null === $table_reference
					|| ! $this->is_mysql_create_table_target_boundary( $tokens, $position, $prefix['statement_end'] )
				) {
					throw new InvalidArgumentException( 'Unsupported PostgreSQL catalog metadata fixture.' );
				}

				$this->sync_mysql_schema_catalog_side_effects_for_schema(
					$this->get_postgresql_catalog_mysql_schema_metadata_or_fail( $query ),
					$this->get_mysql_create_table_select_backend_schema( $table_reference, false )
				);
			},
			$driver,
			WP_PostgreSQL_Driver::class
		);

		if ( ! $store_metadata instanceof Closure ) {
			throw new RuntimeException( 'Could not bind MySQL metadata test helper.' );
		}

		$store_metadata( $query );
	}

	/**
	 * Collect backend SQL generated by the last driver query.
	 *
	 * @param WP_PostgreSQL_Driver $driver      Driver under test.
	 * @param string               $context     Collection context.
	 * @param string[]             $backend_sql Collected backend SQL.
	 */
	private function collect_last_postgresql_queries(
		WP_PostgreSQL_Driver $driver,
		string $context,
		array &$backend_sql
	): void {
		unset( $context );

		foreach ( $driver->get_last_postgresql_queries() as $query ) {
			$sql           = (string) ( $query['sql'] ?? '' );
			$backend_sql[] = $sql;
		}
	}

	/**
	 * Assert SHOW OPEN TABLES uses the PostgreSQL relation and lock catalog path.
	 *
	 * @param array $query Captured query.
	 */
	private function assert_show_open_tables_catalog_query_shape( array $query ): void {
		$this->assertStringContainsString( 'FROM pg_catalog.pg_class c', $query['sql'] );
		$this->assertStringContainsString( 'INNER JOIN pg_catalog.pg_namespace n', $query['sql'] );
		$this->assertStringContainsString( 'LEFT JOIN pg_catalog.pg_locks l', $query['sql'] );
		$this->assertStringContainsString( 'pg_catalog.pg_backend_pid()', $query['sql'] );
		$this->assertStringContainsString( 'c.relkind IN (\'r\', \'p\', \'v\', \'m\', \'f\')', $query['sql'] );
		$this->assertStringContainsString( 'ORDER BY c.relname', $query['sql'] );
		$this->assertSame( array( 'public' ), $query['params'] );
	}

	/**
	 * Assert SHOW TRIGGERS uses the PostgreSQL information_schema trigger path.
	 *
	 * @param array  $query          Captured query.
	 * @param string $display_schema Expected MySQL display schema.
	 */
	private function assert_show_triggers_catalog_query_shape( array $query, string $display_schema ): void {
		$this->assertStringContainsString( 'FROM information_schema.triggers t', $query['sql'] );
		$this->assertStringContainsString( 't."TRIGGER_NAME" AS "Trigger"', $query['sql'] );
		$this->assertStringContainsString( 'WHERE t."TRIGGER_SCHEMA" = ?', $query['sql'] );
		$this->assertStringContainsString( 'ORDER BY t."TRIGGER_NAME"', $query['sql'] );
		$this->assertSame( array( $display_schema ), $query['params'] );
	}

	/**
	 * Assert SHOW FUNCTION/PROCEDURE STATUS uses the PostgreSQL information_schema routine path.
	 *
	 * @param array  $query        Captured query.
	 * @param string $routine_type Expected routine type.
	 */
	private function assert_show_routine_status_catalog_query_shape( array $query, string $routine_type ): void {
		$this->assertStringContainsString( 'FROM information_schema.routines r', $query['sql'] );
		$this->assertStringContainsString( 'r."ROUTINE_NAME" AS "Name"', $query['sql'] );
		$this->assertStringContainsString( 'WHERE r."ROUTINE_TYPE" = ?', $query['sql'] );
		$this->assertStringContainsString( 'ORDER BY r."ROUTINE_SCHEMA", r."ROUTINE_NAME"', $query['sql'] );
		$this->assertSame( array( $routine_type ), $query['params'] );
	}

	/**
	 * Get a row value using case-insensitive column lookup.
	 *
	 * @param array|object $row    Row object or associative array.
	 * @param string       $column Column name.
	 * @return mixed Row value.
	 */
	private function get_row_value( $row, string $column ) {
		$values = is_array( $row ) ? $row : get_object_vars( $row );
		foreach ( $values as $name => $value ) {
			if ( 0 === strcasecmp( (string) $name, $column ) ) {
				return $value;
			}
		}

		$this->fail(
			sprintf(
				'Expected row column %s in row with columns: %s.',
				$column,
				implode( ', ', array_keys( $values ) )
			)
		);
		return null;
	}

	/**
	 * Find the first row matching a case-insensitive column value.
	 *
	 * @param array  $rows          Rows.
	 * @param string $column        Column name.
	 * @param string $expected_value Expected value.
	 * @return array|object Matching row.
	 */
	private function find_row_by_value( array $rows, string $column, string $expected_value ) {
		foreach ( $rows as $row ) {
			if ( $expected_value === (string) $this->get_row_value( $row, $column ) ) {
				return $row;
			}
		}

		$this->fail(
			sprintf(
				'Expected a row with %s = %s.',
				$column,
				$expected_value
			)
		);
		return null;
	}

	/**
	 * Find the first row matching a case-insensitive column value, if present.
	 *
	 * @param array  $rows          Rows.
	 * @param string $column        Column name.
	 * @param string $expected_value Expected value.
	 * @return array|object|null Matching row, or null.
	 */
	private function find_optional_row_by_value( array $rows, string $column, string $expected_value ) {
		foreach ( $rows as $row ) {
			if ( $expected_value === (string) $this->get_row_value( $row, $column ) ) {
				return $row;
			}
		}

		return null;
	}

	/**
	 * Drop public PostgreSQL tables using the given task prefix.
	 *
	 * @param PDO    $pdo    PostgreSQL PDO connection.
	 * @param string $prefix Table-name prefix before the separator underscore.
	 */
	private function drop_public_pgsql_tables_with_prefix( PDO $pdo, string $prefix ): void {
		foreach ( $this->get_public_pgsql_tables_with_prefix( $pdo, $prefix ) as $table_name ) {
			$pdo->exec(
				'DROP TABLE IF EXISTS '
				. WP_PostgreSQL_Connection::quote_identifier_value( 'public' )
				. '.'
				. WP_PostgreSQL_Connection::quote_identifier_value( (string) $table_name )
				. ' CASCADE'
			);
		}
	}

