	/**
	 * Drop PostgreSQL roles using the given task prefix.
	 *
	 * @param PDO    $pdo    PostgreSQL PDO connection.
	 * @param string $prefix Role-name prefix before the separator underscore.
	 */
	private function drop_pgsql_roles_with_prefix( PDO $pdo, string $prefix ): void {
		$current_user = (string) $pdo->query( 'SELECT current_user' )->fetchColumn();
		$current_sql  = WP_PostgreSQL_Connection::quote_identifier_value( $current_user );

		foreach ( $this->get_pgsql_roles_with_prefix( $pdo, $prefix ) as $role_name ) {
			$role_sql = WP_PostgreSQL_Connection::quote_identifier_value( (string) $role_name );

			$pdo->exec( 'REVOKE ' . $role_sql . ' FROM ' . $current_sql );
			$pdo->exec( 'DROP OWNED BY ' . $role_sql );
			$pdo->exec( 'DROP ROLE IF EXISTS ' . $role_sql );
		}
	}

	/**
	 * Get PostgreSQL schemas using the given task prefix.
	 *
	 * @param PDO    $pdo    PostgreSQL PDO connection.
	 * @param string $prefix Schema-name prefix before the separator underscore.
	 * @return string[] Schema names.
	 */
	private function get_pgsql_schemas_with_prefix( PDO $pdo, string $prefix ): array {
		$stmt = $pdo->prepare(
			"SELECT schema_name
			FROM information_schema.schemata
			WHERE schema_name LIKE ? ESCAPE '\\'
			ORDER BY schema_name"
		);
		$stmt->execute( array( $prefix . '\\_%' ) );

		return $stmt->fetchAll( PDO::FETCH_COLUMN );
	}

