	/**
	 * Get PostgreSQL type rows by schema and type name.
	 *
	 * @param PDO      $pdo        PostgreSQL PDO connection.
	 * @param string   $schema     Schema name.
	 * @param string[] $type_names Type names.
	 * @return array<string,array<string,string|null>> Type rows keyed by type name.
	 */
	private function get_pgsql_type_rows_by_name( PDO $pdo, string $schema, array $type_names ): array {
		if ( array() === $type_names ) {
			return array();
		}

		$placeholders = implode( ', ', array_fill( 0, count( $type_names ), '?' ) );
		$stmt         = $pdo->prepare(
			"SELECT
				t.typname,
				t.typtype,
				pg_catalog.format_type(t.typbasetype, t.typtypmod) AS base_type,
				pg_catalog.obj_description(t.oid, 'pg_type') AS type_comment
			FROM pg_catalog.pg_type t
			INNER JOIN pg_catalog.pg_namespace n
				ON n.oid = t.typnamespace
			WHERE n.nspname = ?
				AND t.typname IN ({$placeholders})
			ORDER BY t.typname"
		);
		$stmt->execute( array_merge( array( $schema ), $type_names ) );

		$rows = array();
		foreach ( $stmt->fetchAll( PDO::FETCH_ASSOC ) as $row ) {
			$rows[ (string) $row['typname'] ] = $row;
		}
		return $rows;
	}

	/**
	 * Get PostgreSQL enum labels by schema and enum type name.
	 *
	 * @param PDO    $pdo       PostgreSQL PDO connection.
	 * @param string $schema    Schema name.
	 * @param string $type_name Enum type name.
	 * @return string[] Enum labels.
	 */
	private function get_pgsql_enum_labels( PDO $pdo, string $schema, string $type_name ): array {
		$stmt = $pdo->prepare(
			'SELECT e.enumlabel
			FROM pg_catalog.pg_enum e
			INNER JOIN pg_catalog.pg_type t
				ON t.oid = e.enumtypid
			INNER JOIN pg_catalog.pg_namespace n
				ON n.oid = t.typnamespace
			WHERE n.nspname = ?
				AND t.typname = ?
			ORDER BY e.enumsortorder'
		);
		$stmt->execute( array( $schema, $type_name ) );

		return $stmt->fetchAll( PDO::FETCH_COLUMN );
	}

	/**
	 * Get PostgreSQL table references in schemas using the given task prefix.
	 *
	 * @param PDO    $pdo    PostgreSQL PDO connection.
	 * @param string $prefix Schema-name prefix before the separator underscore.
	 * @return string[] Schema-qualified table names.
	 */
	private function get_pgsql_tables_in_schemas_with_prefix( PDO $pdo, string $prefix ): array {
		$stmt = $pdo->prepare(
			"SELECT table_schema || '.' || table_name AS table_reference
			FROM information_schema.tables
			WHERE table_schema LIKE ? ESCAPE '\\'
			ORDER BY table_schema, table_name"
		);
		$stmt->execute( array( $prefix . '\\_%' ) );

		return $stmt->fetchAll( PDO::FETCH_COLUMN );
	}

