	/**
	 * Get physical PostgreSQL index names for a public table.
	 *
	 * @param PDO    $pdo        PostgreSQL PDO connection.
	 * @param string $table_name Public table name.
	 * @return string[] Index names.
	 */
	private function get_public_pgsql_index_names_for_table( PDO $pdo, string $table_name ): array {
		$stmt = $pdo->prepare(
			"SELECT idx.relname
			FROM pg_catalog.pg_index i
			INNER JOIN pg_catalog.pg_class t
				ON t.oid = i.indrelid
			INNER JOIN pg_catalog.pg_namespace n
				ON n.oid = t.relnamespace
			INNER JOIN pg_catalog.pg_class idx
				ON idx.oid = i.indexrelid
			WHERE n.nspname = 'public'
				AND t.relname = ?
			ORDER BY idx.relname"
		);
		$stmt->execute( array( $table_name ) );

		return $stmt->fetchAll( PDO::FETCH_COLUMN );
	}

	/**
	 * Check whether a public PostgreSQL trigger exists on a table.
	 *
	 * @param PDO    $pdo          PostgreSQL PDO connection.
	 * @param string $table_name   Public table name.
	 * @param string $trigger_name Trigger name.
	 * @return bool Whether the trigger exists.
	 */
	private function public_pgsql_trigger_exists( PDO $pdo, string $table_name, string $trigger_name ): bool {
		$stmt = $pdo->prepare(
			"SELECT 1
			FROM pg_catalog.pg_trigger tr
			INNER JOIN pg_catalog.pg_class t
				ON t.oid = tr.tgrelid
			INNER JOIN pg_catalog.pg_namespace n
				ON n.oid = t.relnamespace
			WHERE n.nspname = 'public'
				AND t.relname = ?
				AND tr.tgname = ?
				AND NOT tr.tgisinternal
			LIMIT 1"
		);
		$stmt->execute( array( $table_name, $trigger_name ) );

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Check whether a public PostgreSQL function exists.
	 *
	 * @param PDO    $pdo           PostgreSQL PDO connection.
	 * @param string $function_name Function name.
	 * @return bool Whether the function exists.
	 */
	private function public_pgsql_function_exists( PDO $pdo, string $function_name ): bool {
		$stmt = $pdo->prepare(
			"SELECT 1
			FROM pg_catalog.pg_proc p
			INNER JOIN pg_catalog.pg_namespace n
				ON n.oid = p.pronamespace
			WHERE n.nspname = 'public'
				AND p.prokind = 'f'
				AND p.proname = ?
			LIMIT 1"
		);
		$stmt->execute( array( $function_name ) );

		return false !== $stmt->fetchColumn();
	}

	/**
	 * Drop a public PostgreSQL no-argument function if it exists.
	 *
	 * @param PDO    $pdo           PostgreSQL PDO connection.
	 * @param string $function_name Function name.
	 */
	private function drop_public_pgsql_function( PDO $pdo, string $function_name ): void {
		$pdo->exec(
			'DROP FUNCTION IF EXISTS '
			. WP_PostgreSQL_Connection::quote_identifier_value( 'public' )
			. '.'
			. WP_PostgreSQL_Connection::quote_identifier_value( $function_name )
			. '() CASCADE'
		);
	}

	/**
	 * Get public PostgreSQL functions using the given task prefix.
	 *
	 * @param PDO    $pdo    PostgreSQL PDO connection.
	 * @param string $prefix Function-name prefix before the separator underscore.
	 * @return array<int,array{name:string,arguments:string}> Function rows.
	 */
	private function get_public_pgsql_functions_with_prefix( PDO $pdo, string $prefix ): array {
		$stmt = $pdo->prepare(
			"SELECT
				p.proname AS name,
				pg_catalog.pg_get_function_identity_arguments(p.oid) AS arguments
			FROM pg_catalog.pg_proc p
			INNER JOIN pg_catalog.pg_namespace n
				ON n.oid = p.pronamespace
			WHERE n.nspname = 'public'
				AND p.prokind = 'f'
				AND p.proname LIKE ? ESCAPE '\\'
			ORDER BY p.proname, arguments"
		);
		$stmt->execute( array( $prefix . '\\_%' ) );

		return $stmt->fetchAll( PDO::FETCH_ASSOC );
	}

