	 * @param string $prefix Procedure-name prefix before the separator underscore.
	 * @return array<int,array{name:string,arguments:string}> Procedure rows.
	 */
	private function get_public_pgsql_procedures_with_prefix( PDO $pdo, string $prefix ): array {
